__reload_all = true
local System = require("System.System")
local readonly = System.readonly
local Text_Voice = readonly({
  Voice_100335_AwakerVoiceContent = {
    Text = "守密人，請問我什麼時候能去學院的墓地裡參觀嗎？那裡埋葬的偉大靈魂，一定能給我帶來異乎尋常的靈感！請放心，我保證不會再把那些屍體挖出來近距離觀摩了……"
  },
  Voice_100335_AwakerVoiceTitle = {
    Text = "閒話：關於模特"
  },
  Voice_100336_AwakerVoiceContent = {
    Text = "等等！我想到了一種新的表現方式，一定會震撼整個繪畫界的！"
  },
  Voice_100336_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_100337_AwakerVoiceContent = {
    Text = "我即光影，我即色彩，我……即繪畫本身！"
  },
  Voice_100337_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_100338_AwakerVoiceContent = {
    Text = "嘶……一種我從未見過的色彩，在你的精神世界裡閃耀……究竟是什麼呢……"
  },
  Voice_100338_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_100338_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_100339_AwakerVoiceContent = {
    Text = "多麼棒的黑色顏料！我曾經搜集了許多融蝕液來作畫，最後那些畫作都消失了。來自原初宇宙的顏色，所有畫面都被吞噬的、不被任何人記住的畫作……更棒了不是嗎？！"
  },
  Voice_100339_AwakerVoiceTitle = {
    Text = "閒話·關於危機"
  },
  Voice_100340_AwakerVoiceContent = {
    Text = "讓我靠近一點……讓我再多看一點！這些光影，這些色彩，這些姿態……跟它們比起來，我以前所畫出來的東西都是一堆廢紙……"
  },
  Voice_100340_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_100340_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_100341_AwakerVoiceContent = {
    Text = "杜勒賽因老是跟我講他的烹飪是多麼具有藝術感，要我看，進食與藝術根本就毫不相干！不但要浪費寶貴的創作時間去做那些繁複的屍體處理工作，好不容易創作出一道形色兼備的食物出來，還得將它啃食、吞掉！這簡直就是對藝術的犯罪！"
  },
  Voice_100341_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_100342_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_100343_AwakerVoiceContent = {
    Text = "惡劣的模特……"
  },
  Voice_100343_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_100344_AwakerVoiceContent = {
    Text = "不行不行，又是一幅糟糕的畫作……得去哪裡找找靈感。墓地？或者刑場……"
  },
  Voice_100344_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_100345_AwakerVoiceContent = {
    Text = "雖然我覺得雕刻這種藝術形式有些過於生硬古板，但那位叫做珊的雕刻家，她的刻刀能夠擁有超越這個藝術形式所能承載的表達力……真是一位難得的天才！"
  },
  Voice_100345_AwakerVoiceTitle = {
    Text = "閒話：關於珊"
  },
  Voice_100345_UnlockDesc = {
    Text = "獲得喚醒體「珊」後解鎖"
  },
  Voice_100346_AwakerVoiceContent = {
    Text = "看到這幅畫了嗎，守密人？這是我為您畫的肖像。看看您啃食屍體的樣子，多麼迷人！我知道，並不是所有的人都能理解我的畫作，但這幅畫裡所傳達的那些瘋狂的美，您一定已經觸碰到了對吧？！對我來說，這就已經足夠，完全足夠了……"
  },
  Voice_100346_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_100346_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_100347_AwakerVoiceContent = {
    Text = "您剛才說想買下這幅畫……是真的嗎？！謝、謝謝您，守密人！很、很少有人類能夠欣賞這些……"
  },
  Voice_100347_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_100347_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_100348_AwakerVoiceContent = {
    Text = "守密人，你最近還有空來做我的模特嗎？跟上次在你身上見到的景象比起來，其他的模特都完全是在浪費我的時間……"
  },
  Voice_100348_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_100349_AwakerVoiceContent = {
    Text = "在這畫作裡，見證新生！"
  },
  Voice_100349_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_100350_AwakerVoiceContent = {
    Text = "看這生動的線條！"
  },
  Voice_100351_AwakerVoiceContent = {
    Text = "我有預感，這只畫筆所創造的東西，將會令所有人驚歎！"
  },
  Voice_100351_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_100352_AwakerVoiceContent = {
    Text = "啊！一種新奇的顏料……我會把它塗抹在最恰當的位置！"
  },
  Voice_100352_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_100353_AwakerVoiceContent = {
    Text = "這裡真是個讓人靈感迸發的好地方！我又有了一些新的創作，守密人，您最近有空去我的畫室裡面參觀嗎？來吧來吧！"
  },
  Voice_100353_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_100353_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_100354_AwakerVoiceContent = {
    Text = "沒錯，沒錯！被鮮血澆灌的勝利！一幅多麼絕妙的構圖！"
  },
  Voice_100354_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_100355_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_100356_AwakerVoiceContent = {
    Text = "啊！請坐，守密人。做我的模特是一件辛苦的差事。請放心，我一定會為你創作出一幅驚人的畫作的。"
  },
  Voice_100356_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_100356_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_100357_AwakerVoiceContent = {
    Text = "一個藝術家，眼裡應當只有作品本身，並不會在意別人對自己的目光，可我做不到……從第一次拿起畫筆的那天，我就希望能夠將真正的美帶給所有人。"
  },
  Voice_100357_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_100357_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_100358_AwakerVoiceContent = {
    Text = "這裡讓我想起以前在繪畫學院的那些時光。雖然教授和同學大都是一些完全不懂藝術的庸人，不過總會有那麼一兩個有識之士，能從我的畫作裡窺見到我所窺見的美。"
  },
  Voice_100358_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格"
  },
  Voice_100359_AwakerVoiceContent = {
    Text = "這場野蠻的表演，又會碰撞出怎樣瘋狂的藝術？！"
  },
  Voice_100359_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_100360_AwakerVoiceContent = {
    Text = "我的調色盤！"
  },
  Voice_100360_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_100361_AwakerVoiceContent = {
    Text = "痛苦亦是藝術……"
  },
  Voice_100362_AwakerVoiceContent = {
    Text = "啊！我看見它了……那隱藏在深淵之下的無目之瞳，那宇宙的終級圖景……請再等等，守密人，我們就快完成它了！"
  },
  Voice_100362_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_100362_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_100363_AwakerVoiceContent = {
    Text = "我的畫筆，用我的脛骨製成。顏料盤，這些顏色是我在二十個城市的墓地裡搜集而來……還有我珍貴的皮質畫布！守密人，請拿上這些，為我畫上一幅肖像畫吧！不不不，這不需要您有什麼繪畫的技巧……我相信，當這種心靈上的無間共鳴呈現在畫布上，一定會是我從未想像過的、至美的畫作……！"
  },
  Voice_100363_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_100363_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_100364_AwakerVoiceContent = {
    Text = "我即光影，我即色彩，我……即繪畫本身！"
  },
  Voice_100364_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_100365_AwakerVoiceContent = {
    Text = "試試這顏色！"
  },
  Voice_100365_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_100366_AwakerVoiceContent = {
    Text = "藝術的本質，即是瘋狂……！"
  },
  Voice_100366_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_100367_AwakerVoiceContent = {
    Text = "您的意思是，下次可以在畫作中嘗試對這個部位進行特寫嗎？嗯……我竟然沒有想過！真是一個天才的思路！"
  },
  Voice_100367_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_100368_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_100369_AwakerVoiceContent = {
    Text = "藝術的本質，即是瘋狂……！"
  },
  Voice_100369_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_100370_AwakerVoiceContent = {
    Text = "我的調色盤！"
  },
  Voice_100370_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_100371_AwakerVoiceContent = {
    Text = "噢！這流暢的頜骨，明亮的眼睛，完美的身形，還有、還有這星空般浩瀚的精神世界……我是畫家皮克曼，能有幸邀請您，成為我的模特嗎？"
  },
  Voice_100371_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_100372_AwakerVoiceContent = {
    Text = "我信奉的藝術理念是瘋狂、躁動不安的，哈姆林的音樂完全不一樣，嚴謹得像是那些死氣沉沉的公墓墓碑。但不知道為什麼，我總能在那些整齊的音符裡，看到宇宙深處最強烈的混亂……"
  },
  Voice_100372_AwakerVoiceTitle = {
    Text = "閒話：關於哈姆林"
  },
  Voice_100372_UnlockDesc = {
    Text = "獲得喚醒體「哈姆林」後解鎖"
  },
  Voice_100373_AwakerVoiceContent = {
    Text = "看吶，守密人！畫布上那永恆的、瘋狂的景象，多麼動人心魄，多麼令人絕望！在這終極的瘋狂與痛苦中所盛開出的，才是藝術啊……"
  },
  Voice_100373_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_100373_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_100374_AwakerVoiceContent = {
    Text = "啊！抱、抱歉，守密人……我在你的身上看到了前所未有的景象……比深淵更可怖，比深淵更迷人……"
  },
  Voice_100374_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_100374_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_100375_AwakerVoiceContent = {
    Text = "真不明白，人類要是有機會，為什麼不去做一個食屍鬼？這種鮮血淋漓的瘋狂的美感，難道不比在大宅子裡做一個毫無激情的人類有意思得多嗎？！"
  },
  Voice_100375_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_100376_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_116964_AwakerVoiceContent = {
    Text = "懲戒罪惡！"
  },
  Voice_116965_AwakerVoiceContent = {
    Text = "懲戒罪惡！"
  },
  Voice_117791_AwakerVoiceContent = {
    Text = "我承認她偷東西的本事有幾分厲害，但淑女還用不上這樣卑鄙的伎倆，我想要的東西，讓大家「自願」給我不就好了？"
  },
  Voice_117791_AwakerVoiceTitle = {
    Text = "閒話·關於詹金"
  },
  Voice_117791_UnlockDesc = {
    Text = "獲得喚醒體「詹金」後解鎖"
  },
  Voice_117792_AwakerVoiceContent = {
    Text = "哈哈哈，我的，我的，彌薩格所有糖果都是我的了！還等什麼，跟著本女巫走，馬上準備去征服整個倫蒂尼恩的糖果店吧！"
  },
  Voice_117792_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_117792_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_117793_AwakerVoiceContent = {
    Text = "不給？那本女巫可要動真格了！"
  },
  Voice_117793_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_117794_AwakerVoiceContent = {
    Text = "你說這些糖果的夾心是怎麼裝進去的，完全找不到縫隙或者針孔呀，真想讓發明這些糖果的人也去彌薩格的餐廳上班，每天都給本小姐發明一種新的甜點！"
  },
  Voice_117794_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_117796_AwakerVoiceContent = {
    Text = "之前總覺得糖果相比蛋糕來說太過簡陋、不夠優雅，現在看來，是我小瞧了這些五顏六色的塑料紙裡的小東西嘛。尤其是比起蛋糕，這些糖果的保質期可長多了，想囤多少都不怕壞掉，真想把整個屋子都堆滿！"
  },
  Voice_117796_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_117797_AwakerVoiceContent = {
    Text = "你找到了一種新的糖果？給我看看……什麼呀，這戒指糖長得也太好笑了，哪有雞蛋這麼大的鑽戒啊！等等，你你你送我戒指是什麼意思？給我說清楚啊！"
  },
  Voice_117797_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_117797_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_117798_AwakerVoiceContent = {
    Text = "聽說女巫的身邊通常都跟著一隻神秘的黑貓，選校園裡那只野貓實在太丟淑女的面子了，決定了，就讓你戴上貓耳朵頭箍，來充當我的小黑貓吧。"
  },
  Voice_117798_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_117798_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_117799_AwakerVoiceContent = {
    Text = "反抗是沒有用的。"
  },
  Voice_117800_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_117801_AwakerVoiceContent = {
    Text = "世界上真的有女巫嗎？她們一個人住在連人影都沒有的森林裡，誰給她們做飯、洗衣、準備甜點呢？要是連下午茶都吃不到，這樣的生活還有什麼意思，想想就要受不了了。"
  },
  Voice_117801_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_117801_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_117802_AwakerVoiceContent = {
    Text = "女巫來了！"
  },
  Voice_117802_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_117803_AwakerVoiceContent = {
    Text = "你手裡還有巧克力？很好，都給我吧。怎麼了？你的東西就是我的東西，這不是天經地義的嗎？"
  },
  Voice_117803_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_117803_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_117804_AwakerVoiceContent = {
    Text = "你問我最喜歡哪一種糖？讓我想想，榛仁酥糖的回味很香，焦糖巧克力也很好吃，夾心的草莓軟糖、葡萄軟糖口感很有意思，還有一種可以拉得很長很長的麥芽糖，顏色像蜂蜜一樣好看……不行，選不出來，每種糖都有每種糖的特色，反正南瓜籃子有的是，我全都要就好了！"
  },
  Voice_117804_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_117804_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_117805_AwakerVoiceContent = {
    Text = "我現在的人生目標是吃遍世界上所有的糖果，只要一想到世上還有那麼多種數不清的糖果在等著我，我就對每天起床這件事充滿了動力。你說蛋糕？蛋糕是我的另一個人生目標。"
  },
  Voice_117805_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_117805_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_117806_AwakerVoiceContent = {
    Text = "你別看他長得像小孩，實際上歲數大得早就能入土了，不要說糖果，就是任何活人喜歡的東西他也不會感興趣的。所以，要送給他的那份糖，不如通通送給我，我才是最不會辜負它們的人。"
  },
  Voice_117806_AwakerVoiceTitle = {
    Text = "閒話·關於圖魯"
  },
  Voice_117806_UnlockDesc = {
    Text = "獲得喚醒體「圖魯」後解鎖"
  },
  Voice_117807_AwakerVoiceContent = {
    Text = "我要是做女巫，一定要做住在豪華宮殿的女巫，宮殿裡要熱熱鬧鬧的，再找十個最好的廚師每天為我做不一樣的蛋糕和糖果……你說那種叫公主？怎麼了，我可以做個公主女巫嘛！"
  },
  Voice_117807_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_117807_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_117808_AwakerVoiceContent = {
    Text = "喂，趕緊給我多準備幾種牙膏來，沒有，我沒吃多少糖啊，我才沒有蛀牙，只是晚上睡覺的時候有一點點疼而已……"
  },
  Voice_117808_AwakerVoiceTitle = {
    Text = "閒話·關於糖果"
  },
  Voice_117809_AwakerVoiceContent = {
    Text = "雖然彌薩格餐廳的規矩經常令人不爽，但他們做甜點的手藝，唔……還勉強過得去吧。"
  },
  Voice_117809_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_117810_AwakerVoiceContent = {
    Text = "這個世界上就是存在那麼多黑漆漆的、令人噁心的地方，有時間擔憂世界毀滅，不如在那之前多吃幾塊糖。"
  },
  Voice_117810_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_117811_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_117812_AwakerVoiceContent = {
    Text = "雖然現在沒有了那些羊羔絨地毯、遠洋黑珍珠項鍊、東方綢緞睡衣，但每天能在堆滿了糖的房間裡醒來，一伸手就能摸到滿滿當當的南瓜籃子，這樣的生活，或許才是幸福該有的樣子吧……喂，不許笑得那麼得意，要一直一直侍奉本小姐，你還要繼續努力呢！"
  },
  Voice_117812_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_117812_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_117813_AwakerVoiceContent = {
    Text = "可惡的彌薩格，竟敢阻攔我拿糖果，怎麼樣，還不是被我吃到了？"
  },
  Voice_117813_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_117814_AwakerVoiceContent = {
    Text = "幹什麼？想吃我的糖嗎？哼哼，也不是不能大發慈悲地賞賜給你，來，叫一聲女巫大人聽聽！"
  },
  Voice_117814_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_117815_AwakerVoiceContent = {
    Text = "這怎麼能叫強盜呢？我只不過在行使淑女尊貴的權力。"
  },
  Voice_117815_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_117816_AwakerVoiceContent = {
    Text = "正義的糖果女巫來了，所有失落的糖果，都該回到它們應有的歸處！"
  },
  Voice_117816_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_117817_AwakerVoiceContent = {
    Text = "可惡，小氣的傢伙，女巫會記住你的……"
  },
  Voice_117817_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_117818_AwakerVoiceContent = {
    Text = "憑什麼那只小耗子能大搖大擺地搜刮糖果，我卻不能？你們這是對淑女的針對！不敬！"
  },
  Voice_117818_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_117819_AwakerVoiceContent = {
    Text = "不給？那本女巫可要動真格了！"
  },
  Voice_117819_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_117820_AwakerVoiceContent = {
    Text = "請你吃糖！"
  },
  Voice_117820_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_117821_AwakerVoiceContent = {
    Text = "跟那些餐廳的侍者比，還是你最善解人意了，知道為我特地準備一份糖，要再接再厲哦，我的專屬僕人。"
  },
  Voice_117821_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_117821_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_117822_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_117823_AwakerVoiceContent = {Text = "過分！"},
  Voice_117823_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_117824_AwakerVoiceContent = {
    Text = "攔著我幹嘛？作為本小姐忠實的僕從，你不應該主動幫本小姐把糖果通通搶……拿來嗎？"
  },
  Voice_117824_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_117825_AwakerVoiceContent = {
    Text = "站住，打劫！我勸你最好識相一點，乖乖把所有糖果都交出來，否則，哼哼……"
  },
  Voice_117825_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_117826_AwakerVoiceContent = {
    Text = "軟的、硬的、脆的、酥的、奶味的、果味的、堅果味的、巧克力味的……啊，世界上怎麼會有這麼多種我沒吃過的糖果？決定了，向彌薩格提議每週過一次諸聖節吧！"
  },
  Voice_117826_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_117827_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_117828_AwakerVoiceContent = {
    Text = "偉大的女巫必將勝利！糖果之神庇佑著我，而我，庇佑著所有糖果！啊哈哈哈哈！"
  },
  Voice_117828_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_117829_AwakerVoiceContent = {
    Text = "反抗是沒有用的。"
  },
  Voice_117830_AwakerVoiceContent = {
    Text = "一切糖果終將屬於我！"
  },
  Voice_117830_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_117831_AwakerVoiceContent = {
    Text = "那個孩子聽話得有點嚇人了，只要你向她要糖，她就會給，甚至自己一顆也沒留下，讓人還怪不好意思的……咳咳，我是說，既然她這麼識趣，仁慈的女巫當然會給她留下一些作為賞賜啦。"
  },
  Voice_117831_AwakerVoiceTitle = {
    Text = "閒話·關於莉莉"
  },
  Voice_117831_UnlockDesc = {
    Text = "獲得喚醒體「莉莉」後解鎖"
  },
  Voice_117833_AwakerVoiceContent = {
    Text = "我生氣了！"
  },
  Voice_117833_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_117834_AwakerVoiceContent = {
    Text = "一切糖果終將屬於我！"
  },
  Voice_117834_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_117835_AwakerVoiceContent = {
    Text = "你說什麼，這種棉花糖還可以烤著吃？咦，熱乎乎、黏唧唧的能好吃嗎？讓我嚐嚐？好吧，那我就勉為其難地嘗一口，你要是敢耍我……嗯？！這個酥酥軟軟的口感，好好吃啊！"
  },
  Voice_117835_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_117835_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_122115_AwakerVoiceContent = {
    Text = "虛妄，倒錯，都是命運！"
  },
  Voice_122115_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_122117_AwakerVoiceContent = {
    Text = "虛妄，倒錯，都是命運！"
  },
  Voice_122117_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_123312_AwakerVoiceContent = {
    Text = "因為直面過真正的恐怖，所以不會害怕真實的我？哼，真是狡猾的回答，卻也讓我對你……越來越好奇了。"
  },
  Voice_123312_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_123312_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_123313_AwakerVoiceContent = {
    Text = "你眼中的世界是怎樣的？那些恐怖的極限又在哪裡？不，我不想聽你講述，我想和你一起去感受，感受那些瘋狂、死亡、恐怖。我決定了！在滿足好奇前，我才不會離開你。"
  },
  Voice_123313_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_123313_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_123314_AwakerVoiceContent = {
    Text = "不受控的瘋子？你說得沒錯。這裡可不是我的世界，沒有那些無聊的法律和規矩……在這裡，我想做什麼就做什麼，所以守密人，你可要小心了，千萬別被失控的瘋子咬了。"
  },
  Voice_123314_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_123314_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_123315_AwakerVoiceContent = {
    Text = "為了我的身心健康，想要進行深度談話？好吧，讓我們快點開始，這種無聊的事情，早開始早結束。"
  },
  Voice_123315_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_123315_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_123316_AwakerVoiceContent = {
    Text = "我只是在偽裝正常人回答你的問題？啊，還是被你發現了——那麼，你做好看見我真實面目的準備了嗎？"
  },
  Voice_123316_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_123316_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_123770_AwakerVoiceContent = {
    Text = "砍你腦殼。"
  },
  Voice_123770_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_123771_AwakerVoiceContent = {
    Text = "男女老少都愛看的！閃耀☆龍捲風——！！"
  },
  Voice_123771_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_123772_AwakerVoiceContent = {
    Text = "該倒下的不是我……"
  },
  Voice_123772_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_123773_AwakerVoiceContent = {
    Text = "風暴衝擊！"
  },
  Voice_123774_AwakerVoiceContent = {
    Text = "你想拯救這個扭曲恐怖的世界？真是個瘋狂又有趣的死法——就讓我看看你能走多遠。"
  },
  Voice_123774_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_123775_AwakerVoiceContent = {
    Text = "小寶貝們，想嚐嚐我的斧頭嗎？別著急，這就來了……"
  },
  Voice_123775_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_123776_AwakerVoiceContent = {
    Text = "守密人，我好像看到光了，難道說這次……不知道調查團的同事都怎麼樣了？千萬不要留一大堆工作給我，我可不想加班。"
  },
  Voice_123776_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_123776_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_123777_AwakerVoiceContent = {
    Text = "通過這個儀式我就能回家？你確定？這已經是第幾次嘗試了……好吧，反正試試又沒什麼壞處。"
  },
  Voice_123777_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_123777_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_123778_AwakerVoiceContent = {
    Text = "哈哈，果然比起無聊的日常，還是這種腎上腺素飆升的生活更適合我！"
  },
  Voice_123778_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_123779_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_123780_AwakerVoiceContent = {
    Text = "該倒下的不是我……"
  },
  Voice_123780_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_123781_AwakerVoiceContent = {
    Text = "閃耀☆超新星——放射！"
  },
  Voice_123782_AwakerVoiceContent = {
    Text = "男女老少都愛看的！閃耀☆龍捲風——！！"
  },
  Voice_123782_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_123783_AwakerVoiceContent = {
    Text = "現在的感覺……就像進入了霧裡。說起霧，我又想起了那些霧裡的小傢伙們。真可惜，心情不爽時不能再找它們發洩了。"
  },
  Voice_123783_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_123783_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_123784_AwakerVoiceContent = {
    Text = "討厭？我可不會這麼說，我只是真心希望那些乏味的會議、社交還有普世價值全部消失而已。"
  },
  Voice_123784_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_123785_AwakerVoiceContent = {
    Text = "就是這樣……我能感覺到，我離「真實的自己」越來越近了。"
  },
  Voice_123785_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_123786_AwakerVoiceContent = {
    Text = "啊，意料之中的失敗。人生就是這樣起起落落落落落，習慣就好了……不過，還是感謝你這次的嘗試。"
  },
  Voice_123786_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_123786_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_123787_AwakerVoiceContent = {
    Text = "就像霧災，我對於融蝕也一無所知。這正是它們令人著迷的地方，不是嗎？"
  },
  Voice_123787_AwakerVoiceTitle = {
    Text = "閒話·關於危機"
  },
  Voice_123788_AwakerVoiceContent = {
    Text = "茉夏，調查團……哦不，現在已經不是調查團前鋒了。那麼，我再重新介紹一下自己——我叫茉夏，只是一個可愛的女孩子~"
  },
  Voice_123788_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_123789_AwakerVoiceContent = {Text = "滾開！"},
  Voice_123789_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_123790_AwakerVoiceContent = {
    Text = "這裡離人類的聚居地太近了，到處都是無聊的大人……有沒有想過將學校搬到無人的深山老林裡？"
  },
  Voice_123790_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格"
  },
  Voice_123791_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_123792_AwakerVoiceContent = {
    Text = "我都要愛上這種在異世界漂泊的感覺了，強大的喚醒體、恐怖的融蝕還有未知的神祇！啊，一切都是遠離平凡社會的舒暢！"
  },
  Voice_123792_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_123793_AwakerVoiceContent = {
    Text = "還有嗎？我玩得正高興呢——快，誰讓我再砍一斧頭。"
  },
  Voice_123793_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_123794_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_123795_AwakerVoiceContent = {
    Text = "一次失敗並不能代表什麼……才怪。你們都洗乾淨脖子等著我！"
  },
  Voice_123795_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_123796_AwakerVoiceContent = {
    Text = "有任務？下次不用打招呼，我們已經熟到不需要表演「社交見面流程」了。"
  },
  Voice_123796_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_123797_AwakerVoiceContent = {
    Text = "為了別人而犧牲自己，真是愚蠢又令人生氣的想法。沒有誰可以這樣要求別人，就算是神也不行。"
  },
  Voice_123797_AwakerVoiceTitle = {
    Text = "閒話：關於薩爾瓦多"
  },
  Voice_123797_UnlockDesc = {
    Text = "獲得喚醒體「薩爾瓦多」後解鎖"
  },
  Voice_123798_AwakerVoiceContent = {
    Text = "不賴嘛——"
  },
  Voice_123798_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_123799_AwakerVoiceContent = {
    Text = "終於不用再偽裝了……接下來，讓我們好好玩玩。"
  },
  Voice_123799_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_123800_AwakerVoiceContent = {
    Text = "儀式還沒有結束嗎？真想趕緊回去吃瑞文羅格燉魚、熱騰騰的榛果卡瓦茶，當然，這裡的錫蘭島紅茶、安達盧西亞吉事果也不錯。"
  },
  Voice_123800_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_123800_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_123801_AwakerVoiceContent = {
    Text = "一直提升我的能力，你就不怕我有天會失控嗎……哈哈，開玩笑的。"
  },
  Voice_123801_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_123802_AwakerVoiceContent = {
    Text = "其實暫時留在這個世界也不錯。我會將這裡發生的一切都牢牢記住，寫下來，等到回去分享給那邊的大家。嗯，名字就叫「茉夏的異世界冒險記」，聽起來很棒吧？"
  },
  Voice_123802_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_123802_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_123803_AwakerVoiceContent = {
    Text = "我承認她很可愛……嗯，沒錯，看她和那些流浪在校園裡的野貓追逐、打架確實挺可愛的。"
  },
  Voice_123803_AwakerVoiceTitle = {
    Text = "閒話：關於墨菲"
  },
  Voice_123803_UnlockDesc = {
    Text = "獲得喚醒體「墨菲」後解鎖"
  },
  Voice_123804_AwakerVoiceContent = {
    Text = "雖然這些力量無法讓我回到自己的世界，但變強總是好的。"
  },
  Voice_123804_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_123805_AwakerVoiceContent = {
    Text = "女僕啊，我也做過，找個時間給她看看我開發的、使用吸塵器戰鬥的辦法！"
  },
  Voice_123805_AwakerVoiceTitle = {
    Text = "閒話：關於珈倫"
  },
  Voice_123805_UnlockDesc = {
    Text = "獲得喚醒體「珈倫」後解鎖"
  },
  Voice_123806_AwakerVoiceContent = {
    Text = "哈哈，果然比起無聊的日常，還是這種腎上腺素飆升的生活更適合我！"
  },
  Voice_123806_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_124737_AwakerVoiceContent = {
    Text = "一擊斃命。"
  },
  Voice_124738_AwakerVoiceContent = {
    Text = "一個一個排好隊。"
  },
  Voice_124769_AwakerVoiceContent = {
    Text = "湮滅吧！"
  },
  Voice_126946_AwakerVoiceContent = {
    Text = "勿思勿擾，盲聽啞從，凡塵皆為負累！"
  },
  Voice_126946_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_126947_AwakerVoiceContent = {
    Text = "勿思勿擾，盲聽啞從，凡塵皆為負累！"
  },
  Voice_126947_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_126948_AwakerVoiceContent = {
    Text = "您問祂們為何顱內空空？唔，許是生來如此。"
  },
  Voice_126948_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_126949_AwakerVoiceContent = {
    Text = "休怒休怨，萬事成空。"
  },
  Voice_126949_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_126950_AwakerVoiceContent = {
    Text = "如此殷勤，會讓妾身忍不住更想逗弄您。"
  },
  Voice_126950_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_126951_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_126952_AwakerVoiceContent = {
    Text = "您在期待妾身更美貌，還是更可怖？"
  },
  Voice_126952_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_126953_AwakerVoiceContent = {
    Text = "那位從愉悅中誕生的公主，她的裙袍繡著金線，皮膚宛如象牙，沉香在她周身浮動，眼波流轉間便讓人神魂顛倒。"
  },
  Voice_126953_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_126953_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_126954_AwakerVoiceContent = {
    Text = "很快她就厭倦了這種玩樂，她的信徒們只是不斷地重複著同樣的戲碼，沉迷生於欲的愛，或生於愛的欲，因為失去和背叛痛不欲生，他們的愚蠢讓她厭倦，她們的眼淚也讓她厭倦。"
  },
  Voice_126954_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_126954_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_126955_AwakerVoiceContent = {
    Text = "爾等宵小的目光，真讓妾身生厭。"
  },
  Voice_126955_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_126956_AwakerVoiceContent = {
    Text = "那位紅夫人，曾給妾身發過幾回沙龍請柬。\n異邦糕點的滋味還不錯，不過……\n她該早些告訴妾身，在她的宅邸裡，點心和侍從不是一個意思的。"
  },
  Voice_126956_AwakerVoiceTitle = {
    Text = "閒話：關於索蕾爾"
  },
  Voice_126956_UnlockDesc = {
    Text = "獲得喚醒體「索蕾爾」後解鎖"
  },
  Voice_126958_AwakerVoiceContent = {
    Text = "不是愛嗎、那被包圍時為何畏懼呢？不是厭棄嗎、當永不可回時為何潸然淚下呢？\n呀、現在您害怕妾身的影子了嗎、白玉蘭的香氣、已經變成您無法理解的甜膩腥膻了嗎？"
  },
  Voice_126958_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_126958_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_126959_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_126960_AwakerVoiceContent = {
    Text = "咦？您問我為什麼她們會在腋下紋上那種紋路？難道您不覺得非常好玩嗎？"
  },
  Voice_126960_AwakerVoiceTitle = {
    Text = "閒話：關於臃容眾"
  },
  Voice_126961_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_126963_AwakerVoiceContent = {
    Text = "比起信徒的進奉，這些倒更合妾身心意。"
  },
  Voice_126963_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_126964_AwakerVoiceContent = {
    Text = "先是儀態，再是身形，直到祂們同樣擁有了一雙……或者說能讓人記住的只剩下一雙美麗的、勾魂攝魄的眼睛——與妾身一樣的眼睛。"
  },
  Voice_126964_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_126964_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_126965_AwakerVoiceContent = {
    Text = "妾身今日實在無聊透了，您沒有什麼願望需要實現嗎？\n太遺憾了，僅僅為了一些無聊的目的，就有很多人願意揮起鐮刀，為妾身奉上血食。\n但如果是您的話……"
  },
  Voice_126965_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_126965_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_126966_AwakerVoiceContent = {
    Text = "臃容眾為何追隨在妾身身邊，又因何組建？有趣的問題，您也有過什麼求而不得之人，力所不逮之悔嗎？\n\n唔，看上去似乎沒有，好可惜。\n\n那種在絕境中掙扎的表情，若是出現在您臉上，一定非常~非常有意思。"
  },
  Voice_126966_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_126966_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_126967_AwakerVoiceContent = {
    Text = "……您若再如此僭越，妾身用以面對您的，就不一定是此番姿態了呢。"
  },
  Voice_126967_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_126968_AwakerVoiceContent = {
    Text = "她的故事，妾身已快遺忘殆盡了，但那是一個關於歡欣的故事，一個關於殘忍的故事，一個一開始關於拋棄和報應，後來關於犧牲和盲從的故事。"
  },
  Voice_126968_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_126968_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_126969_AwakerVoiceContent = {
    Text = "取悅妾身，在痛和懼中自相殘殺吧~"
  },
  Voice_126970_AwakerVoiceContent = {
    Text = "……這倒是讓妾身生出些許興致來了。"
  },
  Voice_126970_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_126971_AwakerVoiceContent = {
    Text = "每個人都會在妾身的扇下，看到自己最愛之人的面目。妾身把這種力量借予弱者，成為利刃，以此取樂。\n但或許，妾身只是說，或許。\n若您願因此著迷，妾身會感受到真正的，無上的狂喜。"
  },
  Voice_126971_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_126971_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_126972_AwakerVoiceContent = {
    Text = "不用擔心，您與祂們那些庸人不同。\n噓，別去看妾身的身後，別在意無形的觸摸——看著妾身的眼睛。"
  },
  Voice_126972_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_126972_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_126973_AwakerVoiceContent = {
    Text = "*輕笑 爾等可敢直視吾之真容？"
  },
  Voice_126973_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_126975_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_126976_AwakerVoiceContent = {
    Text = "怎麼？又在盯著妾身的扇子，入迷了？\n呵呵，無論您想在扇下看見誰的容顏，妾身都會滿足您……來，再靠近些——\n誒，不要？說著這麼冷漠的話，表情卻很可愛……"
  },
  Voice_126976_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_126976_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_126977_AwakerVoiceContent = {
    Text = "您來不夢鄉，想要找尋什麼呢？"
  },
  Voice_126978_AwakerVoiceContent = {
    Text = "休怒休怨，萬事成空。"
  },
  Voice_126978_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_126979_AwakerVoiceContent = {
    Text = "不可無禮。"
  },
  Voice_126979_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_126980_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_126981_AwakerVoiceContent = {
    Text = "妾身也有過這麼一個漂亮的、唯唯諾諾的小姑娘。\n惹眼的花骨朵，當然要給她加上一些尖刺，可不能插進花瓶裡。"
  },
  Voice_126981_AwakerVoiceTitle = {
    Text = "閒話：關於莉莉"
  },
  Voice_126981_UnlockDesc = {
    Text = "獲得喚醒體「莉莉」後解鎖"
  },
  Voice_126982_AwakerVoiceContent = {
    Text = "學院堅決拒絕了妾身去心理諮詢室任職的申請，真奇怪啊，到底有何不妥？"
  },
  Voice_126982_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格"
  },
  Voice_126983_AwakerVoiceContent = {
    Text = "一切終會歸於虛無，何不多與妾身尋些樂子？\n請放心，若您有一日無法抵抗，妾身不會讓祂先奪走您。"
  },
  Voice_126983_AwakerVoiceTitle = {
    Text = "閒話·關於危機"
  },
  Voice_126984_AwakerVoiceContent = {Text = "無趣。"},
  Voice_126984_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_126985_AwakerVoiceContent = {
    Text = "您真是個妙人，在註定要滅亡的世界裡，竟為這麼多身外之事忙碌著。\n令妾身也忍不住生出興致了。"
  },
  Voice_126985_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_126985_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_126986_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_126988_AwakerVoiceContent = {
    Text = "妾身乃不夢鄉之主，徐。 若您心中，有想見卻不得見之人，妾身願摘扇，予君一觀。"
  },
  Voice_126988_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_127088_AwakerVoiceContent = {
    Text = "所有生物的幼崽都很麻煩。\n小，軟，吵，無意間便將周身事物支配得團團轉。妾身喜歡熱鬧，卻屬實不喜歡這種熱鬧，望您千萬讓它們離遠些。"
  },
  Voice_127088_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_127089_AwakerVoiceContent = {
    Text = "妾身的小茉莉花，妾身的乖寶貝，妾身甘之如飴置身其中的家家酒~\n啊，一些心情好的胡言亂語，您不必掛心。"
  },
  Voice_127089_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_127090_AwakerVoiceContent = {
    Text = "在磐龍國的傳說中，孔雀是種美麗招搖的兇獸。\n美麗又惡毒，聽上去就讓人心悸，若是醜陋而善良，則有些乏味了。"
  },
  Voice_127090_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_129651_AwakerVoiceContent = {
    Text = "吃掉吃掉、全部吃掉"
  },
  Voice_129651_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_129652_AwakerVoiceContent = {
    Text = "咕嚕咕嚕～"
  },
  Voice_129652_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_129653_AwakerVoiceContent = {
    Text = "小煤球、我、吃飯、一起？一起！"
  },
  Voice_129653_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_129653_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_129654_AwakerVoiceContent = {
    Text = "莫絲！非常強！"
  },
  Voice_129655_AwakerVoiceContent = {
    Text = "深淵！螺旋！毀滅！全部——變成漩渦吧！"
  },
  Voice_129655_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_129656_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_129657_AwakerVoiceContent = {
    Text = "碰我、不要！碰我、壞掉！"
  },
  Voice_129657_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_129657_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_129658_AwakerVoiceContent = {
    Text = "貝殼、亮閃閃！亮閃閃、好看、給你！"
  },
  Voice_129658_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_129658_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_129659_AwakerVoiceContent = {
    Text = "冷冰冰、可怕、莫絲、躲起來！"
  },
  Voice_129659_AwakerVoiceTitle = {
    Text = "閒話：關於朵爾"
  },
  Voice_129659_UnlockDesc = {
    Text = "獲得喚醒體「朵爾」後解鎖"
  },
  Voice_129660_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_129661_AwakerVoiceContent = {
    Text = "狩獵、可惡！壞掉！莫絲、打他們、壞掉！"
  },
  Voice_129661_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_129662_AwakerVoiceContent = {
    Text = "好好玩！下次！還要！"
  },
  Voice_129662_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_129662_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_129663_AwakerVoiceContent = {
    Text = "摸摸、好！莫絲、你、摸摸！"
  },
  Voice_129663_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_129664_AwakerVoiceContent = {
    Text = "不、不要！小煤球、莫絲、保護！"
  },
  Voice_129664_AwakerVoiceTitle = {
    Text = "閒話·關於危機"
  },
  Voice_129665_AwakerVoiceContent = {
    Text = "再來？再來！"
  },
  Voice_129665_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_129666_AwakerVoiceContent = {
    Text = "嘿嘿、莫絲、要玩！"
  },
  Voice_129666_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_129667_AwakerVoiceContent = {
    Text = "大浪來啦！"
  },
  Voice_129667_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_129668_AwakerVoiceContent = {Text = "丟！"},
  Voice_129668_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_129669_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_129670_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_129671_AwakerVoiceContent = {
    Text = "儀式？！帶我一起！"
  },
  Voice_129671_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_129671_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_129672_AwakerVoiceContent = {
    Text = "漩渦！力量！棒！"
  },
  Voice_129672_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_129672_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_129674_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_129675_AwakerVoiceContent = {
    Text = "呼啦呼啦～"
  },
  Voice_129675_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_129676_AwakerVoiceTitle = {
    Text = "閒話：關於戈利亞"
  },
  Voice_129676_UnlockDesc = {
    Text = "獲得喚醒體「戈利亞」後解鎖"
  },
  Voice_129677_AwakerVoiceContent = {
    Text = "找到好多、亮閃閃！"
  },
  Voice_129677_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_129677_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_129678_AwakerVoiceContent = {
    Text = "深淵！螺旋！毀滅！全部——變成漩渦吧！"
  },
  Voice_129678_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_129679_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_129680_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_129681_AwakerVoiceContent = {
    Text = "莫絲！非常強！"
  },
  Voice_129682_AwakerVoiceContent = {
    Text = "吃掉吃掉、全部吃掉"
  },
  Voice_129682_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_129683_AwakerVoiceContent = {
    Text = "鸚鵡螺、諾締拉、小煤球！閃亮晶晶！"
  },
  Voice_129683_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_129684_AwakerVoiceContent = {
    Text = "莫絲、裝彈！"
  },
  Voice_129684_AwakerVoiceTitle = {
    Text = "技能·二·裝填一"
  },
  Voice_129685_AwakerVoiceContent = {
    Text = "莫絲、衝走！"
  },
  Voice_129685_AwakerVoiceTitle = {
    Text = "技能·二·裝填二"
  },
  Voice_129686_AwakerVoiceContent = {
    Text = "擁抱！莫絲！喜歡！"
  },
  Voice_129686_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_129686_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_129687_AwakerVoiceContent = {
    Text = "小煤球、朋友！莫絲、永遠！"
  },
  Voice_129687_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_129688_AwakerVoiceContent = {
    Text = "快點、快點！"
  },
  Voice_129688_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_129688_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_129689_AwakerVoiceContent = {
    Text = "莫絲！小煤球！一起、一直接下去？永遠！"
  },
  Voice_129689_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_129689_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_129690_AwakerVoiceContent = {
    Text = "呼呀呼呀~大浪掀起來！"
  },
  Voice_129690_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_129690_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_129691_AwakerVoiceContent = {
    Text = "朋友！好多！喜歡！"
  },
  Voice_129691_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格"
  },
  Voice_129692_AwakerVoiceContent = {
    Text = "莫絲！厲害！"
  },
  Voice_129692_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_129693_AwakerVoiceContent = {
    Text = "諾締拉、想見。欸、諾締拉、莫絲、莫絲！"
  },
  Voice_129693_AwakerVoiceTitle = {
    Text = "閒話：關於諾締拉"
  },
  Voice_129693_UnlockDesc = {
    Text = "獲得喚醒體「諾締拉」後解鎖"
  },
  Voice_129694_AwakerVoiceContent = {
    Text = "變強了！"
  },
  Voice_129694_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_129695_AwakerVoiceContent = {
    Text = "我！莫絲！你好！"
  },
  Voice_129695_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_130511_AwakerVoiceTitle = {
    Text = "技能·二·裝填三"
  },
  Voice_133720_AwakerVoiceContent = {
    Text = "錯誤將被修正。"
  },
  Voice_133720_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_133721_AwakerVoiceContent = {
    Text = "您所見的悲劇，不過是萬千可能性的其中一瞥。掀開命運的帷幕，我看到了那片漆黑的舞台。燈滅，人散，萬象歸於混沌之淵。然而……一切並非終局。我的意志尚在，足以支撐這徒勞的苦役，等待下一束輝光點燃。"
  },
  Voice_133721_AwakerVoiceTitle = {
    Text = "閒話·關於危機"
  },
  Voice_133722_AwakerVoiceContent = {
    Text = "世人的命運皆由絲線牽引……可是您的命運，是我無法讀懂的劇本。我期待著，您會為這個世界帶來怎樣精彩的即興表演？"
  },
  Voice_133722_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_133723_AwakerVoiceContent = {
    Text = "主演的木偶，登上屬於你的舞台吧。"
  },
  Voice_133724_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_133725_AwakerVoiceContent = {
    Text = "凡是過往，皆為序章。你我的新篇，正等待著您的書寫，守密人。"
  },
  Voice_133725_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_133725_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_133726_AwakerVoiceContent = {
    Text = "若您鍾情於喜劇，《仲夏夜之夢》是不錯的選擇。我尤愛迫克那些狡黠的譫語，精靈的嬉笑間，總藏著命運不經意洩露的密語。"
  },
  Voice_133726_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_133726_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_133727_AwakerVoiceContent = {
    Text = "依從於此。"
  },
  Voice_133727_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_133728_AwakerVoiceContent = {
    Text = "紡輪，於此轉動。"
  },
  Voice_133729_AwakerVoiceContent = {
    Text = "命運悲哀的囚徒啊，受領你命定的判決吧。"
  },
  Voice_133729_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_133730_AwakerVoiceContent = {
    Text = "縱是洞悉萬象的觀者，亦不過是自身劇本中笨拙的伶人。執掌命運之網，卻終被紡線所縛，在這命定的處境裡，我們走在不同的道路上，但都從未放棄過那些徒勞的追尋。愚魯也好，痴妄也罷，我是這樣，她亦如是。"
  },
  Voice_133730_AwakerVoiceTitle = {
    Text = "閒話：關於塔薇"
  },
  Voice_133730_UnlockDesc = {
    Text = "獲得喚醒體「塔薇」後解鎖"
  },
  Voice_133731_AwakerVoiceContent = {
    Text = "意外的轉折？"
  },
  Voice_133731_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_133732_AwakerVoiceContent = {
    Text = "承蒙您一路相伴於幕起幕落之間。未來，我定不負所期，為您奉上更動人心魄的戲劇之夜。"
  },
  Voice_133732_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_133732_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_133733_AwakerVoiceContent = {
    Text = "如此有天賦的歌者，天賜的嗓音，清澈又灼熱，彷彿源自命運之聲……若能請來我的劇院，想必即使是最挑剔的觀眾也會感到驚喜。"
  },
  Voice_133733_AwakerVoiceTitle = {
    Text = "閒話：關於汀克特"
  },
  Voice_133733_UnlockDesc = {
    Text = "獲得喚醒體「汀克特」後解鎖"
  },
  Voice_133734_AwakerVoiceContent = {
    Text = "你與我，那兩根無法看清的命運絲線，早已緊緊相纏、無分彼此，編織成囚籠與道路。我無法看清囚籠的邊際，也無法看清道路的終點。這正是這段故事裡，最令人著迷的部分。"
  },
  Voice_133734_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_133734_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_133735_AwakerVoiceContent = {
    Text = "命運的絲線，已然垂下。"
  },
  Voice_133736_AwakerVoiceContent = {
    Text = "她常來我的劇院落座……可我知道，她並非為戲而來，而是藉這方舞台，映照自己的格調。然而那樣精湛的演技，若只作看客，未免可惜。它本該在聚光燈下綻放，而非隱於觀眾席的暗影之中。"
  },
  Voice_133736_AwakerVoiceTitle = {
    Text = "閒話：關於索蕾爾"
  },
  Voice_133736_UnlockDesc = {
    Text = "獲得喚醒體「索蕾爾」後解鎖"
  },
  Voice_133737_AwakerVoiceContent = {
    Text = "我曾聽過他的演奏，那美妙的旋律，讓人靈魂震顫……或許，該邀請他為我的新戲譜一曲命運的交響？"
  },
  Voice_133737_AwakerVoiceTitle = {
    Text = "閒話：關於哈姆林"
  },
  Voice_133737_UnlockDesc = {
    Text = "獲得喚醒體「哈姆林」後解鎖"
  },
  Voice_133738_AwakerVoiceContent = {
    Text = "又一段圓滿的故事，落下帷幕。"
  },
  Voice_133738_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_133739_AwakerVoiceContent = {
    Text = "無盡的命運之網，我已窺見全貌。"
  },
  Voice_133739_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_133740_AwakerVoiceContent = {
    Text = "如果您允許……我想為您編織一幕只屬於您和我的雙人劇。無需觀眾，不必彩排……我只是期待著，當您站在光下時，那根我無法看清的絲線，將有著怎樣令人驚嘆的躍動。"
  },
  Voice_133740_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_133740_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_133741_AwakerVoiceContent = {
    Text = "不幸的舞者啊，我目睹了她的舞步。那是一種迫近毀滅的美，每一轉旋都燃起綠色的焰火，試圖將命運之線燒毀，可惜終將被那些絲線割裂出最淒豔的圖景。若有機會，我願為她寫一齣獨屬於她的舞劇。"
  },
  Voice_133741_AwakerVoiceTitle = {
    Text = "閒話：關於莉茲"
  },
  Voice_133741_UnlockDesc = {
    Text = "獲得喚醒體「莉茲」後解鎖"
  },
  Voice_133742_AwakerVoiceContent = {
    Text = "於此編織，於此衡量，於此裁斷。"
  },
  Voice_133742_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_133743_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_133744_AwakerVoiceContent = {
    Text = "又一根絲線，清晰了。"
  },
  Voice_133744_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_133745_AwakerVoiceContent = {
    Text = "帷幕已為你敞開，命運的劇本靜待開啟。告訴我，您更願步入哪一重命定的軌跡？是悲慟的終局，抑或歡愉的序章？"
  },
  Voice_133745_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_133745_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_133746_AwakerVoiceContent = {
    Text = "我的確沉醉於這日復一日的紡織……在重複而靜謐的牽引中，預見萬千故事的始終，旁觀所有命運的落幕，恍若已超然於命運之外。然而，命運之網避無可避，僅作旁觀終究寂寥。於是，我步入劇院，在扮演之中，親嘗那些我親手紡出、卻未曾親歷的悲歡。"
  },
  Voice_133746_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_133747_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_133748_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_133749_AwakerVoiceContent = {
    Text = "於此編織，於此衡量，於此裁斷。"
  },
  Voice_133749_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_133750_AwakerVoiceContent = {
    Text = "命運的低語，更近了。"
  },
  Voice_133750_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_133751_AwakerVoiceContent = {
    Text = "劇院新排了一齣浪漫喜劇，我已在命運的席位上，為您留了一隅空座。我將在每個命運交織的長夜裡，靜候與你相逢的星光。"
  },
  Voice_133751_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_133751_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_133752_AwakerVoiceContent = {
    Text = "如此執著於撥動命運的紡線……您，也想要窺見屬於自己的篇章？"
  },
  Voice_133752_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_133753_AwakerVoiceContent = {
    Text = "未來已至。"
  },
  Voice_133754_AwakerVoiceContent = {
    Text = "若您願步入悲劇的殿堂，請容我為您呈上《安提戈涅》。於神律與塵世的對峙間，她每一步都踏在命運紡就的絲線上，直至踏入石墓深沉的陰影。正因這桎梏不可掙脫，她那渺小身軀裡迸發的意志，才如長夜中的孤焰般灼目。"
  },
  Voice_133754_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_133754_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_133755_AwakerVoiceContent = {
    Text = "從無定數的結局，逃不開因果的羅網……"
  },
  Voice_133755_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_133756_AwakerVoiceContent = {
    Text = "紡線之上，我窺見彩虹流轉萬端的光色——它勾連起無盡網羅，鋪展無垠世界，延展出無限之可能，最終織就世間最瑰麗斑斕的圖樣。無論神明或凡人，英雄或惡徒，都被那一道纖細的紡線操縱，在命運的注視下義無反顧地奔向屬於自己的結局。"
  },
  Voice_133756_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格"
  },
  Voice_133757_AwakerVoiceContent = {
    Text = "我本以為世間再無選擇能令我驚訝……您對戲劇的品味，讓我印象深刻。"
  },
  Voice_133757_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_133757_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_133758_AwakerVoiceContent = {
    Text = "命運的絲線總在暗處連接……您驚動了這根絲線，也驚動了我。"
  },
  Voice_133758_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_133758_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_133759_AwakerVoiceContent = {
    Text = "我始終不願看到一成不變的樣板戲。走進劇院的意義，本就在於親歷那無法被複刻的現場，若每一場都只是機械的重複，那舞台便成了精緻的牢籠，而觀劇，也淪為對已知結局的倦怠巡禮。那樣的演出，再華麗，也失去了靈魂。您是怎樣看待的呢？"
  },
  Voice_133759_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_133760_AwakerVoiceContent = {
    Text = "命運之線本在我掌心流轉有序……直到您的出現，讓它們的軌跡生出未曾預料的漣漪。"
  },
  Voice_133760_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_133760_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_133761_AwakerVoiceContent = {
    Text = "命運悲哀的囚徒啊，受領你命定的判決吧。"
  },
  Voice_133761_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_133762_AwakerVoiceContent = {
    Text = "我於無盡的絲縷間，紡織唯一的軌跡。"
  },
  Voice_133762_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_133763_AwakerVoiceContent = {
    Text = "命運的舞台之上，眾生在各自的因果中靜候登場，萬般悲歡在齒輪轉動間悄然成章……帷幕已啟，守密人，你我之間的故事，至此便要開始了。"
  },
  Voice_133763_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_133764_AwakerVoiceContent = {
    Text = "紛爭已至，您要扮演的，是破網的英雄，還是順命的配角？"
  },
  Voice_133764_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_133765_AwakerVoiceContent = {
    Text = "徒勞的反抗。"
  },
  Voice_133765_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_139865_AwakerVoiceContent = {
    Text = "謝謝。我會好好珍惜這份禮物的。"
  },
  Voice_139865_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_139866_AwakerVoiceContent = {
    Text = "關於喚醒體的構造學了很多，已經算得上是專家了哦。但銀芯中的「靈性」這種東西，還是有點搞不明白呢……"
  },
  Voice_139866_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_139866_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_139867_AwakerVoiceContent = {
    Text = "這就是，新世界的開始……"
  },
  Voice_139867_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_139868_AwakerVoiceContent = {
    Text = "我能做到那樣的事情哦。重組其他生物的身體啦、調整啦……"
  },
  Voice_139868_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_139868_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_139869_AwakerVoiceContent = {
    Text = "該怎麼調整哪裡，因生物種類不同而各有差異，所以不好好學習的話可不行哦。"
  },
  Voice_139869_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_139869_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_139870_AwakerVoiceContent = {
    Text = "不可怕嗎，我的樣子？誒，有點無聊呢……"
  },
  Voice_139870_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_139871_AwakerVoiceContent = {
    Text = "不會讓任何人妨礙我們的"
  },
  Voice_139872_AwakerVoiceContent = {
    Text = "我準備好了哦。"
  },
  Voice_139872_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_139873_AwakerVoiceContent = {
    Text = "生物真的是充滿多樣性呢。想了解更多！"
  },
  Voice_139873_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_139875_AwakerVoiceContent = {
    Text = "你要和沙耶一起玩嗎？"
  },
  Voice_139875_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_139876_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_139877_AwakerVoiceContent = {
    Text = "這就是，新世界的開始……"
  },
  Voice_139877_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_139878_AwakerVoiceContent = {
    Text = "吃飽了，多謝款待！"
  },
  Voice_139878_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_139880_AwakerVoiceContent = {
    Text = "守密人，你曾經愛過什麼人，思念過什麼人嗎？"
  },
  Voice_139880_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_139880_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_139881_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_139882_AwakerVoiceContent = {
    Text = "是這裡嗎？"
  },
  Voice_139883_AwakerVoiceContent = {
    Text = "辛苦了！有好的收穫嗎？"
  },
  Voice_139883_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_139884_AwakerVoiceContent = {
    Text = "做了各種驗證之後，大體弄明白了哦。每個喚醒體持有的「靈性」是完全不同的。然後，我的銀芯中的靈性似乎是「愛」呢。"
  },
  Voice_139884_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_139884_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_139885_AwakerVoiceContent = {
    Text = "怎麼樣，嚇了一跳吧？"
  },
  Voice_139885_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_139886_AwakerVoiceContent = {
    Text = "這是送給你的、最後的禮物。"
  },
  Voice_139886_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_139887_AwakerVoiceContent = {
    Text = "「在這些星星中的某一顆上，我的花正在綻放……」這樣說的呢。\n你好像也說過類似的話呢。"
  },
  Voice_139887_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_139887_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_139888_AwakerVoiceContent = {
    Text = "「銀芯」這種東西，似乎與非常遙遠的意志相連。真是不可思議呢……"
  },
  Voice_139888_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_139888_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_139889_AwakerVoiceContent = {
    Text = "這是送給你的、最後的禮物。"
  },
  Voice_139889_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_139891_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_139892_AwakerVoiceContent = {
    Text = "小王子說，是他對玫瑰的照料，讓玫瑰與眾不同……你也這麼覺得嗎？"
  },
  Voice_139892_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_139892_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_139893_AwakerVoiceContent = {
    Text = "昨天，我在莉莉的書櫃裡看到一本叫做《小王子》的書。我把它借來了。要來和我一起讀嗎？"
  },
  Voice_139893_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_139893_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_139895_AwakerVoiceContent = {
    Text = "嗯，也研究了銀芯的構造，對喚醒體的大致輪廓漸漸有了認識哦。"
  },
  Voice_139895_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_139895_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_139896_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_139899_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_139900_AwakerVoiceContent = {
    Text = "你好！……這樣說對嗎？\n我是沙耶。嗯……請多關照——"
  },
  Voice_139900_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_139901_AwakerVoiceContent = {
    Text = "有一種叫蒲公英的花，會讓種子乘著風漂流的。毛茸茸的種子被風帶著，離開故鄉好遠好遠，也許會落在沒有一棵草木的沙漠裡。那種時候，那一粒小小的種子會想些什麼呢……"
  },
  Voice_139901_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_139901_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_139902_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_139903_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_139906_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_140533_AwakerVoiceContent = {
    Text = "超喜歡美味的食物！也喜歡對沙耶溫柔的人。被溫柔對待的話，真的很開心呢——"
  },
  Voice_140533_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_140534_AwakerVoiceContent = {
    Text = "那是喚醒我的人嗎？總覺得好耀眼呢……嗯~那，你幫她找到姐姐了嗎？"
  },
  Voice_140534_AwakerVoiceTitle = {
    Text = "閒話：關於汀克特"
  },
  Voice_140534_UnlockDesc = {
    Text = "獲得喚醒體「汀克特」後解鎖"
  },
  Voice_140535_AwakerVoiceContent = {
    Text = "每當沙耶想要獨佔守密人的時候，就會有很多怪人圍上來的地方。還是更喜歡在密境裡的時候——"
  },
  Voice_140535_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格"
  },
  Voice_140536_AwakerVoiceContent = {
    Text = "原來如此。了解！"
  },
  Voice_140537_AwakerVoiceContent = {
    Text = "守密人、鏈接、喚醒體，是你告訴我的關係吧。能感覺到兩個人的靈魂鏈接在一起……通過銀色的絲？之類的，嗯——總覺得各種各樣都好難懂啊……"
  },
  Voice_140537_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_140538_AwakerVoiceContent = {
    Text = "用血肉運送種子？嗯~原來是這樣。對她的羊有點感興趣呢。"
  },
  Voice_140538_AwakerVoiceTitle = {
    Text = "閒話：關於泰旖絲"
  },
  Voice_140538_UnlockDesc = {
    Text = "獲得喚醒體「泰旖絲」後解鎖"
  },
  Voice_140539_AwakerVoiceContent = {
    Text = "威脅這個世界的某種危機，會導致存在消亡的黑暗，對吧？我知道的。從朵爾教授那裡聽到很多呢。"
  },
  Voice_140539_AwakerVoiceTitle = {
    Text = "閒話·關於危機"
  },
  Voice_140540_AwakerVoiceContent = {
    Text = "不喜歡粗暴的人。讓人覺得不舒服……"
  },
  Voice_140540_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_140541_AwakerVoiceContent = {
    Text = "她的種族，似乎也是靠掠奪其他種群來獲得在新星球繁衍的機會呢。嗯~原來是這樣……"
  },
  Voice_140541_AwakerVoiceTitle = {
    Text = "閒話：關於溫柯爾"
  },
  Voice_140541_UnlockDesc = {
    Text = "獲得喚醒體「溫柯爾」後解鎖"
  },
  Voice_141964_AwakerVoiceContent = {Text = "誒！"},
  Voice_141965_AwakerVoiceTitle = {
    Text = "受擊·五"
  },
  Voice_143501_AwakerVoiceContent = {
    Text = "太遺憾了，當你改變主意的時候，你知道該在哪裡找到我。"
  },
  Voice_143501_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_143501_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_143502_AwakerVoiceContent = {
    Text = "可惡……"
  },
  Voice_143502_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_143503_AwakerVoiceContent = {
    Text = "皮膚、肌肉、神經、骨骼，它們全部都會被重構，重新健康完好，重新煥發活力。"
  },
  Voice_143503_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_143503_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_143504_AwakerVoiceContent = {
    Text = "海洋面前，沒有不可摧毀的敵人！"
  },
  Voice_143504_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_143505_AwakerVoiceContent = {
    Text = "宴飲、追獵、庇護？\n向我祈禱，最古老的海水會告訴你我的名字。\n我乃深淵之主，龐托斯。"
  },
  Voice_143505_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_143506_AwakerVoiceContent = {
    Text = "呵呵，思念在厄波揚斯的時光嗎……\n它就在這具身體裡，隨時都歡迎著你回來。"
  },
  Voice_143506_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_143507_AwakerVoiceContent = {
    Text = "雖然我沒有那麼做，要是哪天你耳朵裡出現海水和翅膀的翕動聲，別擔心，是正常現象。"
  },
  Voice_143507_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_143508_AwakerVoiceContent = {
    Text = "獻出你的感官，永遠在深淵中反省！"
  },
  Voice_143509_AwakerVoiceContent = {
    Text = "我喜歡有活力的年輕人，可惜，彌薩格對狂歡的管制實在太嚴了，甚至都沒有一個像樣的狩獵場。\n而且，裡面還有那個膽敢公開招搖過市，甚至掛著教授頭銜的髒東西。"
  },
  Voice_143509_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格"
  },
  Voice_143510_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_143511_AwakerVoiceContent = {
    Text = "我做了這麼多，你甚至不願意再叫我一聲舅舅，真讓人頭疼啊。"
  },
  Voice_143511_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_143513_AwakerVoiceContent = {
    Text = "不用著急，海洋最深處的黑暗必將吞噬你們。"
  },
  Voice_143513_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_143514_AwakerVoiceContent = {
    Text = "跪下，成為厄波揚斯的養料。"
  },
  Voice_143515_AwakerVoiceContent = {
    Text = "至於選中我的這個存在……只能說既友善又惡劣。\n掉落在哪裡全隨心情，必然會救你脫離險境，至於那裡是不是另一個險境，就不是這次「旅程」需要考慮的事情了。\n多麼有意思，多麼難以預料，我在考慮延續這種傳統。"
  },
  Voice_143515_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_143515_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_143516_AwakerVoiceContent = {
    Text = "我跟厄波揚斯存在某種特殊的聯繫，不如說，我即是厄波揚斯，厄波揚斯維繫於我，藉由我的身體而存在。"
  },
  Voice_143516_AwakerVoiceTitle = {
    Text = "閒話：關於厄波揚斯"
  },
  Voice_143517_AwakerVoiceContent = {
    Text = "抬起頭，把你的喉嚨露出來。"
  },
  Voice_143518_AwakerVoiceContent = {
    Text = "抹除記憶，抹去存在。令人熟悉……你明白我的意思，雖然來源不同，但看來祂們總會從無光之處滋生。"
  },
  Voice_143518_AwakerVoiceTitle = {
    Text = "閒話·關於危機"
  },
  Voice_143519_AwakerVoiceContent = {
    Text = "你們不該蠢到侵探我的威嚴。"
  },
  Voice_143519_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_143520_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_143521_AwakerVoiceContent = {
    Text = "在厄波揚斯，狂歡永遠不會停止，厄波揚斯的敵人，也將永遠不得安寧。"
  },
  Voice_143521_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_143521_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_143522_AwakerVoiceContent = {
    Text = "啊，我對你的戰慄感同身受，但那全無必要，我年輕的朋友。\n接納你對平庸和被消磨的恐懼，看著我，你明白你總有另一種選擇。"
  },
  Voice_143522_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_143522_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_143523_AwakerVoiceContent = {
    Text = "沒錯，我知道那場災難不是他直接指使，只是取樂途中的偶然，但這顯然只會讓我更想殺了他。\n那團黑霧最好不要落單，也不要被我抓到。"
  },
  Voice_143523_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_143524_AwakerVoiceContent = {
    Text = "那些黏糊糊的魚人並非我的朋友，而是我的敵人。很意外嗎？海洋本來就不屬於他們。"
  },
  Voice_143524_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_143524_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_143525_AwakerVoiceContent = {
    Text = "亙久地，留滯於此！"
  },
  Voice_143525_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_143526_AwakerVoiceContent = {
    Text = "準備好了嗎，獵物們！"
  },
  Voice_143526_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_143527_AwakerVoiceContent = {
    Text = "靈性催生出新的軀體，軀體被填入無關緊要的智識，然後那些漂亮靈動的個體會永遠齊聚在一個地方。\n還記得我說的嗎，海洋的最深處容納一切……留下一切。"
  },
  Voice_143527_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_143527_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_143528_AwakerVoiceContent = {
    Text = "魇，擋住祂們。"
  },
  Voice_143528_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_143529_AwakerVoiceContent = {
    Text = "希望這些小東西不會把你吃窮，你知道，養一大家子的確不是容易事。"
  },
  Voice_143529_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_143530_AwakerVoiceContent = {
    Text = "在很久很久以前，陸地還未浮上海洋之前，這顆星球就蘇生了某些特殊的靈性。強大、威嚴、不可窺探。\n祂們無法被界定為敵意抑或友善，人類就像過往的無數生靈一樣，對祂們而言無關緊要，會像灰塵一樣被拭去，也會與領土一同被保護。"
  },
  Voice_143530_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_143530_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_143531_AwakerVoiceContent = {
    Text = "唯有衰老是你需要獨自面對的冒險、你最好的朋友和最難纏的敵人，厄波揚斯的燈光會把它驅逐殆盡……只是一些無關緊要的記憶，你不需要被它們錨定。"
  },
  Voice_143531_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_143531_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_143532_AwakerVoiceContent = {
    Text = "放棄逃脫的幻想吧。"
  },
  Voice_143533_AwakerVoiceContent = {
    Text = "你將化為灰白的齏粉。"
  },
  Voice_143533_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_143534_AwakerVoiceTitle = {Text = "打擊"},
  Voice_143535_AwakerVoiceContent = {
    Text = "很聰明的做法，小朋友，外來怪物的信徒總是笨到把屍體扔進海裡，那可不算是禮物，對吧？"
  },
  Voice_143535_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_143536_AwakerVoiceContent = {
    Text = "你已經被盯上了。"
  },
  Voice_143537_AwakerVoiceContent = {
    Text = "即使不願意承認，某些非常偶爾的偶爾，我會覺得衰老並非時間帶來的唯一一件東西，而只是一種象徵。\n所以，我允許它存在於我身上。當然——僅限外表。"
  },
  Voice_143537_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_143539_AwakerVoiceContent = {
    Text = "祈禱是有效的，想像一下，就算蟲子在你面前組成雷歐文字，你也會考慮一下回應蟲子的訴求。"
  },
  Voice_143539_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_143539_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_143540_AwakerVoiceContent = {
    Text = "哈哈哈哈，好了，不要這個表情，我的小朋友。\n那只是一些所謂「舊神祇」要遵循的傳統，至於你，不需要任何代價和條件，我會永遠站在你這邊。"
  },
  Voice_143540_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_143540_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_143554_AwakerVoiceContent = {
    Text = "哼，與外來怪物同流合污的小怪物。\n居然有蠢東西把我和他放在一個神壇上，簡直是侮辱！"
  },
  Voice_143554_AwakerVoiceTitle = {
    Text = "閒話：關於圖魯"
  },
  Voice_143554_UnlockDesc = {
    Text = "獲得喚醒體「圖魯」後解鎖"
  },
  Voice_143555_AwakerVoiceContent = {
    Text = "敵人的敵人就是朋友，如果有機會，我不介意做一樁搶走死對頭最喜歡的玩具的好買賣。"
  },
  Voice_143555_AwakerVoiceTitle = {
    Text = "閒話：關於萊克"
  },
  Voice_143555_UnlockDesc = {
    Text = "獲得喚醒體「萊克」後解鎖"
  },
  Voice_146158_AwakerVoiceContent = {
    Text = "哦？想在這裡和我動手？我不介意。"
  },
  Voice_146158_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_146159_AwakerVoiceContent = {
    Text = "更多，給我更多的力量！"
  },
  Voice_146159_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_146160_AwakerVoiceContent = {
    Text = "我不喜歡不純粹的人，因為不純粹通常意味著弱小。但你是一個例外。我曾經認為，一個背負了許多東西的人，無法走向更遠的前方。可你所走上的道路，即便是我也感到詫異……或許，一個行走在不同道路上的人，才是更值得培養和挑戰的對象。你說是吧，「對手」？"
  },
  Voice_146160_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_146161_AwakerVoiceContent = {
    Text = "星天的游鯨，將一切吞噬！"
  },
  Voice_146161_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_146162_AwakerVoiceContent = {
    Text = "為成為我的對手而感到榮幸吧！"
  },
  Voice_146163_AwakerVoiceContent = {
    Text = "讓星海，見證毀滅！"
  },
  Voice_146164_AwakerVoiceContent = {
    Text = "不夠，遠遠不夠……"
  },
  Voice_146164_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_146165_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_146166_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_146167_AwakerVoiceContent = {
    Text = "我不在意一切的消散，但我不會允許它成為我追尋力量之路上的阻礙。"
  },
  Voice_146167_AwakerVoiceTitle = {
    Text = "閒話·關於危機"
  },
  Voice_146168_AwakerVoiceContent = {
    Text = "因為注定要到來的湮滅，就開始質疑一切存在的意義……我沒有興趣參與這種小孩子的無聊爭辯。無所謂毀滅，也無需去銘記。力量本身，便是意義。"
  },
  Voice_146168_AwakerVoiceTitle = {
    Text = "閒話：關於熔毀·朵爾"
  },
  Voice_146168_UnlockDesc = {
    Text = "獲得喚醒體「熔燬·朵爾」後解鎖"
  },
  Voice_146169_AwakerVoiceContent = {
    Text = "在你的眼睛裡，我看到了不屬於這裡的意志。它並不純粹，但足夠堅韌。來吧，向我證明，你是依靠著怎樣的力量與渴望，站在我的面前。"
  },
  Voice_146169_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_146170_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_146171_AwakerVoiceContent = {
    Text = "為成為我的對手而感到榮幸吧！"
  },
  Voice_146172_AwakerVoiceContent = {
    Text = "混沌的氣息，久違了……從這片虛無中誕生的那一刻開始，我所追求之物，從未變化過。"
  },
  Voice_146172_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_146172_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_146173_AwakerVoiceContent = {
    Text = "想挑戰我？我欣賞你的勇氣，也願意給予你被打敗的榮幸。這是我對「彌薩格守密人」的尊重。"
  },
  Voice_146173_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_146173_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_146174_AwakerVoiceContent = {
    Text = "一個虛假的烏托邦裡，擠滿了一群弱者、膽小鬼與自欺欺人的蠢貨。但無所謂，這裡能帶給我最令人興奮的敵人，這就足夠了。"
  },
  Voice_146174_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格"
  },
  Voice_146175_AwakerVoiceContent = {
    Text = "明明擁有強大的力量，卻因為恐懼、愧疚與疲倦，將自己的才能困在漫長的夢境裡面，真是浪費。"
  },
  Voice_146175_AwakerVoiceTitle = {
    Text = "閒話：關於圖魯"
  },
  Voice_146175_UnlockDesc = {
    Text = "獲得喚醒體「圖魯」後解鎖"
  },
  Voice_146176_AwakerVoiceContent = {
    Text = "不堪一擊。"
  },
  Voice_146176_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_146177_AwakerVoiceContent = {
    Text = "封印鬆動了些……星海深處的力量正在上湧。我已經很久沒有感受過這種感覺了……"
  },
  Voice_146177_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_146177_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_146178_AwakerVoiceContent = {
    Text = "星天的游鯨，將一切吞噬！"
  },
  Voice_146178_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_146179_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_146180_AwakerVoiceContent = {
    Text = "我在星海間流浪了無數年，親手將那些自詡強大的存在送入深淵。你有著自己的特別之處，但若想與我並肩，就先學會在我面前昂起頭來。懦弱的同行者，我不需要。"
  },
  Voice_146180_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_146180_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_146181_AwakerVoiceContent = {
    Text = "勇敢的，懦弱的，堅強的，脆弱的……呵，不，我不在意對手是一個什麼樣的人。無論是什麼樣的一個有實力的對手，便能讓我感到愉悅。"
  },
  Voice_146181_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_146182_AwakerVoiceContent = {
    Text = "弱小。這個世上有無數令人作嘔的東西，弱小是最不堪的原罪。每個人都是帶著劍來到這個世界上，沒有人有資格在終點前鬆手，帶著失敗的念頭踏上注定的戰場。那是對對手，也是對自己的侮辱。"
  },
  Voice_146182_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_146183_AwakerVoiceContent = {
    Text = "腐化的星骸，甦醒吧——"
  },
  Voice_146183_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_146184_AwakerVoiceContent = {
    Text = "呵……令人興奮的對手。下次，我不會再留手了。"
  },
  Voice_146184_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_146185_AwakerVoiceContent = {
    Text = "我的骨骼正因歡欣而顫動……你付出的努力，我已見證。這是你有資格站在我身邊的證明，守密人。"
  },
  Voice_146185_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_146185_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_146186_AwakerVoiceContent = {
    Text = "呵……你看得很明白，守密人。力量的枷鎖，就是用來打碎的！"
  },
  Voice_146186_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_146186_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_146187_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_146188_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_146189_AwakerVoiceContent = {
    Text = "就在前方……我畢生所追尋的、那力量的終點……一路跟隨著我，將我引領至此的，是你。我很期待，與你一起見證終極的那一天！"
  },
  Voice_146189_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_146189_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_146190_AwakerVoiceContent = {
    Text = "也許我之前那些話有些太過輕率了……你成長的速度，還有你身上那些潛藏的力量，都有些出乎我的意料。我見過太多在時間中湮滅的生命，但你……的確不同尋常。我很想知道，你身上那些力量的秘密，究竟來自何處？"
  },
  Voice_146190_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_146190_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_146192_AwakerVoiceContent = {
    Text = "地獄之口，為我洞開！"
  },
  Voice_146192_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_146193_AwakerVoiceContent = {
    Text = "啊，我看見了……力量的終點，從未存在過……真正的挑戰，現在才向我敞開！是你將我帶到了這裡，讓我看清了一切。很快，我便會將一個更加完美的戰士，帶到你的面前。希望在那個時候，我也能看到一個更加完美的你，我的「對手」。"
  },
  Voice_146193_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_146193_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_146194_AwakerVoiceContent = {
    Text = "小把戲。"
  },
  Voice_146194_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_146195_AwakerVoiceContent = {
    Text = "力量在骨髓裡沸騰！"
  },
  Voice_146195_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_146196_AwakerVoiceContent = {
    Text = "吞噬殆盡！"
  },
  Voice_146196_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_146197_AwakerVoiceContent = {
    Text = "仁慈，軟弱，迷茫……你的眼裡裝滿了雜質。一個不夠純粹的人，永遠無法理解何為力量。"
  },
  Voice_146197_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_146197_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_146198_AwakerVoiceContent = {
    Text = "真正的力量，從來就與復仇、與守護無關。力量就只是力量，另一個我從未「真正」明白這個道理。這便是她不夠強大的根源。"
  },
  Voice_146198_AwakerVoiceTitle = {
    Text = "閒話：關於蘿坦"
  },
  Voice_146198_UnlockDesc = {
    Text = "獲得喚醒體「蘿坦」後解鎖"
  },
  Voice_146199_AwakerVoiceContent = {
    Text = "聽好了，我只說一次：\n我，蘿坦，認定你為值得等待的對手。\n在你抵達巔峰之前，我會成為你最值得信賴的劍。我的承諾與忠誠和情緒無關。你是最令我愉悅的對手，我絕不會讓你在路途中倒下。"
  },
  Voice_146199_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_146199_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_146200_AwakerVoiceContent = {
    Text = "來吧，殺死我，或者，被我殺死。"
  },
  Voice_146200_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_146201_AwakerVoiceContent = {
    Text = "地獄之口，為我洞開！"
  },
  Voice_146201_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_146521_AwakerVoiceContent = {
    Text = "骨刃所向，萬物崩解！"
  },
  Voice_147047_AwakerVoiceContent = {
    Text = "力量……永無盡頭！"
  },
  Voice_147493_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_147493_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_147494_AwakerVoiceContent = {
    Text = "（一段沙啞平緩的歌聲）"
  },
  Voice_147495_AwakerVoiceContent = {
    Text = "觀眾，需要更多觀眾……"
  },
  Voice_147495_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_147496_AwakerVoiceContent = {
    Text = "沙……白色的沙漠……這裡很危險，快和我一起離開。"
  },
  Voice_147496_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_147496_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_147497_AwakerVoiceContent = {
    Text = "我還記得新家園的地圖，都是彩色的，非常漂亮。這是我們應該去的地方。我們可以唱歌，我們可以得到幸福。"
  },
  Voice_147497_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_147498_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_147499_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_147499_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_147500_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_147501_AwakerVoiceContent = {
    Text = "那是……星穹之聲……"
  },
  Voice_147501_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_147502_AwakerVoiceContent = {
    Text = "你又來了啊。像過去一樣，坐在我身邊然後一起等待吧。等待什麼……？等待，就是等待啊。"
  },
  Voice_147502_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_147503_AwakerVoiceContent = {
    Text = "完美的彩排，我想我已經做好登臺準備了。"
  },
  Voice_147503_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_147503_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_147504_AwakerVoiceContent = {
    Text = "墜落吧。"
  },
  Voice_147504_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_147505_AwakerVoiceContent = {
    Text = "獻給荒蕪與死亡。"
  },
  Voice_147505_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_147506_AwakerVoiceContent = {
    Text = "我既不是瘋子，也從未感到悲傷。請勿聽信荒謬的謠言。"
  },
  Voice_147506_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_147507_AwakerVoiceContent = {
    Text = "奇怪，他們好像很懼怕我的歌聲……"
  },
  Voice_147507_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_147508_AwakerVoiceContent = {Text = "噓……"},
  Voice_147509_AwakerVoiceContent = {
    Text = "真是漂亮的演出服，亮閃閃，亮閃閃……"
  },
  Voice_147509_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_147509_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_147510_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_147511_AwakerVoiceContent = {
    Text = "殘存至今的群星之彩啊。"
  },
  Voice_147511_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_147512_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_147513_AwakerVoiceContent = {
    Text = "正確的發聲訓練……？可我很滿意自己現在的聲音呢。"
  },
  Voice_147513_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_147513_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_147514_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_147515_AwakerVoiceContent = {
    Text = "聲音好像發生了一些變化……"
  },
  Voice_147515_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_147515_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_147516_AwakerVoiceContent = {
    Text = "怎麼樣，我的歌聲好聽嗎？"
  },
  Voice_147516_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_147518_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_147519_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_147520_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_147521_AwakerVoiceContent = {
    Text = "謝謝……我應該說謝謝嗎？"
  },
  Voice_147521_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_147522_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_147523_AwakerVoiceContent = {
    Text = "綻放光芒吧。"
  },
  Voice_147523_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_147524_AwakerVoiceContent = {
    Text = "久違的感覺……終於再度回歸舞臺。謝謝你，守密人。"
  },
  Voice_147524_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_147524_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_147525_AwakerVoiceContent = {
    Text = "冒昧打擾……能將我從樹上放下來嗎？我不記得自己為什麼爬了上去，或許是因為頭頂的雲彩令人有些懷念……"
  },
  Voice_147525_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_147526_AwakerVoiceContent = {
    Text = "我的族人從未離開我，他們只是去了很遠、很遠的地方。"
  },
  Voice_147526_AwakerVoiceTitle = {
    Text = "閒話·關於族人"
  },
  Voice_147527_AwakerVoiceContent = {
    Text = "聽到了嗎？"
  },
  Voice_147528_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_147529_AwakerVoiceContent = {
    Text = "你好像總是徘徊在我身邊……我知道了，你一定是我的歌迷吧。"
  },
  Voice_147529_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_147529_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_147530_AwakerVoiceContent = {
    Text = "啦啦啦~什麼，這裡有毀滅世界的災厄？啊……那我得好好梳一下頭髮，還要去找姐姐……"
  },
  Voice_147530_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_147531_AwakerVoiceContent = {
    Text = "噓……別說話，有壞人來了。他們要來抓走我和姐姐，還不讓我們上船……"
  },
  Voice_147531_AwakerVoiceTitle = {
    Text = "閒話·關於安全"
  },
  Voice_147532_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_147532_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_147533_AwakerVoiceContent = {
    Text = "當我醒來的時候，星球正在毀滅。我看見夜空一縷縷剝落下來，世界成了被大風灌注的帆布，先是變形，然後再撕裂、粉碎了。"
  },
  Voice_147533_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_147533_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_147534_AwakerVoiceContent = {
    Text = "這是我的簽名海報，皮克曼先生為我繪製的。我把它贈與你。"
  },
  Voice_147534_AwakerVoiceTitle = {
    Text = "閒話·關於菲茵特"
  },
  Voice_147534_UnlockDesc = {
    Text = "獲得喚醒體「菲茵特」後解鎖"
  },
  Voice_149667_AwakerVoiceContent = {
    Text = "嗯嗯？很好奇嗎？教母的寶庫，可不能隨便給外人看呀。要是想知道裡面鼓鼓囊囊的是什麼，不如現在就來加入仙女教派吧，嘻嘻？"
  },
  Voice_149667_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_149668_AwakerVoiceContent = {
    Text = "你不相信卡拉布的結論？嗚嗚，果然很難瞞天過海嗎……其實我是@1公國博希蒙德六世的私生女，隱姓埋名流落人間，為了躲避敵軍的追捕才假稱仙女的……我都已經把最重要的秘密告訴你了，你不會不相信我吧？"
  },
  Voice_149668_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_149668_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_149669_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_149670_AwakerVoiceContent = {
    Text = "吃太多糖果了？不不不，這可是教母保持微笑的秘訣哦，不可能因為蛀牙這種小事就停下來吧？~~"
  },
  Voice_149670_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_149671_AwakerVoiceContent = {
    Text = "來吧，站到本仙女身邊來。什麼？大家一起分祭品吃？……好吧，如果這是彌薩格的規矩……那我……我肯定沒有任何反對意見呀，來吧，大家一起熱鬧起來！"
  },
  Voice_149671_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_149671_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_149672_AwakerVoiceContent = {
    Text = "唉呀，真是虔誠的小羊羔呢。"
  },
  Voice_149672_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_149673_AwakerVoiceContent = {
    Text = "再多一點，仙女才會給你賜福哦？"
  },
  Voice_149673_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_149674_AwakerVoiceContent = {
    Text = "你們還嫩了點~"
  },
  Voice_149676_AwakerVoiceContent = {
    Text = "這一次的敬拜儀式，比往日的都更加隆重，祭品的數量也要更多……哎呀，當然不會是人彘啦，我可是心善的仙女，不會做傷害別人的事情的~"
  },
  Voice_149676_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_149676_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_149677_AwakerVoiceContent = {
    Text = "守密人，您已經準備好聽卡拉布的真心話了嗎？\n卡拉布從哪裡來，根本就不重要。重要的是，您是我上天賜給我的最寶貴的禮物，卡拉布已經決定永遠、永遠留在您這位貴人身邊了。\n您覺得這也是詭計的一部分，好讓您不要再追查了？嘻嘻，您猜呢？\n總之，作為說出真心話的獎賞，可以給卡拉布一顆蘋果味軟糖嗎？"
  },
  Voice_149677_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_149677_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_149678_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_149680_AwakerVoiceContent = {
    Text = "沒關係，下一次專注保護本仙女，就不會失敗啦~"
  },
  Voice_149680_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_149682_AwakerVoiceContent = {
    Text = "別想騙我！"
  },
  Voice_149682_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_149683_AwakerVoiceContent = {
    Text = "嗚哇，居然有這麼多貢品……咳，哼哼，做得不錯，值得嘉獎！來，仙女賜給你一個仙女之吻！想什麼呢，當然是在額頭上！"
  },
  Voice_149683_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_149683_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_149684_AwakerVoiceContent = {
    Text = "感謝諸位信眾的供奉！善解人意的教母會在神殿內為你也雕築一尊純金塑像的。唉呀，為了這尊塑像能夠展現出您那冷峻優美的體態，可還得再好好搜羅一番呐~"
  },
  Voice_149684_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_149684_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_149685_AwakerVoiceContent = {
    Text = "你？……你是我們教會尚未開悟的一員，卡拉布會耐心等待你認知到世界真諦的一天的。到那時候，記得要為教主獻上你的肉體、忠心和財物，嘻嘻。"
  },
  Voice_149685_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_149686_AwakerVoiceContent = {
    Text = "清單上的東西……這就集齊了？彌薩格的財力深不可測啊……早知道我就……嗯嗯？我在嘀咕什麼？只是在感謝德克斯特勳爵的慷慨，嘻嘻~"
  },
  Voice_149686_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_149686_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_149687_AwakerVoiceContent = {
    Text = "最討厭的東西？當然是那些沒有契約精神的巫師啦。有個秘密偷偷告訴你，其實所有的巫師都是大騙子，他們所說的一切預言與詛咒都是為了把你騙成窮光蛋！至於防範的方法……只要讓你的錢都蒙受仙女的祝福就好啦！"
  },
  Voice_149687_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_149688_AwakerVoiceContent = {
    Text = "初次見面，我是來自遠方的蒼白仙女，有興趣了解一下嗎？仙女賜福根據會費檔次有不同強度哦，嘻嘻~"
  },
  Voice_149688_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_149689_AwakerVoiceContent = {
    Text = "以往的敬拜儀式中，除了七重禮拜和三重宣誓的流程，信眾們還會為我特別搭建嶄新的神殿和獻上豐盛的貢品。這裡是清單！"
  },
  Voice_149689_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_149689_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_149690_AwakerVoiceContent = {
    Text = "來吧，把想要割捨的事物都埋進深雪裡……"
  },
  Voice_149690_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_149691_AwakerVoiceContent = {
    Text = "我聽說你在打聽我的出身，嘻嘻，這可是教母的秘密。不過，如果你執意想要調查的話，仙女教派裡存有我親自撰寫的傳記，只要上交十萬枚銀芯就能閱覽，要來試試嗎？"
  },
  Voice_149691_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_149691_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_149692_AwakerVoiceContent = {
    Text = "很好啊，這裡有很多非常可愛的孩子和慷慨到令人髮指的生活補助。有了他們，我遲早能攢夠前往東方的路費……"
  },
  Voice_149692_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格"
  },
  Voice_149693_AwakerVoiceContent = {
    Text = "記得朝拜教母哦，嘻嘻。"
  },
  Voice_149693_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_149694_AwakerVoiceContent = {
    Text = "抱歉啊，仙女的領地可是很神聖的，恕不接待奇怪的狼人……什麼空氣裡有謊言的味道之類的，只是他鼻子失靈了吧？"
  },
  Voice_149694_AwakerVoiceTitle = {
    Text = "閒話：關於萊克"
  },
  Voice_149694_UnlockDesc = {
    Text = "獲得喚醒體「萊克」後解鎖"
  },
  Voice_149695_AwakerVoiceContent = {
    Text = "咦，有人說我是假仙女…被拆穿了呢，嘻嘻。我知道你不會在意的，對吧？"
  },
  Voice_149695_AwakerVoiceTitle = {
    Text = "閒話·關於傳言"
  },
  Voice_149696_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_149697_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_149698_AwakerVoiceContent = {
    Text = "誤入歧途的羔羊們，本仙女來洗清爾等罪孽，嘻~"
  },
  Voice_149698_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_149699_AwakerVoiceContent = {
    Text = "居然還沒放棄嗎？好吧，就讓卡拉布親自告訴你吧。其實卡拉布是東方一座高聳入雲的雪山所屬女神烏摩缽蒂的女兒……嗯哼，你說那位女神只有兩個兒子沒有女兒？關於神明的記錄總是會有缺損的嘛。"
  },
  Voice_149699_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_149699_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_149700_AwakerVoiceContent = {
    Text = "鏘鏘~仙女的光輝已經照耀在你身上了，衝吧！"
  },
  Voice_149700_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_149701_AwakerVoiceContent = {
    Text = "好啦好啦別再查了，好不好嘛？作為乖巧中止這一冒犯行為的補償，我可以偷偷把最寶貴的糖果分你一半。要知道，在東征軍的戰場上，甜甜的糖果可是稀罕的東西。"
  },
  Voice_149701_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_149701_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_149702_AwakerVoiceContent = {
    Text = "卡拉布的祝福可以治癒世間所有疾病，當然也能治癒這種黑色的瘟疫……當然是真的啦，只要你足夠虔誠、足夠信任卡拉布就可以啦，嘻嘻。"
  },
  Voice_149702_AwakerVoiceTitle = {
    Text = "閒話·關於危機"
  },
  Voice_149703_AwakerVoiceContent = {Text = "討厭！"},
  Voice_149703_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_149704_AwakerVoiceContent = {
    Text = "仙女的光輝~"
  },
  Voice_149705_AwakerVoiceContent = {
    Text = "七重禮拜，三重宣誓，用它們來換取仙女的赦免吧！"
  },
  Voice_149705_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_150079_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_150104_AwakerVoiceContent = {
    Text = "咦，奧吉爾怎麼把您放進來了？不是說好攔住所有人的嗎？您是他的主君……？不靠譜的小孩子真讓人困擾啊，為了這次集會，我可是花費了不少精力準備呢。要不……收到的供奉五五分成，您為我網開一面吧？"
  },
  Voice_150104_AwakerVoiceTitle = {
    Text = "閒話：關於奧吉爾"
  },
  Voice_150104_UnlockDesc = {
    Text = "獲得喚醒體「奧吉爾」後解鎖"
  },
  Voice_22276_AwakerVoiceContent = {
    Text = "快點結束吧，不要在街頭逗留。"
  },
  Voice_22276_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_36679_AwakerVoiceContent = {
    Text = "他是在我沉睡期間加入教團的，我和他沒什麼交集。\n不過，聽說他是自己找上門來的。想要放棄人類形體，成為完全的「蹈海者」……哼，又一個被力量衝昏頭腦的蠢材。"
  },
  Voice_36679_AwakerVoiceTitle = {
    Text = "閒話·關於凱刻斯"
  },
  Voice_36679_UnlockDesc = {
    Text = "通關「調查行動」第6章後解鎖"
  },
  Voice_36680_AwakerVoiceContent = {
    Text = "戈利亞從來都不是忠心耿耿的小狗，真搞不明白彌利亞姆為什麼這麼器重他……如果沒有被鏈子拴著，第一個跑掉的就是他。"
  },
  Voice_36680_AwakerVoiceTitle = {
    Text = "閒話·關於戈利亞"
  },
  Voice_36680_UnlockDesc = {
    Text = "通關「調查行動」第6章後解鎖"
  },
  Voice_36681_AwakerVoiceContent = {
    Text = "蹈海者不是一生下來就是這幅模樣的。為了隱藏在人群中，他們的前半生和人類沒什麼兩樣……\n你可要小心點了，說不定你最喜歡的蛋糕店老闆，也是他們的一員哦？"
  },
  Voice_36681_AwakerVoiceTitle = {
    Text = "閒話·關於蹈海者"
  },
  Voice_36681_UnlockDesc = {
    Text = "通關「調查行動」第6章後解鎖"
  },
  Voice_36682_AwakerVoiceContent = {
    Text = "希萊斯特跑調的船歌，船長的拿手好菜熏肉燉鮮魚，被海風吹得又腥又硬的被子……雖然危險又緊張，但和他們流亡大海的這幾個月時光，我一輩子都不會忘記。"
  },
  Voice_36682_AwakerVoiceTitle = {
    Text = "閒話·關於「幽靈船」"
  },
  Voice_36682_UnlockDesc = {
    Text = "通關「調查行動」第6章後解鎖"
  },
  Voice_36683_AwakerVoiceContent = {
    Text = "雖然學校裡的大家看起來都很忙，但……\n但在這裡，有一種我以前從沒感受過的安逸。\n為了相同的目標聚在一起，共同為之努力的感覺……哼，還算不錯吧。"
  },
  Voice_36683_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學·II"
  },
  Voice_36683_UnlockDesc = {
    Text = "通關「調查行動」第6章後解鎖"
  },
  Voice_36684_AwakerVoiceContent = {
    Text = "床太硬，天氣太冷，午後的紅茶總泡得像洗草水……本小姐有一千個不喜歡這裡的理由。\n不過，只憑「有你在」這點，我倒也不是不能勉強留下來啦……"
  },
  Voice_36684_AwakerVoiceTitle = {
    Text = "閒話·關於守密人·III"
  },
  Voice_36684_UnlockDesc = {
    Text = "通關「調查行動」第6章後解鎖"
  },
  Voice_36685_AwakerVoiceContent = {
    Text = "謝、謝謝……欸？為什麼向你道謝？這、這還用說嗎！當然是為了你在海上為我所做的一切……\n等等，你這傢伙為什麼笑了？你就是想看本小姐出糗對吧！"
  },
  Voice_36685_AwakerVoiceTitle = {
    Text = "閒話·關於守密人·II"
  },
  Voice_36685_UnlockDesc = {
    Text = "通關「調查行動」第6章後解鎖"
  },
  Voice_36686_AwakerVoiceContent = {
    Text = "我曾以為，我和她之間是有親情的……\n但在那一切都發生後我才意識到，或許，那些片刻溫情從一開始就是我的一廂情願。\n你要怎麼對她，是你們間的事，只要別再讓她靠近我就好。"
  },
  Voice_36686_AwakerVoiceTitle = {
    Text = "閒話·關於彌利亞姆·II"
  },
  Voice_36686_UnlockDesc = {
    Text = "通關「調查行動」第6章後解鎖"
  },
  Voice_36687_AwakerVoiceContent = {
    Text = "好奇怪……這感覺真的好奇怪。\n心臟明明已經不再跳了，可身體卻還是熱的……喂，你過來摸一下我的手，告訴我這不是錯覺。"
  },
  Voice_36687_AwakerVoiceTitle = {
    Text = "閒話·關於「喚醒體」"
  },
  Voice_36687_UnlockDesc = {
    Text = "通關「調查行動」第6章後解鎖"
  },
  Voice_45153_AwakerVoiceContent = {
    Text = "我或許並非出生在雷歐王國，大聖堂卻是我獲得第二生命的地方。如此看來，將這裡視作我的故鄉，又有什麼不可呢？"
  },
  Voice_45153_AwakerVoiceTitle = {
    Text = "閒話·關於故鄉"
  },
  Voice_45154_AwakerVoiceContent = {
    Text = "在無形的瘟疫肆虐多年後，父神終於聽到了我的禱告，為我降下了這可以與苦難抗衡的「賜福」。它確實能夠給予生命，但也需要代價。\n我作為代行者，自然應當代那些受賜的人承擔。"
  },
  Voice_45154_AwakerVoiceTitle = {
    Text = "閒話·關於「賜福」"
  },
  Voice_45155_AwakerVoiceContent = {
    Text = "對我而言，喚醒體這一狀態是父神給予懷中靈魂的恩賜。這是第二次生命，也是一個彌補過去遺憾的機會。\n我會繼續行父神的事，盡代行者的責，消除更多的苦難。"
  },
  Voice_45155_AwakerVoiceTitle = {
    Text = "閒話·關於「喚醒體」"
  },
  Voice_45156_AwakerVoiceContent = {
    Text = "請容我再一次向你表達感謝，守密人，你尊重了我的意見，替我向審查會保守了秘密。若是他們介入，恐怕是不會允許我繼續為聖堂區服務的。"
  },
  Voice_45156_AwakerVoiceTitle = {
    Text = "閒話·關於守密人·Ⅱ"
  },
  Voice_45156_UnlockDesc = {
    Text = "通關特遣紀錄「血的顏色」後解鎖"
  },
  Voice_45157_AwakerVoiceContent = {
    Text = "那孩子赤誠、堅定、善良，有著一個不可多得的明亮靈魂。上一次見到這樣的人，還是在我第一次人生中的事了。"
  },
  Voice_45157_AwakerVoiceTitle = {
    Text = "閒話·關於奧吉爾"
  },
  Voice_45157_UnlockDesc = {
    Text = "通關特遣紀錄「血的顏色」後解鎖"
  },
  Voice_45158_AwakerVoiceContent = {
    Text = "失去視覺並不代表我就此盲目。父神在讓黑暗降臨於我的同時，也讓我變得能夠看見靈魂的微光。"
  },
  Voice_45158_AwakerVoiceTitle = {
    Text = "閒話·關於視覺"
  },
  Voice_45159_AwakerVoiceContent = {
    Text = "那時的我雖受「賜福」，卻也不過是一個普通人。受苦的太多，需要「賜福」的人太多，我想救下他們全部，卻沒能成功。\n這是我最大的遺憾，也是我永恆的愧疚。"
  },
  Voice_45159_AwakerVoiceTitle = {
    Text = "閒話·關於第一次生命"
  },
  Voice_45160_AwakerVoiceContent = {
    Text = "教廷內不少人認為，《聖典》中提到的“白色的火焰”指的是月光：蒼白的使者將從月光中顯現，帶領我們離開苦難。\n但我知道，真正的火焰是在你我心中燃燒的靈魂。"
  },
  Voice_45160_AwakerVoiceTitle = {
    Text = "閒話·關於「蒼白之火」"
  },
  Voice_45161_AwakerVoiceContent = {
    Text = "事實上，隱瞞我的身份是大主教的意思。他沒有細說原因，只是告誡我：至純的地方也可能存在陰影，為善亦需多加小心。\n當然，對於你，我是完全信任的。"
  },
  Voice_45161_AwakerVoiceTitle = {
    Text = "閒話·關於隱瞞身分"
  },
  Voice_45161_UnlockDesc = {
    Text = "通關特遣紀錄「血的顏色」後解鎖"
  },
  Voice_4908_AwakerVoiceContent = {
    Text = "我的歌聲，有成為您的助力嗎？"
  },
  Voice_4908_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_4909_AwakerVoiceContent = {
    Text = "可惡，他明明也是小孩子，你們怎麼都那麼尊敬他！拿出同樣的態度來對待本小姐，知道嗎！"
  },
  Voice_4909_AwakerVoiceTitle = {
    Text = "閒話·關於圖魯"
  },
  Voice_4909_UnlockDesc = {
    Text = "獲得喚醒體「圖魯」後解鎖"
  },
  Voice_4910_AwakerVoiceContent = {
    Text = "喂，你知道其他喚醒體平常都在做什麼嗎？別誤會了，我可不想交朋友，只是想……對，我只是想視察一下！"
  },
  Voice_4910_AwakerVoiceTitle = {
    Text = "閒話·關於日常"
  },
  Voice_4911_AwakerVoiceContent = {
    Text = "可惡可惡可惡！下次一定要把他們的屍首扔去喂蜘蛛！"
  },
  Voice_4911_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_4912_AwakerVoiceContent = {Text = "餘韻。"},
  Voice_4912_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_4913_AwakerVoiceContent = {Text = "韻律。"},
  Voice_4913_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_4914_AwakerVoiceContent = {
    Text = "大膽的嘗試。"
  },
  Voice_4914_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_4915_AwakerVoiceContent = {
    Text = "不必這樣急切……有什麼是我能為您做的嗎？"
  },
  Voice_4915_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_4916_AwakerVoiceContent = {Text = "大膽！"},
  Voice_4916_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_4917_AwakerVoiceContent = {
    Text = "（饒有興致的質問）"
  },
  Voice_4917_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_4918_AwakerVoiceContent = {
    Text = "自然是賜予我無上尊榮之物。你覺得這很不像我？"
  },
  Voice_4918_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_4919_AwakerVoiceContent = {
    Text = "做什麼？"
  },
  Voice_4919_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_4920_AwakerVoiceContent = {
    Text = "我做得不錯吧？那麼，報酬。——怎麼，天下可沒有白吃的午餐！"
  },
  Voice_4920_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_4921_AwakerVoiceContent = {Text = "走開！"},
  Voice_4921_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_4922_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_4923_AwakerVoiceContent = {
    Text = "真是美妙的勝利啊……我將把這瞬間銘刻成永恆。"
  },
  Voice_4923_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_4924_AwakerVoiceContent = {
    Text = "感受到了不淨之源......向本體又接近了一步......啊啊啊，讓我來撕碎這個世界！"
  },
  Voice_4924_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_4924_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_4925_AwakerVoiceContent = {
    Text = "我們......準備好了。請下達指令吧，守密人。"
  },
  Voice_4925_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_4925_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_4926_AwakerVoiceContent = {
    Text = "老爺，您真是個好心人。可惜我沒有什麼可以報答您，我只是個一無是處的傢伙......"
  },
  Voice_4926_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_4926_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_4927_AwakerVoiceContent = {
    Text = "......再進一步，就能和「她們」徹底分離了嗎？"
  },
  Voice_4927_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_4927_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_4928_AwakerVoiceContent = {
    Text = "咦，我還活著......您，真的不會偷走我的器官，抓我去做實驗嗎？"
  },
  Voice_4928_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_4928_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_4929_AwakerVoiceContent = {
    Text = "溫柯爾的原生種族擁有進入生物大腦的能力，與我相融的外域意志為此十分忌憚她。不過，她現在也只是個被軀殼束縛住的可憐靈魂罷了。"
  },
  Voice_4929_AwakerVoiceTitle = {
    Text = "閒話·關於溫柯爾"
  },
  Voice_4929_UnlockDesc = {
    Text = "獲得喚醒體「溫柯爾」後解鎖"
  },
  Voice_4930_AwakerVoiceContent = {
    Text = "所有的一切，艾繼絲都很喜歡。開飯的時候，大家環繞著桌子祈禱的時候也好；守密人出外勤，所有人等待您凱旋歸來的時候也好……空氣中總是彌漫著幸福的味道……這樣的我，真的配享受這些美好嗎？"
  },
  Voice_4930_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_4931_AwakerVoiceContent = {
    Text = "沉沒吧。"
  },
  Voice_4931_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_4932_AwakerVoiceContent = {
    Text = "綻放吧。"
  },
  Voice_4932_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_4933_AwakerVoiceContent = {
    Text = "「信賴」、「服從」、「奴隸」、「戀情」、「尊敬」……語言模組重建與學習中，還請守密人多多指教。"
  },
  Voice_4933_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_4933_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_4934_AwakerVoiceContent = {
    Text = "艾瑞卡目前處於待機狀態，機體將於一小時十五分鐘後完成冷卻，<Del:想啟動就拿你的心臟來交換>是否緊急啟動？……權限驗證中……守密人最高權限驗證完畢。你好，守密人。"
  },
  Voice_4934_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_4934_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_4935_AwakerVoiceContent = {
    Text = "調查任務平均危險指數為7，平均醫療損耗為煉金補充劑8瓶，平均屍體善後時長為十小時。\n結論：守密人的工作非常危險，在行動中請注意安全。"
  },
  Voice_4935_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_4935_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_4936_AwakerVoiceContent = {
    Text = "正在查詢教師檔案：艾瑞卡·雷菲爾，銀芯機械與自動化專業講師，已故——你想要查詢的不是這個嗎？好的，正在重新檢索關鍵字「艾瑞卡」。"
  },
  Voice_4936_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_4936_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_4937_AwakerVoiceContent = {
    Text = "如需查詢資料，請完整說明檔案名稱，模糊搜索功能暫不可用。"
  },
  Voice_4937_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_4937_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_4938_AwakerVoiceContent = {
    Text = "（驚呼）"
  },
  Voice_4938_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_4939_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_4940_AwakerVoiceContent = {
    Text = "（驚呼）"
  },
  Voice_4940_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_4941_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_4942_AwakerVoiceContent = {
    Text = "充能完畢，準備爆破。"
  },
  Voice_4942_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_4943_AwakerVoiceContent = {
    Text = "充能完畢，準備爆破。"
  },
  Voice_4943_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_4944_AwakerVoiceContent = {
    Text = "這種小事，以後就不要來打擾王女的休憩了。"
  },
  Voice_4944_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_4945_AwakerVoiceContent = {
    Text = "我會像保護汀克特一樣，保護你。"
  },
  Voice_4945_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_4946_AwakerVoiceContent = {
    Text = "我不是什麼重要之人，不過是眾多信徒中渺小的一滴……只要能為那位大人效力，引得其側目，我願獻上我所有的精與神……"
  },
  Voice_4946_AwakerVoiceTitle = {
    Text = "閒話·關於過去"
  },
  Voice_4946_UnlockDesc = {
    Text = "獲得喚醒體「圖魯」後解鎖"
  },
  Voice_4947_AwakerVoiceContent = {
    Text = "看著我！"
  },
  Voice_4948_AwakerVoiceContent = {
    Text = "看著我！"
  },
  Voice_4949_AwakerVoiceContent = {
    Text = "……罷了，只要不用那些狂熱的祭拜叨擾余，與他們共處一室也未嘗不可。"
  },
  Voice_4949_AwakerVoiceTitle = {
    Text = "閒話·關於蹈海者"
  },
  Voice_4949_UnlockDesc = {
    Text = "獲得喚醒體「彌利亞姆」「戈利亞」「凱刻斯」「珊」「法洛思」其一後解鎖"
  },
  Voice_4950_AwakerVoiceContent = {
    Text = "我討厭那種黑色的感覺，像是內心被掏空了，不被滿足的感覺讓身上到處都癢癢的……"
  },
  Voice_4950_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_4951_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_4953_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_4954_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_4955_AwakerVoiceContent = {
    Text = "那些認定神國已然覆滅的史學家，大言不慚得令人煩躁……但無妨，言語不會成為神國重燃榮光的阻礙。"
  },
  Voice_4955_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_4956_AwakerVoiceContent = {
    Text = "其實……悄悄告訴你，我對現在的摩托挺不滿意的——我不是不喜歡它！只是，我總感覺，它好像缺了什麼……"
  },
  Voice_4956_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_4957_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_4959_AwakerVoiceContent = {
    Text = "抱歉......我不想這樣的……"
  },
  Voice_4959_AwakerVoiceTitle = {
    Text = "技能·二·抑鬱"
  },
  Voice_4960_AwakerVoiceContent = {
    Text = "（饒有興致的低呼）"
  },
  Voice_4960_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_4961_AwakerVoiceContent = {
    Text = "@1@2年，華德·菲利普斯先生、刻拉爾克什與塔薇三人，一同創立了彌薩格學院。而後經過漫長的發展，才最終誕生了<Del:這所該死的監獄>彌薩格大學。"
  },
  Voice_4961_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_4962_AwakerVoiceContent = {
    Text = "正義、忠誠、頑強、自律。這些早已在我心中刻下烙印。"
  },
  Voice_4962_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_4963_AwakerVoiceContent = {
    Text = "我會好好完成您交代的事情。"
  },
  Voice_4963_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_4964_AwakerVoiceContent = {
    Text = "究竟是怎樣不負責的父母，才會以女妖之盾命名自己的女兒？你說那孩子沒有父母？嗯……我們這段對話，沒必要讓她知道。"
  },
  Voice_4964_AwakerVoiceTitle = {
    Text = "閒話·關於艾繼絲"
  },
  Voice_4964_UnlockDesc = {
    Text = "獲得喚醒體「艾繼絲」後解鎖"
  },
  Voice_4965_AwakerVoiceContent = {
    Text = "無聊的話，不如來迷宮裡“陪陪我”。反正你這無望的人生和無盡的迷宮，壓根就沒什麼兩樣！"
  },
  Voice_4965_AwakerVoiceTitle = {
    Text = "閒話·關於迷宮"
  },
  Voice_4966_AwakerVoiceContent = {
    Text = "朵爾在的時候，調查員們的效率普遍提高78.312%，相應的也有更多人陷入情緒低潮。引用她的一句話：有的人如果能管好嘴，世界運轉會更加流暢。"
  },
  Voice_4966_AwakerVoiceTitle = {
    Text = "閒話·關於朵爾"
  },
  Voice_4966_UnlockDesc = {
    Text = "獲得喚醒體「朵爾」後解鎖"
  },
  Voice_4967_AwakerVoiceContent = {
    Text = "降臨吧！"
  },
  Voice_4969_AwakerVoiceContent = {
    Text = "怎麼會有人不喜歡冒險呢？深入沒人去過的神秘領域，探訪未知，編織屬於自己的故事……多麼刺激！"
  },
  Voice_4969_AwakerVoiceTitle = {
    Text = "閒話·關於冒險"
  },
  Voice_4970_AwakerVoiceContent = {
    Text = "貴安，我是來自費弗爾的寧菲亞。您為我帶來了這副能夠自由呼吸的身體……我該做些什麼來報答您呢？"
  },
  Voice_4970_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_4971_AwakerVoiceContent = {
    Text = "剛才我好像又聽見了，那些自稱是我主人的傢伙的哀嚎——真是美妙。"
  },
  Voice_4971_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_4971_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_4972_AwakerVoiceContent = {
    Text = "可以不吃蔬菜嗎？雖然汀克特說過不能挑食，但我不喜歡它們的色彩……"
  },
  Voice_4972_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_4973_AwakerVoiceContent = {
    Text = "造物神有言：苦非我的造物。將它承擔消解吧，我的代行者，在地上建造無苦的國。為此我願獻出一切，包括生命。"
  },
  Voice_4973_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_4973_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_4974_AwakerVoiceContent = {
    Text = "在摧毀一切的消融詛咒面前，其他苦難都相形失色。即使我無法替他人承受詛咒，也要盡力為他們減輕傷痛。"
  },
  Voice_4974_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_4974_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_4975_AwakerVoiceContent = {
    Text = "現在的我，是否足以減輕他們身上的苦痛，慰藉他們的靈魂了呢？"
  },
  Voice_4975_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_4975_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_4976_AwakerVoiceContent = {
    Text = "如此，我便能承擔萬物疾苦，為所有生靈鋪就通往那無有苦難之地的道路。"
  },
  Voice_4976_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_4976_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_4977_AwakerVoiceContent = {
    Text = "這靈魂深處的暖意……感謝你的賜予，蒼白之火。有了這份力量，或許我終於能履行代行者的責任，拯救更多的人。"
  },
  Voice_4977_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_4977_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_4978_AwakerVoiceContent = {
    Text = "我真的可以吃這麼多嗎？"
  },
  Voice_4978_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_4978_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_4979_AwakerVoiceContent = {
    Text = "哼哼……那可不是死亡，那只是你的未來，我的未來，這個世界的未來。"
  },
  Voice_4979_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_4980_AwakerVoiceContent = {
    Text = "汀克特……聽到她哀婉的歌聲，就會忍不住想要起舞……"
  },
  Voice_4980_AwakerVoiceTitle = {
    Text = "閒話·關於汀克特"
  },
  Voice_4980_UnlockDesc = {
    Text = "獲得喚醒體「汀克特」後解鎖"
  },
  Voice_4981_AwakerVoiceContent = {
    Text = "凡俗的歷練也能激發血脈的價值嗎？這倒是在我的意料之外。"
  },
  Voice_4981_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_4982_AwakerVoiceContent = {
    Text = "武器變得順手了。"
  },
  Voice_4982_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_4983_AwakerVoiceContent = {
    Text = "別以為這樣我就會感激你，我的種族不容許。"
  },
  Voice_4983_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_4984_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_4985_AwakerVoiceContent = {
    Text = "那個男人……喂，等我一下，我們的賭局還沒有結束吧？"
  },
  Voice_4985_AwakerVoiceTitle = {
    Text = "閒話·關於其他人"
  },
  Voice_4986_AwakerVoiceContent = {
    Text = "我很喜歡學院的記錄儀，要是能改造出一個隨身版本，實時提醒我忘了什麼就好了……"
  },
  Voice_4986_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_4987_AwakerVoiceContent = {
    Text = "遍地螻蟻……不，連螻蟻都算不上，只是麵包屑而已，為祂的降生提供養分。"
  },
  Voice_4987_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_4988_AwakerVoiceContent = {
    Text = "補給在此。"
  },
  Voice_4989_AwakerVoiceContent = {
    Text = "補給在此。"
  },
  Voice_4990_AwakerVoiceContent = {
    Text = "嗯......用力，用力點。對，就像這樣......"
  },
  Voice_4990_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_4991_AwakerVoiceContent = {
    Text = "還沒有完全覺醒，就勝出得輕而易舉。"
  },
  Voice_4991_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_4992_AwakerVoiceContent = {
    Text = "哎呀，帽子歪了……嗯，這樣正好嗎？真不錯！"
  },
  Voice_4992_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_4992_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_4993_AwakerVoiceContent = {
    Text = "“擁有如此能力的我，真的還是人類嗎？”自從開始接受戰鬥訓練以來，我每一天都在這麼問自己。我熱愛這個世界，即使它是如此灰暗、污濁、無趣，但你們的存在讓它如塵埃中的鑽石般閃閃發光。\n我一度很害怕，隨著力量的增長，我作為人類的立場會發生轉變……現在，我很慶倖身邊有你，我們間的默契把我緊緊綁在了人類世界。以後的日子，也要請你多多關照了，守密人。"
  },
  Voice_4993_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_4993_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_4994_AwakerVoiceContent = {
    Text = "啊啊……你會有顧慮也是當然的事，是我考慮不周，作為搭檔，我應該最開始就向你解釋清楚的。如你所見，我的身上確實有異於常人之處，這恐怕與我的身世相關。說不好奇，是不可能的吧？但能擁有學院這樣的容身之所，是我的幸運，所以，我選擇不去揭開命運的面紗。"
  },
  Voice_4994_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_4994_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_4995_AwakerVoiceContent = {
    Text = "你和那個女人見過面了吧？就是那個披著白色頭紗的喚醒體，她是這所大學建立的根基之一……\n但老實說，我不喜歡她。那種目空一切，彷彿對全世界都不在意的態度真讓人火大……啊，你說覺得我和她長得像？我陪你去校醫院檢查一下視力吧？"
  },
  Voice_4995_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_4995_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_4996_AwakerVoiceContent = {
    Text = "你在好奇我與教授的關係嗎？不是什麼秘密，告訴你也無妨。德克斯特教授是我的養父，至於養母……我在學校中長大，受到所有老師們照顧，不過相比之下，我與朵爾會更親近些。"
  },
  Voice_4996_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_4996_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_4997_AwakerVoiceContent = {
    Text = "不管是喚醒體事務處的手續流程，還是食堂印度菜的供應日期，學院的一應事務，我都可以為你解答——不用擔心打擾我，我看上去就這麼不近人情嗎？"
  },
  Voice_4997_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_4997_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_4998_AwakerVoiceContent = {
    Text = "魔鏡魔鏡，誰是世界上最厲害的魔術師？我？答對啦！"
  },
  Voice_4998_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_4998_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_4999_AwakerVoiceContent = {
    Text = "還不錯嘛。"
  },
  Voice_5000_AwakerVoiceContent = {
    Text = "真不錯～"
  },
  Voice_5001_AwakerVoiceContent = {
    Text = "（驚呼）"
  },
  Voice_5001_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_5002_AwakerVoiceContent = {
    Text = "成功……了嗎？我幫上您的忙了嗎？"
  },
  Voice_5002_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5003_AwakerVoiceContent = {
    Text = "沒用的！"
  },
  Voice_5003_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5004_AwakerVoiceContent = {
    Text = "（隱忍）"
  },
  Voice_5004_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_5005_AwakerVoiceContent = {
    Text = "看過來！"
  },
  Voice_5006_AwakerVoiceContent = {
    Text = "讓這裡成為大家的喧囂海洋吧！"
  },
  Voice_5006_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_5007_AwakerVoiceContent = {
    Text = "需要護衛同行嗎？如果你的追求是正義的，我會幫助你。"
  },
  Voice_5007_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5008_AwakerVoiceContent = {
    Text = "無法燃盡。"
  },
  Voice_5009_AwakerVoiceContent = {
    Text = "無法燃盡。"
  },
  Voice_5010_AwakerVoiceContent = {
    Text = "是想要一個擁抱嗎？"
  },
  Voice_5010_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_5011_AwakerVoiceContent = {
    Text = "看看我身上的這些鐐銬吧——它們不是裝飾，而是提醒。讓我不忘記被背叛、被踐踏的滋味。"
  },
  Voice_5011_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5012_AwakerVoiceContent = {
    Text = "如果想知道學院的過去，我推薦你去檔案館翻資料。\n拜託，包括學院前身在內，那可是長達300年的歷史！你不會真的想要我逐年複述吧？"
  },
  Voice_5012_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_5013_AwakerVoiceContent = {
    Text = "這是在挑釁我嗎？隨時奉陪！"
  },
  Voice_5013_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_5014_AwakerVoiceContent = {
    Text = "深海將贈予您永眠。"
  },
  Voice_5014_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5015_AwakerVoiceContent = {
    Text = "深海將贈予您永眠。"
  },
  Voice_5015_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_5016_AwakerVoiceContent = {
    Text = "沉淪吧，燃燒吧！告死之舞！"
  },
  Voice_5016_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5017_AwakerVoiceContent = {
    Text = "在此獻上，永恆綠炎的告死之舞！"
  },
  Voice_5017_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5018_AwakerVoiceContent = {
    Text = "那位像是燈塔一樣的小姐……在永夜的航行中，要是能夠看到她那樣耀眼的光芒，或許我就不會陷入迷失了吧……"
  },
  Voice_5018_AwakerVoiceTitle = {
    Text = "閒話·關於法洛思"
  },
  Voice_5018_UnlockDesc = {
    Text = "獲得喚醒體「法洛思」後解鎖"
  },
  Voice_5019_AwakerVoiceContent = {
    Text = "你最好能展現出值得我離開實驗室的價值，新任守密人。"
  },
  Voice_5019_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5020_AwakerVoiceContent = {
    Text = "我是主人，你是僕役。我想要什麼，必須伸手即來。怎麼啦，你這僕人還要賞賜嗎？好吧好吧，給你就是了！"
  },
  Voice_5020_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5021_AwakerVoiceContent = {
    Text = "（驚呼）"
  },
  Voice_5021_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_5022_AwakerVoiceContent = {
    Text = "恥辱，就用這招來洗清！"
  },
  Voice_5022_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5023_AwakerVoiceContent = {
    Text = "（驚呼）"
  },
  Voice_5023_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5024_AwakerVoiceContent = {
    Text = "（驚呼）"
  },
  Voice_5024_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_5025_AwakerVoiceContent = {
    Text = "獻出即為所得。"
  },
  Voice_5026_AwakerVoiceContent = {
    Text = "獻出即為所得。"
  },
  Voice_5027_AwakerVoiceContent = {
    Text = "會受傷的！"
  },
  Voice_5027_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5028_AwakerVoiceContent = {
    Text = "別過來！"
  },
  Voice_5028_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_5029_AwakerVoiceContent = {
    Text = "我喜歡滿月時金色的月光。神秘，溫柔，風一吹來，海面上泛起金色的磷光，像夢幻般爛漫。"
  },
  Voice_5029_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_5030_AwakerVoiceContent = {
    Text = "如果我們的故鄉沒有發生融蝕，我和汀克特就不會分開……我討厭融蝕，比討厭蔬菜更討厭。"
  },
  Voice_5030_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_5031_AwakerVoiceContent = {
    Text = "前方是寶藏還是港口，於我而言並無差異。我的使命是護您順利歸航。"
  },
  Voice_5031_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5031_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5032_AwakerVoiceContent = {
    Text = "跟隨天堂鳥的軌跡吧，終點就在碧藍色的前方。"
  },
  Voice_5032_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_5032_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_5033_AwakerVoiceContent = {
    Text = "我時常會眺望著海平面，幻想地平線另一端的光景，那是我愈發趨近卻永遠無法抵達的遙遠大陸。若有那麼一天，請您與我一同去看看吧。"
  },
  Voice_5033_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5033_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5034_AwakerVoiceContent = {
    Text = "承蒙您的垂愛，如今，即便是狂暴之海，我也有勇氣為您捎去無悔的祝福。"
  },
  Voice_5034_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5034_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5035_AwakerVoiceContent = {
    Text = "彷彿聽見了槳手們的歌謠，熟悉的故鄉的味道。"
  },
  Voice_5035_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5035_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5036_AwakerVoiceContent = {
    Text = "您是來拯救我的，對嗎？從腐朽的世道中，從浸染雙目的仇恨中，從永恆的綠炎中……"
  },
  Voice_5036_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5037_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5038_AwakerVoiceContent = {
    Text = "我將此視作參加您的投名狀了。"
  },
  Voice_5038_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5038_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_5039_AwakerVoiceContent = {
    Text = "嚐嚐教訓！"
  },
  Voice_5040_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5041_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5042_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_5043_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_5044_AwakerVoiceContent = {
    Text = "嚐嚐老鼠的厲害吧！"
  },
  Voice_5044_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5045_AwakerVoiceContent = {
    Text = "嚐嚐老鼠的厲害吧！"
  },
  Voice_5045_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_5046_AwakerVoiceContent = {
    Text = "骰子已經擲出。那麼，速戰速決吧！"
  },
  Voice_5046_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_5047_AwakerVoiceContent = {
    Text = "我將在致謝致辭中加上您的姓名，是您讓這被黑血玷污的雙足再次踏入美妙的芭蕾世界。從今往後，也請看著我起舞吧，守密人。"
  },
  Voice_5047_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5047_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5048_AwakerVoiceContent = {
    Text = "無論如何掙扎，依舊無法違抗命運。但那片刻的光輝，將凝固為永恆。"
  },
  Voice_5048_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5048_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5049_AwakerVoiceContent = {
    Text = "你說，該怎麼處置這些敗者呢？"
  },
  Voice_5049_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5050_AwakerVoiceContent = {
    Text = "即便胸中再無渴望，我也會扮演好那只天鵝。"
  },
  Voice_5050_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_5050_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_5051_AwakerVoiceContent = {
    Text = "閉上眼，告訴我，您看見了什麼？無瑕的月光，平靜的湖面……"
  },
  Voice_5051_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5051_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5052_AwakerVoiceContent = {
    Text = "招致毀滅與悲運的災厄啊，為何偏偏纏繞上了我和姐姐呢？"
  },
  Voice_5052_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_5053_AwakerVoiceContent = {
    Text = "接受我的愛意吧。"
  },
  Voice_5054_AwakerVoiceContent = {
    Text = "接受我的愛意吧。"
  },
  Voice_5055_AwakerVoiceContent = {
    Text = "感覺舒暢了許多，謝謝您。"
  },
  Voice_5055_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_5056_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5057_AwakerVoiceContent = {
    Text = "如果可以，我想贈您一朵淡紫睡蓮作為回禮。"
  },
  Voice_5057_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5058_AwakerVoiceContent = {
    Text = "我也能變得更強嗎？"
  },
  Voice_5058_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_5059_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5060_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_5061_AwakerVoiceContent = {
    Text = "這條傷腿嗎？沒想到你也會在意這個。是生前在戰場上留下的。\n不必掛懷，成為喚醒體之後，它不會再干擾我的戰鬥了。\n疼痛？不，我沒有思考過這種問題。"
  },
  Voice_5061_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_5061_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_5062_AwakerVoiceContent = {
    Text = "茜爾維婭詢問了我的心理狀況，是你叫她來的吧？我承認幻肢疼痛會不時發作。但無需在意我的感受。我是你的刀，是你的利刃，只要還能為正義而戰，區區疼痛不會帶來任何影響。"
  },
  Voice_5062_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_5062_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_5063_AwakerVoiceContent = {
    Text = "茶會茶會，來辦茶會吧！我從茜爾維婭那裡拿了好多茶葉和甜點哦！嗯，是用福特沃肯舞換的！"
  },
  Voice_5063_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_5064_AwakerVoiceContent = {
    Text = "我的自稱？您對我的私人事務如此關心嗎？只是想聊聊天……好吧。\n在軍隊裡，我們不會因性別而區別對待戰友，包括力量和速度，自然也包括髮型和稱謂。久而久之，就習慣這種表達了。"
  },
  Voice_5064_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5064_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_5065_AwakerVoiceContent = {
    Text = "有意思......你不害怕獲得力量後我將你撕成碎片喂魚嗎？"
  },
  Voice_5065_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_5066_AwakerVoiceContent = {
    Text = "為了成為配得上我的守密人，你也很努力嘛！"
  },
  Voice_5066_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5067_AwakerVoiceContent = {
    Text = "是時候撕碎幾個弱者的咽喉試試了。"
  },
  Voice_5067_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_5068_AwakerVoiceContent = {
    Text = "舞蹈是純粹的。言語會招致誤解，但舞步不會。"
  },
  Voice_5068_AwakerVoiceTitle = {
    Text = "閒話·關於舞蹈"
  },
  Voice_5069_AwakerVoiceContent = {
    Text = "我討厭大海，是理所當然的事吧。海洋吞噬了我所愛的一切……"
  },
  Voice_5069_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5070_AwakerVoiceContent = {
    Text = "遺忘也好，丟失也好，這次我們一定會返航！"
  },
  Voice_5070_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_5071_AwakerVoiceContent = {
    Text = "遺忘也好，丟失也好，這次我們一定會返航！"
  },
  Voice_5071_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5072_AwakerVoiceContent = {
    Text = "請、請不要再靠近我了，很危險。"
  },
  Voice_5072_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5073_AwakerVoiceContent = {
    Text = "隨便摸......這些都是當年在角鬥場留下的疤痕，男人的勳章！"
  },
  Voice_5073_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_5074_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5075_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5076_AwakerVoiceContent = {
    Text = "（吃痛的悶哼）"
  },
  Voice_5076_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_5077_AwakerVoiceContent = {
    Text = "（不難煩的悶哼）"
  },
  Voice_5077_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_5078_AwakerVoiceContent = {
    Text = "身體裡好像有什麼在沸騰，這就是啟靈的感受嗎。"
  },
  Voice_5078_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5078_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_5079_AwakerVoiceContent = {
    Text = "這是什麼新的技術嗎？我的義肢似乎輕便了許多。"
  },
  Voice_5079_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5079_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_5080_AwakerVoiceContent = {
    Text = "聞到了海風的鹹味，距離我的國已經不遠了。"
  },
  Voice_5080_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5080_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5081_AwakerVoiceContent = {
    Text = "逝去的同胞，能循著此光找到歸途嗎。"
  },
  Voice_5081_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_5081_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_5082_AwakerVoiceContent = {
    Text = "我已經尋覓了數千數萬年，不差這彈指百年的時間。在抵達你的彼岸前，我會繼續幫助你。"
  },
  Voice_5082_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5082_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5083_AwakerVoiceContent = {
    Text = "我只會為了故國而閃爍，你……"
  },
  Voice_5083_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5083_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5084_AwakerVoiceContent = {
    Text = "我感覺到了微風，它裹挾著細沙拂過我的腳面。"
  },
  Voice_5084_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5084_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5085_AwakerVoiceContent = {
    Text = "我能為您貢獻的力量就到此為止了，太貪得無厭可不好哦？"
  },
  Voice_5085_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5085_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5086_AwakerVoiceContent = {
    Text = "話已至此，您希望我回饋些什麼呢？只是戰鬥嗎？"
  },
  Voice_5086_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5086_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5087_AwakerVoiceContent = {
    Text = "愛之頭顱，怨之頭顱，憎之頭顱，欲之頭顱……哦呀，您又來啦？"
  },
  Voice_5087_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_5087_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_5088_AwakerVoiceContent = {
    Text = "既然是交易，我也不能只是收取您的饋贈。您需要在這店中挑選些什麼嗎？"
  },
  Voice_5088_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5088_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_50898_AwakerVoiceContent = {
    Text = "我會教會您喜悅、樂趣、抵達頂峰時的快感……與之相對的，你也要誠實地袒露自己的欲望噢？"
  },
  Voice_50898_AwakerVoiceTitle = {
    Text = "閒話·關於守密人2"
  },
  Voice_50899_AwakerVoiceContent = {
    Text = "我即是母樹，母樹也是我。樹的乳汁在我的血脈中奔湧，樹的意志在我的識海中徘徊……"
  },
  Voice_50899_AwakerVoiceTitle = {
    Text = "閒話·關於豐穰母樹"
  },
  Voice_50899_UnlockDesc = {
    Text = "通關「調查行動」第7章後解鎖"
  },
  Voice_5089_AwakerVoiceContent = {
    Text = "為背叛之行付出代價吧！"
  },
  Voice_5089_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_50900_AwakerVoiceContent = {
    Text = "我剛才在鑰塚尋覓隱蔽之地時，似乎見到了您的墓碑……我的木乃伊也會葬在此處嗎？不會嗎？真遺憾吶。"
  },
  Voice_50900_AwakerVoiceTitle = {
    Text = "閒話·關於鑰塚"
  },
  Voice_50900_UnlockDesc = {
    Text = "通關「調查行動」第7章後解鎖"
  },
  Voice_50901_AwakerVoiceContent = {
    Text = "狼的小哥啊……他和那位N之間，可有些說不清道不明的關係……"
  },
  Voice_50901_AwakerVoiceTitle = {
    Text = "閒話·關於萊克"
  },
  Voice_50901_UnlockDesc = {
    Text = "獲得喚醒體「萊克」後解鎖"
  },
  Voice_50902_AwakerVoiceContent = {
    Text = "靠近我、擁抱我、品嘗我……不要忘了我。"
  },
  Voice_50902_AwakerVoiceTitle = {
    Text = "閒話·關於守密人3"
  },
  Voice_50902_UnlockDesc = {
    Text = "通關「調查行動」第7章後解鎖"
  },
  Voice_50903_AwakerVoiceContent = {
    Text = "那是個過分勤勉和謹慎的孩子，我當然不會苛責她了~如果沒有她，隨心所欲的種群早就毀滅於變遷之中了吧？"
  },
  Voice_50903_AwakerVoiceTitle = {
    Text = "閒話·關於艾爾瓦"
  },
  Voice_50903_UnlockDesc = {
    Text = "獲得喚醒體「艾爾瓦」後解鎖"
  },
  Voice_50904_AwakerVoiceContent = {
    Text = "降生於黃沙，又回歸黃沙之內。在這趟短暫的旅程中，您總得留下點什麼，播種點什麼吧？"
  },
  Voice_50904_AwakerVoiceTitle = {
    Text = "閒話·關於沙漠"
  },
  Voice_50905_AwakerVoiceContent = {
    Text = "欲望都是由愛生髮而成的，愛是參天的巨樹誕生之前，那最初的種子。"
  },
  Voice_50905_AwakerVoiceTitle = {
    Text = "閒話·關於欲望"
  },
  Voice_50906_AwakerVoiceContent = {
    Text = "哎呀，可愛的小老鼠躥過去了……我聽說，老鼠可是喜歡偷腥的動物呢，可惜，這一隻還太小，尚在襁褓之中……"
  },
  Voice_50906_AwakerVoiceTitle = {
    Text = "閒話·關於詹金"
  },
  Voice_50906_UnlockDesc = {
    Text = "獲得喚醒體「詹金」後解鎖"
  },
  Voice_50907_AwakerVoiceContent = {
    Text = "他們延續了我的骨肉與血脈，化作滔滔河水豐沃勒姆瓦希……從今往後，就只能依靠您來為我繁衍存續了……"
  },
  Voice_50907_AwakerVoiceTitle = {
    Text = "閒話·關於亞蘭"
  },
  Voice_50907_UnlockDesc = {
    Text = "通關「調查行動」第7章後解鎖"
  },
  Voice_50908_AwakerVoiceContent = {
    Text = "蜘蛛啊……蜘蛛。嗯~我喜歡蜘蛛，他們密密麻麻降生的瞬間就獲得了行走的力量，這種繁殖和生存能力可真是讓人羡慕……"
  },
  Voice_50908_AwakerVoiceTitle = {
    Text = "閒話·關於阿格里帕"
  },
  Voice_50908_UnlockDesc = {
    Text = "獲得喚醒體「阿格里帕」後解鎖"
  },
  Voice_50909_AwakerVoiceContent = {
    Text = "所有流淌樹之血液的生靈都是我的孩子，吞下了樹種的您也一樣噢？"
  },
  Voice_50909_AwakerVoiceTitle = {
    Text = "閒話·關於子嗣"
  },
  Voice_50909_UnlockDesc = {
    Text = "通關「調查行動」第7章後解鎖"
  },
  Voice_5090_AwakerVoiceContent = {
    Text = "我銷售的商品嗎？可以說應有盡有，滿足你全部的欲望……只是要付出相應的代價。"
  },
  Voice_5090_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5090_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_50910_AwakerVoiceContent = {
    Text = "哎呀，不得不承認我輸給她一次了呢……好在，被她選擇的您，也會飲下樹的乳汁，將我的血與種帶往新的世界吧？"
  },
  Voice_50910_AwakerVoiceTitle = {
    Text = "閒話·關於塔薇"
  },
  Voice_50910_UnlockDesc = {
    Text = "獲得喚醒體「拉蒙娜」後解鎖"
  },
  Voice_50911_AwakerVoiceContent = {
    Text = "同為三大質體之一，那傢伙是個不可捉摸的怪物，您可別輕易信了他的甜言蜜語，那我可是會心疼不已的……"
  },
  Voice_50911_AwakerVoiceTitle = {
    Text = "閒話·關於N"
  },
  Voice_50912_AwakerVoiceContent = {
    Text = "有意識之物，就有欲望，就算是機械的生物也不會例外吧？"
  },
  Voice_50912_AwakerVoiceTitle = {
    Text = "閒話·關於艾瑞卡"
  },
  Voice_50912_UnlockDesc = {
    Text = "獲得喚醒體「艾瑞卡」後解鎖"
  },
  Voice_5091_AwakerVoiceContent = {
    Text = "為背叛之行付出代價吧！"
  },
  Voice_5091_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5092_AwakerVoiceContent = {
    Text = "歡迎來到不可思議國度！"
  },
  Voice_5092_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5093_AwakerVoiceContent = {
    Text = "（低號）"
  },
  Voice_5093_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_5094_AwakerVoiceContent = {
    Text = "我熟知雕琢的痛苦，還有那蛻變的灼燙。然而這一切，在永恆的美面前，渺若塵埃。"
  },
  Voice_5094_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5094_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5095_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_5096_AwakerVoiceContent = {
    Text = "那些未曾啟齒的話語，我將在作品裡向你訴說。"
  },
  Voice_5096_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5096_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5097_AwakerVoiceContent = {
    Text = "（驚呼）"
  },
  Voice_5097_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5098_AwakerVoiceContent = {
    Text = "沉睡的主宰在我耳邊夢囈，深海的廢墟在我眼前不斷重組......無數次出現在夢裡的景象，終於成真了嗎？"
  },
  Voice_5098_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5098_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5099_AwakerVoiceContent = {
    Text = "謝謝您為我準備的工作室。在這裡，一切都沐浴在陽光下。似乎每一件作品，每一把刻刀，身上都發著金色的光。哦，春天是金色的。"
  },
  Voice_5099_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5099_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5100_AwakerVoiceContent = {
    Text = "雖然性情不同，但我很喜歡那孩子。她身上有一種足以超脫一切困境與束縛的勇氣。要是我也能那般勇敢和頑強，或許就不會選擇投入大海的結局了吧……"
  },
  Voice_5100_AwakerVoiceTitle = {
    Text = "閒話·關於墨菲"
  },
  Voice_5100_UnlockDesc = {
    Text = "獲得喚醒體「墨菲」後解鎖"
  },
  Voice_5101_AwakerVoiceContent = {
    Text = "紅夫人和我侍奉過的任何主君都不一樣……不，我並不是討厭她，只是、只是有些難以招架……"
  },
  Voice_5101_AwakerVoiceTitle = {
    Text = "閒話·關於索蕾爾"
  },
  Voice_5101_UnlockDesc = {
    Text = "獲得喚醒體「索蕾爾」後解鎖"
  },
  Voice_5102_AwakerVoiceContent = {
    Text = "擁抱瘋狂！"
  },
  Voice_5103_AwakerVoiceContent = {
    Text = "苟延殘喘。"
  },
  Voice_5104_AwakerVoiceContent = {
    Text = "趕盡殺絕！"
  },
  Voice_5104_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5105_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_5106_AwakerVoiceContent = {
    Text = "心是無底的深淵，永遠無法被填滿。"
  },
  Voice_5106_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_5107_AwakerVoiceContent = {
    Text = "不痛不癢，但......依然十分感謝。"
  },
  Voice_5107_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5108_AwakerVoiceContent = {
    Text = "啊……你在向我搭話嗎？抱歉，我剛剛在回憶桅杆上看見過的光景，可以再複述一遍你的問題嗎？"
  },
  Voice_5108_AwakerVoiceTitle = {
    Text = "閒話·關於過去"
  },
  Voice_5109_AwakerVoiceContent = {
    Text = "是主人，也是母親。"
  },
  Voice_5109_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5110_AwakerVoiceContent = {
    Text = "可乘之機！"
  },
  Voice_5111_AwakerVoiceContent = {
    Text = "可乘之機！"
  },
  Voice_5112_AwakerVoiceContent = {
    Text = "預備——"
  },
  Voice_5112_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5113_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5114_AwakerVoiceContent = {
    Text = "再用力一點~"
  },
  Voice_5115_AwakerVoiceContent = {
    Text = "滾燙的愛！"
  },
  Voice_5116_AwakerVoiceContent = {
    Text = "融蝕現象……我無法向你透露太多。不過這東西的出現，可比你們想像中要早得多。"
  },
  Voice_5116_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_5118_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5119_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5120_AwakerVoiceContent = {
    Text = "出發吧。"
  },
  Voice_5120_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5121_AwakerVoiceContent = {
    Text = "呵，我們的傀儡公主，又在哭哭啼啼了。是奶瓶不合嘴，還是搖籃曲不好聽？"
  },
  Voice_5121_AwakerVoiceTitle = {
    Text = "閒話·關於墨菲"
  },
  Voice_5121_UnlockDesc = {
    Text = "獲得喚醒體「墨菲」後解鎖"
  },
  Voice_5122_AwakerVoiceContent = {
    Text = "嗚嗚……我不想面對那些東西……"
  },
  Voice_5122_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_5123_AwakerVoiceContent = {
    Text = "現在，輪到我報答您了。"
  },
  Voice_5123_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5124_AwakerVoiceContent = {
    Text = "力量提升的感覺，如同火焰般熾熱蝕骨。"
  },
  Voice_5124_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_5125_AwakerVoiceContent = {
    Text = "啊……抱歉，請不要亂動！"
  },
  Voice_5125_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5126_AwakerVoiceContent = {
    Text = "觸手可及的溫度……"
  },
  Voice_5126_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5127_AwakerVoiceContent = {
    Text = "庭院中的玫瑰花，正在綻放。"
  },
  Voice_5127_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_5128_AwakerVoiceContent = {
    Text = "幹得不錯，還有餘力繼續前進嗎？"
  },
  Voice_5128_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5129_AwakerVoiceContent = {
    Text = "騎士是一種無形之物，是忠誠、驍勇與美德賦予了它形體。我的武器也是如此，是守護的意志給予了它槍盾之形。"
  },
  Voice_5129_AwakerVoiceTitle = {
    Text = "閒話·關於騎士"
  },
  Voice_5130_AwakerVoiceContent = {
    Text = "詹金、戴安娜、麥克、提尤格、布朗……哇！不好意思，我只是在自言自語！您問我，為什麼念這些名字嗎？因為艾繼絲不想忘記大家……"
  },
  Voice_5130_AwakerVoiceTitle = {
    Text = "閒話·關於朋友"
  },
  Voice_5131_AwakerVoiceContent = {
    Text = "別靠近我！"
  },
  Voice_5131_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5132_AwakerVoiceContent = {
    Text = "討厭死了！"
  },
  Voice_5132_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_5135_AwakerVoiceContent = {
    Text = "感謝您的召喚。若有需要獻聲的場合，煩請您預先告知於我。"
  },
  Voice_5135_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5137_AwakerVoiceContent = {
    Text = "那是......血管裡奔湧的漆黑黏液，湮滅一切呻吟的終極力量！「我」即誕生於此，為破壞而生！哈哈哈！"
  },
  Voice_5137_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_5138_AwakerVoiceContent = {
    Text = "叫我出來，是要賭一把嗎？……什麼，探案？不要啦，太浪費運氣了……"
  },
  Voice_5138_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5139_AwakerVoiceContent = {
    Text = "理論課還挺沒意思的，上課時我都在教室最後面偷偷讀調查記錄。這件事只和你說，千萬別讓朵爾知道。"
  },
  Voice_5139_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5140_AwakerVoiceContent = {
    Text = "品嘗惡果吧！"
  },
  Voice_5141_AwakerVoiceContent = {
    Text = "品嘗惡果吧！"
  },
  Voice_5142_AwakerVoiceContent = {
    Text = "我不曾怪過於麗埃特，她也不過是黑色苦難的受害者罷了，但……她似乎不願意聽我說這些。你能替我轉告她嗎，使者？"
  },
  Voice_5142_AwakerVoiceTitle = {
    Text = "閒話·關於於麗埃特"
  },
  Voice_5142_UnlockDesc = {
    Text = "未實裝語音"
  },
  Voice_5143_AwakerVoiceContent = {Text = "慢點。"},
  Voice_5143_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5144_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_5145_AwakerVoiceContent = {
    Text = "喂！別摸了，弄得亂七八糟的！……算啦，本小姐大人有大量。"
  },
  Voice_5145_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_5146_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_5147_AwakerVoiceContent = {Text = "嘖！"},
  Voice_5147_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5148_AwakerVoiceContent = {
    Text = "自你將我從黑暗中喚醒的那一天起，我便確定了，你能夠將萬物從名為融蝕的絕望中拯救，送入無垢的淨土。我期待這一天的到來。"
  },
  Voice_5148_AwakerVoiceTitle = {
    Text = "閒話·關於守密人·Ⅰ"
  },
  Voice_5149_AwakerVoiceContent = {
    Text = "聞到了……鮮血的味道。"
  },
  Voice_5149_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_5150_AwakerVoiceContent = {
    Text = "目標在哪？作為將我喚醒的回報，我會為你解決掉對方。"
  },
  Voice_5150_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5151_AwakerVoiceContent = {
    Text = "我的帽子已經迫不及待了！"
  },
  Voice_5151_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_5152_AwakerVoiceContent = {
    Text = "這具軀殼，不該為祂以外的存在產生悸動……可你的溫度……"
  },
  Voice_5152_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_5153_AwakerVoiceContent = {
    Text = "怎麼，要打一場？"
  },
  Voice_5153_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_5155_AwakerVoiceContent = {
    Text = "不能原諒。"
  },
  Voice_5156_AwakerVoiceContent = {
    Text = "艾瑞卡目前運轉正常，與彌薩格大學內電氣設備連接良好。需要我打開宿舍的電燈嗎？"
  },
  Voice_5156_AwakerVoiceTitle = {
    Text = "閒話·關於艾瑞卡"
  },
  Voice_5157_AwakerVoiceContent = {
    Text = "接下來，用餐時間到，呵呵……"
  },
  Voice_5157_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5159_AwakerVoiceContent = {
    Text = "不要讓那個戴紫色寬簷帽的女人靠近舞臺！沒有為什麼，只要你不想讓禮帽裡流出黏糊糊的灰質的話，就別讓她過來！"
  },
  Voice_5159_AwakerVoiceTitle = {
    Text = "閒話·關於達芙黛爾"
  },
  Voice_5159_UnlockDesc = {
    Text = "獲得喚醒體「達芙黛爾」後解鎖"
  },
  Voice_5160_AwakerVoiceContent = {
    Text = "你一直都這樣嗎？向所有人託付後背，交付信任？太天真了。"
  },
  Voice_5160_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5161_AwakerVoiceContent = {
    Text = "仇恨或能緩解，但絕不可能消除。"
  },
  Voice_5161_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5162_AwakerVoiceContent = {
    Text = "喚醒體？嗯……是這樣的哦，七點喚醒是最佳時間！我們明早七點去海邊撿貝殼吧！"
  },
  Voice_5162_AwakerVoiceTitle = {
    Text = "閒話·關於喚醒體"
  },
  Voice_5163_AwakerVoiceContent = {
    Text = "賜你永生！"
  },
  Voice_5163_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5166_AwakerVoiceContent = {
    Text = "抱歉，如果艾繼絲在這裡會對您造成困擾的話，我馬上就離開！"
  },
  Voice_5166_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5166_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_5167_AwakerVoiceContent = {
    Text = "您為我提供落腳之處，我很感激。但請原諒，我已經不配再次立於舞臺之上了。"
  },
  Voice_5167_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5168_AwakerVoiceContent = {
    Text = "謝謝您允許我留在這裡，如果能報答您的話，讓艾繼絲做什麼都可以的。需要給您斟茶嗎？"
  },
  Voice_5168_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_5168_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_5169_AwakerVoiceContent = {
    Text = "因為很溫暖，所以捨不得離開。一個人的時候，真的好黑、好冷、好害怕……"
  },
  Voice_5169_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_5169_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_5170_AwakerVoiceContent = {
    Text = "艾繼絲……真的可以回到人群中嗎？我還沒有做好準備，但您卻已經接納了我……既然如此，以後也、也請多多關照……守密人。"
  },
  Voice_5170_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_5170_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_5171_AwakerVoiceContent = {
    Text = "想起來了，我想起來了……！人類污濁的血困住了我…我，我沒能蛻變！怎麼會，我怎麼……我的鰓呢？為什麼它們不動？！為什麼！"
  },
  Voice_5171_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5172_AwakerVoiceContent = {
    Text = "我喜歡吃烤章魚、煮章魚、煎章魚......某些人認為我在故意褻瀆神明，不好意思，因為章魚實在是太美味了，哈哈哈哈哈！"
  },
  Voice_5172_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_5173_AwakerVoiceContent = {
    Text = "蠕蟲。群星。吾乃......尤烏哈希！殺......讓我殺！"
  },
  Voice_5173_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5173_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5174_AwakerVoiceContent = {
    Text = "深紅色的胴體，脈動的觸手，不斷開闔的口器......很好，很好！我已經等不及要撕爛某個人的喉嚨了！"
  },
  Voice_5174_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5174_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5175_AwakerVoiceContent = {
    Text = "哈哈哈哈哈，就是這種感覺！給我再來點......雙倍，不，十倍劑量！"
  },
  Voice_5175_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5175_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5176_AwakerVoiceContent = {
    Text = "我會一直忍受的。"
  },
  Voice_5176_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5177_AwakerVoiceContent = {
    Text = "這奇妙的感覺......還不賴。比黎凡特巫師的顛茄強點。"
  },
  Voice_5177_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5177_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5178_AwakerVoiceContent = {
    Text = "同伴？哼……不需要什麼同伴，我不會被同樣的累贅拖累兩次。"
  },
  Voice_5178_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5178_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_5179_AwakerVoiceContent = {
    Text = "會與你合作，只是因為你展示出了足夠與我相配的力量。不要忘了，這份契約到你力量衰弱之時就會終止，屆時，我會毫不猶豫地斬下你的頭顱。"
  },
  Voice_5179_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_5179_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_5180_AwakerVoiceContent = {
    Text = "我從你的雙眼裡......看到了閃爍的輝光，那是野心和欲望之烈火。凡人，認識你自己！我們才是同類人！"
  },
  Voice_5180_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_5180_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_5181_AwakerVoiceContent = {
    Text = "知道信天翁吧？牠們從不把人類放在眼裡，而是奮力揮動羽翼，迎接暴風雨的挑戰。然而一旦被放逐到地面，落在一片嘲罵聲裡，碩大的垂翼反倒成了可悲的阻礙。\n這個故事沒什麼深意，只是和你在一起很放鬆，隨便聊聊罷了。"
  },
  Voice_5181_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_5181_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_5182_AwakerVoiceContent = {
    Text = "或許，時代真的變了。現如今，羸弱之人也能越過礁石，叱吒於海浪之上，成為青空之王。\n凡人，我等著看你改寫歷史的那天。屆時，我將很榮幸成為你手中的巨刃！"
  },
  Voice_5182_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_5182_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_5183_AwakerVoiceContent = {
    Text = "轉換率太低了，明天到我辦公室報導重新學習。"
  },
  Voice_5183_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_5184_AwakerVoiceContent = {
    Text = "你和另一個朵爾見過面了嗎？所謂「世界的真相」，竟會將如此冷靜理智的朵爾變成完全另一個人……到了最後，你我也會變成那副模樣嗎？"
  },
  Voice_5184_AwakerVoiceTitle = {
    Text = "閒話·關於@2"
  },
  Voice_5184_UnlockDesc = {
    Text = "獲得喚醒體@2後解鎖"
  },
  Voice_5185_AwakerVoiceContent = {
    Text = "主人……我需要命令，請給我下命令。"
  },
  Voice_5185_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5186_AwakerVoiceContent = {
    Text = "機體性能已經提升。"
  },
  Voice_5186_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5189_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5190_AwakerVoiceContent = {
    Text = "更多的夥伴！"
  },
  Voice_5191_AwakerVoiceContent = {
    Text = "更多的夥伴！"
  },
  Voice_5192_AwakerVoiceContent = {
    Text = "抱歉，我不能離開搖籃……這樣子會擋住大家的視線吧，所以我呆在教室最後面就可以了。"
  },
  Voice_5192_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_5193_AwakerVoiceContent = {
    Text = "什麼！君士坦丁堡的地毯，錫蘭島紅茶，安達盧西亞吉事果……一個都沒買到嗎？！嗚……那女人總是輕而易舉就能搞到這些東西，我還以為很常見呢……"
  },
  Voice_5193_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_5194_AwakerVoiceContent = {
    Text = "距離我最初的模樣還差得遠。"
  },
  Voice_5194_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5194_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5195_AwakerVoiceContent = {
    Text = "如此急切，對您這般的才傑而言，未免有些粗鄙了。"
  },
  Voice_5195_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_5196_AwakerVoiceContent = {
    Text = "不管再怎麼提升，這只獸的外貌都不會改變。說到底，它只是我力量的具現而已。"
  },
  Voice_5196_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5196_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5197_AwakerVoiceContent = {
    Text = "感覺像是回到混沌海洋裡一樣，還不賴。"
  },
  Voice_5197_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_5197_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_5198_AwakerVoiceContent = {
    Text = "看在你如此竭盡全力的份上，就勉強認可你作為同行者吧。"
  },
  Voice_5198_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5198_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5199_AwakerVoiceContent = {
    Text = "像打碎迷宮牆壁一樣，打碎力量的壁壘吧。"
  },
  Voice_5199_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5199_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5200_AwakerVoiceContent = {
    Text = "不能隨便撕碎食物，也不能壓碎食堂的凳子……好的，莉莉下次不會了。"
  },
  Voice_5200_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_5200_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_5201_AwakerVoiceContent = {
    Text = "我可以叫您母親嗎？"
  },
  Voice_5201_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_5201_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_5202_AwakerVoiceContent = {
    Text = "有什麼命令嗎，主人？\n「不要帶著它們在室外行走，大家會害怕」？\n莉莉明白了，莉莉這就把它們藏起來。"
  },
  Voice_5202_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5202_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_5203_AwakerVoiceContent = {
    Text = "成為喚醒體，原來是這麼一回事啊。"
  },
  Voice_5203_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5203_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_5204_AwakerVoiceContent = {
    Text = "母親，我能睡在你身邊嗎？一個人的時候，會做黑漆漆的夢。莉莉的手和腳都掉下來了，真的好疼……"
  },
  Voice_5204_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_5204_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_5205_AwakerVoiceContent = {
    Text = "呀！承蒙主人看重，珈倫只是一介卑微的侍女罷了......"
  },
  Voice_5205_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5205_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_5206_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_5207_AwakerVoiceContent = {
    Text = "我需要收集一些雕刻素材，最好是足夠新鮮的。"
  },
  Voice_5207_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_5208_AwakerVoiceContent = {
    Text = "請安靜。"
  },
  Voice_5208_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5209_AwakerVoiceContent = {
    Text = "執迷不悟之人，行徒勞無功之事。"
  },
  Voice_5209_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5209_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5210_AwakerVoiceContent = {
    Text = "事已至此，余多少能理解你的用意。無礙，繼續吧。"
  },
  Voice_5210_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5210_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5211_AwakerVoiceContent = {
    Text = "余看見了你的決心，再次沉睡前，余將成為你的見證人，見證人之子反抗命運的壯舉。但現在，我需要一點休息時間。"
  },
  Voice_5211_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5211_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5212_AwakerVoiceContent = {
    Text = "順應天命，不好嗎？為什麼要反抗命運的意志。"
  },
  Voice_5212_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_5212_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_5213_AwakerVoiceContent = {
    Text = "為實現願望，你竟然能付出如此之多……"
  },
  Voice_5213_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5213_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5214_AwakerVoiceContent = {
    Text = "哈啊？不覺得煩嗎？別再為那傢伙的事打擾我了！……算了，隨你們便，就當是打發時間吧。"
  },
  Voice_5214_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5215_AwakerVoiceContent = {
    Text = "融蝕……那些污濁的黑液時常侵擾余的夢境，不勝其煩。"
  },
  Voice_5215_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_5216_AwakerVoiceContent = {
    Text = "權力是雙刃劍，我又如何不懂呢……只是醒悟得太遲了，太遲了。一旦我放手，他們就會撲上來，把我撕成碎片……如果我從一開始就像您這般清醒，也不至於以那樣悲慘的方式落幕。誒、誒？您說，我以後可以在休息室舉辦沙龍？！這真是……除了親自服侍您外，我還能如何報答您呢……"
  },
  Voice_5216_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_5216_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_5217_AwakerVoiceContent = {
    Text = "您真是位油鹽不進的客人，究竟需要我如何款待，您才肯出讓手中特權呢？權力只會招致禍端，如此淺顯的道理，您不會不明白吧？"
  },
  Voice_5217_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_5217_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_5218_AwakerVoiceContent = {
    Text = "在沙龍開始前，您想聽故事嗎？一個鄉村女孩如何摘下權力桂冠的故事……該從哪裡開始呢，從她被父母逼嫁給耄耋老人講起，還是您更想聽她在貴族花園中綻放的橋段？"
  },
  Voice_5218_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_5218_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_5219_AwakerVoiceContent = {
    Text = "在過去，賓客們都以「紅夫人」之名稱呼我。當然，您也可以叫我「索蕾爾」，畢竟您是我最特別的客人……"
  },
  Voice_5219_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_5219_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_5220_AwakerVoiceContent = {
    Text = "作為沙龍的女主人，讓每位客人滿意是我的職責。"
  },
  Voice_5220_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5220_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_5221_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_5222_AwakerVoiceContent = {
    Text = "主君？是我的站姿有問題嗎？"
  },
  Voice_5222_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_5223_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5224_AwakerVoiceContent = {Text = "壞運氣~"},
  Voice_5224_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5225_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_5226_AwakerVoiceContent = {
    Text = "我記得這種感受，那個光榮的時刻就要來了……"
  },
  Voice_5226_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5226_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5227_AwakerVoiceContent = {
    Text = "雖然鰓痕依然沒有出現，但我已經不會為此而焦慮了。這膜翼會化作守護你的護盾，守密人。"
  },
  Voice_5227_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5227_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5228_AwakerVoiceContent = {
    Text = "你……的確比其他人類更有耐心……居然為我傾注這麼多資源，你真的……不討厭我？"
  },
  Voice_5228_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5228_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5229_AwakerVoiceContent = {
    Text = "啊？儀式結束了，為什麼我還是沒能長出鰓？蛻變又失敗了嗎！可惡！可惡！可惡！"
  },
  Voice_5229_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5229_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5230_AwakerVoiceContent = {
    Text = "那個聲音又在呼喚我了……那來自幽邃深海的瓊音！"
  },
  Voice_5230_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_5230_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_5231_AwakerVoiceContent = {
    Text = "猜——錯——啦——"
  },
  Voice_5232_AwakerVoiceContent = {
    Text = "來自西岱的雕砌者珊，為您獻上刻刀。您或許充滿缺陷，但仍值得雕琢。"
  },
  Voice_5232_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5238_AwakerVoiceContent = {
    Text = "不聽話的孩子們，集合啦~"
  },
  Voice_5238_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_5239_AwakerVoiceContent = {
    Text = "真正的藝術無需解釋。"
  },
  Voice_5239_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_5240_AwakerVoiceContent = {
    Text = "真正的藝術無需解釋。"
  },
  Voice_5240_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5241_AwakerVoiceContent = {
    Text = "奧瑞塔，可以幫上忙嗎？"
  },
  Voice_5241_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5242_AwakerVoiceContent = {
    Text = "吹響號角！"
  },
  Voice_5243_AwakerVoiceContent = {
    Text = "不惜代價！"
  },
  Voice_5244_AwakerVoiceContent = {
    Text = "沐浴在陽光下的感覺......原來這樣柔軟，令人想要落淚。"
  },
  Voice_5244_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5244_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5245_AwakerVoiceContent = {
    Text = "為表感謝......我要在我的痛苦深處，為您築起一座隱秘的祭壇。"
  },
  Voice_5245_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5245_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5246_AwakerVoiceContent = {
    Text = "哥哥的血肉和我的身體，融合得更加契合緊密了......"
  },
  Voice_5246_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_5246_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_5247_AwakerVoiceContent = {
    Text = "我比您想像的要堅韌。所以、使用我的時候，可以再用力一點，不必客氣哦。"
  },
  Voice_5247_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5247_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5248_AwakerVoiceContent = {
    Text = "是我的錯覺嗎？對鮮血的渴求似乎減輕了一些。"
  },
  Voice_5248_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5248_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5249_AwakerVoiceContent = {
    Text = "從還沒正式入學時，我就期待著你的出現。現在看來，我們配合得還算不錯吧？搭檔。"
  },
  Voice_5249_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5250_AwakerVoiceContent = {
    Text = "真不像樣。"
  },
  Voice_5250_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_5251_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5252_AwakerVoiceTitle = {
    Text = "打擊·躁狂"
  },
  Voice_5253_AwakerVoiceTitle = {
    Text = "打擊·抑鬱"
  },
  Voice_5254_AwakerVoiceContent = {
    Text = "盡情傷害我吧！"
  },
  Voice_5255_AwakerVoiceContent = {
    Text = "艾繼絲很害怕。不，不是害怕大家，是害怕自己再次給你們帶去恐懼和悲傷。"
  },
  Voice_5255_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_5256_AwakerVoiceContent = {
    Text = "這個時代的童話書，比我那時候看的要有趣多了！啊、啊！主君別誤會！我已經過了睡前聽故事的年紀了！"
  },
  Voice_5256_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_5257_AwakerVoiceContent = {
    Text = "盡情傷害我吧！"
  },
  Voice_5258_AwakerVoiceContent = {
    Text = "呼……艾繼絲沒有給大家添麻煩吧？"
  },
  Voice_5258_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5259_AwakerVoiceContent = {
    Text = "你一直懷揣著那令人發笑的信任，在我身邊停留……好吧，或許，為你所用並不是一件壞事。但你記住：我不能容忍任何背叛，尤其是來自於你的。"
  },
  Voice_5259_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_5259_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_5260_AwakerVoiceContent = {
    Text = "我只後悔當時沒有把他們的屍骨釘上木樁，掛上城牆！所有背叛我的、踐踏我的、侮辱我的，我一個都不會放過！"
  },
  Voice_5260_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_5260_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_5261_AwakerVoiceContent = {
    Text = "沒錯，我也曾經在那些人面前搖尾乞憐，這沒有什麼好否認的。他們利用了我的無知，而我也讓他們付出了代價。"
  },
  Voice_5261_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_5261_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_5262_AwakerVoiceContent = {
    Text = "你以為幾句花言巧語，幾天虛假的優待，就能讓我自願重新戴上枷鎖，成為你的玩物嗎？"
  },
  Voice_5262_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_5262_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_5263_AwakerVoiceContent = {
    Text = "所有試圖掌控我、利用我的人，最後都被我親手送往了冥界——我不介意也送你一程。"
  },
  Voice_5263_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5263_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_5264_AwakerVoiceContent = {
    Text = "啊……抱歉，請不要亂動！"
  },
  Voice_5264_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_5265_AwakerVoiceContent = {
    Text = "別碰我！"
  },
  Voice_5265_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5266_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_5267_AwakerVoiceContent = {
    Text = "臣服吧……歡迎來到享樂與夢的國度。"
  },
  Voice_5267_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5268_AwakerVoiceContent = {
    Text = "此乃萬千死者徘徊失鄉之都。"
  },
  Voice_5268_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_5269_AwakerVoiceContent = {
    Text = "艾繼絲會加油的！"
  },
  Voice_5269_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_5270_AwakerVoiceContent = {
    Text = "那個……我沒有辦法控制自己吸收生命力，所以請不要把手伸進搖籃裡，這麼做你會生病的。"
  },
  Voice_5270_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_5271_AwakerVoiceContent = {
    Text = "希望在我們進行這場對話時，她的運行不要出錯。我可愛又可憎的助手啊，已經沒有多餘的實驗室供她爆破了。"
  },
  Voice_5271_AwakerVoiceTitle = {
    Text = "閒話·關於艾瑞卡"
  },
  Voice_5271_UnlockDesc = {
    Text = "獲得喚醒體「艾瑞卡」後解鎖"
  },
  Voice_5272_AwakerVoiceContent = {
    Text = "手臂，惱人的手臂！它們總愛拽住我的頭髮不放。連自己的手都控制不了，我真是個一無是處的傢伙......不如......"
  },
  Voice_5272_AwakerVoiceTitle = {
    Text = "閒話·關於自己"
  },
  Voice_5274_AwakerVoiceContent = {
    Text = "感謝您的引導，我終於理解了菲茵特的選擇。我把這一切當成理所當然，沒想到給她造成了那麼大的心理負擔。從今往後，我會試著為自己而活……"
  },
  Voice_5274_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_5274_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_5275_AwakerVoiceContent = {
    Text = "在漫長漫長的時光中，我和菲茵特都只有彼此……不過，現在我有了新的重要的人了……守密人，請容我收回前言，您和他們不一樣，您並非只在意我的歌喉與禮裙，而是注視著我。因此，我也會注視著您。"
  },
  Voice_5275_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_5275_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_5276_AwakerVoiceContent = {
    Text = "沉眠夢境中的群星，去應去之處，指向神國之所在！"
  },
  Voice_5276_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_5277_AwakerVoiceContent = {
    Text = "我為何隨時隨地都穿著這身禮服？這樣，便能隨時為您獻聲了。"
  },
  Voice_5277_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5277_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_5278_AwakerVoiceContent = {
    Text = "我自己想做的事情？……抱歉，我不明白您在說什麼……實際上，菲茵特也詢問過我很多次這個問題，可是我只希望她能早日痊癒……"
  },
  Voice_5278_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_5278_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_5279_AwakerVoiceContent = {
    Text = "在荒星的時候，那些大人物的憐憫給了我們姐妹二人生存的資源。最後，也是他們給了我逃離荒星的機會，雖然僅限一人。他們都是我的恩人，就像給了我棲身之所的守密人您一樣。"
  },
  Voice_5279_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_5279_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_5280_AwakerVoiceContent = {
    Text = "您是提供我住處的好心人，艾繼絲會聽您的話。如果艾繼絲能更有用一點就好了……"
  },
  Voice_5280_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5281_AwakerVoiceContent = {
    Text = "別忘記準備場地。你預約的場地不會比艾爾沃斯那個還要小吧？"
  },
  Voice_5281_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5281_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_5282_AwakerVoiceContent = {
    Text = "很好，珈倫現在更有幹勁了，可以一天打掃二十間屋子！"
  },
  Voice_5282_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5282_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5283_AwakerVoiceContent = {
    Text = "這是與湖水同樣古老、屬於「我們」的音樂。主人，一起來跳舞吧！趁珈倫的聲音還沒有被「祂」奪走......"
  },
  Voice_5283_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5283_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5284_AwakerVoiceContent = {
    Text = "主人！珈倫的聲音......在消失......救......"
  },
  Voice_5284_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5284_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5285_AwakerVoiceContent = {
    Text = "珈倫的眼力提升了......主人，你是不是又忘記梳頭了！"
  },
  Voice_5285_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_5285_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_5286_AwakerVoiceContent = {
    Text = "就算變強了，珈倫也一點都不想復仇哦。珈倫只想唱歌！跳舞！開派對！"
  },
  Voice_5286_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5286_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5287_AwakerVoiceContent = {
    Text = "為了在一切毀滅後仍存續於世，我將靈與血分給了太多太多人。我如今的力量，與剛接受這意志時的可相去甚遠……"
  },
  Voice_5287_AwakerVoiceTitle = {
    Text = "閒話·關於過去"
  },
  Voice_5288_AwakerVoiceContent = {
    Text = "不用指望在教學樓裡找到我。這裡充滿了腐爛老學究的臭味，我一天都待不下去。"
  },
  Voice_5288_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_5289_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_5290_AwakerVoiceContent = {
    Text = "我的故國信仰著「神明」，與之相對應的，我所追隨的王自然是一名「通神之人」。"
  },
  Voice_5290_AwakerVoiceTitle = {
    Text = "閒話·關於永恆之國"
  },
  Voice_5291_AwakerVoiceContent = {
    Text = "您這裡倒是人才濟濟，值得一場盛大的沙龍……放心，屆時，邀請函一定會由我的僕從送到您手中。"
  },
  Voice_5291_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_5292_AwakerVoiceContent = {Text = "來吧！"},
  Voice_5292_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5293_AwakerVoiceContent = {
    Text = "如果有更多夥伴的話……"
  },
  Voice_5293_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_5294_AwakerVoiceContent = {
    Text = "我和那傢伙可不一樣，她供應的只有充滿敵意的戰慄和恐懼，我給予的可是肌膚相親、甜蜜滾燙的疼痛與愛哦？"
  },
  Voice_5294_AwakerVoiceTitle = {
    Text = "閒話·關於旺達"
  },
  Voice_5294_UnlockDesc = {
    Text = "獲得喚醒體「旺達」後解鎖"
  },
  Voice_5295_AwakerVoiceContent = {
    Text = "別想著就這麼過去了！這次受的屈辱，我會一一討回來！"
  },
  Voice_5295_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_5296_AwakerVoiceContent = {
    Text = "你的手如你的靈魂一般溫暖，蒼白之火，我……感謝你的觸碰。"
  },
  Voice_5296_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_5297_AwakerVoiceContent = {
    Text = "在教室打橋牌有什麼不可以？有桌子，有人，我帶了牌，這就意味著“牌局開始”！"
  },
  Voice_5297_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_5299_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5300_AwakerVoiceContent = {
    Text = "凝視深淵！"
  },
  Voice_5300_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5301_AwakerVoiceContent = {
    Text = "凝視深淵！"
  },
  Voice_5301_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_5302_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_5303_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5304_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5305_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_5306_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5307_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_5308_AwakerVoiceContent = {
    Text = "弱小的靈魂聚在一起，除了聒噪還能有什麼用呢，唉……"
  },
  Voice_5308_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_5311_AwakerVoiceContent = {
    Text = "戰爭總是會帶來痛苦的，忍受折磨是戰士的義務。即使失去雙手、失去雙足、失去一切，我也依然為你、為世界的正義而戰。"
  },
  Voice_5311_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_5312_AwakerVoiceContent = {
    Text = "這就是你獻給祂的貢品？"
  },
  Voice_5312_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_5313_AwakerVoiceContent = {
    Text = "你以為這樣便可改變未來？"
  },
  Voice_5313_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5314_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_5315_AwakerVoiceContent = {
    Text = "呵，算你識相。"
  },
  Voice_5315_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_5316_AwakerVoiceContent = {
    Text = "向主子進貢，理所當然。"
  },
  Voice_5316_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_5317_AwakerVoiceContent = {
    Text = "你努力討好我的模樣，還挺可愛的。"
  },
  Voice_5317_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5318_AwakerVoiceContent = {
    Text = "布朗尼蛋糕、焦糖布丁、撒哈蛋糕、巧克力慕斯、曲奇……必須每桌都有！"
  },
  Voice_5318_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5318_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5319_AwakerVoiceContent = {
    Text = "幫我看看，我的裙子都打理好了嗎？不能有褶皺，不能有鬆散……怎麼了？你有什麼不滿意嗎？"
  },
  Voice_5319_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5319_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5320_AwakerVoiceContent = {
    Text = "歡迎來到本小姐的最終啟靈儀式！這一切都是本小姐精心設計的。當然，守密人也有那麼一點點功勞……"
  },
  Voice_5320_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5320_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5321_AwakerVoiceContent = {
    Text = "桌椅要用和我氣質相配的蕾絲妝點起來，盆栽必須用紅色的吊蘭……快去準備！"
  },
  Voice_5321_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_5321_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_5322_AwakerVoiceContent = {
    Text = "去預約賓客啦！怎麼連這麼點小事都做不好？"
  },
  Voice_5322_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5322_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5323_AwakerVoiceContent = {
    Text = "無路可逃！"
  },
  Voice_5324_AwakerVoiceContent = {
    Text = "無路可逃！"
  },
  Voice_5325_AwakerVoiceContent = {
    Text = "我會努力的！為了不辜負主君的期望。"
  },
  Voice_5325_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5325_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_5326_AwakerVoiceContent = {
    Text = "我還挺喜歡那女人的，我們有那個，那個什麼……對，共同語言！"
  },
  Voice_5326_AwakerVoiceTitle = {
    Text = "閒話·關於旺達"
  },
  Voice_5326_UnlockDesc = {
    Text = "獲得喚醒體「旺達」後解鎖"
  },
  Voice_5327_AwakerVoiceContent = {
    Text = "無禮之徒！"
  },
  Voice_5328_AwakerVoiceContent = {
    Text = "無禮之徒！"
  },
  Voice_5329_AwakerVoiceContent = {
    Text = "化為殘骸。"
  },
  Voice_5329_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_5330_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5331_AwakerVoiceContent = {
    Text = "鑽破現實的壁壘吧！"
  },
  Voice_5331_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5332_AwakerVoiceContent = {
    Text = "近期有渡海的打算嗎？能否答應我的不情之請，讓我同行？只要能讓我到大海上……"
  },
  Voice_5332_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_5332_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_5333_AwakerVoiceContent = {
    Text = "如果你還信任我，請允許我成為旅途的道標。不過，就算是如此簡單的工作，我也曾失職過……"
  },
  Voice_5333_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_5333_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_5334_AwakerVoiceContent = {
    Text = "不想去大海上嗎？讓我看看如今的海圖……南緯47度9分，西經126度43分，就是這裡。"
  },
  Voice_5334_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5334_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_5335_AwakerVoiceContent = {
    Text = "過去的我曾引發了不少災難，甚至差點毀滅了某些文明……我……如果說不是故意的，是否已經太晚了？"
  },
  Voice_5335_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_5335_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_5336_AwakerVoiceContent = {
    Text = "我是駐守永恆之國入口之人，為歸鄉者指引方向。多麼可笑啊，身負此等職責之人，竟然會遺忘故鄉所在……\n你……會成為我的燈塔嗎？"
  },
  Voice_5336_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_5336_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_5337_AwakerVoiceContent = {
    Text = "星團啊。"
  },
  Voice_5337_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_5338_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_5339_AwakerVoiceContent = {
    Text = "濃霧啊。"
  },
  Voice_5339_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5340_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5341_AwakerVoiceContent = {
    Text = "為大多數人擔任護航的庇佑者都沒有什麼區別，但那個女人除外。如果可以，請為我安排其他航線吧。"
  },
  Voice_5341_AwakerVoiceTitle = {
    Text = "閒話·關於彌利亞姆"
  },
  Voice_5341_UnlockDesc = {
    Text = "獲得喚醒體「彌利亞姆」後解鎖"
  },
  Voice_5342_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_5343_AwakerVoiceContent = {
    Text = "無所謂。"
  },
  Voice_5343_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5344_AwakerVoiceContent = {
    Text = "把手拿開。"
  },
  Voice_5344_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_5345_AwakerVoiceContent = {
    Text = "在我回到海底宮殿之前，勉強借你這貧弱的人類一些深海的力量，僅此而已。"
  },
  Voice_5345_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5346_AwakerVoiceContent = {Text = "來！"},
  Voice_5346_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5347_AwakerVoiceContent = {
    Text = "喜歡？我喜歡疼痛，喜歡紅腫發燙的皮膚，喜歡夾雜享受與痛苦的呻吟。疼痛才是最原始最真實的欲望吧？"
  },
  Voice_5347_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_5348_AwakerVoiceContent = {
    Text = "加入奧瑞塔吧！"
  },
  Voice_5349_AwakerVoiceContent = {
    Text = "加入奧瑞塔吧！"
  },
  Voice_5350_AwakerVoiceContent = {
    Text = "那個大姐姐，總是兇兇地瞪著我。可不知道為什麼，我總有種親切的感覺。是因為像母親？"
  },
  Voice_5350_AwakerVoiceTitle = {
    Text = "閒話·關於希洛"
  },
  Voice_5350_UnlockDesc = {
    Text = "獲得喚醒體「希洛」後解鎖"
  },
  Voice_5351_AwakerVoiceContent = {
    Text = "腦子變得更靈活了，感覺還不錯。"
  },
  Voice_5351_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5351_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5352_AwakerVoiceContent = {
    Text = "比起出勤，我更喜歡實驗室的工作——難不成你以為，那些輔助工具是從海里撈出來的？"
  },
  Voice_5352_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5352_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5353_AwakerVoiceContent = {
    Text = "不管是螺絲還是釘子，當然是多多益善啦。"
  },
  Voice_5353_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5354_AwakerVoiceContent = {
    Text = "軀體已經難以承載這份力量了，但現在還不是更換人偶的時候。愣著幹嘛，來幫我捧著這條腿，我需要調試一下。"
  },
  Voice_5354_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5354_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5355_AwakerVoiceContent = {
    Text = "指引光明的擔子能將至純的聖人壓垮，如果你感到疲憊了，我的白焰，請務必與我訴說。我必將盡我所能為你排解苦悶，分擔萬千福祉共同的重量。"
  },
  Voice_5355_AwakerVoiceTitle = {
    Text = "閒話·關於疲憊"
  },
  Voice_5356_AwakerVoiceContent = {
    Text = "您的認可，是我作為騎士存在的理由。"
  },
  Voice_5356_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5356_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5357_AwakerVoiceContent = {
    Text = "沐浴在了神靈的輝光之下，這就是吾主所擁有的神力嗎？如此磅礴，如此神聖。"
  },
  Voice_5357_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5357_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5358_AwakerVoiceContent = {
    Text = "神靈的門扉，已在咫尺之間。"
  },
  Voice_5358_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5358_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5359_AwakerVoiceContent = {
    Text = "愈來愈明亮，愈來愈清晰……"
  },
  Voice_5359_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_5359_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_5360_AwakerVoiceContent = {
    Text = "竟能以喚醒體之身重歸完人……我已經聽到了，神國為我奏響的聖音……"
  },
  Voice_5360_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5360_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5361_AwakerVoiceContent = {
    Text = "祂將迎我入聖堂，許我側榻安眠……"
  },
  Voice_5361_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5361_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5362_AwakerVoiceContent = {
    Text = "請放心，我們幾個都是很有用的。我可以縫紉、打掃，另一個我擅長戰鬥，還有其他的我......"
  },
  Voice_5362_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5363_AwakerVoiceContent = {
    Text = "我討厭明亮、柔軟的東西。溫柔像一面鏡子，所有的醜陋、貪婪和脆弱都在它面前無所遁形。"
  },
  Voice_5363_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5364_AwakerVoiceContent = {
    Text = "想摸布朗嗎？我可做不了主，你得親自問問她。"
  },
  Voice_5364_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_5365_AwakerVoiceContent = {
    Text = "想討我歡心？那就跪下，伸出你的脖頸，並確保在我吸乾你之前保持安靜。"
  },
  Voice_5365_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5366_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5367_AwakerVoiceContent = {
    Text = "我昨晚做了一個夢，那是我遊蕩群星的起點。"
  },
  Voice_5367_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5367_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_5368_AwakerVoiceContent = {
    Text = "艾繼絲可以幫上忙嗎？"
  },
  Voice_5368_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5368_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_5369_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5371_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5372_AwakerVoiceContent = {Text = "退後。"},
  Voice_5372_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_5373_AwakerVoiceContent = {
    Text = "沒有人會受到傷害…的……世界……"
  },
  Voice_5373_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5374_AwakerVoiceContent = {
    Text = "（嬌嗔）"
  },
  Voice_5374_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5375_AwakerVoiceContent = {
    Text = "請允許我安置一尊吾主的祭壇。這是以虔誠信徒之力雕就的法像，不會為你帶來任何詛咒。"
  },
  Voice_5375_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_5376_AwakerVoiceContent = {
    Text = "只要一點點……"
  },
  Voice_5377_AwakerVoiceContent = {
    Text = "我的扳手還沒就位！"
  },
  Voice_5377_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_5378_AwakerVoiceContent = {
    Text = "化學、物理學、銀芯應用學……這個時代，已經不需要學習騎士七技了嗎？原來如此。那麼，請主君也為我安排相應的課程吧！"
  },
  Voice_5378_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_5379_AwakerVoiceContent = {
    Text = "奧瑞塔可是旅行過的！不是隨著海浪飄走，而是大篷車旅行哦！"
  },
  Voice_5379_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5379_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_5380_AwakerVoiceContent = {
    Text = "燈塔水母、冠水母、桃花水母，大家都是成群結隊的呢，當然，奧瑞塔也是！奧瑞塔也要和大家在一起！"
  },
  Voice_5380_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_5380_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_5381_AwakerVoiceContent = {
    Text = "以前的事情？不太想得起來了……但是奧瑞塔記得，自己有在水族館工作過哦！日薪是2片什！"
  },
  Voice_5381_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_5381_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_5382_AwakerVoiceContent = {
    Text = "悄悄和你說，奧瑞塔其實是亞蘭、特蘭斯……唔，總之奧瑞塔是海底人哦！只要奧瑞塔乖乖聽話，多吃蔬菜，多交朋友，亞特斯什麼的就會歡迎奧瑞塔！"
  },
  Voice_5382_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_5382_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_5383_AwakerVoiceContent = {
    Text = "奧瑞塔的家、水族館的夥伴、奧瑞塔最喜歡的水母們，大家都不見了……你也會不見嗎？不可以永遠陪奧瑞塔一起玩嗎？"
  },
  Voice_5383_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_5383_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_5384_AwakerVoiceContent = {
    Text = "贏了嗎？太好了……"
  },
  Voice_5384_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5387_AwakerVoiceContent = {
    Text = "為了和平。"
  },
  Voice_5388_AwakerVoiceContent = {
    Text = "為了正義。"
  },
  Voice_5389_AwakerVoiceContent = {
    Text = "我知道你就在我體內！"
  },
  Voice_5389_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5390_AwakerVoiceContent = {
    Text = "人類、偽神、喚醒體乃至融蝕……這世間所有，都將成為我重鑄永恆國土的基石。"
  },
  Voice_5390_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_5391_AwakerVoiceContent = {
    Text = "甦醒吧，甦醒吧，我知道你就在我體內！"
  },
  Voice_5391_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_5392_AwakerVoiceContent = {
    Text = "尤烏哈希......他有點像我的哥哥，總讓我想起那些陰暗、冷淡而失眠的日子。"
  },
  Voice_5392_AwakerVoiceTitle = {
    Text = "閒話·關於尤烏哈希"
  },
  Voice_5392_UnlockDesc = {
    Text = "獲得喚醒體「尤烏哈希」後解鎖"
  },
  Voice_5393_AwakerVoiceContent = {
    Text = "我們的關係，就像福爾摩斯和華生吧？您有關注近期流行的雜誌嗎？"
  },
  Voice_5393_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5394_AwakerVoiceContent = {
    Text = "匍匐於美吧。"
  },
  Voice_5395_AwakerVoiceContent = {
    Text = "匍匐於美吧。"
  },
  Voice_5396_AwakerVoiceContent = {
    Text = "厭惡，形容動詞，意為對事物產生討厭。討厭，動詞，意為討厭和避忌事物時的感情。反感，名詞，討厭的感覺，<Del:討厭被壓制讓我破壞讓我破壞讓我>——抱歉，我恐怕我不明白什麼是「討厭」。"
  },
  Voice_5396_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5397_AwakerVoiceContent = {
    Text = "終究還是……"
  },
  Voice_5397_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_5398_AwakerVoiceContent = {
    Text = "變得更加不同了。"
  },
  Voice_5398_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5399_AwakerVoiceContent = {
    Text = "記住我的名字，戈利亞。這個名字註定會踏平人類微不足道的歷史。"
  },
  Voice_5399_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5400_AwakerVoiceContent = {
    Text = "請不要有顧慮。"
  },
  Voice_5400_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_5401_AwakerVoiceContent = {
    Text = "希望你不會辜負自身的潛質和人類的期望，新一任守密人。"
  },
  Voice_5401_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5402_AwakerVoiceContent = {Text = "超載。"},
  Voice_5403_AwakerVoiceContent = {
    Text = "超速運轉。"
  },
  Voice_5404_AwakerVoiceContent = {
    Text = "嗯，你從錢包裡翻到的照片？啊，那是以前的我。現在的外貌是我的賭友、也是我的對手為我塑造的哦。"
  },
  Voice_5404_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_5404_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_5405_AwakerVoiceContent = {
    Text = "正好——要來賭一盤嗎？賭贏了我就告訴你一個秘密哦？\n不過要小心，別被艾爾瓦抓到了~"
  },
  Voice_5405_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_5405_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_5406_AwakerVoiceContent = {
    Text = "你很在意這身皮毛嗎？要不要摸摸看？別擔心，我可是很大方的！"
  },
  Voice_5406_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5406_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_5407_AwakerVoiceContent = {
    Text = "當然也有好處，我不是遇到了我的華生嗎？跟這件事比起來，生死與外貌都不算什麼，對吧？"
  },
  Voice_5407_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_5407_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_5408_AwakerVoiceContent = {
    Text = "你問我會後悔嗎？完全不會。人生總是一帆風順的話，也太無聊了不是嗎？"
  },
  Voice_5408_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_5408_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_5409_AwakerVoiceContent = {
    Text = "在我的時代，學校是訓練戰士的場所，看來現在也如此。"
  },
  Voice_5409_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_5410_AwakerVoiceContent = {
    Text = "梅森……不，這樣就很好，至少我們又能在一起了，「24」。"
  },
  Voice_5410_AwakerVoiceTitle = {
    Text = "閒話·關於「24」"
  },
  Voice_5410_UnlockDesc = {
    Text = "獲得喚醒體「24」後解鎖"
  },
  Voice_5411_AwakerVoiceContent = {
    Text = "我做得不錯吧？那麼，報酬。——怎麼，天下可沒有白吃的午餐！"
  },
  Voice_5411_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5412_AwakerVoiceContent = {
    Text = "我來自西岱。在那裡，所有人都想成為演員，沒人甘心只當觀眾。事實上，我們都只是這座城市的可憐注腳罷了。"
  },
  Voice_5412_AwakerVoiceTitle = {
    Text = "閒話·關於過去"
  },
  Voice_5413_AwakerVoiceContent = {
    Text = "您見過古代石刻嗎？與山體相融，依託自然逃過了時間的消磨，多麼美妙的造物啊……只可惜，還是不夠……"
  },
  Voice_5413_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_5414_AwakerVoiceContent = {
    Text = "鴿子，沒有飛回來呢……"
  },
  Voice_5414_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_5415_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_5416_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5417_AwakerVoiceContent = {
    Text = "執行命令！"
  },
  Voice_5417_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5418_AwakerVoiceContent = {Text = "笨蛋"},
  Voice_5418_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5419_AwakerVoiceContent = {
    Text = "……啊？你在叫我嗎？我在修摩托沒聽見……話說，好心的陌生人，你看到我的扳手了嗎？"
  },
  Voice_5419_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5419_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_5420_AwakerVoiceContent = {
    Text = "我的記憶總是很模糊，只能專注在當前的事情上。不過，我會盡力把你的名字刻在腦海里的……叫什麼來著？"
  },
  Voice_5420_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_5420_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_5421_AwakerVoiceContent = {
    Text = "你看上去有些面善，不過我記不起來你的名字了……你是我的助手？那能請你幫我拿七個螺帽來嗎？"
  },
  Voice_5421_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_5421_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_5422_AwakerVoiceContent = {
    Text = "我把你的名字刻在了幻影號上。有朝一日我們一起出去冒險的時候，我就不會忘記怎麼稱呼你了。"
  },
  Voice_5422_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_5422_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_5423_AwakerVoiceContent = {
    Text = "很熟悉，很熟悉，我們之間一定發生過什麼吧？給我點時間回憶一下……啊，是你啊，守密人！"
  },
  Voice_5423_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_5423_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_5424_AwakerVoiceContent = {
    Text = "您真是個不坦誠的孩子。幸好，我有足夠的時間與耐心等待您……"
  },
  Voice_5424_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5425_AwakerVoiceContent = {
    Text = "“皆大歡喜”，不是嗎？"
  },
  Voice_5425_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5426_AwakerVoiceContent = {
    Text = "斬獲了不錯的頭顱呢……雖然無法與我最好的收藏相比，但是尋找新藏品的旅行總是令人興奮的。下次也邀請我吧。"
  },
  Voice_5426_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5428_AwakerVoiceContent = {
    Text = "專業的女僕會幫主人掃清一切，包括壞人哦~"
  },
  Voice_5428_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5429_AwakerVoiceContent = {
    Text = "我們現在算是同夥了吧。哪天你淪落街頭，我不會讓你靠吃垃圾為生的。"
  },
  Voice_5429_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5430_AwakerVoiceContent = {
    Text = "繁衍吧，生長吧，我的小樹苗。"
  },
  Voice_5430_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_5431_AwakerVoiceContent = {
    Text = "繁衍吧，生長吧，我的小樹苗。"
  },
  Voice_5431_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5432_AwakerVoiceContent = {
    Text = "感覺骰運上升了一點！"
  },
  Voice_5432_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_5433_AwakerVoiceContent = {
    Text = "嗚呼！手氣很旺呢！"
  },
  Voice_5433_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_5434_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5435_AwakerVoiceContent = {
    Text = "不許靠近我。"
  },
  Voice_5436_AwakerVoiceContent = {
    Text = "不許靠近我。"
  },
  Voice_5437_AwakerVoiceContent = {
    Text = "我必須控訴您，守密人。您對我實在太溫柔了，這讓我很不安——對我而言，唯有肉體的疼痛才是真實永恆的。"
  },
  Voice_5437_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5438_AwakerVoiceContent = {
    Text = "很好，伺候得不錯。"
  },
  Voice_5438_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_5439_AwakerVoiceContent = {
    Text = "這點程度可是遠遠不夠的。"
  },
  Voice_5439_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_5440_AwakerVoiceContent = {
    Text = "說吧，想要什麼獎勵？"
  },
  Voice_5440_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5441_AwakerVoiceContent = {
    Text = "噫！這滿地的髒污與穢亂......我的雙腳無處安放。那麼，獻出你柔軟的背脊吧，凡人。"
  },
  Voice_5441_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5442_AwakerVoiceContent = {
    Text = "終於……找到了！"
  },
  Voice_5442_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5443_AwakerVoiceContent = {
    Text = "就連布朗的皮毛都變順滑了。"
  },
  Voice_5443_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5443_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5444_AwakerVoiceContent = {
    Text = "做保安的話有些勉強，但跑腿送信的活可以都交給我做。"
  },
  Voice_5444_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5444_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5445_AwakerVoiceContent = {
    Text = "瞧你面對布朗時的那副樣子。\n……嘿嘿，布朗大人今晚要吃膽小鬼的腳指頭，看看是誰會這麼倒楣呢？"
  },
  Voice_5445_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5445_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5446_AwakerVoiceContent = {
    Text = "不知道能不能長高一些。"
  },
  Voice_5446_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_5446_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_5447_AwakerVoiceContent = {
    Text = "是要準備幹活了嗎？好吧好吧，布朗，打起幹勁！"
  },
  Voice_5447_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5447_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5448_AwakerVoiceContent = {
    Text = "阿格里帕？不好意思，我親手送走的人太多了，他們大多面目模糊，沒有什麼值得銘記的對手。"
  },
  Voice_5448_AwakerVoiceTitle = {
    Text = "閒話·關於阿格里帕"
  },
  Voice_5448_UnlockDesc = {
    Text = "獲得喚醒體「阿格里帕」後解鎖"
  },
  Voice_5449_AwakerVoiceContent = {
    Text = "危險的船員……不，只是從航行安全的角度出發……"
  },
  Voice_5449_AwakerVoiceTitle = {
    Text = "閒話·關於法洛思"
  },
  Voice_5449_UnlockDesc = {
    Text = "獲得喚醒體「法洛思」後解鎖"
  },
  Voice_5450_AwakerVoiceContent = {
    Text = "別過來！"
  },
  Voice_5450_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_5451_AwakerVoiceContent = {
    Text = "請小心！"
  },
  Voice_5451_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5452_AwakerVoiceContent = {
    Text = "您的指令我已經完成了……啊，我又弄得一團糟了，對嗎？"
  },
  Voice_5452_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5453_AwakerVoiceContent = {
    Text = "啊，這正是我需要的零件，謝謝你！……誒？我叫你幫忙找的？我一點印象也沒有耶，你是不是記錯啦？"
  },
  Voice_5453_AwakerVoiceTitle = {
    Text = "閒話·關於零件"
  },
  Voice_5454_AwakerVoiceContent = {
    Text = "靈感，源源不斷......"
  },
  Voice_5454_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5455_AwakerVoiceContent = {
    Text = "品味不錯。"
  },
  Voice_5455_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_5456_AwakerVoiceContent = {
    Text = "您為了我選擇了最合適的刻刀。"
  },
  Voice_5456_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_5457_AwakerVoiceContent = {
    Text = "我討厭失控。不過，你的存在讓我發現，些許微妙的失控，也能帶來別樣的樂趣。"
  },
  Voice_5457_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5458_AwakerVoiceContent = {
    Text = "有稍微長大些嗎？"
  },
  Voice_5458_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_5459_AwakerVoiceContent = {
    Text = "抱歉，我很難長身體……"
  },
  Voice_5459_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_54601_AwakerVoiceContent = {
    Text = "以此來認知世界。"
  },
  Voice_54601_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_54602_AwakerVoiceContent = {
    Text = "以此來認知世界。"
  },
  Voice_54602_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_54605_AwakerVoiceContent = {
    Text = "客官請慢用！"
  },
  Voice_54605_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_54606_AwakerVoiceContent = {
    Text = "客官請慢用！"
  },
  Voice_54606_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_54607_AwakerVoiceContent = {
    Text = "接下來，對世界本質進行解算！"
  },
  Voice_54607_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_54608_AwakerVoiceContent = {
    Text = "接下來，對世界本質進行解算！"
  },
  Voice_54608_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_54609_AwakerVoiceContent = {
    Text = "殉身！交還吾主——"
  },
  Voice_54609_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_5460_AwakerVoiceContent = {
    Text = "謝、謝謝款待……"
  },
  Voice_5460_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_54610_AwakerVoiceContent = {
    Text = "殉身！交還吾主——"
  },
  Voice_54610_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_54611_AwakerVoiceContent = {
    Text = "別妨礙我！"
  },
  Voice_54611_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_54612_AwakerVoiceContent = {
    Text = "深淵中…會有正義之光。"
  },
  Voice_54612_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_54613_AwakerVoiceContent = {
    Text = "別妨礙我！"
  },
  Voice_54613_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_54614_AwakerVoiceContent = {
    Text = "沉溺在這獨一無二的痛楚裡！"
  },
  Voice_54614_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_54615_AwakerVoiceContent = {
    Text = "沉溺在這獨一無二的痛楚裡！"
  },
  Voice_54615_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_54616_AwakerVoiceContent = {
    Text = "“是的，孩子，你已葬身於洶湧的河流！”"
  },
  Voice_54616_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_54617_AwakerVoiceContent = {
    Text = "“是的，孩子，你已葬身於洶湧的河流！”"
  },
  Voice_54617_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_54618_AwakerVoiceContent = {
    Text = "無定形之物啊，成為守護之盾吧！"
  },
  Voice_54618_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_54619_AwakerVoiceContent = {
    Text = "無定形之物啊，成為守護之盾吧！"
  },
  Voice_54619_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_5461_AwakerVoiceContent = {
    Text = "勞您費心了，我會心存感激的。"
  },
  Voice_5461_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5461_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_54620_AwakerVoiceContent = {
    Text = "深淵之獸，吞噬一切！"
  },
  Voice_54620_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_54621_AwakerVoiceContent = {
    Text = "深淵之獸，吞噬一切！"
  },
  Voice_54621_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_54622_AwakerVoiceContent = {
    Text = "深淵中…會有正義之光。"
  },
  Voice_54622_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_54623_AwakerVoiceContent = {
    Text = "我是、撕裂禁錮之人——Tokuli—Li！"
  },
  Voice_54623_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_54624_AwakerVoiceContent = {
    Text = "我是、撕裂禁錮之人——Tokuli—Li！"
  },
  Voice_54624_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_54625_AwakerVoiceContent = {
    Text = "此身即為，揭露未來之人！"
  },
  Voice_54625_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_54626_AwakerVoiceContent = {
    Text = "此身即為，揭露未來之人！"
  },
  Voice_54626_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_54627_AwakerVoiceContent = {
    Text = "拜倒於裙擺之下，親吻我的足尖吧！"
  },
  Voice_54627_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_54628_AwakerVoiceContent = {
    Text = "所有螺殼都在這裡了！"
  },
  Voice_54628_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_54629_AwakerVoiceContent = {
    Text = "所有螺殼都在這裡了！"
  },
  Voice_54629_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_5462_AwakerVoiceContent = {
    Text = "卓越之力，非深海之軀不可承受。你一定很羡慕我吧，哈哈，生為孱弱的人類並不是你的錯，想開點。"
  },
  Voice_5462_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5462_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_54630_AwakerVoiceContent = {
    Text = "拜倒於裙擺之下，親吻我的足尖吧！"
  },
  Voice_54630_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_5463_AwakerVoiceContent = {
    Text = "能把這些戰敗的傢伙當成我的奴隸嗎？"
  },
  Voice_5463_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5464_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5465_AwakerVoiceContent = {
    Text = "不過如此。"
  },
  Voice_5465_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5466_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_5467_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_5468_AwakerVoiceContent = {
    Text = "如果我能早點知道，當年那些人是因為這消融一切的詛咒而痛苦掙扎，我……不，現在知道也不晚。我一定要消除它，消除所有苦痛，即使要我再次付出生命。"
  },
  Voice_5468_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_5469_AwakerVoiceContent = {
    Text = "別灰心。大海會包容所有人的。"
  },
  Voice_5469_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_5470_AwakerVoiceContent = {
    Text = "僅憑這樣的羸弱之軀，成為我的同伴還是太勉強了。走吧，帶你去學院的運動俱樂部開開眼界，加強訓練！"
  },
  Voice_5470_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5471_AwakerVoiceContent = {
    Text = "借我力量的那個可憐傢伙，她可被融蝕折磨得不輕……你這是什麼眼神？別想了！我不會告訴你她在哪的！"
  },
  Voice_5471_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_5472_AwakerVoiceContent = {
    Text = "只要足夠幸運，你也能戰無不勝."
  },
  Voice_5472_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5473_AwakerVoiceContent = {
    Text = "會太粗暴嗎？"
  },
  Voice_5474_AwakerVoiceContent = {
    Text = "誒呀，這裡的大家，大多都還是孩子呢。那位紳士已經鬚髮皆白，那個冷面小哥缺了一隻手臂，都不是完美的人選……真是難辦呢。"
  },
  Voice_5474_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_5475_AwakerVoiceContent = {
    Text = "會太粗暴嗎？"
  },
  Voice_5476_AwakerVoiceContent = {
    Text = "精心描繪的符文，虔誠雕琢的神像，反復精煉的禁忌藥劑……一個都不可缺少。"
  },
  Voice_5476_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5476_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5477_AwakerVoiceContent = {
    Text = "王座當以深海開採的遠古青石壘起，祭壇上應該塗滿牲祭的鮮血……還不去準備嗎？"
  },
  Voice_5477_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_5477_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_5478_AwakerVoiceContent = {
    Text = "將那些傢伙全部喚來吧，他們理當震顫跪服著迎接祂的降臨。"
  },
  Voice_5478_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5478_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5479_AwakerVoiceContent = {
    Text = "我將前往那深海遺跡，以祂誕生的海水沐浴……"
  },
  Voice_5479_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5479_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5480_AwakerVoiceContent = {
    Text = "歡迎來到祂的降生儀式，共同見證祂的生辰……什麼？你說祂的消亡也是註定的命運？……不，絕不可能……我已經付出了那麼多代價……"
  },
  Voice_5480_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5480_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5481_AwakerVoiceContent = {
    Text = "遵照神的訓誡。"
  },
  Voice_5482_AwakerVoiceContent = {
    Text = "您的身邊，會是我和菲茵特的歸宿嗎？"
  },
  Voice_5482_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5482_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5483_AwakerVoiceContent = {
    Text = "嗯，那時候，我失去了我的嗓音。是您的澤潤讓它恢復原狀。"
  },
  Voice_5483_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5483_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5484_AwakerVoiceContent = {
    Text = "遵照神的訓誡。"
  },
  Voice_5485_AwakerVoiceContent = {
    Text = "浩瀚的星宇，無垠的深空，永無止境的旅途曾使我陷入迷失……"
  },
  Voice_5485_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5485_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5486_AwakerVoiceContent = {
    Text = "提升方式走了捷徑，但技藝的訓練也不能落下。"
  },
  Voice_5486_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_5487_AwakerVoiceContent = {
    Text = "原來這種方法也適用於我……"
  },
  Voice_5487_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_5488_AwakerVoiceContent = {
    Text = "奇妙的感覺。"
  },
  Voice_5488_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5492_AwakerVoiceContent = {
    Text = "祂的降臨，會讓這種黑色死亡帶來的痛苦終結，不是嗎？"
  },
  Voice_5492_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_5493_AwakerVoiceContent = {
    Text = "日安，主君。如果您要外出調查，請務必讓我同行護衛。"
  },
  Voice_5493_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5493_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_5494_AwakerVoiceContent = {
    Text = "做什麼？無聊的話，就去把這次的行動報告寫了吧。"
  },
  Voice_5494_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_5495_AwakerVoiceContent = {
    Text = "終於要開始了嗎？我的小寵物們可是餓了很久很久了……"
  },
  Voice_5495_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_5496_AwakerVoiceContent = {
    Text = "血脈的力量正在噴湧。"
  },
  Voice_5496_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_5497_AwakerVoiceContent = {
    Text = "……等一下，我見過這種東西。他們喂給我的水里有這種黑色的黏液。我獲得綠炎的力量或許與此有關？那也算是因禍得福吧。"
  },
  Voice_5497_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_5498_AwakerVoiceContent = {
    Text = "拉蒙娜·德克斯特，叫我拉蒙娜就好。期待接下來與你的合作，守密人。"
  },
  Voice_5498_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5499_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_5500_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5501_AwakerVoiceContent = {
    Text = "哼，不敬之人，就讓本小姐陪你們玩玩。"
  },
  Voice_5501_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_5502_AwakerVoiceContent = {
    Text = "討厭的東西？恰好抽完的煙斗，沒能趕上的馬車，穿新皮鞋時下起的雨。總之，一切的壞運氣都很討厭。"
  },
  Voice_5502_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5503_AwakerVoiceContent = {
    Text = "呆扳手、活扳手、梅花扳手、一字螺絲刀、十字螺絲刀、沉頭螺絲、盤頭螺絲……只要是能把壞掉的東西修好的，我都喜歡。"
  },
  Voice_5503_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_5504_AwakerVoiceContent = {
    Text = "誒呀~被你發現啦~\n沒事啦，喚醒體的精神力那麼豐沛，至少還要偷365次，她們才會變成無知無覺的傀儡啦~不能做嗎？好吧，我下次一定注意！嗯，只在人體鋸斷的時候偷一點點“恐懼”，沒關係吧？"
  },
  Voice_5504_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_5504_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_5505_AwakerVoiceContent = {
    Text = "喂，你已經知道卡茜亞魔術的秘密了吧？嗯，為了防止你洩密，無論到哪兒巡演，你都得跟著我才行~哈哈，你說我是為了收集你的情緒？果然沒有秘密能瞞過你呢！"
  },
  Voice_5505_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_5505_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_5506_AwakerVoiceContent = {
    Text = "你，來做卡茜亞的魔術助手吧！別害怕~只要鑽進我的魔術箱裡一會兒就好。\n\n躲好了嗎？我要把劍插進去了哦~對了，裡面沒有機關~"
  },
  Voice_5506_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5506_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_5507_AwakerVoiceContent = {
    Text = "來吧，戴上這頂禮帽！然後，說出你最想要的禮物。好的，是這樣啊，我知道了！現在，摸摸帽子裡面——"
  },
  Voice_5507_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_5507_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_5508_AwakerVoiceContent = {
    Text = "有點困擾呢。那幾個孩子每次都來看表演，我的存貨很快就要耗盡了……嗯，魔術師不能在同一批觀眾面前表演相同的戲法。創造新的魔術？抱歉，我沒有那種才能，我所擅長的只是模仿而已。"
  },
  Voice_5508_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_5508_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_5509_AwakerVoiceContent = {
    Text = "這所學院破舊不堪，只有院長先生那間休息室能稍稍入眼。您覺得如何？"
  },
  Voice_5509_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5509_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5510_AwakerVoiceContent = {
    Text = "那些傲慢卑劣的傢伙，全都要成為我手下的亡魂。"
  },
  Voice_5510_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_5511_AwakerVoiceContent = {
    Text = "復仇的刀刃，愈發鋒利。"
  },
  Voice_5511_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5512_AwakerVoiceContent = {
    Text = "我的沙龍可不像舞會那般純真，您準備好了嗎？"
  },
  Voice_5512_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5512_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5513_AwakerVoiceContent = {
    Text = "我的沙龍是土壤，是花園，令人沉醉的美麗與權力都將在此盛放……"
  },
  Voice_5513_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5513_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5514_AwakerVoiceContent = {
    Text = "絲綢軟塌、紅茶、馬卡龍……還需要晨露掛枝的新鮮玫瑰裝點我的會客室。"
  },
  Voice_5514_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_5514_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_5515_AwakerVoiceContent = {
    Text = "不能通融一番，讓外邊的賓客也進入學院嗎？"
  },
  Voice_5515_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5515_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5516_AwakerVoiceContent = {
    Text = "運行錯誤、錯誤、錯誤、錯誤……"
  },
  Voice_5516_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_5517_AwakerVoiceContent = {
    Text = "呀！現在幾點了！抱歉主人......珈倫不該工作開小差的！可實在是太困了......"
  },
  Voice_5517_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_5518_AwakerVoiceContent = {
    Text = "我只能等待死亡嗎？有人能幫助我嗎？我能反抗他們的控制嗎？我曾經每天都這麼問自己，但答案其實一直都在腦子裡，只是我不敢面對罷了……如果你沒有出現，我不確定自己是否有反抗到底的勇氣。\n謝、謝謝你——別誤會，這可不是什麼告白啊！"
  },
  Voice_5518_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_5518_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_5519_AwakerVoiceContent = {
    Text = "我活在他們虛假的夢境中，被一則滑稽的預言剝奪了作為普通人的資格，甚至連選擇的權利都不曾有……為了逃離這樣的生活，我什麼都願意做。"
  },
  Voice_5519_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_5519_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_5520_AwakerVoiceContent = {
    Text = "“低垂的睡蓮在四周歎息，\n熟睡的榿木間，她偶爾驚醒；\n一隻鳥在巢中窸窣顫慄，\n神秘的歌聲降自金色群星。”\n啊，讓您聽見了嗎？抱歉，這是我很喜歡的句子……您要一起來閱讀嗎？"
  },
  Voice_5520_AwakerVoiceTitle = {
    Text = "閒話·關於閱讀"
  },
  Voice_5521_AwakerVoiceContent = {
    Text = "別隨便進淑女的房間，也別對淑女的儀態指手畫腳。趕緊退下，本小姐要休息了。"
  },
  Voice_5521_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_5521_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_5522_AwakerVoiceContent = {
    Text = "你最好不要對我擺架子，認清自己的身分，睜大眼睛看看誰才是真正的主人。"
  },
  Voice_5522_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5522_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_5523_AwakerVoiceContent = {
    Text = "哎呀，需要展示商品嗎？"
  },
  Voice_5523_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_5524_AwakerVoiceContent = {
    Text = "幹得漂亮。是時候來一桶朗姆酒慶祝勝利了！"
  },
  Voice_5524_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5525_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_5526_AwakerVoiceContent = {
    Text = "交給我吧！"
  },
  Voice_5527_AwakerVoiceContent = {
    Text = "被我踩在腳下的滋味，一定十分美妙吧~"
  },
  Voice_5527_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5529_AwakerVoiceContent = {
    Text = "很在意眼罩之下的樣子嗎？在更合適的場合，我會讓你看的，別太心急。"
  },
  Voice_5529_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_5530_AwakerVoiceContent = {
    Text = "這麼快就結束了？……我的興致才剛被挑起呢。"
  },
  Voice_5530_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5531_AwakerVoiceContent = {
    Text = "喂，別在我身上動手動腳，真正的戰士從不依靠外物。"
  },
  Voice_5531_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5531_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_5532_AwakerVoiceContent = {
    Text = "艾繼絲變強了……我會用這雙眼讓敵人動彈不得的！"
  },
  Voice_5532_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5533_AwakerVoiceContent = {
    Text = "彌薩格大學和部隊沒有什麼不同。我們每個人都守在前線，擦亮武器，準備作戰。"
  },
  Voice_5533_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_5536_AwakerVoiceContent = {
    Text = "我可以被戴上鐐銬，可以被拽著頭髮跪在你面前，做你的奴隸。這些都沒有任何問題——只要讓我殺人，雕塑家、提燈、路過的哮喘老太婆……隨便什麼人，我保證會幫你撕爛他們的喉嚨，喝乾他們的血。"
  },
  Voice_5536_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_5536_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_5537_AwakerVoiceContent = {
    Text = "自融蝕傷口中流淌而出的，除了黑色的黏液，還有源源不斷的靈感。說實話，我不介意再來一點。"
  },
  Voice_5537_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_5538_AwakerVoiceContent = {
    Text = "害怕？哈哈哈哈，那就對了！讓一切都見鬼去吧，我只想品嘗你們的恐懼。"
  },
  Voice_5538_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5538_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_5539_AwakerVoiceContent = {
    Text = "有意思，你的鮮血味道嘗起來……很香甜，像蜂蜜酒一樣。"
  },
  Voice_5539_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_5539_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_5540_AwakerVoiceContent = {
    Text = "那時候，數萬人齊聲歡呼我的姓名，名為「尤烏哈希」的海洋淹沒一切，慶祝我剛剛擰斷了一個禿頭軟蛋的脖子。那感覺真是妙極了，身為我的同伴，你一定能理解。"
  },
  Voice_5540_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_5540_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_5541_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5542_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5543_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_5544_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_5545_AwakerVoiceContent = {
    Text = "正在廣域檔案中搜索“融蝕”……不需要？你希望知道我對融蝕的態度嗎？我明白了，正在喚醒體系私域中搜索“對融蝕兵器”……結果為：「0」。"
  },
  Voice_5545_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_5546_AwakerVoiceContent = {
    Text = "偽造之物，脆弱如煙塵，絲縷清風就能吹散……"
  },
  Voice_5546_AwakerVoiceTitle = {
    Text = "閒話·關於墨菲"
  },
  Voice_5546_UnlockDesc = {
    Text = "獲得喚醒體「墨菲」後解鎖"
  },
  Voice_5547_AwakerVoiceContent = {
    Text = "稍微有些吵鬧，是學生們嗎？\n他們，很像信天翁，你知道那種鳥兒嗎？無盡的活力，旅途彷彿永遠沒有盡頭……"
  },
  Voice_5547_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5548_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5549_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_5550_AwakerVoiceContent = {
    Text = "學院裡也就拉蒙娜那孩子有點意思，她在劍術上頗具天賦，剩下的全是墨守成規的傢伙……你不會也是吧？你當真覺得寫行動報告有意思？"
  },
  Voice_5550_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_5551_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5552_AwakerVoiceContent = {
    Text = "母親和母親不太一樣。有好的母親，也有壞的母親。\n主人是好的母親。"
  },
  Voice_5552_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_5552_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_5553_AwakerVoiceContent = {
    Text = "是我沒能保護好您……"
  },
  Voice_5553_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_5554_AwakerVoiceContent = {
    Text = "場地預約好了嗎？要超過一百五十平的花園噢！"
  },
  Voice_5554_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5554_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_5555_AwakerVoiceContent = {
    Text = "將死之人的鮮血是一種滑膩的液體。只需在脖頸上輕輕一劃，鮮血便順著牙齒之間，變成幾道溫熱的細線，慢慢灌進我的肚子裡......呵呵，美味。"
  },
  Voice_5555_AwakerVoiceTitle = {
    Text = "閒話·關於血液"
  },
  Voice_5558_AwakerVoiceContent = {Text = "誒"},
  Voice_5559_AwakerVoiceContent = {
    Text = "感謝您的仁慈之心，為我提供了棲身之所。希望我不會為您招來悲劇的命運……"
  },
  Voice_5559_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5560_AwakerVoiceContent = {
    Text = "我來自遙遠的異星。那裡風雪肆虐，是極度冰寒的所在。不過沒關係，在我的莊園裡有超過一千名僕從，他們的依偎令人倍感溫暖。"
  },
  Voice_5560_AwakerVoiceTitle = {
    Text = "閒話·關於過去"
  },
  Voice_5561_AwakerVoiceContent = {
    Text = "在迎得您歸來前，我不能在此倒下。"
  },
  Voice_5561_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_5562_AwakerVoiceContent = {
    Text = "在迎得您歸來前，我不能在此倒下。"
  },
  Voice_5562_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5563_AwakerVoiceContent = {
    Text = "哎呀，世間怎麼會有這樣傲慢的客人，想要「世界上最好用的武器」？我告訴他，需要用浸滿仇恨的頭顱來換，他就悻悻地走了……"
  },
  Voice_5563_AwakerVoiceTitle = {
    Text = "閒話·關於戈利亞"
  },
  Voice_5563_UnlockDesc = {
    Text = "獲得喚醒體「戈利亞」後解鎖"
  },
  Voice_5564_AwakerVoiceContent = {
    Text = "你這幅躊躇滿志，好像隨時都為為「拯救世界」而獻身的樣子，讓人看到就感覺關節發癢。"
  },
  Voice_5564_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5564_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_5565_AwakerVoiceContent = {
    Text = "在你們頒下研究禁令前，只差一點，我就能讓湮滅覆蓋這所謂的融蝕庇護所……可惜，太可惜了。"
  },
  Voice_5565_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_5565_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_5566_AwakerVoiceContent = {
    Text = "是的，我有無數具備用軀體，也有無數次逃離融蝕的機會。但，當一條通往真理的道路於面前鋪開，任何學者都不會拒絕。我回應了內心的渴望，為此，我並不後悔。"
  },
  Voice_5566_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_5566_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_5567_AwakerVoiceContent = {
    Text = "世界的真實，世界的起點，世界的盡頭，全都是沒有意義的東西。若你也想走上通往真實之路，我不介意成為你的引路人……就像我們從前那樣。"
  },
  Voice_5567_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_5567_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_5568_AwakerVoiceContent = {
    Text = "你們或許能阻止我，但終結是無法阻擋的……我會將這所學校，將你，留至最後。我們將於高塔上沐浴時間的黃昏，目睹文明的陷落……怎麼樣，這麼做，總沒有辜負我們間的情誼吧？"
  },
  Voice_5568_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_5568_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_5569_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5570_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_5571_AwakerVoiceContent = {
    Text = "願我的祈禱能成為喚醒故國的晨鐘……"
  },
  Voice_5571_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5572_AwakerVoiceContent = {
    Text = "我沒有想過，會有汀克特以外的人願意接納我。我很慶倖能與你相遇，守密人。我會盡全力學習控制力量的，這樣的話，我擁抱你時就不會抽乾你的生命力了……是擁抱吧？人類用於表達感謝的方式？"
  },
  Voice_5572_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_5572_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_5573_AwakerVoiceContent = {
    Text = "我留在這裡，不需要付出什麼報酬嗎？我可以幫你提升在這裡的地位。只要威脅會吸乾他們的生命，很簡單的，就像以前我幫汀克特一樣……啊！這、這件事你千萬不要告訴別人！"
  },
  Voice_5573_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_5573_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_5574_AwakerVoiceContent = {
    Text = "抱歉，我和其他同類不一樣，是個劣等品……"
  },
  Voice_5574_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5574_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_5575_AwakerVoiceContent = {
    Text = "一名優秀的侍女能為沙龍增色不少，但藍綠色的侍女……容我再斟酌一番……"
  },
  Voice_5575_AwakerVoiceTitle = {
    Text = "閒話·關於珈倫"
  },
  Voice_5575_UnlockDesc = {
    Text = "獲得喚醒體「珈倫」後解鎖"
  },
  Voice_5576_AwakerVoiceContent = {
    Text = "汀克特是我的雙生妹妹，和我不一樣，她總是閃閃發光……\n如果沒有我的拖累，她一定會有更美好的未來，歌聲能響遍整個星系……"
  },
  Voice_5576_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_5576_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_5577_AwakerVoiceContent = {
    Text = "搖籃裡很擠，沒有辦法舒展身體……但是汀克特說過，為了所有人的安全，她要我別離開搖籃……既然她是這麼希望的，我會聽的。"
  },
  Voice_5577_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_5577_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_5578_AwakerVoiceContent = {
    Text = "我時常感覺自己處於生與死的隙間。只要是我存在的地方，憂鬱漫延如潮，悲劇連袂登場。即便如此，你也願意讓我為你寫詩嗎？唔……或許，你值得一首最甜美的……"
  },
  Voice_5578_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5578_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5579_AwakerVoiceContent = {
    Text = "“玫瑰還沒盛開，黎明就要來臨了。”"
  },
  Voice_5579_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5579_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5580_AwakerVoiceContent = {
    Text = "您渴望什麼呢？是辭藻繾綣的美，是蜚聲海內的名望，又或者是那詞句背後滴血的真心？"
  },
  Voice_5580_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5580_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5581_AwakerVoiceContent = {
    Text = "以不可見的水墨，刻畫出畸形的蓓蕾……這幽靈般飄渺的玫瑰花枝，竟然能激發詩的靈感……"
  },
  Voice_5581_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_5581_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_55825_AwakerVoiceContent = {
    Text = "聆聽吾主。"
  },
  Voice_55825_AwakerVoiceTitle = {
    Text = "靈知覺醒·二"
  },
  Voice_55826_AwakerVoiceContent = {
    Text = "殉身！重塑神國——"
  },
  Voice_55826_AwakerVoiceTitle = {
    Text = "靈知覺醒·三"
  },
  Voice_5582_AwakerVoiceContent = {
    Text = "若您執意，我將重新步入陽光下……與離開西岱那一日別無二致的陽光啊……"
  },
  Voice_5582_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5582_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5583_AwakerVoiceContent = {
    Text = "嘿嘿，你想要看到毀滅的宇宙嗎？誒，現在反悔可來不及啦！"
  },
  Voice_5583_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5583_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5584_AwakerVoiceContent = {
    Text = "啜飲吧，甘美的死亡。"
  },
  Voice_5584_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5585_AwakerVoiceContent = {
    Text = "啜飲吧，甘美的死亡。"
  },
  Voice_5585_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_5586_AwakerVoiceContent = {
    Text = "到此為止！"
  },
  Voice_5587_AwakerVoiceContent = {Text = "別……"},
  Voice_5587_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5588_AwakerVoiceContent = {
    Text = "見證余的威儀吧。"
  },
  Voice_5588_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5589_AwakerVoiceContent = {
    Text = "凌晨4點的大學空氣宜人，很高興您願意和我一起鍛煉。不得不說，雕塑可是件體力活。"
  },
  Voice_5589_AwakerVoiceTitle = {
    Text = "閒話·關於早上"
  },
  Voice_5590_AwakerVoiceContent = {
    Text = "這力量，使用起來還不錯。"
  },
  Voice_5590_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5590_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5591_AwakerVoiceContent = {
    Text = "我討厭買東西不付帳的人。只要開店的時間夠久，總會遇到這種煩惱吧。沒辦法，我也只能親自出手，把賬單追回來了~"
  },
  Voice_5591_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5594_AwakerVoiceContent = {Text = "裝載。"},
  Voice_5595_AwakerVoiceContent = {Text = "啟動。"},
  Voice_5596_AwakerVoiceContent = {
    Text = "讓這裡成為大家的喧囂海洋吧！"
  },
  Voice_5596_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5597_AwakerVoiceContent = {
    Text = "怎麼，指望我向你道謝嗎？"
  },
  Voice_5597_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_5598_AwakerVoiceContent = {
    Text = "作為貢品來說根本不合格……但看在你如此有誠意的份上，我就勉為其難地收下吧。"
  },
  Voice_5598_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_5599_AwakerVoiceContent = {
    Text = "你以為這樣我就會聽你的嗎？"
  },
  Voice_5599_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5600_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5601_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5602_AwakerVoiceContent = {
    Text = "忘恩負義的怪物，刺客，殺手，也有被你認可的價值嗎？怪人。"
  },
  Voice_5602_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5602_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5603_AwakerVoiceContent = {
    Text = "不管堆積了多少軟墊，青金石御座都無法比上羽絨床榻。從這點上看，你們這裡還算有些可取之處。"
  },
  Voice_5603_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_5604_AwakerVoiceContent = {
    Text = "小小的懲罰。"
  },
  Voice_5605_AwakerVoiceContent = {
    Text = "我討厭孤獨，討厭在望不到盡頭的黑暗中，擔憂著某個人的感受……所以，請您不要拋下我，好嗎？"
  },
  Voice_5605_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5606_AwakerVoiceContent = {
    Text = "如果我是你，就會把所有喚醒體都關在籠子裡！瘋狗出籠後，總是最先咬死主人。"
  },
  Voice_5606_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_5606_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_5607_AwakerVoiceContent = {
    Text = "這次會面我遲到了一個小時——都怪那些推翻奴隸制的好事之徒，現在都沒人替我梳頭了！"
  },
  Voice_5607_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_5607_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_5608_AwakerVoiceContent = {
    Text = "難以想像，我的故鄉竟然就這樣湮滅了……那可是偉大的羅馬！你不可能沒聽聞過！"
  },
  Voice_5608_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5608_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_5609_AwakerVoiceContent = {
    Text = "來吧，贏個開門紅！"
  },
  Voice_5609_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_5610_AwakerVoiceContent = {
    Text = "這是，吾主的賜福。"
  },
  Voice_5610_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5611_AwakerVoiceContent = {
    Text = "收收你憐憫的眼神，我不喜歡，也不需要人可憐。再這麼看著我，我會忍不住狠狠折磨你……你也不想事情變得無法收場吧，那麼，乖一點，聽話一點，乖乖當我的角鬥士……"
  },
  Voice_5611_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_5611_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_5612_AwakerVoiceContent = {
    Text = "別*消音*再問了。我疏忽了，大意了，讓角鬥士逃了，害得全家都死了！像如今的羅馬帝國一樣，被燒得灰都不剩！"
  },
  Voice_5612_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_5612_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_5613_AwakerVoiceContent = {
    Text = "和各具才華的大家相比，寧菲亞只是個沒有建立過任何功績、沒有創造過任何價值的，再平凡不過的凡人罷了。\n讓我被喚醒的……或許是一些小小的、卑微的願望吧……"
  },
  Voice_5613_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_5614_AwakerVoiceContent = {
    Text = "今天我又打破校規，上課遲到了五分鐘……所以，我懇請接受最嚴厲的懲罰，若是守密人來執行，就更好了。"
  },
  Voice_5614_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_5615_AwakerVoiceContent = {
    Text = "工具也是需要維護的哦，一套趁手的工具可是機械師的靈魂。"
  },
  Voice_5615_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5615_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_5616_AwakerVoiceContent = {
    Text = "（不屑的隱忍）"
  },
  Voice_5616_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5617_AwakerVoiceContent = {
    Text = "再有下次的話，我會替你申請留校察看。"
  },
  Voice_5617_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_5618_AwakerVoiceContent = {
    Text = "除了戰鬥外，我當然還有其他工作要做。就算在太古宙，我也不是無所事事的……喂，你不會真把我當只會打架的粗人了吧！"
  },
  Voice_5618_AwakerVoiceTitle = {
    Text = "閒話·關於工作"
  },
  Voice_5619_AwakerVoiceContent = {
    Text = "人們靠近我時，總是會回想起人生中最為悲傷的經歷，從而不由自主地落下淚來。這樣的我，也可以成長嗎？"
  },
  Voice_5619_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5619_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_5620_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_5621_AwakerVoiceContent = {
    Text = "這樣嗎？"
  },
  Voice_5621_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_5622_AwakerVoiceContent = {
    Text = "這裡比髒兮兮臭烘烘的新門監獄好多了！躺在沙發也好，壓在牆角也好，都很舒服哦？"
  },
  Voice_5622_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_5623_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5624_AwakerVoiceContent = {
    Text = "螺殼，到哪去了……"
  },
  Voice_5625_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5626_AwakerVoiceContent = {
    Text = "螺殼到哪去了啊！"
  },
  Voice_5627_AwakerVoiceContent = {
    Text = "流淌的銀河……"
  },
  Voice_5627_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5628_AwakerVoiceContent = {
    Text = "奧瑞塔不喜歡突然走掉的夥伴……但、但如果還會回來的話，奧瑞塔就會原諒他！"
  },
  Voice_5628_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5629_AwakerVoiceContent = {
    Text = "會獨自航船漂洋過海的女人，除了女神，還有女瘋子。當初我把彌利亞姆認作女神，真是天大的錯誤。"
  },
  Voice_5629_AwakerVoiceTitle = {
    Text = "閒話·關於彌利亞姆"
  },
  Voice_5629_UnlockDesc = {
    Text = "獲得喚醒體「彌利亞姆」後解鎖"
  },
  Voice_56313_AwakerVoiceContent = {
    Text = "我偷偷去看了卡茜亞小姐的魔術。她的表演帶給了觀眾很多的快樂，可我卻總是將悲傷帶給大家……您說，眼淚與笑容，是同樣珍貴的事物？或許……"
  },
  Voice_56313_AwakerVoiceTitle = {
    Text = "閒話·關於卡茜亞"
  },
  Voice_56313_UnlockDesc = {
    Text = "獲得喚醒體「卡茜亞」後解鎖"
  },
  Voice_56314_AwakerVoiceContent = {
    Text = "詩、火焰和悲傷是類似的東西，它們會在不覺中將你吞沒……回過神時，已經沉浸在詩的世界中了……"
  },
  Voice_56314_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_56315_AwakerVoiceContent = {
    Text = "讓來自往昔的詩篇，喚醒潛藏心底的花園。"
  },
  Voice_56315_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_56316_AwakerVoiceContent = {
    Text = "詩歌與鮮花，大概是同一種事物吧？一樣的短暫，雋永，在這個沒有邊際的世界上，只用很小的一塊地方，便裝下了那些最為刻骨銘心的瞬間……我想，所有的人都曾為一首詩而沉默，就像為一朵花的綻放而駐足一樣。"
  },
  Voice_56316_AwakerVoiceTitle = {
    Text = "閒話·關於詩"
  },
  Voice_56317_AwakerVoiceContent = {
    Text = "我已經快要忘記了……這個季節的西岱，會開出什麼樣的花來呢？"
  },
  Voice_56317_AwakerVoiceTitle = {
    Text = "閒話·關於西岱"
  },
  Voice_56318_AwakerVoiceContent = {
    Text = "您令我筆下墨色重新彙聚為涓涓細流，我也將為您的故事續寫詩篇。"
  },
  Voice_56318_AwakerVoiceTitle = {
    Text = "閒話·關於守密人1"
  },
  Voice_56319_AwakerVoiceContent = {
    Text = "花的盛放有多麼美，花的凋謝就有多麼令人難過，可無論難過多少次，我總是忍不住為那些花停留、哀悼。如果因為畏懼痛苦就它們視而不見，那這些花，該有多傷心啊……"
  },
  Voice_56319_AwakerVoiceTitle = {
    Text = "閒話·關於痛苦"
  },
  Voice_5631_AwakerVoiceContent = {
    Text = "為了在艾瑞卡「睡覺」時研究這具身體的內部構造，溫柯爾要求我夜晚去她的辦公室休眠。\n是否需要告知，艾瑞卡休眠時仍保有一部分意識？"
  },
  Voice_5631_AwakerVoiceTitle = {
    Text = "閒話·關於溫柯爾"
  },
  Voice_5631_UnlockDesc = {
    Text = "獲得喚醒體「溫柯爾」後解鎖"
  },
  Voice_56320_AwakerVoiceContent = {
    Text = "那位紅夫人可真美。她的強大與自信，她面對命運的優雅微笑，她那如同紅薔薇般旺盛又決絕的生命力，都讓我無比羡慕……"
  },
  Voice_56320_AwakerVoiceTitle = {
    Text = "閒話·關於索蕾爾"
  },
  Voice_56320_UnlockDesc = {
    Text = "獲得喚醒體「索蕾爾」後解鎖"
  },
  Voice_56321_AwakerVoiceContent = {
    Text = "我昨天新寫了一首詩，還沒有給別人看過。寫得不好，但是……守、守密人的話，會願意看看嗎？"
  },
  Voice_56321_AwakerVoiceTitle = {
    Text = "閒話·關於守密人2"
  },
  Voice_56322_AwakerVoiceContent = {
    Text = "學生詩會希望我成為他們的指導者……我沒有辦法答應他們。我不想掃年輕人的興，但我只會帶給他們沮喪與消沉。"
  },
  Voice_56322_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_56323_AwakerVoiceContent = {
    Text = "這世間沒有討厭的事物，黃金的歲月值得頌揚，而垂暮的衰老則值得憐憫；青春的華服惹人豔羨，而殘朽的襤褸引人追思。"
  },
  Voice_56323_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_56324_AwakerVoiceContent = {
    Text = "每次看到寧菲亞小姐，我都會想起那幅畫著睡蓮的畫。她的身上，有著睡蓮般寧靜的苦澀與清香……不知道她眼中的世界會是什麼樣子呢？"
  },
  Voice_56324_AwakerVoiceTitle = {
    Text = "閒話·關於寧菲亞"
  },
  Voice_56324_UnlockDesc = {
    Text = "獲得喚醒體「寧菲亞」後解鎖"
  },
  Voice_56325_AwakerVoiceContent = {
    Text = "從以前起，我就能感受到身邊存在著“幽靈”，就像某種難以解釋的附身，或者說著魔現象，祂讓我日漸失去了對世界的期待。但如果是幽靈的話，那憑空消失的牛奶與清水又該如何解釋呢……"
  },
  Voice_56325_AwakerVoiceTitle = {
    Text = "閒話·關於幽靈"
  },
  Voice_56326_AwakerVoiceContent = {
    Text = "我的身體並未受到融蝕侵染，那些黑色液體只是濃墨罷了。但話說回來，就算沒有融蝕，事物的存在也會化作虛無，不是麼？"
  },
  Voice_56326_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_56327_AwakerVoiceContent = {
    Text = "在鑰塚的墓碑裡，我看到了守密人的名字……生前的記憶是痛苦的，但我從未想過要忘記它們。對守密人來說，那些失去了的記憶，一定也彌足珍貴吧？"
  },
  Voice_56327_AwakerVoiceTitle = {
    Text = "閒話·關於記憶"
  },
  Voice_56328_AwakerVoiceContent = {
    Text = "假如詩歌是為讚頌美而存在的，那她的存在就像是詩歌本身。當她開始歌唱的時候，我突然就明白了前輩們形容的，夜鶯般的歌喉……"
  },
  Voice_56328_AwakerVoiceTitle = {
    Text = "閒話·關於汀克特"
  },
  Voice_56328_UnlockDesc = {
    Text = "獲得喚醒體「汀克特」後解鎖"
  },
  Voice_56329_AwakerVoiceContent = {
    Text = "那位美貌的舞者……她身上碧綠色的火焰，讓人忍不住想要去觸碰，即便被焚燒殆盡也無所謂……"
  },
  Voice_56329_AwakerVoiceTitle = {
    Text = "閒話·關於莉茲"
  },
  Voice_56329_UnlockDesc = {
    Text = "獲得喚醒體「莉茲」後解鎖"
  },
  Voice_5632_AwakerVoiceContent = {
    Text = "用這種方式取代吸食原質嗎？"
  },
  Voice_5632_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_5633_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_5634_AwakerVoiceContent = {
    Text = "客人呀，您想要什麼樣的報酬呢？"
  },
  Voice_5634_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5635_AwakerVoiceContent = {
    Text = "快點結束吧，不要在街頭逗留。"
  },
  Voice_5635_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_5636_AwakerVoiceContent = {
    Text = "無可避免的犧牲。"
  },
  Voice_5637_AwakerVoiceContent = {
    Text = "（忍耐的悶哼）"
  },
  Voice_5637_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_56386_AwakerVoiceContent = {
    Text = "電流輸入完畢。電流發射。"
  },
  Voice_56386_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_56387_AwakerVoiceContent = {
    Text = "別小看街頭第一神偷！"
  },
  Voice_56387_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_56388_AwakerVoiceContent = {
    Text = "獻上開幕的禮讚！"
  },
  Voice_56388_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_56389_AwakerVoiceContent = {
    Text = "於此浮現的千面幻象！"
  },
  Voice_56389_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_5638_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5638_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_56390_AwakerVoiceContent = {
    Text = "沉淪吧，燃燒吧！告死之舞！"
  },
  Voice_56390_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_56391_AwakerVoiceContent = {
    Text = "此乃萬千死者徘徊失鄉之都。"
  },
  Voice_56391_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_56392_AwakerVoiceContent = {
    Text = "就讓我給予你吧，我僅剩的遷移能量……！"
  },
  Voice_56392_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_56393_AwakerVoiceContent = {
    Text = "別小看街頭第一神偷！"
  },
  Voice_56393_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_5639_AwakerVoiceContent = {
    Text = "是敵人嗎？請給我出擊指令。\n黑色黏液是敵人……莉莉也是敵人？"
  },
  Voice_5639_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_5640_AwakerVoiceContent = {
    Text = "自動人偶艾瑞卡，軀幹編號EA307881，電機編號MF311028。很高興為你效勞。"
  },
  Voice_5640_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5641_AwakerVoiceContent = {
    Text = "在敵人完全潰敗前，全力戰鬥吧！"
  },
  Voice_5641_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_5642_AwakerVoiceContent = {
    Text = "你好，我是……你能告訴我我叫什麼嗎？"
  },
  Voice_5642_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5643_AwakerVoiceContent = {
    Text = "來到學校後，我才理解自身所感染、名為融蝕的疾病。生前，父母總是希望我遠離海洋，如今看來，這感染或許確實與我親近海洋的舉動有所關聯……"
  },
  Voice_5643_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_5644_AwakerVoiceContent = {
    Text = "好吧，我不會讓你“失望”的。"
  },
  Voice_5644_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_5645_AwakerVoiceContent = {
    Text = "這灼熱的呼吸——"
  },
  Voice_5645_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_5646_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5647_AwakerVoiceContent = {
    Text = "旋轉吧。"
  },
  Voice_5647_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_5648_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5650_AwakerVoiceContent = {
    Text = "這一天終究到來……"
  },
  Voice_5650_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_5651_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5652_AwakerVoiceContent = {
    Text = "我還沒有盡興……不如你爬起來，讓我再殺一次如何？"
  },
  Voice_5652_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5654_AwakerVoiceContent = {
    Text = "守密人，我必須跟你談談。在我們取得最終勝利之前，某些人不應當如此奢靡浪費。要知道，我不是為那種人的貴族生活而奮戰的。"
  },
  Voice_5654_AwakerVoiceTitle = {
    Text = "閒話·關於索蕾爾"
  },
  Voice_5654_UnlockDesc = {
    Text = "獲得喚醒體「索蕾爾」後解鎖"
  },
  Voice_5655_AwakerVoiceContent = {
    Text = "作為戰俘被帶走的話，迎接我的，會是怎樣殘酷的命運呢？"
  },
  Voice_5655_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_5656_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5657_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5658_AwakerVoiceContent = {
    Text = "呼——好困，在休息之前，你們有準備好放鬆用的茶點嗎？"
  },
  Voice_5658_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5659_AwakerVoiceContent = {
    Text = "母親，你要摸摸它們嗎？很柔軟的，據說。"
  },
  Voice_5659_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5659_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5660_AwakerVoiceContent = {
    Text = "哼哼哼，啦啦啦~打掃打掃，我愛打掃，心情好好~"
  },
  Voice_5660_AwakerVoiceTitle = {
    Text = "閒話·關於工作"
  },
  Voice_5661_AwakerVoiceContent = {
    Text = "（難耐的呼痛）"
  },
  Voice_5661_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_5662_AwakerVoiceContent = {
    Text = "嗯……不錯。"
  },
  Voice_5662_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5663_AwakerVoiceContent = {
    Text = "（難耐的呼痛）"
  },
  Voice_5663_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5664_AwakerVoiceContent = {
    Text = "（難耐的呼痛）"
  },
  Voice_5664_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_5665_AwakerVoiceContent = {
    Text = "怒火燃燒！"
  },
  Voice_5666_AwakerVoiceContent = {
    Text = "我看不少人因為融蝕發了瘋。說實話，我已經夠瘋了，融蝕對我應該不會有什麼影響。"
  },
  Voice_5666_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_5667_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5668_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_5669_AwakerVoiceContent = {
    Text = "感覺就像活過來了一樣。"
  },
  Voice_5669_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5670_AwakerVoiceContent = {
    Text = "不錯嘛。"
  },
  Voice_5670_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_5671_AwakerVoiceContent = {
    Text = "能揮出更強的一劍了。"
  },
  Voice_5671_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_5672_AwakerVoiceContent = {
    Text = "又要保持出勤率，又要維持研究進度，還有帶教任務需要完成。看來，時間壓縮的反向實驗要提上日程了。"
  },
  Voice_5672_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_5672_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_5673_AwakerVoiceContent = {
    Text = "距離正式冒險又近了一步。"
  },
  Voice_5673_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_5674_AwakerVoiceContent = {
    Text = "不要讓人家接近水嘛，對你的愛情火苗可是會熄滅的哦？"
  },
  Voice_5674_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5675_AwakerVoiceContent = {
    Text = "戰鬥到底！"
  },
  Voice_5675_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5676_AwakerVoiceContent = {
    Text = "你可真是勇氣可嘉。看看這些觸手，你就不害怕被瘋狂吞噬嗎？"
  },
  Voice_5676_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_5676_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_5677_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5678_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_5679_AwakerVoiceContent = {
    Text = "請住手！"
  },
  Voice_5679_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5680_AwakerVoiceContent = {
    Text = "要摸摸看嗎？我的心臟正因您的存在而跳動著。"
  },
  Voice_5680_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5680_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_5681_AwakerVoiceContent = {
    Text = "它們嘰嘰咕咕地，很開心呢。謝謝你，主人。"
  },
  Voice_5681_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_5681_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_5682_AwakerVoiceContent = {
    Text = "胸口有什麼在甦醒……暖洋洋的，莉莉、莉莉的眼淚都快要……\n母親，一起慶祝吧。"
  },
  Voice_5682_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5682_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5683_AwakerVoiceContent = {
    Text = "和母親在一起，就會有幸福的感覺。"
  },
  Voice_5683_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5683_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5684_AwakerVoiceContent = {
    Text = "已經吃不下了…肚子飽飽。\n儀式結束後，莉莉會變強嗎？"
  },
  Voice_5684_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5684_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5685_AwakerVoiceContent = {
    Text = "我喜歡大海，會很諷刺嗎？因為我所擁有的一切，都已經沉於深海……"
  },
  Voice_5685_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_5686_AwakerVoiceContent = {
    Text = "小心點！"
  },
  Voice_5686_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5687_AwakerVoiceContent = {
    Text = "討厭的東西......？沒有哦。您會討厭一粒塵埃，或是一片樹葉嗎？"
  },
  Voice_5687_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5688_AwakerVoiceContent = {
    Text = "我好幾次拒絕了女僕小姐的宴會邀請，她看起來有些失落……但相比起玩樂，自然是主君的安危更為重要！"
  },
  Voice_5688_AwakerVoiceTitle = {
    Text = "閒話·關於珈倫"
  },
  Voice_5688_UnlockDesc = {
    Text = "獲得喚醒體「珈倫」後解鎖"
  },
  Voice_5689_AwakerVoiceContent = {
    Text = "主君是騎士存在的理由，所以請儘管差使我吧！"
  },
  Voice_5689_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5690_AwakerVoiceContent = {
    Text = "……這個可能需要用到扭力扳手……唔，抱歉，你剛才有叫我嗎？"
  },
  Voice_5690_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_5691_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_5692_AwakerVoiceContent = {Text = "大膽！"},
  Voice_5692_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5693_AwakerVoiceContent = {
    Text = "（優雅的輕哼）"
  },
  Voice_5693_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5694_AwakerVoiceContent = {
    Text = "（忍耐的悶哼）"
  },
  Voice_5694_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_5695_AwakerVoiceContent = {
    Text = "適可而止吧。"
  },
  Voice_5695_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5696_AwakerVoiceContent = {
    Text = "溫柔些吧。"
  },
  Voice_5696_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_5697_AwakerVoiceContent = {
    Text = "果然還是難以集中精神……"
  },
  Voice_5697_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_5698_AwakerVoiceContent = {
    Text = "她在夜裡時常會待在我附近，是我這顆頭顱太顯眼了嗎？"
  },
  Voice_5698_AwakerVoiceTitle = {
    Text = "閒話·關於溫柯爾"
  },
  Voice_5698_UnlockDesc = {
    Text = "獲得喚醒體「溫柯爾」後解鎖"
  },
  Voice_5699_AwakerVoiceContent = {
    Text = "我一直都在等待毀滅的降臨，卻從未想過還有“抗爭”這一選擇……您願意帶著靈魂如此淺薄的我跨越湮滅嗎？在死裡逃生的世界裡，也依舊給予我救贖……"
  },
  Voice_5699_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_5699_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_5700_AwakerVoiceContent = {
    Text = "既然作為您的使徒被喚醒，那麼除了您的平安喜樂外，我別無所求，這是我的願…唔啊……啊……果然，存續，存續，存續，存續，活下去……"
  },
  Voice_5700_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_5700_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_5701_AwakerVoiceContent = {
    Text = "不沉溺於我的愛意中試試嗎？您將我喚醒，難道不就是為了我懷中的溫度嗎？"
  },
  Voice_5701_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5701_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_5702_AwakerVoiceContent = {
    Text = "不想和來路不明的女人糾纏不清嗎，好吧，好吧。尼尼微的亡國君，意圖通天的示拿之人，幼發拉底聖樹下被剝奪意志的少女……您想從哪裡開始聽起呢？"
  },
  Voice_5702_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_5702_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_5703_AwakerVoiceContent = {
    Text = "您為什麼總是躲著我呢？是害羞了嗎？真可愛，您這幅不敢直面欲望的樣子……"
  },
  Voice_5703_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_5703_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_5704_AwakerVoiceContent = {
    Text = "糟透了，這地方糟透了！怎麼會讓本大小姐和其他人在一張桌子上喝下午茶！……手制曲奇的味道倒是還可以，晚飯後送一點到我的臥室去。"
  },
  Voice_5704_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_5705_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5706_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_5707_AwakerVoiceContent = {
    Text = "融蝕……故鄉的書院是有相關的記載啦，不過珈倫討厭看書，全都忘光光啦！"
  },
  Voice_5707_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_5708_AwakerVoiceContent = {
    Text = "您想讓我再度起航嗎？若您不介意我曾經失職，我會試著這麼做。"
  },
  Voice_5708_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5708_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_5709_AwakerVoiceContent = {
    Text = "討厭的東西？那可太多了——要求工人工作到深夜的老闆，自以為是的修女，咕咕亂叫的肚子，插著碎玻璃的黑麵包……"
  },
  Voice_5709_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5710_AwakerVoiceContent = {
    Text = "是艾繼絲不好，全部，都是我的錯……"
  },
  Voice_5710_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_5711_AwakerVoiceContent = {
    Text = "結束吧！"
  },
  Voice_5711_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5712_AwakerVoiceContent = {
    Text = "承蒙漢娜小姐關照，我旁聽了唱詩班的練習。唱詩和船歌很不一樣，在庇佑航船的時間裡，我從未聽過如此別致的音律……"
  },
  Voice_5712_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_5713_AwakerVoiceContent = {
    Text = "這招如何！"
  },
  Voice_5714_AwakerVoiceContent = {
    Text = "這招如何！"
  },
  Voice_5715_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5716_AwakerVoiceContent = {Text = "嗚......"},
  Voice_5716_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5717_AwakerVoiceContent = {
    Text = "你好呀，我的新主人！今天的菜品有蛞蝓布丁、蟾蜍燉菜和綠焰酒，主人可以隨意挑選哦~"
  },
  Voice_5717_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5718_AwakerVoiceContent = {
    Text = "那就是回歸本源的形態嗎……不，和我想像中有些不一樣。不過，要是我也能變成那個樣子就好了。"
  },
  Voice_5718_AwakerVoiceTitle = {
    Text = "閒話·關於深海血脈"
  },
  Voice_5718_UnlockDesc = {
    Text = "獲得喚醒體「圖魯」「墨菲」「彌利亞姆」「戈利亞」其一後解鎖"
  },
  Voice_5719_AwakerVoiceContent = {
    Text = "等待時機。"
  },
  Voice_5721_AwakerVoiceContent = {
    Text = "羔羊啊，神的憐憫會救贖你們。"
  },
  Voice_5721_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_5722_AwakerVoiceContent = {
    Text = "羔羊啊，神的憐憫會救贖你們。"
  },
  Voice_5722_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5723_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5724_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5725_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5726_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5727_AwakerVoiceContent = {
    Text = "她也是個可憐人，終將被命運蹂躪。因為，祂真正降生之刻，就是我將死亡賜予她之時。"
  },
  Voice_5727_AwakerVoiceTitle = {
    Text = "閒話·關於彌利亞姆"
  },
  Voice_5727_UnlockDesc = {
    Text = "獲得喚醒體「彌利亞姆」後解鎖"
  },
  Voice_5728_AwakerVoiceContent = {
    Text = "染上鮮血吧！"
  },
  Voice_5729_AwakerVoiceContent = {
    Text = "復仇……！"
  },
  Voice_5730_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5731_AwakerVoiceContent = {
    Text = "（隱忍的痛呼）"
  },
  Voice_5731_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_5732_AwakerVoiceContent = {
    Text = "（隱忍的痛呼）"
  },
  Voice_5732_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5733_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_5734_AwakerVoiceContent = {
    Text = "您想要和我一同沉沒嗎？"
  },
  Voice_5734_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_5735_AwakerVoiceContent = {Text = "滾開！"},
  Voice_5735_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5736_AwakerVoiceContent = {
    Text = "討厭的東西……擺放無序的書桌，亂糟糟的衣櫃，積灰的窗臺——是的，我在描述你的房間。明早七點前，我要見到它恢復成你入住前的樣子。"
  },
  Voice_5736_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5737_AwakerVoiceContent = {
    Text = "（饒有興致的輕哼）"
  },
  Voice_5737_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_5738_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5739_AwakerVoiceContent = {
    Text = "（不屑的譏笑）"
  },
  Voice_5739_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_5740_AwakerVoiceContent = {
    Text = "如果需要的話，我可以離開搖籃……"
  },
  Voice_5740_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_5741_AwakerVoiceContent = {
    Text = "想要嗎？"
  },
  Voice_5741_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_5742_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5743_AwakerVoiceContent = {
    Text = "Double、double、double！"
  },
  Voice_5744_AwakerVoiceContent = {
    Text = "這讓我想起來八歲時收到的第一雙紅舞鞋。我真的很喜歡，謝謝你，守密人。"
  },
  Voice_5744_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5744_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_5745_AwakerVoiceContent = {
    Text = "朋友……是主人？還是母親？"
  },
  Voice_5745_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_5746_AwakerVoiceContent = {
    Text = "我的庇佑，也有失靈的時候……"
  },
  Voice_5746_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_5747_AwakerVoiceContent = {
    Text = "（悶哼）"
  },
  Voice_5747_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5748_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5749_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_5750_AwakerVoiceContent = {
    Text = "喜歡的東西？在伯羅奔尼薩斯的戰場上，也有人問過我這個問題……太晚了，我早已捨棄了這類私人的好惡。"
  },
  Voice_5750_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_5751_AwakerVoiceContent = {
    Text = "噓……關於我變強這件事，請別讓「她們」發現。"
  },
  Voice_5751_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_5752_AwakerVoiceContent = {
    Text = "「她們」說……非常感謝。"
  },
  Voice_5752_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_5753_AwakerVoiceContent = {
    Text = "那個……這是什麼？"
  },
  Voice_5753_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5754_AwakerVoiceContent = {
    Text = "這只會將讓我更加靠近深淵。"
  },
  Voice_5754_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5754_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5755_AwakerVoiceContent = {
    Text = "你是我心愛的僕從。我知道，你們把這稱為朋友、夥伴、同志......沒關係，一切隨你高興。"
  },
  Voice_5755_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5756_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5756_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5757_AwakerVoiceContent = {
    Text = "是「恐懼」嗎？還是「傷心」？你頹喪的臉色真讓人著迷。"
  },
  Voice_5757_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5757_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5758_AwakerVoiceContent = {
    Text = "死亡與湮滅的氣味，如此清晰。"
  },
  Voice_5758_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_5758_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_5759_AwakerVoiceContent = {
    Text = "這裡的生活？挺、挺好的。只要我給朵爾小姐一些機械科學和精神研究方面的知識，她就允許我一直開著燈呢。"
  },
  Voice_5759_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_5760_AwakerVoiceContent = {
    Text = "希望詹金和布朗在學院裡過得開心，父親的袖扣同她的自在比起來，不值一提，我相信他還有一整盒備用的。"
  },
  Voice_5760_AwakerVoiceTitle = {
    Text = "閒話·關於詹金"
  },
  Voice_5760_UnlockDesc = {
    Text = "獲得喚醒體「詹金」後解鎖"
  },
  Voice_5761_AwakerVoiceContent = {
    Text = "不能離開……"
  },
  Voice_5762_AwakerVoiceContent = {
    Text = "脫離了劣等種族的我，根本不會畏懼這種影響。即使寄宿的軀體破碎，高貴的血脈也不會消亡。"
  },
  Voice_5762_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_5763_AwakerVoiceContent = {
    Text = "討厭假笑的人！從他們身上根本偷不到任何情緒！"
  },
  Voice_5763_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5764_AwakerVoiceContent = {
    Text = "嗯？大家怎麼都不說話了？珈倫討厭安靜，我來給你們講個故事吧。從前有座山......"
  },
  Voice_5764_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5765_AwakerVoiceContent = {
    Text = "莉莉會抓住未來……Tokuli—Li！"
  },
  Voice_5765_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5766_AwakerVoiceContent = {
    Text = "莉莉會抓住未來……Tokuli—Li！"
  },
  Voice_5766_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5767_AwakerVoiceContent = {
    Text = "若你是為了感知祂的存在，我就暫時寬恕你的無禮吧。"
  },
  Voice_5767_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_5768_AwakerVoiceContent = {
    Text = "不想這麼做……"
  },
  Voice_5770_AwakerVoiceContent = {
    Text = "逐漸、逐漸能跟上您的指揮步調了！"
  },
  Voice_5770_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5771_AwakerVoiceContent = {
    Text = "距離成為正式騎士，又近了一些！"
  },
  Voice_5771_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_5772_AwakerVoiceContent = {
    Text = "感謝您的拔擢，不勝榮幸。"
  },
  Voice_5772_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_5773_AwakerVoiceContent = {
    Text = "浴場是個消磨時間的好地方，不僅飯好吃，還提供肌肉放鬆服務。心動了？那就在學校裡也修一間，立刻，馬上！"
  },
  Voice_5773_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_5774_AwakerVoiceContent = {
    Text = "不、不要離開！"
  },
  Voice_5774_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5775_AwakerVoiceContent = {
    Text = "準備好了。"
  },
  Voice_5776_AwakerVoiceContent = {
    Text = "（吃痛的悶哼）"
  },
  Voice_5776_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_5777_AwakerVoiceContent = {
    Text = "（不屑的隱忍）"
  },
  Voice_5777_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5778_AwakerVoiceContent = {
    Text = "（不屑的隱忍）"
  },
  Voice_5778_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_5779_AwakerVoiceContent = {
    Text = "（不屑的隱忍）"
  },
  Voice_5779_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5780_AwakerVoiceContent = {
    Text = "託付給我吧。"
  },
  Voice_57818_AwakerVoiceContent = {
    Text = "所有侮辱我的人，都要付出代價！"
  },
  Voice_57818_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_57819_AwakerVoiceContent = {
    Text = "所有侮辱我的人，都要付出代價！"
  },
  Voice_57819_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_5781_AwakerVoiceContent = {
    Text = "託付給我吧。"
  },
  Voice_57820_AwakerVoiceContent = {
    Text = "尋找故國的步伐，沒有人能阻擋！"
  },
  Voice_57820_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_57821_AwakerVoiceContent = {
    Text = "盡情享受這場殺戮盛宴吧！"
  },
  Voice_57821_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_57822_AwakerVoiceContent = {
    Text = "尋找故國的步伐，沒有人能阻擋！"
  },
  Voice_57822_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_57823_AwakerVoiceContent = {
    Text = "虛假的使命，被定義的未來……我會反抗到底！"
  },
  Voice_57823_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_57824_AwakerVoiceContent = {
    Text = "虛假的使命，被定義的未來……我會反抗到底！"
  },
  Voice_57824_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_57825_AwakerVoiceContent = {
    Text = "盡情享受這場殺戮盛宴吧！"
  },
  Voice_57825_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_57826_AwakerVoiceContent = {
    Text = "加入我的儀式吧，成為我的種子！"
  },
  Voice_57826_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_57827_AwakerVoiceContent = {
    Text = "背叛者，品嘗我的絕望與憤怒吧！"
  },
  Voice_57827_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_57828_AwakerVoiceContent = {
    Text = "背叛者，品嘗我的絕望與憤怒吧！"
  },
  Voice_57828_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_57829_AwakerVoiceContent = {
    Text = "加入我的儀式吧，成為我的種子！"
  },
  Voice_57829_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_5782_AwakerVoiceContent = {
    Text = "我一直不好意思告訴奧瑞塔，我並沒有她想像中那麼年幼……能替我勸勸她，不要再叫我“妹妹”了嗎？"
  },
  Voice_5782_AwakerVoiceTitle = {
    Text = "閒話·關於奧瑞塔"
  },
  Voice_5782_UnlockDesc = {
    Text = "獲得喚醒體「奧瑞塔」後解鎖"
  },
  Voice_57830_AwakerVoiceContent = {
    Text = "失落已久的螺湮之城，終於褪去了她的面紗。"
  },
  Voice_57830_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_57831_AwakerVoiceContent = {
    Text = "失落已久的螺湮之城，終於褪去了她的面紗。"
  },
  Voice_57831_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_57832_AwakerVoiceContent = {
    Text = "是余兌現諾言之時了。"
  },
  Voice_57832_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_57833_AwakerVoiceContent = {
    Text = "是余兌現諾言之時了。"
  },
  Voice_57833_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_57834_AwakerVoiceContent = {
    Text = "一切皆為祂的安排。"
  },
  Voice_57834_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_57835_AwakerVoiceContent = {
    Text = "一切皆為祂的安排。"
  },
  Voice_57835_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_57836_AwakerVoiceContent = {
    Text = "自群星而來之物，向您獻上邀約。"
  },
  Voice_57836_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_57837_AwakerVoiceContent = {
    Text = "我仍是……來自群星的色彩！"
  },
  Voice_57837_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_57838_AwakerVoiceContent = {
    Text = "我仍是……來自群星的色彩！"
  },
  Voice_57838_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_57839_AwakerVoiceContent = {
    Text = "自群星而來之物，向您獻上邀約。"
  },
  Voice_57839_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_5783_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_57840_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_57841_AwakerVoiceContent = {
    Text = "蟄伏地底的迷宮之神，向諸位宣判！"
  },
  Voice_57841_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_57842_AwakerVoiceContent = {
    Text = "蟄伏地底的迷宮之神，向諸位宣判！"
  },
  Voice_57842_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_57843_AwakerVoiceContent = {
    Text = "翱翔碧空之鳥，請回應我的祈願。"
  },
  Voice_57843_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_57844_AwakerVoiceContent = {
    Text = "翱翔碧空之鳥，請回應我的祈願。"
  },
  Voice_57844_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_57845_AwakerVoiceContent = {
    Text = "不准動不准動不准動！"
  },
  Voice_57845_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_57846_AwakerVoiceContent = {
    Text = "在血鏈下顫抖……在血鏈下毀滅！"
  },
  Voice_57846_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_57847_AwakerVoiceContent = {
    Text = "在血鏈下顫抖……在血鏈下毀滅！"
  },
  Voice_57847_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_57848_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_57849_AwakerVoiceContent = {
    Text = "不准動不准動不准動！"
  },
  Voice_57849_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_5784_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_57850_AwakerVoiceContent = {
    Text = "見識一下吧，這就是非利士人所依仗的力量！"
  },
  Voice_57850_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_57851_AwakerVoiceContent = {
    Text = "見識一下吧，這就是非利士人所依仗的力量！"
  },
  Voice_57851_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_5785_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5786_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5787_AwakerVoiceContent = {
    Text = "唔……主人看起來心情不太好？珈倫來扮鬼臉吧，嘻——哈！\n怎麼樣，現在開心一點了嗎？"
  },
  Voice_5787_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5788_AwakerVoiceContent = {
    Text = "以人類知性……解明世界本質！"
  },
  Voice_5788_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_5789_AwakerVoiceContent = {
    Text = "我在走廊裡遇到了一些讓我感覺不妙的人。或許受局勢所迫，你必須要和她們協同作戰，但請時刻保持警惕。比戰爭更殘酷的東西唯有人心，最可怕的背叛往往來源於內部。"
  },
  Voice_5789_AwakerVoiceTitle = {
    Text = "閒話·關於@2"
  },
  Voice_5789_UnlockDesc = {
    Text = "獲得喚醒體「希洛」或「莉莉」後解鎖"
  },
  Voice_5790_AwakerVoiceContent = {
    Text = "你的作業完成了吧，可以陪我去一趟倫蒂尼恩市區嗎……誒？數學作業還沒有完成？！\n啊、啊……抱歉，我沒想到會有人不懂微積分……讓我來幫你吧？"
  },
  Voice_5790_AwakerVoiceTitle = {
    Text = "閒話·關於學習"
  },
  Voice_5791_AwakerVoiceContent = {
    Text = "我向您發誓，那位店主絕對在楓丹白露的沙龍中露過臉……原來如此，從那時起，她就是如此模樣嗎。不知道從她手中，能換得多少密辛呢？"
  },
  Voice_5791_AwakerVoiceTitle = {
    Text = "閒話·關於達芙黛爾"
  },
  Voice_5791_UnlockDesc = {
    Text = "獲得喚醒體「達芙黛爾」後解鎖"
  },
  Voice_5792_AwakerVoiceContent = {
    Text = "（驚呼）"
  },
  Voice_5792_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5793_AwakerVoiceContent = {
    Text = "別弄碎了。"
  },
  Voice_5793_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_5794_AwakerVoiceContent = {
    Text = "奧瑞塔喜歡和大家一起玩！你也要來嗎？這孩子叫啫喱，那個是海拉，那邊那個叫啫喱……咦？"
  },
  Voice_5794_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_5795_AwakerVoiceContent = {
    Text = "恥辱，就用這招來洗清！"
  },
  Voice_5795_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_5796_AwakerVoiceContent = {
    Text = "達芙黛爾的小店開張了，沒有做好準備的孩子們，最好不要隨意走進來哦？"
  },
  Voice_5796_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5796_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_5797_AwakerVoiceContent = {
    Text = "請不要摸我的脖子……看不見，不代表不存在。"
  },
  Voice_5797_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_5798_AwakerVoiceContent = {
    Text = "我喜歡有信念的傢伙，不管是動物、喚醒體還是人類。要是這些傢伙武技超群，就更棒了。"
  },
  Voice_5798_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_5799_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5800_AwakerVoiceContent = {
    Text = "別擔心！"
  },
  Voice_5800_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_5801_AwakerVoiceContent = {
    Text = "拉蒙娜討厭失去……抱歉，我的意思是，我不喜歡別離，這太令人傷感了。"
  },
  Voice_5801_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5802_AwakerVoiceContent = {
    Text = "我不擅長與神職者相處。他們無趣又古板，還將腰帶交給了他們敬愛的「神」，真可惜，薩爾瓦多先生明明聞起來是如此的甜美……"
  },
  Voice_5802_AwakerVoiceTitle = {
    Text = "閒話·關於薩爾瓦多"
  },
  Voice_5802_UnlockDesc = {
    Text = "獲得喚醒體「薩爾瓦多」後解鎖"
  },
  Voice_5803_AwakerVoiceContent = {
    Text = "酣暢淋漓的對決勝過一切，包括輸贏。"
  },
  Voice_5803_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_5804_AwakerVoiceContent = {
    Text = "誰不喜歡柔軟的床鋪和不漏風的下水……房間呢。"
  },
  Voice_5804_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_5805_AwakerVoiceContent = {
    Text = "……不要讓我回憶起來……被囚禁在艾爾沃斯的日子……"
  },
  Voice_5805_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5806_AwakerVoiceContent = {
    Text = "燃盡一切！"
  },
  Voice_5807_AwakerVoiceContent = {
    Text = "燃盡一切！"
  },
  Voice_5808_AwakerVoiceContent = {
    Text = "我循著血的香氣找到這處所在。請問……這裡提供新鮮的血包嗎？"
  },
  Voice_5808_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5809_AwakerVoiceContent = {
    Text = "嗯……阿格里帕也有很多夥伴呢，但是大家看起來都很怕她的樣子。難不成，她會搶夥伴們的東西吃？"
  },
  Voice_5809_AwakerVoiceTitle = {
    Text = "閒話·關於阿格里帕"
  },
  Voice_5809_UnlockDesc = {
    Text = "獲得喚醒體「阿格里帕」後解鎖"
  },
  Voice_5810_AwakerVoiceContent = {
    Text = "我的生活裡只有舞蹈，就算讓我學習其他知識，也很難成長。但大家都是善良的人，不會為了虛榮或金錢將我販售出去，我能感覺到。"
  },
  Voice_5810_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_5811_AwakerVoiceContent = {
    Text = "怯懦的傢伙，明明擁有與我相似的強大力量，卻如此壓制自己，這和自願戴上項圈有什麼區別！"
  },
  Voice_5811_AwakerVoiceTitle = {
    Text = "閒話·關於莉莉"
  },
  Voice_5811_UnlockDesc = {
    Text = "獲得喚醒體「莉莉」後解鎖"
  },
  Voice_5812_AwakerVoiceContent = {
    Text = "不夠……力量還不夠……"
  },
  Voice_5812_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_5813_AwakerVoiceContent = {
    Text = "回頭吧。"
  },
  Voice_5813_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5814_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_5815_AwakerVoiceContent = {
    Text = "大禮帽、圓頂禮帽、獵鹿帽、貝雷帽……不得不說，你們上流社會的紳士為了遮掩禿頭竭盡全力的模樣很可笑。"
  },
  Voice_5815_AwakerVoiceTitle = {
    Text = "閒話·關於禮儀"
  },
  Voice_5816_AwakerVoiceContent = {
    Text = "我很嚮往那個人，潔白高雅如同百合花的航海神明……您說這樣的她，也無法掌控自己的命運，最終沉沒於海底嗎？這，實在難以想像……"
  },
  Voice_5816_AwakerVoiceTitle = {
    Text = "閒話·關於希萊斯特"
  },
  Voice_5816_UnlockDesc = {
    Text = "獲得喚醒體「希萊斯特」後解鎖"
  },
  Voice_5817_AwakerVoiceContent = {
    Text = "世上不存在巨人無法匹敵之物！"
  },
  Voice_5817_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5818_AwakerVoiceContent = {
    Text = "世上不存在巨人無法匹敵之物！"
  },
  Voice_5818_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_5819_AwakerVoiceContent = {
    Text = "可惡，可惡……！力量只會把我牢牢鎖在身體裡……"
  },
  Voice_5819_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5819_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5820_AwakerVoiceContent = {
    Text = "好想待在永遠亮堂的地方……對，極點，在這顆星球上，就只有極點了。"
  },
  Voice_5820_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5820_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5821_AwakerVoiceContent = {
    Text = "我、我沒法承擔什麼重任，只能追著光跑。所以，請你不要停止閃爍……"
  },
  Voice_5821_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5821_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5822_AwakerVoiceContent = {
    Text = "如果還能遷移的話，我會想成為一顆恒星……"
  },
  Voice_5822_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_5822_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_5823_AwakerVoiceContent = {
    Text = "再怎麼演算，進行意識遷移的公式都不可解……"
  },
  Voice_5823_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5823_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5824_AwakerVoiceContent = {
    Text = "歡迎光臨，一起來狂歡吧！"
  },
  Voice_5824_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5825_AwakerVoiceContent = {
    Text = "客官請慢用！"
  },
  Voice_5825_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_5826_AwakerVoiceContent = {
    Text = "呼呼——是奧瑞塔喲！一個，兩個，三個……哇！歡迎歡迎！新夥伴增加啦！嗯？是我成為了大家的新夥伴？也可以這麼說吧！"
  },
  Voice_5826_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5827_AwakerVoiceContent = {
    Text = "你們管這小玩具叫手槍？只敢躲在陰影裡偷襲對手，果真是懦夫的武器。"
  },
  Voice_5827_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5828_AwakerVoiceContent = {
    Text = "沒意義，這麼做根本沒意義。"
  },
  Voice_5828_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_5829_AwakerVoiceContent = {
    Text = "你根本什麼都不懂。"
  },
  Voice_5829_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5830_AwakerVoiceContent = {
    Text = "還在指望我成為“救世主”的後援嗎？"
  },
  Voice_5830_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_5831_AwakerVoiceContent = {
    Text = "不好意思，你有見到我的螺絲嗎？真奇怪啊，只要有那個老鼠耳朵的孩子在，我好像更容易忘了自己都把東西放到哪兒去了……"
  },
  Voice_5831_AwakerVoiceTitle = {
    Text = "閒話·關於詹金"
  },
  Voice_5831_UnlockDesc = {
    Text = "獲得喚醒體「詹金」後解鎖"
  },
  Voice_5832_AwakerVoiceContent = {
    Text = "我不會忘記，你為我與吾主的重逢獻上的一切……"
  },
  Voice_5832_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5833_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5834_AwakerVoiceContent = {
    Text = "你已認可我的願望了嗎？"
  },
  Voice_5834_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_5835_AwakerVoiceContent = {
    Text = "但願你的指揮不會讓人失望。"
  },
  Voice_5835_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_5836_AwakerVoiceContent = {
    Text = "得到提升的，是這具軀殼還是我的意識呢？有趣的課題。"
  },
  Voice_5836_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5836_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_5837_AwakerVoiceContent = {Text = "退後。"},
  Voice_5837_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_5838_AwakerVoiceContent = {Text = "讓開。"},
  Voice_5838_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5839_AwakerVoiceContent = {
    Text = "我的脈管中奔湧著求生的意志，它尖叫著，驅使著我將血灑在星球的每一寸土地上……啊啊，讓您聽了如此多牢騷，見笑了。我是泰旖絲，您呼喚我，是已經做好與我相融的準備了嗎？"
  },
  Voice_5839_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5840_AwakerVoiceContent = {
    Text = "要是艾繼絲能替大家承受這種黑色的液體就好了……畢竟，艾繼絲不曾存在過，對這個世界來說應該是好事吧？"
  },
  Voice_5840_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_5841_AwakerVoiceContent = {
    Text = "愛好是黎曼猜想——這是那只孔雀的口頭禪，不是我的。相比之下，我對原子基準量的研究更感興趣。"
  },
  Voice_5841_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_5842_AwakerVoiceContent = {
    Text = "被掃地出門，流亡大海的滋味......體驗一次就夠了。"
  },
  Voice_5842_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_5846_AwakerVoiceContent = {
    Text = "只要你能堅守這份正義，我就會一直承擔利刃的職責。"
  },
  Voice_5846_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5847_AwakerVoiceContent = {
    Text = "您知道這裡流傳著有關「繪者」的傳說嗎？從那些表現主義的塗鴉風格裡，我嗅到了一絲熟悉的味道……"
  },
  Voice_5847_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_5848_AwakerVoiceContent = {
    Text = "好痛，好興奮——"
  },
  Voice_5848_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5849_AwakerVoiceContent = {
    Text = "見識我的憤怒吧！"
  },
  Voice_5849_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5850_AwakerVoiceContent = {
    Text = "用詩篇記錄這場勝利吧。"
  },
  Voice_5850_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5851_AwakerVoiceContent = {
    Text = "長大吧——"
  },
  Voice_5851_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5852_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5853_AwakerVoiceContent = {Text = "誒！"},
  Voice_5853_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_5854_AwakerVoiceContent = {
    Text = "也許長大以後，我就能控制住自己，不把別人的生命力抽乾……只要一點點就夠我生存下去了。"
  },
  Voice_5854_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_5854_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_5855_AwakerVoiceContent = {
    Text = "好像變沉了些，搖籃還能承受我的重量嗎？"
  },
  Voice_5855_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5855_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5856_AwakerVoiceContent = {
    Text = "力量快要溢出來了，背後癢癢的，是要長大了嗎？"
  },
  Voice_5856_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_5856_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_5857_AwakerVoiceContent = {
    Text = "雖然還是小孩的外表，但現在的我……已經擁有保護你的力量了。"
  },
  Voice_5857_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5857_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5858_AwakerVoiceContent = {
    Text = "我會努力長大的。"
  },
  Voice_5858_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_5858_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_5859_AwakerVoiceContent = {
    Text = "不知好歹的東西，為何執著於喚醒我？"
  },
  Voice_5859_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5860_AwakerVoiceContent = {
    Text = "我將成為神之母！"
  },
  Voice_5860_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5861_AwakerVoiceContent = {
    Text = "這是第幾次被召喚了……人類，你最好給我準備了足量的「食物」，不然我可什麼都不敢保證。"
  },
  Voice_5861_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5862_AwakerVoiceContent = {
    Text = "門扉之外！"
  },
  Voice_5862_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5863_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5864_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5865_AwakerVoiceContent = {
    Text = "哼，不錯。下次的對決我將全力以赴。"
  },
  Voice_5865_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_5866_AwakerVoiceContent = {
    Text = "無禮之人！"
  },
  Voice_5866_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_5867_AwakerVoiceContent = {
    Text = "有時候，藝術之美即湮滅之美。而您的失敗……顯然不在此列。"
  },
  Voice_5867_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_5868_AwakerVoiceContent = {
    Text = "您是我最重要的聽眾，無論何時，我都會準備好為您獻上歌喉，以及一切。"
  },
  Voice_5868_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5869_AwakerVoiceContent = {
    Text = "喜歡的東西？水草、魚群、廊柱、迷宮……我當然見過！奧恩叔叔的那本書上都有！"
  },
  Voice_5869_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_5870_AwakerVoiceContent = {
    Text = "這是為調查任務而做的準備嗎？我明白了。"
  },
  Voice_5870_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5870_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_5871_AwakerVoiceContent = {
    Text = "我的名字是希萊斯特。只要你還需要我，我便會存在於此。"
  },
  Voice_5871_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5872_AwakerVoiceContent = {
    Text = "嚐嚐教訓！"
  },
  Voice_5873_AwakerVoiceContent = {
    Text = "放尊重些，後輩。軍隊中長幼有序，令行禁止，這樣出格的行為會受到懲戒。"
  },
  Voice_5873_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_5874_AwakerVoiceContent = {
    Text = "我倒是願意為那些「小玩具」提供售後，問題在於，你們敢接受我的服務嗎？"
  },
  Voice_5874_AwakerVoiceTitle = {
    Text = "閒話·關於發明"
  },
  Voice_5875_AwakerVoiceContent = {
    Text = "您是這裡的主人，但也是我沙龍的客人。我會為您的造訪，準備最上乘的款待——您喜歡豔紅的襯裙，還是白薔色的睡衣呢？"
  },
  Voice_5875_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5876_AwakerVoiceContent = {
    Text = "抱歉，這裡的陽光有些刺眼……來自陰暗地穴的老鼠一時還無法適應。"
  },
  Voice_5876_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_5877_AwakerVoiceContent = {
    Text = "能侵蝕萬物，磨滅一切……那可是個了不得的武器。若是當時的我知道……呵。"
  },
  Voice_5877_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_5878_AwakerVoiceContent = {
    Text = "有傳言說，在焚燒的火焰中抽搐的人體就像在跳舞一樣。"
  },
  Voice_5878_AwakerVoiceTitle = {
    Text = "閒話·關於火焰"
  },
  Voice_5880_AwakerVoiceContent = {
    Text = "不要在夜晚外出，即使帶著2000流明的光源也不是萬分保險……一旦步入黑暗，那些潛伏於目光之外的惡魔就會追上你，吞噬你，追上你，吞噬你……直到什麼都不剩。"
  },
  Voice_5880_AwakerVoiceTitle = {
    Text = "閒話·關於夜晚"
  },
  Voice_5883_AwakerVoiceContent = {
    Text = "那是生命的渴望，催動天鵝為回歸遙遠的天際而掙扎。"
  },
  Voice_5883_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5883_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5884_AwakerVoiceContent = {
    Text = "開始變了！"
  },
  Voice_5885_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5886_AwakerVoiceContent = {
    Text = "（驚呼）"
  },
  Voice_5886_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_5887_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_5888_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_5889_AwakerVoiceContent = {
    Text = "啊，布朗跑過去了！我、我還是迴避一下好了……\n明明想要和她做朋友，沒想到最後還是成為了她的夢魘……她一定不想見到我吧……"
  },
  Voice_5889_AwakerVoiceTitle = {
    Text = "閒話·關於詹金"
  },
  Voice_5889_UnlockDesc = {
    Text = "獲得喚醒體「詹金」後解鎖"
  },
  Voice_5890_AwakerVoiceContent = {
    Text = "禮拜堂？非常感謝，但事實上我並不是那麼的老派。只要心中常懷仁愛之神的教導，並時刻踐行祂的旨意，我的靈魂就不會遠離祂的榮光。"
  },
  Voice_5890_AwakerVoiceTitle = {
    Text = "閒話·關於禮拜堂"
  },
  Voice_5891_AwakerVoiceContent = {
    Text = "我的名字是奧吉爾。依照與您的契約，我將向您獻上騎士的忠義，守護您的安全，排除您的敵人。今日誓言，永志不忘。"
  },
  Voice_5891_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5892_AwakerVoiceContent = {
    Text = "那個乾癟的重瞳女人，聞起來和斯巴達臭蟲如出一轍。"
  },
  Voice_5892_AwakerVoiceTitle = {
    Text = "閒話·關於阿格里帕"
  },
  Voice_5892_UnlockDesc = {
    Text = "獲得喚醒體「阿格里帕」後解鎖"
  },
  Voice_5893_AwakerVoiceContent = {
    Text = "喜歡的東西？當然是好運氣了。每天出門都要討個好彩頭呢。"
  },
  Voice_5893_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_5894_AwakerVoiceContent = {
    Text = "請、請不要告訴漢娜小姐我躲在這裡。我還沒有做好準備……"
  },
  Voice_5894_AwakerVoiceTitle = {
    Text = "閒話·關於漢娜"
  },
  Voice_5895_AwakerVoiceContent = {
    Text = "這樣如何？"
  },
  Voice_5895_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5896_AwakerVoiceContent = {
    Text = "您是我尊貴的客人。要知道，我可只能容許您一個人賒帳。畢竟，好多年沒見過這麼完美的頭顱了……"
  },
  Voice_5896_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5897_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_5898_AwakerVoiceContent = {
    Text = "（驚呼）"
  },
  Voice_5898_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5899_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_5900_AwakerVoiceContent = {
    Text = "喜歡的東西……王不應有如此表徵，但如果能遠離惱人的奏本和禱告，蜷於軟塌之上，余自然是樂得清閒。"
  },
  Voice_5900_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_5901_AwakerVoiceContent = {
    Text = "余會將汝等的不敬之舉，理解為索求長眠。"
  },
  Voice_5901_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_5902_AwakerVoiceContent = {
    Text = "討厭嗎？我討厭無法逃離的命運和註定發生的悲劇。"
  },
  Voice_5902_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5903_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_5904_AwakerVoiceContent = {
    Text = "（隱忍的哼鳴）"
  },
  Voice_5904_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_5905_AwakerVoiceContent = {
    Text = "別過來！"
  },
  Voice_5905_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5906_AwakerVoiceContent = {
    Text = "哦呀，想打聽我的秘密嗎？這名字、這身軀、這容貌、這嗓音，都來自於聖佩德羅的一枚頭顱的女主人。她與我做了交易……在她死後，我便成為了她。至於她的下落……那可是我最美妙的收藏品哦？"
  },
  Voice_5906_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_5906_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_5907_AwakerVoiceContent = {
    Text = "您是一位令人愉快的客人，連我也被您這顆獨一無二的頭顱迷住了……若您有意向轉讓，可一定要來光顧我的小店。呵呵……只是跟您開個玩笑。"
  },
  Voice_5907_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_5907_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_5908_AwakerVoiceContent = {
    Text = "打聽我的真實身分嗎？現在還為時尚早了吧。您只要相信這個就行了：迷途的孩子都能在我的店中找到歸宿。包括您在內哦？"
  },
  Voice_5908_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5908_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_5909_AwakerVoiceContent = {
    Text = "沒有人會受到傷害。"
  },
  Voice_5909_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5910_AwakerVoiceContent = {
    Text = "還沒結束！"
  },
  Voice_5910_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5911_AwakerVoiceContent = {
    Text = "看到您如此努力的身影，我都有點不好意思這麼快收取酬勞了。所以，您的頭顱暫時還是放在原位吧。\n但別忘了，它已經預定為我的私有品了哦？"
  },
  Voice_5911_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_5911_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_5912_AwakerVoiceContent = {
    Text = "曾經的我並非如此形貌，是她給予了我新生。這麼說來，您也是賦予我二次生命之人，我也會好好珍藏您的頭顱的。"
  },
  Voice_5912_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_5912_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_5913_AwakerVoiceContent = {
    Text = "徹底逃離黑暗。"
  },
  Voice_5913_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5914_AwakerVoiceContent = {
    Text = "原來冒險這麼危險……"
  },
  Voice_5914_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_5915_AwakerVoiceContent = {
    Text = "那傻妞怎麼一看見我就跑？下次我要踩著她的毛線，看她能往哪跑。"
  },
  Voice_5915_AwakerVoiceTitle = {
    Text = "閒話·關於艾繼絲"
  },
  Voice_5915_UnlockDesc = {
    Text = "獲得喚醒體「艾繼絲」後解鎖"
  },
  Voice_5916_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5919_AwakerVoiceContent = {
    Text = "那個小鬼很有靈性，街頭生存就需要這種智慧。如果我還在外面探案的話，肯定會和她搞好關係的。"
  },
  Voice_5919_AwakerVoiceTitle = {
    Text = "閒話·關於詹金"
  },
  Voice_5919_UnlockDesc = {
    Text = "獲得喚醒體「詹金」後解鎖"
  },
  Voice_5920_AwakerVoiceContent = {
    Text = "那位聖父沒辦法拯救所有人。他也許能幫助一個倒楣鬼，但不能把所有人拖出泥沼……我很期待他，期待他信仰的崩塌。"
  },
  Voice_5920_AwakerVoiceTitle = {
    Text = "閒話·關於薩爾瓦多"
  },
  Voice_5920_UnlockDesc = {
    Text = "獲得喚醒體「薩爾瓦多」後解鎖"
  },
  Voice_5921_AwakerVoiceContent = {
    Text = "您可以在倫蒂尼恩的下水道裡找到需要的一切：鮭魚、肥皂、喝了一半的威士卡……\n什麼，您問我為什麼這麼了解？我曾經拖著哥哥的屍體，在裡面爬了五里哦……"
  },
  Voice_5921_AwakerVoiceTitle = {
    Text = "閒話·關於下水道"
  },
  Voice_5922_AwakerVoiceContent = {
    Text = "給我跪下！"
  },
  Voice_5923_AwakerVoiceContent = {
    Text = "給我跪下。"
  },
  Voice_5924_AwakerVoiceContent = {
    Text = "在窺見戰場外的真實世界後，我一度懷疑過所謂“英雄”的價值。但好在我遇見了你，正直、勇敢、一塵不染。我會在你的麾下，為世界的和平與安穩不遺餘力地戰鬥。這一次，一定能夠完成我的贖罪。"
  },
  Voice_5924_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_5924_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_5925_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_5926_AwakerVoiceContent = {
    Text = "不潔、穢亂、混沌——這就是我們的力量。"
  },
  Voice_5926_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5927_AwakerVoiceContent = {
    Text = "我討厭你們惺惺作態的樣子。覺得我發瘋了，我很可憐，是嗎？在我看來，你們是被太陽遮蔽了眼睛的伊卡洛斯，你們才是可憐蟲。"
  },
  Voice_5927_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5928_AwakerVoiceContent = {
    Text = "請讓我打頭陣吧！"
  },
  Voice_5928_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_5929_AwakerVoiceContent = {
    Text = "那些傢伙的氣息很陌生，他們不是這顆星球自然誕生的生命吧。"
  },
  Voice_5929_AwakerVoiceTitle = {
    Text = "閒話·關於星外之人"
  },
  Voice_5929_UnlockDesc = {
    Text = "獲得喚醒體「溫柯爾」「汀克特」「菲茵特」「旺達」其一後解鎖"
  },
  Voice_5931_AwakerVoiceContent = {
    Text = "（悶哼）"
  },
  Voice_5931_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_5932_AwakerVoiceContent = {
    Text = "湮滅吧！"
  },
  Voice_5933_AwakerVoiceContent = {
    Text = "請不要……"
  },
  Voice_5933_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5934_AwakerVoiceContent = {
    Text = "成為怪物也無妨，我想要的從始至終都是復仇的力量而已。"
  },
  Voice_5934_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_5934_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_5935_AwakerVoiceContent = {
    Text = "除了除掉對手外，你還有什麼想要的嗎？作為回報，我會實現你的願望……當然是在能力範圍內。"
  },
  Voice_5935_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_5935_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_5936_AwakerVoiceContent = {
    Text = "（悶哼）"
  },
  Voice_5936_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_5937_AwakerVoiceContent = {
    Text = "夥伴嗎？……我會考慮的，在我想清楚前，你別輕易死掉了。"
  },
  Voice_5937_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_5937_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_5938_AwakerVoiceContent = {
    Text = "自首次被明確記載以來，融蝕現象已影響了超過百萬人的生活。我們的行動，關乎著整個人類群體的存亡。"
  },
  Voice_5938_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_5939_AwakerVoiceContent = {
    Text = "馬力全開！"
  },
  Voice_5939_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5940_AwakerVoiceContent = {
    Text = "小心海之狂熱。"
  },
  Voice_5941_AwakerVoiceContent = {
    Text = "小心海之狂熱。"
  },
  Voice_5942_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5943_AwakerVoiceContent = {
    Text = "我是祂的王女，亦是祂的母親。至於你，在祂的面前只是無關緊要的螻蟻罷了。"
  },
  Voice_5943_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5944_AwakerVoiceContent = {
    Text = "一切順利，升起凱旋的桅帆吧。"
  },
  Voice_5944_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_5945_AwakerVoiceContent = {
    Text = "別靠近我，你想成為王女的玩物，還是神誕的祭品？"
  },
  Voice_5945_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5945_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_59463_AwakerVoiceContent = {
    Text = "輕輕鬆鬆、大獲全勝！"
  },
  Voice_59463_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_59464_AwakerVoiceContent = {
    Text = "輕輕鬆鬆、大獲全勝！"
  },
  Voice_59464_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_5946_AwakerVoiceContent = {
    Text = "我准許你成為見證者，見證那顛覆倫理的光輝時刻。"
  },
  Voice_5946_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_5946_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_5947_AwakerVoiceContent = {
    Text = "空洞嗎？隔空取物裡也經常會製造這樣的空洞呢！卡茜亞製造的空洞會連結到異次元，融蝕的也是嗎？"
  },
  Voice_5947_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_5948_AwakerVoiceContent = {
    Text = "守密人，我會用神之母的權能，在那深海王座之側為你留下一個席位，你將見證毀滅後重生的時代。盡情感激吧，這是神之母的許諾！"
  },
  Voice_5948_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_5948_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_5949_AwakerVoiceContent = {
    Text = "看在你如此恭敬的份上，我便賞賜你一個回答吧。最初的時候，當然也有過掙扎。但如今我已明白，我的奢靡生活俱是源於祂。死亡並非終點，祂將重誕下我，借這樣病態的輪回得享永生……"
  },
  Voice_5949_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_5949_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_5950_AwakerVoiceContent = {
    Text = "那女人的願望真是令人發笑。沒有東西能在湮滅後存活，就算是「神」也一樣。"
  },
  Voice_5950_AwakerVoiceTitle = {
    Text = "閒話·關於泰旖絲"
  },
  Voice_5950_UnlockDesc = {
    Text = "獲得喚醒體「泰旖絲」後解鎖"
  },
  Voice_5951_AwakerVoiceContent = {
    Text = "余是通靈之人，並非萬能之人，自然會犯錯。如今那女人把所有人牽扯下水的作為，就是余的無心之失……所以，余需要你的輔佐。為了隨時回應余的傳召，你被允許在余的寢宮置放床榻。"
  },
  Voice_5951_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_5951_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_5952_AwakerVoiceContent = {
    Text = "你肩負著直面災厄的任務吧，對你這個年紀來說還真是沉重……如果，從最開始就知道自己無法改變未來，你還會如此忠實地履行使命嗎？不要急著回答，在余安眠時思慮一番吧，余很好奇你的答案。"
  },
  Voice_5952_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_5952_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_5953_AwakerVoiceContent = {
    Text = "將余喚醒後已經過了一段時間了，你沒有任何想向余索取的嗎？神明的啟示，絕對應驗的預言，哪怕是沉沒大陸的寶藏——你真的都不想知道嗎？\n哼……奇怪的傢伙。"
  },
  Voice_5953_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_5953_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_5954_AwakerVoiceContent = {
    Text = "余從未向任何人要求過膜拜。愚人自以為是的行徑，只讓余愈感覺疲憊……退下吧，休息時間到了。"
  },
  Voice_5954_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_5954_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_5955_AwakerVoiceContent = {
    Text = "在你身上，余看不到任何與余之臣下相似的品質……罷了，也許這是好事。想起那個女人，余就感到睏倦。"
  },
  Voice_5955_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5955_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_5956_AwakerVoiceContent = {
    Text = "神，一視同仁。"
  },
  Voice_5956_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5957_AwakerVoiceContent = {
    Text = "我知道，你是特殊的觀眾，可不能把你嗖地一下丟到異次元去，不然會惹上大麻煩的。誒，有沒有對別人這麼做過？討厭，不要問啦，是人家的秘密！"
  },
  Voice_5957_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_5958_AwakerVoiceContent = {
    Text = "噫呀呀，你對這幅形貌感興趣嗎？看來有失必有得呀，這大概也是我萊克的好運氣之一吧？"
  },
  Voice_5958_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_5959_AwakerVoiceContent = {
    Text = "彌薩格是我留下最多記憶的場所，也是我……最溫暖的家。"
  },
  Voice_5959_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_5960_AwakerVoiceContent = {
    Text = "交給我吧。"
  },
  Voice_5960_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_5961_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5962_AwakerVoiceContent = {
    Text = "深海的聖詠！"
  },
  Voice_5963_AwakerVoiceContent = {
    Text = "我所獲賜之物——"
  },
  Voice_5963_AwakerVoiceTitle = {
    Text = "技能·一·靜海"
  },
  Voice_5964_AwakerVoiceContent = {
    Text = "如果你願意承認我還是「拉蒙娜」的話，請繼續這麼稱呼我吧。"
  },
  Voice_5964_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5965_AwakerVoiceContent = {
    Text = "怎麼，你也想要利用我的憤怒嗎？"
  },
  Voice_5965_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_5965_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_5966_AwakerVoiceContent = {
    Text = "真理…於此闡明。"
  },
  Voice_5966_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_5967_AwakerVoiceContent = {
    Text = "得到的食物立馬就要吃掉，這是街頭的法則。"
  },
  Voice_5967_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_5968_AwakerVoiceContent = {
    Text = "感覺像吃飽了一樣。"
  },
  Voice_5968_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_5969_AwakerVoiceContent = {
    Text = "唔……癢癢的，布朗，幫我撓撓背。"
  },
  Voice_5969_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_5970_AwakerVoiceContent = {
    Text = "嶄新的機械部件對我的機體運轉會有很大幫助——這不能算作喜歡嗎？對不起，我恐怕我不明白你的問題。喜好對機械人偶而言並無意義。"
  },
  Voice_5970_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_5974_AwakerVoiceContent = {
    Text = "考慮清楚。"
  },
  Voice_5974_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_5975_AwakerVoiceContent = {
    Text = "冷靜思考。"
  },
  Voice_5975_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_5976_AwakerVoiceContent = {
    Text = "溫柯爾小姐和我一樣，故鄉都不在這顆星球上……除了汀克特以外，我的家鄉沒有任何值得我留戀的。不知道溫柯爾小姐對她的故鄉，懷有怎樣的感情呢？"
  },
  Voice_5976_AwakerVoiceTitle = {
    Text = "閒話·關於溫柯爾"
  },
  Voice_5976_UnlockDesc = {
    Text = "獲得喚醒體「溫柯爾」後解鎖"
  },
  Voice_5977_AwakerVoiceContent = {
    Text = "別從背後靠近我，除非你想被扭斷脖子。"
  },
  Voice_5977_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_5977_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_5978_AwakerVoiceContent = {
    Text = "哈啊——你們怎麼會放任野貓在校園裡亂跑？！那個沒教養的小東西要是抓傷人怎麼辦！"
  },
  Voice_5978_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5979_AwakerVoiceContent = {
    Text = "我的眼神讓人感到不適了嗎？這就對了，正是這份兇悍，才使我在煉獄中存活下來。"
  },
  Voice_5979_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_5979_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_5980_AwakerVoiceContent = {
    Text = "冠冕堂皇的話就免了，你希望從我身上得到什麼？花精力維持我的理性，一定是有所索取吧。"
  },
  Voice_5980_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_5980_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_5981_AwakerVoiceContent = {
    Text = "我的復仇對象從來都只有斯巴達人，但現在，就連這個城邦都已經不復存在……罷了，成為你的刀刃也未嘗不可。我勉強認可你作為我的夥伴，但如果你敢背叛，我會掏出你的心臟。"
  },
  Voice_5981_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_5981_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_5982_AwakerVoiceContent = {
    Text = "我這雙手沾滿了鮮血。我那軟弱的同族並不認可我的復仇，他們在背後議論我的殘酷，我的不識好歹，我的忘恩負義……復仇，從來都只是為了我自己，與任何人無關。"
  },
  Voice_5982_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_5982_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_5983_AwakerVoiceContent = {
    Text = "該用上更多鋼材了。"
  },
  Voice_5984_AwakerVoiceContent = {
    Text = "該用上更多鋼材了。"
  },
  Voice_5985_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_5986_AwakerVoiceContent = {
    Text = "我是……還是叫我溫柯爾吧，他們都這麼叫我。是的，就這樣叫我，和他們一樣……"
  },
  Voice_5986_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5987_AwakerVoiceContent = {
    Text = "此身即為主君之盾！"
  },
  Voice_5987_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_5988_AwakerVoiceContent = {
    Text = "此身即為主君之盾！"
  },
  Voice_5988_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_5989_AwakerVoiceContent = {
    Text = "《胡桃夾子》本是女孩子的浪漫幻想童話，那些面目可憎的傢伙卻只在其中看見了橫飛的曼妙肢體與庸俗的生理欲望……令人作嘔。"
  },
  Voice_5989_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_5990_AwakerVoiceContent = {
    Text = "必須……要消滅……！"
  },
  Voice_5991_AwakerVoiceContent = {
    Text = "潘狄婭......她管這也叫調教？哈哈......容我先笑一會。人類終歸還是太心慈手軟了一些，做什麼看起來都像過家家。"
  },
  Voice_5991_AwakerVoiceTitle = {
    Text = "閒話·關於潘狄婭"
  },
  Voice_5991_UnlockDesc = {
    Text = "獲得喚醒體「潘狄婭」後解鎖"
  },
  Voice_5992_AwakerVoiceContent = {
    Text = "別過來！"
  },
  Voice_5993_AwakerVoiceContent = {
    Text = "還要自我介紹一次嗎？真拿你沒辦法。我是詹金，這孩子是布朗。「吱！」\n別忘了啊！要是記錯了我們的名字，就等著我用提燈狠狠抽你的*消音*吧！「吱吱？！」"
  },
  Voice_5993_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_5996_AwakerVoiceContent = {
    Text = "獻上開幕的禮讚！"
  },
  Voice_5996_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_5997_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_5998_AwakerVoiceContent = {
    Text = "只需要一點石材，兩把刻刀，以及三束向陽生長的鳶尾花......我能為您創造一切。"
  },
  Voice_5998_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_5998_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_5999_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_6000_AwakerVoiceContent = {
    Text = "只有這種程度？"
  },
  Voice_6000_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_6001_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_6002_AwakerVoiceContent = {
    Text = "這無謂的爭鬥……"
  },
  Voice_6002_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_6003_AwakerVoiceContent = {
    Text = "（悶哼）"
  },
  Voice_6003_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_6004_AwakerVoiceContent = {
    Text = "提比略死後，羅馬的子民終於實現了多年以來的心願——把他丟進臺伯河喂魚。當然，為此他們付出了一點小小的代價：被卡裡古拉扔進競技場，供我取樂。"
  },
  Voice_6004_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_6005_AwakerVoiceContent = {
    Text = "（悶哼）"
  },
  Voice_6005_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_6006_AwakerVoiceContent = {
    Text = "我能感覺到，那個小女孩擁有和我相似的力量。她還沒完全理解這份力量的強大，看在你的份上，我會適當訓練她的。"
  },
  Voice_6006_AwakerVoiceTitle = {
    Text = "閒話·關於莉莉"
  },
  Voice_6006_UnlockDesc = {
    Text = "獲得喚醒體「莉莉」後解鎖"
  },
  Voice_6007_AwakerVoiceContent = {
    Text = "可惡，你們、你們還是瞧不起我嗎？！"
  },
  Voice_6007_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6008_AwakerVoiceContent = {
    Text = "存在的證明。"
  },
  Voice_6009_AwakerVoiceContent = {
    Text = "存在的證明。"
  },
  Voice_6010_AwakerVoiceContent = {
    Text = "我相信一切皆有所因，但……那些無謂的暴行，那些讓兄弟姐妹們彼此反目，相互仇視的偏見，確實讓我難掩悲傷。如果要說讓我反感的，大概就是這個了吧。"
  },
  Voice_6010_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_6011_AwakerVoiceContent = {
    Text = "真不想用這力量。"
  },
  Voice_6011_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_6012_AwakerVoiceContent = {
    Text = "別大意。"
  },
  Voice_6012_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_6013_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_6016_AwakerVoiceContent = {
    Text = "卡茜亞好厲害！她能咻——地一下變出小兔子！"
  },
  Voice_6016_AwakerVoiceTitle = {
    Text = "閒話·關於卡茜亞"
  },
  Voice_6016_UnlockDesc = {
    Text = "獲得喚醒體「卡茜亞」後解鎖"
  },
  Voice_6017_AwakerVoiceContent = {
    Text = "魔術，已就位！"
  },
  Voice_6017_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_6018_AwakerVoiceContent = {
    Text = "融蝕……不得不承認，這世界上確實存在著權力無法操控之物。"
  },
  Voice_6018_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_6019_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_6020_AwakerVoiceContent = {
    Text = "在綠炎中起舞吧。"
  },
  Voice_6020_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_6021_AwakerVoiceContent = {
    Text = "不必懊惱，傷疤是戰士的功勳。"
  },
  Voice_6021_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6022_AwakerVoiceContent = {
    Text = "為這肌肉戰慄吧......它為了斬下你的頭顱而時刻準備著。"
  },
  Voice_6022_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_6024_AwakerVoiceContent = {
    Text = "用餐時間？還是活動時間？"
  },
  Voice_6024_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_6024_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_6025_AwakerVoiceContent = {
    Text = "唔唔！這樣的話，奧瑞塔的夥伴們就不會消失了！"
  },
  Voice_6025_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_6025_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_6026_AwakerVoiceContent = {
    Text = "茜爾維婭老師說，得到什麼的時候要說謝謝……謝謝謝謝謝謝！"
  },
  Voice_6026_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_6026_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_6027_AwakerVoiceContent = {
    Text = "這次換奧瑞塔當鬼！只給你5秒時間藏起來哦！5、4——"
  },
  Voice_6027_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_6027_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_6028_AwakerVoiceContent = {
    Text = "大家開始捉迷藏後都不見了，這一回，奧瑞塔一定要找到大家！"
  },
  Voice_6028_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_6028_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_6029_AwakerVoiceContent = {
    Text = "因為在海底發現了余的遺骨，所以認為余喜歡水，還想在余的寢殿外修泉池？\n哈……隨便你們，別用這種瑣事來叨擾余了。"
  },
  Voice_6029_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_6030_AwakerVoiceContent = {
    Text = "海中渺小的一滴，不朽淺薄的信徒，彌利亞姆……向你致意。"
  },
  Voice_6030_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_6031_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_6032_AwakerVoiceContent = {Text = "呵！"},
  Voice_6032_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_6033_AwakerVoiceContent = {
    Text = "真令人驚歎......您漫不經心的一句話，解開了困擾我數月的創作難題。"
  },
  Voice_6033_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_6033_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_6034_AwakerVoiceContent = {
    Text = "和酒會上那些貴族小姐比起來，墨菲的脾氣簡直算得上可愛。"
  },
  Voice_6034_AwakerVoiceTitle = {
    Text = "閒話·關於墨菲"
  },
  Voice_6034_UnlockDesc = {
    Text = "獲得喚醒體「墨菲」後解鎖"
  },
  Voice_6035_AwakerVoiceContent = {
    Text = "心理療癒大師？是那些孩子們過譽了。我不過是盡我所能聆聽，以排解他們內心的鬱結罷了——一如我一直所做的那樣。"
  },
  Voice_6035_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_6036_AwakerVoiceContent = {
    Text = "別再小瞧我！"
  },
  Voice_6037_AwakerVoiceContent = {
    Text = "別再小瞧我！"
  },
  Voice_6038_AwakerVoiceContent = {
    Text = "覺得渴嗎？潔淨的水源在監獄裡可是難得一見的好東西。"
  },
  Voice_6038_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_6038_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_6039_AwakerVoiceContent = {
    Text = "好孩子乖孩子~不可以半途而廢哦~"
  },
  Voice_6039_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_6039_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_6040_AwakerVoiceContent = {
    Text = "你一定已經淪陷在我的甜蜜陷阱裡了吧？"
  },
  Voice_6040_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_6040_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_6041_AwakerVoiceContent = {
    Text = "努力，再努力一點點~馬上就要到那極樂的最高點了~"
  },
  Voice_6041_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_6041_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_6042_AwakerVoiceContent = {
    Text = "我十四歲時加入學校，如果當時能夠順利畢業的話，你如今應該稱呼我為“校長”。"
  },
  Voice_6042_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_6043_AwakerVoiceContent = {
    Text = "你那孱弱的大腦，看來是沒辦法長記性了。"
  },
  Voice_6043_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_6044_AwakerVoiceContent = {
    Text = "你問我的願望是什麼嗎？庇佑航行、出入平安，不能算嗎？\n其他的，我沒有想過……但我會好好考慮一下，再說給你聽。"
  },
  Voice_6044_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_6044_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_6045_AwakerVoiceContent = {
    Text = "“我所渴求的乃是天地之奧秘，我要弄清楚究竟是什麼力量在支配著我。” 雖然我對這部小說的情節不甚滿意，書中虛構的科學也幼稚得令人發笑，但讀過後，你應該能理解我……等等，你沒看過這本書嗎？"
  },
  Voice_6045_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_6045_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_6046_AwakerVoiceContent = {
    Text = "使命與命運是相似的東西。無法輕易地放下，也沒有必要放下。"
  },
  Voice_6046_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_6046_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_6047_AwakerVoiceContent = {
    Text = "我看起來一直很忙？是的，助手們偶爾能分擔一些工作，但在某些研究上，我無可取代。 你想幫上忙？那就偶爾來確認一下，我是否還活著吧。"
  },
  Voice_6047_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_6047_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_6048_AwakerVoiceContent = {
    Text = "你覺得我在生氣？你知道微笑需要調動多少塊肌肉嗎？我曾在課上講過這個知識點，顯然，從你光溜溜的大腦上滑走了。答案是至少十七塊，並且，我沒有理由對你生氣。"
  },
  Voice_6048_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_6048_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_6049_AwakerVoiceContent = {
    Text = "拉蒙娜小姐說，我沒有必要遷就所有人，你明白這是什麼意思嗎？……是不再需要我的庇佑了嗎？"
  },
  Voice_6049_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_6049_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_6050_AwakerVoiceContent = {
    Text = "有十三份報告亟待審批，六個受損的通訊器等待修理，同時我還需要觀察五個不同的銀芯萃取實驗結果……所以，與其用有限的時間來打擾我，不如想辦法鍛煉你那羸弱的腦白質。"
  },
  Voice_6050_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_6050_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_6051_AwakerVoiceContent = {
    Text = "希望下一次，故國能回應我的呼喚。"
  },
  Voice_6051_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_6052_AwakerVoiceContent = {
    Text = "鎖定解除。"
  },
  Voice_6052_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_6054_AwakerVoiceContent = {
    Text = "我好高興……您是如此的偏袒、偏心我。"
  },
  Voice_6054_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_6054_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_6055_AwakerVoiceContent = {
    Text = "其他人可是會為了您的偏心而生氣的哦。"
  },
  Voice_6055_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_6055_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_6056_AwakerVoiceContent = {
    Text = "難道您也渴望著我嗎？"
  },
  Voice_6056_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_6056_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_6057_AwakerVoiceContent = {
    Text = "終於結束了，終於不用再看到那些黑色、黏糊糊的……"
  },
  Voice_6057_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_6058_AwakerVoiceContent = {
    Text = "為我付出如此之多，您的愛意，已然與我的水乳交融……"
  },
  Voice_6058_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_6058_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_6059_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_6060_AwakerVoiceContent = {
    Text = "好危險啊。"
  },
  Voice_6060_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_6061_AwakerVoiceContent = {
    Text = "付出了這麼多，你也該享受成果了吧？貼近一點，我不會讓你失望的~"
  },
  Voice_6061_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_6061_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_6062_AwakerVoiceContent = {
    Text = "我、我明白了，您的心意……雖然還是很笨拙，但艾繼絲會竭盡全力為您戰鬥的！"
  },
  Voice_6062_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_6062_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_6063_AwakerVoiceContent = {
    Text = "您的目光灼痛我了……艾繼絲是不是給您添麻煩了？"
  },
  Voice_6063_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_6063_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_6064_AwakerVoiceContent = {
    Text = "艾繼絲很惶恐……不知道會不會辜負您的期待……"
  },
  Voice_6064_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_6064_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_6065_AwakerVoiceContent = {
    Text = "您、您這樣注視著我，艾繼絲很不習慣……您不畏懼詛咒嗎？"
  },
  Voice_6065_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_6065_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_6066_AwakerVoiceContent = {
    Text = "請、請不要看著我的眼睛……艾繼絲害怕自己會傷害您……畢竟，我是怪物一樣的存在……"
  },
  Voice_6066_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_6066_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_6067_AwakerVoiceContent = {
    Text = "野獸的嗅覺什麼的，只是運氣而已啦。你不要看錯了哦？"
  },
  Voice_6067_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_6067_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_6068_AwakerVoiceContent = {
    Text = "我還不能停下……"
  },
  Voice_6068_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6069_AwakerVoiceContent = {
    Text = "力量，源源不斷！"
  },
  Voice_6070_AwakerVoiceContent = {
    Text = "力量，源源不斷。"
  },
  Voice_6071_AwakerVoiceContent = {
    Text = "您喜歡海嗎？我無論如何都很喜歡海。我依然記得，在許多年前的那一天，海是那樣溫柔地，將渴盼已久的死亡送給了不幸的我。"
  },
  Voice_6071_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_6073_AwakerVoiceContent = {
    Text = "不知為何湧現出前所未有的快感……"
  },
  Voice_6073_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6074_AwakerVoiceContent = {
    Text = "這暗流，將會撕碎敵人。"
  },
  Voice_6075_AwakerVoiceContent = {
    Text = "這暗流，將會撕碎敵人。"
  },
  Voice_6076_AwakerVoiceContent = {
    Text = "我一直在等待一個人，一個能教會我真實的愛、疼痛與欲望的人。您能滿足我嗎？能將我從黑暗的監牢中救贖出去嗎？"
  },
  Voice_6076_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_6076_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_6077_AwakerVoiceContent = {
    Text = "你想知道真相嗎？我討厭監獄、討厭黑暗，討厭得快要死掉了。我想要被注視、想要被點燃……"
  },
  Voice_6077_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_6077_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_6078_AwakerVoiceContent = {
    Text = "一切都是為了未來那永恆的福祉。"
  },
  Voice_6078_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_6079_AwakerVoiceContent = {
    Text = "想要享用我嗎？那就成為我的奴隸吧。我會讓你熱到熔化哦~"
  },
  Voice_6079_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_6079_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_6080_AwakerVoiceContent = {
    Text = "權當做臣子的進獻了。"
  },
  Voice_6080_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_6081_AwakerVoiceContent = {
    Text = "都膩了啦，都膩了啦。跟那些戰戰兢兢的大塊頭犯人比起來，這簡直是過家家嘛。還是你來陪我吧~"
  },
  Voice_6081_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_6081_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_6082_AwakerVoiceContent = {
    Text = "好想要更多奴隸，想聽他們呻吟和求饒嘛——\n去給我搞更多奴隸來嘛~拜託嘛~"
  },
  Voice_6082_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_6082_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_6083_AwakerVoiceContent = {
    Text = "抱歉，我又沉浸於往事中了。請不要露出悲傷的表情。換你向我講述你的故事吧。你會有寫詩的衝動嗎？你的冒險、你的見聞、你的喜悅、你的悲傷，它們會成為溪流，從腦海流淌至指間嗎？"
  },
  Voice_6083_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_6083_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_6084_AwakerVoiceContent = {
    Text = "我本是羊皮紙卷上終將淡去的水痕，卻因與您的緣分停駐在此刻，這或許是某種奇蹟吧。我會好好珍惜這種奇蹟，為您創作出雋永的詩篇。"
  },
  Voice_6084_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_6084_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_6085_AwakerVoiceContent = {
    Text = "有人曾對我說，詩歌被創作出來，就是為了被人品讀……能讓我聽聽你的想法嗎？"
  },
  Voice_6085_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_6085_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_6086_AwakerVoiceContent = {
    Text = "您是否曾有過這樣的經歷？以寬宥的心態去面對他人的冒犯，最終卻沒能得到期望的結果。贈人玫瑰，手中卻無餘香，徒留銳利花刺刺破的血痕。"
  },
  Voice_6086_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_6086_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_6087_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_6088_AwakerVoiceContent = {
    Text = "我的筆墨……"
  },
  Voice_6088_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_6089_AwakerVoiceContent = {
    Text = "（驚呼）"
  },
  Voice_6089_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_6090_AwakerVoiceContent = {
    Text = "錯了……"
  },
  Voice_6090_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_6091_AwakerVoiceContent = {
    Text = "（驚呼）"
  },
  Voice_6091_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_6092_AwakerVoiceContent = {
    Text = "這是自偉大之物而來的庇佑！"
  },
  Voice_6092_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_6093_AwakerVoiceContent = {
    Text = "偉大蒼白之物的庇佑。"
  },
  Voice_6093_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_6094_AwakerVoiceContent = {
    Text = "我沒有時間休息，融蝕現象已經毀滅了我兩具身體，在被終結追上前，我有太多想要弄明白的東西…… 來幫我吧，就從準備實驗材料開始做起，我相信你不至於笨到算錯配平吧？"
  },
  Voice_6094_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_6094_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_6095_AwakerVoiceContent = {
    Text = "我喜歡楓丹白露的花窗，它給人們的面容染上了不同的顏色：絕望的紫、諂媚的藍，當然，還有我最喜歡的野心之紅……"
  },
  Voice_6095_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_6096_AwakerVoiceContent = {
    Text = "在這裡，時常能感受到吾主的氣息，但我也許還沒有做好面對他的準備……無論如何，感謝你為我提供的棲身之所。"
  },
  Voice_6096_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_6097_AwakerVoiceContent = {
    Text = "背叛會使人變成怪物，無論對哪一方來說都是如此。所以，我憎惡叛徒。"
  },
  Voice_6097_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_60985_AwakerVoiceContent = {
    Text = "哈姆林，願意為您效勞。"
  },
  Voice_60985_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_60986_AwakerVoiceContent = {
    Text = "我曾經見過一個對音樂有著近乎本能的理解的人，出自那人之手的協奏曲和交響曲，都讓人難以忘懷。\n那是真正的天才。"
  },
  Voice_60986_AwakerVoiceTitle = {
    Text = "閒話·關於故人"
  },
  Voice_60987_AwakerVoiceContent = {
    Text = "我並不喜歡將時間花在謀略上。與音樂相比，謀略的藝術價值微乎其微。但對於清理道路上的障礙來說，它是必要的工具。為了抵達音樂那至高的終點，我不介意使用它。"
  },
  Voice_60987_AwakerVoiceTitle = {
    Text = "閒話·關於謀略"
  },
  Voice_60988_AwakerVoiceContent = {Text = "無禮。"},
  Voice_60988_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_60989_AwakerVoiceContent = {
    Text = "又來了，這旋律究竟是什麼？自從上次聽到，它便一直徘徊在我腦海，不肯離去，不願停歇。"
  },
  Voice_60989_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_60989_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_6098_AwakerVoiceContent = {
    Text = "（驚呼）"
  },
  Voice_6098_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_60990_AwakerVoiceContent = {
    Text = "就技巧性而言，計策謀劃與音樂指揮沒有區別。人性，情感，欲望……它們如五線譜上的音符般清晰溫順，陳列在我眼前，跟隨指揮棒的軌跡起舞。通曉了音樂，便通曉了一切。"
  },
  Voice_60990_AwakerVoiceTitle = {
    Text = "閒話·關於共性"
  },
  Voice_60991_AwakerVoiceContent = {
    Text = "還差一點，就一點，我必須完成它，我必須聽到它！"
  },
  Voice_60991_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_60991_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_60992_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_60993_AwakerVoiceContent = {Text = "無禮。"},
  Voice_60993_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_60994_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_60995_AwakerVoiceContent = {
    Text = "音樂超越語言，超越文字，超越一切。如果這都不算完美，我不知道什麼是。"
  },
  Voice_60995_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_60995_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_60996_AwakerVoiceContent = {
    Text = "注意節拍。"
  },
  Voice_60997_AwakerVoiceContent = {
    Text = "調律完畢。"
  },
  Voice_60997_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_60998_AwakerVoiceContent = {
    Text = "很高興你也明白訓練的重要性。"
  },
  Voice_60998_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_60999_AwakerVoiceContent = {
    Text = "我將帶來完美的演出。"
  },
  Voice_60999_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_6099_AwakerVoiceContent = {
    Text = "羡慕嗎？這身堅硬的鱗片正是高貴血統的證明。"
  },
  Voice_6099_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_61000_AwakerVoiceContent = {
    Text = "我也曾經為人讚頌，但……那不是真正的才華。\n我的作品，不過是對前人的仿作罷了。"
  },
  Voice_61000_AwakerVoiceTitle = {
    Text = "閒話·關於作品"
  },
  Voice_61001_AwakerVoiceContent = {
    Text = "管樂、絃樂……交錯上行再交錯，動機再現……我想起來了，這是我作的安魂曲，為那早逝的天才，為那隕落的明星。"
  },
  Voice_61001_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_61001_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_61002_AwakerVoiceContent = {
    Text = "嗯？你有新的樂章要向我展示嗎？"
  },
  Voice_61002_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_61003_AwakerVoiceContent = {
    Text = "以此曲，祭奠逝去的魂靈。"
  },
  Voice_61003_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_61004_AwakerVoiceContent = {
    Text = "那位綠色的舞者，有著足以成為宮廷舞團首席的優雅姿態。\n如果可以的話，真希望能與她合作。"
  },
  Voice_61004_AwakerVoiceTitle = {
    Text = "閒話·關於莉茲"
  },
  Voice_61004_UnlockDesc = {
    Text = "獲得喚醒體「莉茲」後解鎖"
  },
  Voice_61006_AwakerVoiceContent = {
    Text = "樂團內會有首席，但首席組不成一個完整的樂團，我的樂團不需要那些只顧自我展示的人。"
  },
  Voice_61006_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_61007_AwakerVoiceContent = {
    Text = "我好像聽到了一段旋律，這附近有人在排練嗎？"
  },
  Voice_61007_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_61007_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_61008_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_61009_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_61010_AwakerVoiceContent = {
    Text = "沒錯，沒錯，就是這樣，這就是最終的彌撒，獻給音樂本身的安魂曲！"
  },
  Voice_61010_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_61010_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_61011_AwakerVoiceContent = {
    Text = "啊，守密人，你來得正好。告訴我，你對這個樂章的處理怎麼看？"
  },
  Voice_61011_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_61012_AwakerVoiceContent = {
    Text = "絃樂，起。"
  },
  Voice_61014_AwakerVoiceContent = {
    Text = "它變得清晰了，那段曲折迂回，宛如靈魂的哀慟的旋律……我確定我曾經在哪聽過。"
  },
  Voice_61014_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_61014_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_61015_AwakerVoiceContent = {
    Text = "理性，秩序，我以此建立臺階，向上行走，最終，打開那座殿堂的大門。而在那道門之後，理性與秩序便不復存在——真正永恆的音樂，將是超越理性的。"
  },
  Voice_61015_AwakerVoiceTitle = {
    Text = "閒話·關於理性與秩序"
  },
  Voice_61016_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_61017_AwakerVoiceContent = {
    Text = "我聽了你們那個所謂的樂團的演出，簡直錯漏百出。不過沒關係，我已經制定了一個詳細的計劃，一定能在銀霜節前排出一個完美的節目。"
  },
  Voice_61017_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格"
  },
  Voice_61018_AwakerVoiceContent = {
    Text = "我至今無法忘記，第一次聽到意識深處的樂曲的那天。在那些音符與和絃之間，現實世界的一切不復存在，只有音樂，純粹的、崇高的音樂。"
  },
  Voice_61018_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_61019_AwakerVoiceContent = {
    Text = "令人遺憾，看來要加強排練了。"
  },
  Voice_61019_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6101_AwakerVoiceContent = {
    Text = "這是命令。"
  },
  Voice_6101_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_61020_AwakerVoiceContent = {
    Text = "我一般不會發出這種邀請，但……你想要試試看嗎？握住指揮棒，賦予樂曲新的生命？"
  },
  Voice_61020_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_61020_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_61021_AwakerVoiceContent = {
    Text = "比起言語的表達，我更願意通過音樂表述自己。但和你交流的過程就像指揮經過無數次排演的樂團，流暢，甚至時常給人驚喜。\n無論是對音樂本身還是對我而言，你都是特殊的存在。"
  },
  Voice_61021_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_61021_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_61022_AwakerVoiceContent = {
    Text = "交響樂中，器樂之間的配合非常重要，各個聲部如何加入，如何退出，都會給樂曲帶來不一樣的體驗。\n我是想說，如果指揮喚醒體是一場演出，你表現得不錯。"
  },
  Voice_61022_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_61022_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_61023_AwakerVoiceContent = {
    Text = "你也喜歡這首曲子嗎？僅用四個小節便完整呈現了動機，管樂推動旋律上升，直到抵達主題，這樣的設計影響了無數後人……抱歉，我是不是說太多了？"
  },
  Voice_61023_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_61023_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_61024_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_61025_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_61026_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_61027_AwakerVoiceContent = {
    Text = "我們每個人心中都隱藏著一段屬於自己的旋律，它受困於理智和軀體，唯有在癲狂時才能盡情綻放。"
  },
  Voice_61027_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_61028_AwakerVoiceContent = {
    Text = "唯有音樂值得稱頌。"
  },
  Voice_61028_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_61029_AwakerVoiceContent = {
    Text = "唯有音樂值得稱頌。"
  },
  Voice_61029_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_6102_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_61030_AwakerVoiceContent = {
    Text = "聽吧，這最終的安魂曲！"
  },
  Voice_61030_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_6103_AwakerVoiceContent = {
    Text = "求饒吧！"
  },
  Voice_61049_AwakerVoiceContent = {
    Text = "聽吧，這最終的安魂曲！"
  },
  Voice_61049_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_6104_AwakerVoiceContent = {
    Text = "（悶哼）"
  },
  Voice_6104_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_6105_AwakerVoiceContent = {
    Text = "您也想葬身於綠炎中嗎？"
  },
  Voice_6105_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_6107_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_6108_AwakerVoiceContent = {
    Text = "專心點！"
  },
  Voice_6108_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_6109_AwakerVoiceContent = {
    Text = "大學裡怎麼還有這麼可愛的孩子呀~我剛和他說“要不要來當我的奴隸”，他就漲紅了臉，吞吞吐吐地念叨什麼“我已經是守密人的騎士了”……\n明明這根本不衝突嘛~"
  },
  Voice_6109_AwakerVoiceTitle = {
    Text = "閒話·關於奧吉爾"
  },
  Voice_6109_UnlockDesc = {
    Text = "獲得喚醒體「奧吉爾」後解鎖"
  },
  Voice_6110_AwakerVoiceContent = {
    Text = "別想靠近王女。"
  },
  Voice_6110_AwakerVoiceTitle = {
    Text = "技能·一·怒濤"
  },
  Voice_6111_AwakerVoiceTitle = {
    Text = "技能·一·潮湧"
  },
  Voice_6112_AwakerVoiceContent = {
    Text = "故國的大門正在離我遠去……不…不要又一次……"
  },
  Voice_6112_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6113_AwakerVoiceContent = {
    Text = "別擋路！"
  },
  Voice_6114_AwakerVoiceContent = {
    Text = "別擋路！"
  },
  Voice_6115_AwakerVoiceContent = {
    Text = "為你們的行為付出代價。"
  },
  Voice_6115_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_6116_AwakerVoiceContent = {
    Text = "想死嗎？"
  },
  Voice_6116_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_6117_AwakerVoiceContent = {
    Text = "我覺得我又患上了融蝕……我的心被融蝕了！只需要幾片阿司匹林，配合皮鞭和一點疼痛，應該就能痊癒……"
  },
  Voice_6117_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_6118_AwakerVoiceContent = {
    Text = "就連你也沒法子治這鬼毛病？那你還追著融蝕跑，真是不要命。"
  },
  Voice_6118_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_6119_AwakerVoiceContent = {
    Text = "我是最後的羅馬戰士——尤烏哈希！"
  },
  Voice_6119_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_6120_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_6121_AwakerVoiceContent = {
    Text = "我是最後的羅馬戰士——尤烏哈希！"
  },
  Voice_6121_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_6122_AwakerVoiceContent = {
    Text = "融蝕……？我當然知道，不就是主僕關係解除的意思嗎，這有什麼難的。"
  },
  Voice_6122_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_6123_AwakerVoiceContent = {
    Text = "我已蒙宣召，神靈與愚人的邊界已然模糊。"
  },
  Voice_6123_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_6123_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_6124_AwakerVoiceContent = {
    Text = "嗯......輕重有度，按摩手法不錯~"
  },
  Voice_6124_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_6125_AwakerVoiceContent = {
    Text = "這裡的裝修是不是太老氣了？陰森森的，好像鬧鬼哦。"
  },
  Voice_6125_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_6126_AwakerVoiceContent = {
    Text = "這裡有蔥郁的草木、安逸的空氣，還能治癒姐姐的病，對我們二人來說，就是最美好的、新的家園。"
  },
  Voice_6126_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_6127_AwakerVoiceContent = {
    Text = "沒想到竟能在此處重逢……不知道那之後姐姐過著怎樣的生活。無論怎樣詢問，她都只說並無大礙……抱歉，還得感謝您讓我們姐妹二人團聚。"
  },
  Voice_6127_AwakerVoiceTitle = {
    Text = "閒話·關於菲茵特"
  },
  Voice_6127_UnlockDesc = {
    Text = "獲得喚醒體「菲茵特」後解鎖"
  },
  Voice_6128_AwakerVoiceContent = {
    Text = "向吾主的進獻。"
  },
  Voice_6129_AwakerVoiceContent = {
    Text = "向吾主的進獻。"
  },
  Voice_6130_AwakerVoiceContent = {
    Text = "冷靜冷靜冷靜……"
  },
  Voice_6131_AwakerVoiceContent = {
    Text = "我的身體裡有許多「我」，快樂的、悲傷的、憤怒的……她們喜歡海綿蛋糕，她們討厭倫蒂尼恩的下雨天，她們都叫「24」，她們都敬愛著您。"
  },
  Voice_6131_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_6131_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_6132_AwakerVoiceContent = {
    Text = "我曾經每天工作到半夜，紡織、洗衣、打掃、保姆、甚至清道夫……我什麼都做，只要能賺錢。那時候，活著，就只是活著而已。\n現在，我們有新鮮的食物，溫暖的床鋪，還有您這樣好心的老爺......真是想都不敢想。"
  },
  Voice_6132_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_6132_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_6133_AwakerVoiceContent = {
    Text = "無論如何，我們共用一份牛排，一個床鋪，絕不會給您添麻煩的。"
  },
  Voice_6133_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_6133_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_6134_AwakerVoiceContent = {
    Text = "呵呵，那個女人怕我出來，晚上連覺都不敢睡。放輕鬆，看在禮物的份上，我可捨不得殺你。\n我是誰？當然是「24」啊，哈哈哈哈！"
  },
  Voice_6134_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_6134_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_6135_AwakerVoiceContent = {
    Text = "我現在感覺好極了。什麼，您說我已經被其他東西攫取了心智？胡、胡說......呃……"
  },
  Voice_6135_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_6135_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_6136_AwakerVoiceContent = {
    Text = "作為臣子而言，你還算識趣。在迎來下一次長眠前，余就屈尊紆貴，暫留此時。"
  },
  Voice_6136_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_6137_AwakerVoiceContent = {
    Text = "嗯，今夜的海水很是溫暖……"
  },
  Voice_6137_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_6138_AwakerVoiceContent = {
    Text = "於夢境中盤旋的白鳥，降臨了。"
  },
  Voice_6138_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_6139_AwakerVoiceContent = {
    Text = "如你所願，我的存在更為切實了。"
  },
  Voice_6139_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_6140_AwakerVoiceContent = {
    Text = "好滿足好滿足！"
  },
  Voice_6142_AwakerVoiceContent = {
    Text = "交給我吧！"
  },
  Voice_6143_AwakerVoiceContent = {
    Text = "交給我吧！"
  },
  Voice_6144_AwakerVoiceContent = {
    Text = "歡迎來到——我們的盛宴！"
  },
  Voice_6144_AwakerVoiceTitle = {
    Text = "狂氣爆發·躁狂"
  },
  Voice_6145_AwakerVoiceContent = {
    Text = "這女孩身上流淌著的，毫無疑問是余之血脈……不，余的年紀還不足以留下子嗣。但是，她的力量確實與余同宗。"
  },
  Voice_6145_AwakerVoiceTitle = {
    Text = "閒話·關於神之血脈"
  },
  Voice_6145_UnlockDesc = {
    Text = "獲得喚醒體「艾繼絲」「墨菲」其一後解鎖"
  },
  Voice_6146_AwakerVoiceContent = {
    Text = "主人的恩情，珈倫一刻也不敢忘記！"
  },
  Voice_6146_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_6147_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_6148_AwakerVoiceContent = {
    Text = "珈倫最近在減肥，不能吃太多了啦~"
  },
  Voice_6148_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_6149_AwakerVoiceContent = {
    Text = "做我的對手，這些傢伙還不夠格。"
  },
  Voice_6149_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_6150_AwakerVoiceContent = {
    Text = "解釋藝術就像解釋鐵路股票一樣可笑——請不要為難可憐的藝術家了。"
  },
  Voice_6150_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_6151_AwakerVoiceContent = {
    Text = "艾繼絲……做錯什麼事情了嗎？"
  },
  Voice_6151_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_6152_AwakerVoiceContent = {
    Text = "你的祈禱，我聽到了。"
  },
  Voice_6152_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_6153_AwakerVoiceContent = {
    Text = "你的祈禱，我聽到了。"
  },
  Voice_6153_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_6154_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_6155_AwakerVoiceContent = {
    Text = "啊，剛才過去的是不是那位大人？不，沒事了。我上次向他打招呼的時候，他都沒有認出我……明明我在監獄裡一直等他帶我走，可是直到那場暴動他都沒有來……"
  },
  Voice_6155_AwakerVoiceTitle = {
    Text = "閒話·關於「N」"
  },
  Voice_6155_UnlockDesc = {
    Text = "通關「調查行動」第7章 後解鎖"
  },
  Voice_6156_AwakerVoiceContent = {
    Text = "回應人類的喚醒，締結合作關係，是為了完成我未竟的職責——如果你能成長到能與我一戰的程度，那就再好不過了。"
  },
  Voice_6156_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_6157_AwakerVoiceContent = {
    Text = "姐姐、布朗、濟貧院的膽小鬼，我有他們作為朋友就足夠了。唔……好吧，你也算一個。布朗，分一顆糖給守密人。\n「吱吱？！」"
  },
  Voice_6157_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_6157_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_6158_AwakerVoiceContent = {
    Text = "東區貧民窟不適合孩子生存。刁鑽滑頭的老工頭會變著法子克扣報童的薪水，對送奶小工的速度吹、吹毛……挑刺！總之，要在街頭生存，只能靠自己，誰都靠不住，誰都沒法信賴。"
  },
  Voice_6158_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_6158_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_6159_AwakerVoiceContent = {
    Text = "我那些“壞習慣”一時半會兒可沒法改掉，你能理解的吧？睡在橋洞和雨水井裡，靠垃圾果腹，光是活下去就夠難了……你不能要求我馬上就能習慣起床後疊被子！至少還要半個月時間適應吧！"
  },
  Voice_6159_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_6159_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_6160_AwakerVoiceContent = {
    Text = "在空間裡迷路的感覺真不好受。看在你把我從那裡撈出來的份上，有什麼事儘管直說，但我不一定能幫得上忙。\n我的年齡擺在這兒了，你不至於為難一個小孩吧~"
  },
  Voice_6160_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_6160_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_6161_AwakerVoiceContent = {
    Text = "嘿，西區佬！你有見到布朗嗎？那貪吃鬼不知道又聞著什麼味道跑過去了。"
  },
  Voice_6161_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_6161_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_6162_AwakerVoiceContent = {
    Text = "“那些有力的不可用自己的力量欺侮他人，因為你們共有我的血液”——我牢記仁愛之神的訓誡，並會將這力量用於守護身邊的人。"
  },
  Voice_6162_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_6162_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_6163_AwakerVoiceContent = {
    Text = "好奇我在宇宙的起點見到了什麼嗎？我可以告訴你，那裡什麼都沒有。"
  },
  Voice_6163_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_6163_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_6164_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_6165_AwakerVoiceContent = {
    Text = "長明的燈火啊……"
  },
  Voice_6165_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_6166_AwakerVoiceContent = {
    Text = "與故國的連結更強勁了。"
  },
  Voice_6166_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_6167_AwakerVoiceContent = {
    Text = "若能夠使世人擺脫苦痛，我便心滿意足。"
  },
  Voice_6167_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_6168_AwakerVoiceContent = {
    Text = "給予我更多的指令吧，蒼白的使者，願你的火焰指引我前行。"
  },
  Voice_6168_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_6169_AwakerVoiceContent = {
    Text = "（驚呼）"
  },
  Voice_6169_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_6170_AwakerVoiceContent = {
    Text = "人的錘煉不止在軀體，還在內心。"
  },
  Voice_6170_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_6171_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_6172_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_6173_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_6174_AwakerVoiceContent = {
    Text = "唔！您的溫度對珊瑚而言還是有些偏高了。但是......它既溫暖，又熾熱。我很喜歡。"
  },
  Voice_6174_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_6175_AwakerVoiceContent = {
    Text = "啊……您有什麼事嗎？可以的話，我們到後臺去聊吧……"
  },
  Voice_6175_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_6176_AwakerVoiceContent = {
    Text = "未曾綻放，就已經枯萎，就像是被水吞沒的睡蓮……在那冰冷洶湧的潮水中，孱弱地索求寧靜，不敢追求屬於自身的幸福……那就是我啊，守密人。"
  },
  Voice_6176_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_6176_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_6177_AwakerVoiceContent = {
    Text = "我曾經陷入過這樣的困擾：痛苦是否比生命本身更加漫長？既然如此，寧靜的長眠是否比折磨的清醒更加幸福？在甦醒之後，我也一度陷於其中，直到您為我帶來這一處避風的港灣……"
  },
  Voice_6177_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_6177_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_6178_AwakerVoiceContent = {
    Text = "在療養院時，我曾經嘗試過交朋友，但大家不太願意接近我……是因為這蝕骨的“毒”嗎？總之，您接近我的時候需要小心些。"
  },
  Voice_6178_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_6178_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_6179_AwakerVoiceContent = {
    Text = "夜風送來的鐘聲讓人感到平靜。您要坐在石椅上聽一會兒嗎？我會用紗巾為您鋪好坐席。"
  },
  Voice_6179_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_6179_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_6180_AwakerVoiceContent = {
    Text = "您聽說過“海葬”嗎？我生前的小鎮有一種風俗，居民們會將死者的遺體沉入海中，因此大海是所有人的歸宿。而我，是早早回歸海的懷抱之人……"
  },
  Voice_6180_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_6180_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_6181_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_6182_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_6183_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_6184_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_6185_AwakerVoiceContent = {
    Text = "已將作戰日誌進行存檔。辛苦了，守密人。"
  },
  Voice_6185_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_6186_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_6187_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_6188_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_6189_AwakerVoiceContent = {
    Text = "還可以繼續。"
  },
  Voice_6189_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_6190_AwakerVoiceContent = {
    Text = "造訪沙龍的客人，能得到最佳的款待……作為入場券，客人是否準備了足以匹配這場盛宴的密辛呢？"
  },
  Voice_6190_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_6191_AwakerVoiceContent = {
    Text = "我喜歡新鮮的事物。千年的旅行裡，我見證了許多有趣的革新與發明，比如詩的體裁、電影的畫面。人類啊，真是有意思的生物呢。"
  },
  Voice_6191_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_6192_AwakerVoiceContent = {
    Text = "嗯，莉莉認得她。母親不在的時候，莉莉就住在她家裡。"
  },
  Voice_6192_AwakerVoiceTitle = {
    Text = "閒話·關於達芙黛爾"
  },
  Voice_6192_UnlockDesc = {
    Text = "獲得喚醒體「達芙黛爾」後解鎖"
  },
  Voice_6195_AwakerVoiceContent = {
    Text = "打擾余長眠的人，就是你嗎？"
  },
  Voice_6195_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_6196_AwakerVoiceContent = {
    Text = "神？只有愚蠢之人，才會將性命託付給那種縹緲無形的存在。與其把寶壓在所謂神明身上，不如多想想怎麼變強。"
  },
  Voice_6196_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_6197_AwakerVoiceContent = {
    Text = "什麼角鬥士的主人，不過是低劣的蟲豸罷了。"
  },
  Voice_6197_AwakerVoiceTitle = {
    Text = "閒話·關於阿格里帕"
  },
  Voice_6197_UnlockDesc = {
    Text = "獲得喚醒體「阿格里帕」後解鎖"
  },
  Voice_6198_AwakerVoiceContent = {
    Text = "勝利後，請讓我取走用於繁衍後代的材料吧。"
  },
  Voice_6198_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_6199_AwakerVoiceContent = {
    Text = "大朋友！夥伴！呼呼，要和奧瑞塔永遠永遠當好朋友哦！"
  },
  Voice_6199_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_6200_AwakerVoiceContent = {
    Text = "我現在很興奮......不想死的話，最好離我遠遠的。"
  },
  Voice_6200_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_6201_AwakerVoiceContent = {
    Text = "那個人……對其他人那樣的態度真的沒問題嗎？莎拉女士說，小孩子不可以隨便發脾氣……"
  },
  Voice_6201_AwakerVoiceTitle = {
    Text = "閒話·關於墨菲"
  },
  Voice_6201_UnlockDesc = {
    Text = "獲得喚醒體「墨菲」後解鎖"
  },
  Voice_6202_AwakerVoiceContent = {
    Text = "勝利的榮光屬於您。"
  },
  Voice_6202_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_6203_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_6204_AwakerVoiceContent = {
    Text = "內心的空洞，被填滿了啦~"
  },
  Voice_6204_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_6205_AwakerVoiceContent = {
    Text = "又灼熱了一點點~"
  },
  Voice_6205_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_6206_AwakerVoiceContent = {
    Text = "我知道那孩子，她偶爾會遠遠地站在場外觀看演出。她不過來也好，不然，這些小觀眾們可要“身心俱疲”啦！"
  },
  Voice_6206_AwakerVoiceTitle = {
    Text = "閒話·關於菲茵特"
  },
  Voice_6206_UnlockDesc = {
    Text = "獲得喚醒體「菲茵特」後解鎖"
  },
  Voice_6207_AwakerVoiceContent = {
    Text = "汀克特說過，知恩圖報。所以，只要是我力所能及的地方，我都會幫忙的……"
  },
  Voice_6207_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_6208_AwakerVoiceContent = {
    Text = "你好，守密人，請問有什麼需要幫助的嗎？"
  },
  Voice_6208_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_6209_AwakerVoiceContent = {
    Text = "遲早有一天，我會作為衝鋒陷陣的領頭者重返戰場。"
  },
  Voice_6209_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_6209_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_6210_AwakerVoiceContent = {
    Text = "你能相信嗎？我感覺斷裂的腿骨正在癒合。"
  },
  Voice_6210_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_6210_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_6211_AwakerVoiceContent = {
    Text = "衷心感謝您的信賴，竟將我培養至如此境界。想來你也是追求正義之人，那我必將在此續寫軍旅的榮光。"
  },
  Voice_6211_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_6211_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_6212_AwakerVoiceContent = {
    Text = "踏上征程之日即將到來，噴薄的熱血在胸腔中湧動。"
  },
  Voice_6212_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_6212_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_6213_AwakerVoiceContent = {
    Text = "作為戰士的榮譽，正在恢復。"
  },
  Voice_6213_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_6213_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_6214_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_6215_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_6216_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_6217_AwakerVoiceContent = {
    Text = "耍賴皮！"
  },
  Voice_6217_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_6218_AwakerVoiceContent = {
    Text = "唉呀，對不起，下次一定行！"
  },
  Voice_6218_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6219_AwakerVoiceContent = {
    Text = "我聽見有人高呼我的名字，阿格里帕，阿格里帕，阿格里皮娜……"
  },
  Voice_6219_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_6219_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_6220_AwakerVoiceContent = {
    Text = "我看到......祂從井下的黑暗中攀爬而上，無數眼睛自肉卵上浮現。它們凝望著我，喚我......迷宮之神。"
  },
  Voice_6220_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_6220_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_6221_AwakerVoiceContent = {
    Text = "我有非常強烈的，想要觀賞決鬥的衝動……如果地點在迷宮裡，那就更棒了。"
  },
  Voice_6221_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_6221_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_6222_AwakerVoiceContent = {
    Text = "契約……對，我要與你簽一份契約，一份永不失效的主僕契約……"
  },
  Voice_6222_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_6222_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_6223_AwakerVoiceContent = {
    Text = "哼……還不錯，再多來一點，我得喂飽這些蜘蛛崽的肚子。"
  },
  Voice_6223_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_6223_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_6224_AwakerVoiceContent = {
    Text = "何等的污濁、可憎！啊啊——別再說了！求求您！不要讓我看見它，也不要，不要在我耳邊提起它……"
  },
  Voice_6224_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_6225_AwakerVoiceContent = {
    Text = "我的過去按部就班，好比赤道海域般平靜，沒什麼好提及的。"
  },
  Voice_6225_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_6225_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_6226_AwakerVoiceContent = {
    Text = "嗯……？母親，抱抱……嗯，好溫暖……"
  },
  Voice_6226_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_6227_AwakerVoiceContent = {
    Text = "星塵啊……"
  },
  Voice_6228_AwakerVoiceContent = {
    Text = "哎呀，你迷路了嗎？"
  },
  Voice_6229_AwakerVoiceContent = {
    Text = "沒用的。"
  },
  Voice_6229_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_6230_AwakerVoiceContent = {
    Text = "每每回想起那些叛徒跪在地上哭著求饒的樣子，我就感到一陣舒暢，心中的火焰也彷彿消退不少。"
  },
  Voice_6230_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_6231_AwakerVoiceContent = {
    Text = "船主將我從家中帶走，並賦予了我航船聖女的使命。從那時起，我的生命的意義便不再受自己控制。有人告訴我，至少在這作為喚醒體的第二次生命中，要為了自己的願望而活……你會幫我嗎？幫助我變得自私，幫我找到我的願望。"
  },
  Voice_6231_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_6231_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_6232_AwakerVoiceContent = {
    Text = "阿格里帕。我和你沒什麼好說的——要是夠膽自請成為我手下的角鬥士，那就另當別論。"
  },
  Voice_6232_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_6233_AwakerVoiceContent = {
    Text = "塔薇……遠比我們想像中要危險。以後若我不在了，你要對她萬分小心。"
  },
  Voice_6233_AwakerVoiceTitle = {
    Text = "閒話·關於塔薇"
  },
  Voice_6235_AwakerVoiceContent = {
    Text = "以此演繹法……解讀世界！"
  },
  Voice_6235_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_6236_AwakerVoiceContent = {
    Text = "以此演繹法……解讀世界！"
  },
  Voice_6236_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_6237_AwakerVoiceContent = {
    Text = "盡情閃爍！"
  },
  Voice_6237_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_6238_AwakerVoiceContent = {
    Text = "盡我所能。"
  },
  Voice_6239_AwakerVoiceContent = {
    Text = "盡我所能。"
  },
  Voice_6240_AwakerVoiceContent = {
    Text = "就這樣腐朽吧。"
  },
  Voice_6241_AwakerVoiceContent = {
    Text = "就這樣腐朽吧。"
  },
  Voice_6242_AwakerVoiceContent = {
    Text = "微笑和禮儀是一層盔甲，幫助我和其他人保持距離，遠離無趣的紛擾。至於我真實的一面......我不介意展現給您哦。"
  },
  Voice_6242_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_6242_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_6243_AwakerVoiceContent = {
    Text = "思緒堆積成白色的石灰質，又被沖刷成美麗的珊瑚。它們與我融為一體，裡面跳動著我的脈搏......您願意來傾聽嗎？"
  },
  Voice_6243_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_6243_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_6244_AwakerVoiceContent = {
    Text = "靈感就像海水中不斷升騰的泡沫：輕輕一碰，便消失無蹤。您也是這樣嗎？"
  },
  Voice_6244_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_6244_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_6245_AwakerVoiceContent = {
    Text = "戰爭、掠奪、名利都是人類的欲望。謙卑的雕砌者對人類追逐的東西不感興趣，她只願做美的奴隸。"
  },
  Voice_6245_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_6245_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_6246_AwakerVoiceContent = {
    Text = "美妙的人生在於沉迷。有時候，您不應太苛求自己。"
  },
  Voice_6246_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_6246_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_6247_AwakerVoiceContent = {
    Text = "區區小傷……"
  },
  Voice_6247_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_6249_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_6250_AwakerVoiceContent = {Text = "可惡！"},
  Voice_6250_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_6251_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_6252_AwakerVoiceContent = {
    Text = "融蝕現象會帶來各種異動與災難，也許，我的國正是受此災害，才會沉入深海……"
  },
  Voice_6252_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_6253_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_6255_AwakerVoiceContent = {
    Text = "巨人的威儀。"
  },
  Voice_6256_AwakerVoiceContent = {
    Text = "嚐嚐這個！"
  },
  Voice_6256_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_6257_AwakerVoiceContent = {
    Text = "無可避免的犧牲。"
  },
  Voice_6258_AwakerVoiceContent = {
    Text = "還不錯，這就是戰士的榮耀。"
  },
  Voice_6258_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_6259_AwakerVoiceContent = {
    Text = "你這傢伙，怎麼會放那種女人進來！給本小姐劃定禁區！別讓她靠近本小姐周圍五十步內！"
  },
  Voice_6259_AwakerVoiceTitle = {
    Text = "閒話·關於彌利亞姆"
  },
  Voice_6259_UnlockDesc = {
    Text = "獲得喚醒體「彌利亞姆」後解鎖"
  },
  Voice_6260_AwakerVoiceContent = {
    Text = "為什麼想變強？在我的部族，弱者會被扒光衣服，剃掉頭髮，面臨你能想到最骯髒的羞辱——成為弱者的代價，並非人人都能承受。"
  },
  Voice_6260_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_6260_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_6261_AwakerVoiceContent = {
    Text = "幸運女神，賜福我！"
  },
  Voice_6261_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_6262_AwakerVoiceContent = {
    Text = "果然……人類的力量，是有極限的嗎……"
  },
  Voice_6262_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6263_AwakerVoiceContent = {
    Text = "筋骨稍稍放鬆了些。"
  },
  Voice_6263_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_6263_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_6264_AwakerVoiceContent = {
    Text = "讓我的愛意變得更為深厚，這就是您欲望的體現嗎？"
  },
  Voice_6264_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_6264_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_6265_AwakerVoiceContent = {
    Text = "肆意而為吧！"
  },
  Voice_6265_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_6266_AwakerVoiceContent = {
    Text = "（驚呼）"
  },
  Voice_6266_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_6267_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_6268_AwakerVoiceContent = {
    Text = "（驚呼）"
  },
  Voice_6268_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_6269_AwakerVoiceContent = {
    Text = "啊啊，不可饒恕……"
  },
  Voice_6269_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6270_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_6271_AwakerVoiceContent = {
    Text = "莽撞點！"
  },
  Voice_6271_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_6272_AwakerVoiceContent = {Text = "Biu——"},
  Voice_6272_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_6273_AwakerVoiceContent = {
    Text = "保持下去，你的期末成績值得期待。"
  },
  Voice_6273_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_6274_AwakerVoiceContent = {
    Text = "聽說來了個貧民窟的小偷，還帶著一隻胖老鼠？呵呵呵呵......看我替天行道，為主人剷除禍患！"
  },
  Voice_6274_AwakerVoiceTitle = {
    Text = "閒話·關於詹金"
  },
  Voice_6274_UnlockDesc = {
    Text = "獲得喚醒體「詹金」後解鎖"
  },
  Voice_6275_AwakerVoiceContent = {
    Text = "來，深呼吸——"
  },
  Voice_6275_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_6276_AwakerVoiceContent = {
    Text = "有趣，你在戰鬥中的成長速度遠超我的想像。假以時日，或許你能成為下一個……真奇怪啊……跨越了時間，我居然還會對你這樣弱小的生物懷有期待。"
  },
  Voice_6276_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_6276_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_6277_AwakerVoiceContent = {
    Text = "也許現在就是說這話的時機吧，你仔細聽好了。\n星之巨獸蘿坦，正式向你發出決戰邀請……當然，在你成長到巔峰前，我會保護你的安危。認定的對手夭折，這種事我不會讓它發生第二次。"
  },
  Voice_6277_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_6277_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_6278_AwakerVoiceContent = {
    Text = "哼……真搞不懂，拉蒙娜那傢伙怎麼會認可你作為搭檔。我承認你身上有著強者的氣味，但距離成為我的對手，還差得遠。"
  },
  Voice_6278_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_6278_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_6279_AwakerVoiceContent = {
    Text = "對，就像這樣，用崇拜的眼神仰視我吧。我是星球最古老的造物，理應得到渺小者的尊重——我守衛了這顆星球千萬年，索要一場酣暢淋漓的對決作為報酬，這不過分吧？"
  },
  Voice_6279_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_6279_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_6280_AwakerVoiceContent = {
    Text = "哈啊，我可沒精力陪小孩玩過家家。識趣的話，就找個角落乖乖蹲著。"
  },
  Voice_6280_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_6280_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_6281_AwakerVoiceContent = {
    Text = "沒能得到庇佑的靈魂，我將給予你們最後的安寧。"
  },
  Voice_6281_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_6282_AwakerVoiceContent = {Text = "戒備。"},
  Voice_6282_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_6283_AwakerVoiceContent = {Text = "警報。"},
  Voice_6283_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_6284_AwakerVoiceContent = {
    Text = "有什麼東西，在我的大腦裡悲鳴……"
  },
  Voice_6284_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_6284_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_6285_AwakerVoiceContent = {
    Text = "好像有一層白紗籠罩著我的思維。"
  },
  Voice_6285_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_6285_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_6286_AwakerVoiceContent = {
    Text = "聲音越來越響，白紗越來越厚。"
  },
  Voice_6286_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_6286_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_6287_AwakerVoiceContent = {
    Text = "是時針轉動的聲音嗎？"
  },
  Voice_6287_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_6287_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_6288_AwakerVoiceContent = {
    Text = "當鐘聲響起的時候，我還會在這裡嗎？"
  },
  Voice_6288_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_6288_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_6289_AwakerVoiceContent = {
    Text = "這種拙劣的手段……哼，不知天高地厚的傢伙，我怎麼可能那麼輕易就被你束縛？"
  },
  Voice_6289_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_6290_AwakerVoiceContent = {
    Text = "請問……你們見過我的妹妹，詹金嗎？那是個帶著老鼠，有點兇的女孩子……我是不會記錯的。"
  },
  Voice_6290_AwakerVoiceTitle = {
    Text = "閒話·關於詹金"
  },
  Voice_6290_UnlockDesc = {
    Text = "通關「調查行動」第2章後解鎖"
  },
  Voice_6292_AwakerVoiceContent = {
    Text = "感謝您的垂愛。"
  },
  Voice_6292_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_6293_AwakerVoiceContent = {
    Text = "準備好了。"
  },
  Voice_6294_AwakerVoiceContent = {
    Text = "請期待吧。"
  },
  Voice_6294_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_6295_AwakerVoiceContent = {
    Text = "為您而歌。"
  },
  Voice_6295_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_6296_AwakerVoiceContent = {
    Text = "新任守密人？使出你的全力吧，讓我看看你是否有資格成為我的對手。"
  },
  Voice_6296_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_6297_AwakerVoiceContent = {
    Text = "雖然我是個和平主義者，但「她們」顯然不這麼想……"
  },
  Voice_6297_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_6298_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_6299_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_6300_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6301_AwakerVoiceContent = {
    Text = "準備好了嗎，卡茜亞的魔術秀就要開始了！不要移開眼睛，不要錯過精彩的時刻。It's showtime！"
  },
  Voice_6301_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_6302_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_6303_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_6304_AwakerVoiceContent = {
    Text = "我從茜爾維婭那裡拿到了你的日程安排，這對新人來說太過嚴苛了。我明白你們在做正確的事情，但讓新兵承擔重負可能會為團隊製造不必要的麻煩。\n你說你不是新兵？不，我看得出你的眼神，很多事情你都還沒有經歷過。"
  },
  Voice_6304_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_6304_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_6305_AwakerVoiceContent = {
    Text = "我討厭失職的自己……啊！您不必安慰我！那些過往已經成為了支撐我成長的動力，我已經成為了您的助力，不是麼？"
  },
  Voice_6305_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_6306_AwakerVoiceContent = {
    Text = "我和那個男人聊不來的啦。人生哪有那麼多罪啊罰啊的，及時行樂才比較要緊吧？"
  },
  Voice_6306_AwakerVoiceTitle = {
    Text = "閒話·關於薩爾瓦多"
  },
  Voice_6306_UnlockDesc = {
    Text = "獲得喚醒體「薩爾瓦多」後解鎖"
  },
  Voice_6307_AwakerVoiceContent = {
    Text = "時間不多了，出擊吧。"
  },
  Voice_6307_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_6308_AwakerVoiceContent = {
    Text = "討厭容易熄滅的火燭，討厭黑麵包，討厭裙擺上的線頭……沒什麼理由，討厭這些，不是理所當然的嗎？"
  },
  Voice_6308_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_6309_AwakerVoiceContent = {
    Text = "既然冠我以聖女之名，那汝等應當臣服！"
  },
  Voice_6309_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_6310_AwakerVoiceContent = {
    Text = "既然冠我以聖女之名，那汝等應當臣服！"
  },
  Voice_6310_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_6311_AwakerVoiceContent = {
    Text = "歌詠吧。"
  },
  Voice_6311_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_6312_AwakerVoiceContent = {
    Text = "《淑女衣櫥》、《女工指南》都是很棒的讀物……即使買不起，看看漂亮的裙子也是很不錯的。"
  },
  Voice_6312_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_6313_AwakerVoiceContent = {
    Text = "很奇怪，我記其他東西總是很困難，記你卻只用了幾天……什麼，已經三個月了嗎？真抱歉，我又忘記了。"
  },
  Voice_6313_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_6314_AwakerVoiceContent = {
    Text = "品鑒吧。"
  },
  Voice_6314_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_6316_AwakerVoiceContent = {
    Text = "繼續提升儀態吧。"
  },
  Voice_6316_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_6317_AwakerVoiceContent = {
    Text = "再練習二十遍揮鞭轉。"
  },
  Voice_6317_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_6318_AwakerVoiceContent = {
    Text = "我的動作足夠準確嗎？"
  },
  Voice_6318_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_6319_AwakerVoiceContent = {Text = "請吧！"},
  Voice_6319_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_6320_AwakerVoiceContent = {
    Text = "快帶著布朗離開！"
  },
  Voice_6320_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6323_AwakerVoiceContent = {
    Text = "人類面對欲望的各色神情，總能讓我驚喜不已。可惜，人類還是太脆弱、太渺小了……只有這點，讓我想起來就像有貓在心口撓般難受。"
  },
  Voice_6323_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_6324_AwakerVoiceContent = {
    Text = "從她的記憶裡，我看到了很多關於「融蝕」的過往……但每次想告訴你時，我的意識就會中斷，恐怕這也是她搞的鬼。"
  },
  Voice_6324_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_6325_AwakerVoiceContent = {
    Text = "就這樣歸於湮滅，不好嗎？"
  },
  Voice_6325_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6326_AwakerVoiceContent = {
    Text = "一名合格的僕從必須弱不禁風，大腦空空——我喜歡柔順的羔羊。"
  },
  Voice_6326_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_6327_AwakerVoiceContent = {
    Text = "你我能如此相見，想必是神對苦難者的應許——你即是那消除災難的蒼白火焰，而我自當為你臂膀，伴你左右。"
  },
  Voice_6327_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_6328_AwakerVoiceContent = {
    Text = "到此為止！"
  },
  Voice_6329_AwakerVoiceContent = {
    Text = "試過將融蝕漿直接灌進身體嗎？黑色的黏液就像蝰蛇，一路纏上你的心臟，然後......砰！你的身體會炸成一團溫暖的漿水。噁心，但很有效。"
  },
  Voice_6329_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_6330_AwakerVoiceContent = {
    Text = "哼，弱者抱團取暖之地。"
  },
  Voice_6330_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_6331_AwakerVoiceContent = {
    Text = "每隔一段時間，那個騎摩托的小姑娘都會幫我進行義肢保養。不過，最近檢修的頻率是不是有些過高了？"
  },
  Voice_6331_AwakerVoiceTitle = {
    Text = "閒話·關於諾締拉"
  },
  Voice_6331_UnlockDesc = {
    Text = "獲得喚醒體「諾締拉」後解鎖"
  },
  Voice_6332_AwakerVoiceContent = {
    Text = "我們之間的關係？還需要問嗎？就是你想像中的那種關係哦？"
  },
  Voice_6332_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_6333_AwakerVoiceContent = {
    Text = "不是我擅長的體裁，但如果你執意的話。"
  },
  Voice_6333_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_6334_AwakerVoiceContent = {
    Text = "你的黑眼圈又重了......何必如此勞碌？你得像我一樣，學著享受閒暇的時光。"
  },
  Voice_6334_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_6334_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_6335_AwakerVoiceContent = {
    Text = "等等，未經余允許……"
  },
  Voice_6335_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_6335_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_6336_AwakerVoiceContent = {
    Text = "很好......開始接近原本的模樣了。"
  },
  Voice_6336_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_6336_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_6337_AwakerVoiceContent = {
    Text = "這是足以抗衡「綠色腐敗」的力量......你觸碰了不該觸碰的東西。我呢，再也不會放你離開了。"
  },
  Voice_6337_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_6337_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_6338_AwakerVoiceContent = {
    Text = "噓......清晨河谷的霞光，想必也是第一次見吧？這是對你忠誠的獎勵。"
  },
  Voice_6338_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_6338_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_6339_AwakerVoiceContent = {
    Text = "這本《@1@2啟示錄》賜予你罷。有助於開啟靈智，或是快速入眠。"
  },
  Voice_6339_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_6339_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_6340_AwakerVoiceContent = {
    Text = "塵世還是太過喧鬧，如果你能為我在學院內尋一個清淨角落，那就再好不過了……不，我不需要壁爐。唯有苦修，能讓神靈聽見我的禱言……"
  },
  Voice_6340_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_6341_AwakerVoiceContent = {
    Text = "這身軀上滴下的是蠟油還是蜂蜜，你來舔一口嚐嚐不就知道了？"
  },
  Voice_6341_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_6341_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_6342_AwakerVoiceContent = {
    Text = "初、初次見面。我的名字是艾繼絲……請、請您當我不存在就好！"
  },
  Voice_6342_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_6343_AwakerVoiceContent = {
    Text = "只要我還是「拉蒙娜」，我們就還是搭檔，對嗎？"
  },
  Voice_6343_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_6344_AwakerVoiceContent = {
    Text = "那位黑眼圈很重的小姐，曾向我諮詢「永遠活在陽光下」的方法……的確，只要在兩個世界中往返遷移就好了。可是，她無論如何都不肯踏入維度隧道呢……真傷腦筋。"
  },
  Voice_6344_AwakerVoiceTitle = {
    Text = "閒話·關於溫柯爾"
  },
  Voice_6344_UnlockDesc = {
    Text = "獲得喚醒體「溫柯爾」後解鎖"
  },
  Voice_6345_AwakerVoiceContent = {
    Text = "歡迎來到我的樂園！做好接受鞭笞的準備了嗎？"
  },
  Voice_6345_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_6346_AwakerVoiceContent = {
    Text = "既然祂承認了你，我就不會將你視作敵人。"
  },
  Voice_6346_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_6347_AwakerVoiceContent = {
    Text = "什麼叫我拿的，你可別冤枉好人！她那些破螺絲不見的時候我可是——布朗別！……嘿嘿，你就當什麼也沒看見吧？"
  },
  Voice_6347_AwakerVoiceTitle = {
    Text = "閒話·關於諾締拉"
  },
  Voice_6347_UnlockDesc = {
    Text = "獲得喚醒體「諾締拉」後解鎖"
  },
  Voice_6348_AwakerVoiceContent = {
    Text = "冒險果然和故事裡說的一樣有趣！那個故事……是什麼來著？"
  },
  Voice_6348_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_6349_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_6350_AwakerVoiceContent = {
    Text = "進入人類身體後，我失去了所有同胞的音訊。我害怕其他人沒能逃過惡魔的追趕，害怕我已經是種族的最後一人……救救我，守密人，讓我留在你身邊，不要把我留給黑暗……"
  },
  Voice_6350_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_6350_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_6351_AwakerVoiceContent = {
    Text = "星球毀滅之時，我放棄了身體，將意識遷移到了人類身體中……但黑色惡魔追著我，死死束縛著我的精神讓我無法脫身！祂要把世界都拖入漆黑的泥沼！"
  },
  Voice_6351_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_6351_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_6352_AwakerVoiceContent = {
    Text = "求求你，守密人……只要能讓我待在定位儀上不離開，除了進入黑暗和直面那個、那個黑色的以外……我什麼都可以做！我不能離開定位儀，馬上，馬上我就能定位到母星的殘骸了！只差十二億次運算就可以了！"
  },
  Voice_6352_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_6352_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_6353_AwakerVoiceContent = {
    Text = "能用你的補給份額幫我申請兩袋咖啡因補劑嗎？……我不能睡覺，為什麼要睡覺？千萬不要睡覺！閉上眼後一切都是黑暗，黑暗……"
  },
  Voice_6353_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_6353_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_6354_AwakerVoiceContent = {
    Text = "哇！別靠近我！先、先證明你不是黑暗的走狗！對，走狗，只要脫掉衣服讓我看看你身上有沒有那種噁心的黑色黏液，我就能確認你是不是惡魔……"
  },
  Voice_6354_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_6354_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_6355_AwakerVoiceContent = {
    Text = "別問了，別問了……！你明明知道我最討厭，最害怕什麼！黑暗，永無止境的黑暗！"
  },
  Voice_6355_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_6356_AwakerVoiceContent = {
    Text = "治癒融蝕的方法？那種東西，哪裡都不存在哦。\n你問我是怎麼不被感染的？呵呵……只要「不被看見」就可以了哦？"
  },
  Voice_6356_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_6357_AwakerVoiceContent = {
    Text = "謝謝主人。"
  },
  Voice_6357_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_6358_AwakerVoiceContent = {
    Text = "它們也很開心。"
  },
  Voice_6358_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_6359_AwakerVoiceContent = {
    Text = "莉莉，長大了。"
  },
  Voice_6359_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_6360_AwakerVoiceContent = {
    Text = "要壓碎嗎？"
  },
  Voice_6360_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_6361_AwakerVoiceContent = {
    Text = "你怎麼會把他召喚出來！那個沒用的瞌睡蟲！自甘墮落、不思進取……枉我曾對他寄予厚望！我們走！我不想見到這個傢伙！"
  },
  Voice_6361_AwakerVoiceTitle = {
    Text = "閒話·關於圖魯"
  },
  Voice_6361_UnlockDesc = {
    Text = "獲得喚醒體「圖魯」後解鎖"
  },
  Voice_6362_AwakerVoiceContent = {Text = "噁心！"},
  Voice_6362_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_6363_AwakerVoiceContent = {
    Text = "煩不煩！"
  },
  Voice_6363_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_6364_AwakerVoiceContent = {
    Text = "下次，和您一起去看海吧。去費弗爾也行，我可以給您當嚮導，去別的什麼地方也行，天涯海角，我都想和您一起去看看。"
  },
  Voice_6364_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_6364_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_6365_AwakerVoiceContent = {
    Text = "大海有自己的語言。\n……像這樣，我可以偶爾和水池裡的小魚們聊聊家鄉的話題。如果您好奇的話，我來幫您翻譯如何？"
  },
  Voice_6365_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_6365_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_6366_AwakerVoiceContent = {
    Text = "能夠被您拯救，我時常幸福得感到害怕……請您告訴我吧，這裡不是夢境，您也不會悄無聲息地消失在大海里，對嗎？"
  },
  Voice_6366_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_6366_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_6367_AwakerVoiceContent = {
    Text = "這種感覺可以稱之為“幸福”嗎？我以前……從來沒有奢望過這種事。"
  },
  Voice_6367_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_6367_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_6368_AwakerVoiceContent = {
    Text = "身體暖暖的，好像被溫柔的海水包圍一樣，真是不可思議。"
  },
  Voice_6368_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_6368_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_6369_AwakerVoiceContent = {
    Text = "那便是祂的切片嗎？不錯，倒是很有王之威儀。"
  },
  Voice_6369_AwakerVoiceTitle = {
    Text = "閒話·關於圖魯"
  },
  Voice_6369_UnlockDesc = {
    Text = "獲得喚醒體「圖魯」後解鎖"
  },
  Voice_6370_AwakerVoiceContent = {
    Text = "不要、不要繼續了……它會找到我、它會找到我！"
  },
  Voice_6370_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_6371_AwakerVoiceContent = {
    Text = "這樣就可以一直保持清醒了吧。"
  },
  Voice_6371_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_6372_AwakerVoiceContent = {
    Text = "完了完了完了，這樣一定會被發現的……"
  },
  Voice_6372_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_6373_AwakerVoiceContent = {
    Text = "我們贏了，你開心嗎？“開心”是一種什麼樣的感覺？"
  },
  Voice_6373_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_6374_AwakerVoiceContent = {
    Text = "喜歡的東西？我喜歡汀克特的搖籃曲……當、當然，你唱的也非常動聽！"
  },
  Voice_6374_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_6375_AwakerVoiceContent = {
    Text = "他是個好用的戰士，我曾將他視作“同伴”……什麼，你說，我對“同伴”的定義有問題？願聞其詳。"
  },
  Voice_6375_AwakerVoiceTitle = {
    Text = "閒話·關於戈利亞"
  },
  Voice_6375_UnlockDesc = {
    Text = "獲得喚醒體「戈利亞」後解鎖"
  },
  Voice_6380_AwakerVoiceContent = {
    Text = "源源不斷的力量，充盈全身……"
  },
  Voice_6380_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_6381_AwakerVoiceContent = {Text = "飛吧！"},
  Voice_6381_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_6382_AwakerVoiceContent = {
    Text = "不錯，你比看上去有用多了。"
  },
  Voice_6382_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_6383_AwakerVoiceContent = {
    Text = "二十、二十一、二十四……誒不對，我數到幾了來著？一個、兩個、三個……"
  },
  Voice_6383_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_6383_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_6384_AwakerVoiceContent = {
    Text = "我終於搞清楚之前有多少材料了，這樣我就能更快地完成修補啦——咦，這些又是哪裡來的？"
  },
  Voice_6384_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_6384_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_6385_AwakerVoiceContent = {
    Text = "最近維修的效率好像變高了，多虧有你幫忙，這樣很快就能去進行冒險啦。"
  },
  Voice_6385_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_6385_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_6386_AwakerVoiceContent = {
    Text = "我好像開始有點記得事情了……昨天你是不是給我遞了一個7號扳手來著？"
  },
  Voice_6386_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_6386_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_6387_AwakerVoiceContent = {
    Text = "修、補、完、成！未知的冒險，神秘的世界，我來了！"
  },
  Voice_6387_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_6387_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_6388_AwakerVoiceContent = {Text = "Boom——"},
  Voice_6388_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_6389_AwakerVoiceContent = {
    Text = "別自欺欺人了，精神上的鐐銬一樣是鐐銬，稱不上公正。"
  },
  Voice_6389_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_6390_AwakerVoiceContent = {
    Text = "這樣一來，我和喚醒體的界限就更模糊了。你可要看緊我啊。"
  },
  Voice_6390_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_6390_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_6391_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_6391_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_6392_AwakerVoiceContent = {
    Text = "感覺和一口氣讀完《物種起源》一樣清爽。"
  },
  Voice_6392_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_6392_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_6393_AwakerVoiceContent = {
    Text = "變得更強了，下次任務讓我單獨執行試試看吧？"
  },
  Voice_6393_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_6393_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_6394_AwakerVoiceContent = {
    Text = "除了戰鬥力外，記憶力和邏輯能力好像沒有顯著提升，果然還是要靠自己思考啊。"
  },
  Voice_6394_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_6394_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_6395_AwakerVoiceContent = {
    Text = "我要讓他們也嚐嚐，人生顛覆、一無所有、萬人踐踏是什麼樣的滋味。"
  },
  Voice_6395_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_6395_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_6396_AwakerVoiceContent = {
    Text = "我所受的屈辱，我所失去的一切……我要他們付出代價，要他們所有人付出代價。"
  },
  Voice_6396_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_6396_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_6397_AwakerVoiceContent = {
    Text = "多麼甜美的仇恨，若是佐以仇人的鮮血，定是世上最美味的佳餚。"
  },
  Voice_6397_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_6397_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_6398_AwakerVoiceContent = {
    Text = "啊！不要突然從後面靠近啊！"
  },
  Voice_6398_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_6399_AwakerVoiceContent = {
    Text = "灼熱的火焰在我胸口燃燒……是的，我從未忘記，也不可能忘記。"
  },
  Voice_6399_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_6399_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_6400_AwakerVoiceContent = {
    Text = "焚燒吧，詩歌的靈魂。"
  },
  Voice_6400_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_6401_AwakerVoiceContent = {
    Text = "（輕哼）"
  },
  Voice_6401_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_6402_AwakerVoiceContent = {
    Text = "（輕哼）"
  },
  Voice_6402_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_6403_AwakerVoiceContent = {
    Text = "（輕哼）"
  },
  Voice_6403_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_6404_AwakerVoiceContent = {
    Text = "（輕哼）"
  },
  Voice_6404_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_6405_AwakerVoiceContent = {
    Text = "好癢！和侍女用羽毛撓腳底一樣，你*消音*不是故意的吧。"
  },
  Voice_6405_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_6405_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_6406_AwakerVoiceContent = {
    Text = "願你有個好夢。"
  },
  Voice_6407_AwakerVoiceContent = {
    Text = "願你有個好夢。"
  },
  Voice_6408_AwakerVoiceContent = {
    Text = "賜予寧靜…！"
  },
  Voice_6408_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_6409_AwakerVoiceContent = {
    Text = "優雅地行動吧。"
  },
  Voice_6409_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_6410_AwakerVoiceContent = {
    Text = "能聽見嗎？我的聲音。"
  },
  Voice_6411_AwakerVoiceContent = {
    Text = "能聽見嗎？我的聲音。"
  },
  Voice_6412_AwakerVoiceContent = {
    Text = "下雨了。雨水會沖刷掉一切，變質的食物、頑固的污穢、還有像我這樣的……多餘的……"
  },
  Voice_6412_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_6413_AwakerVoiceContent = {
    Text = "復仇的狂浪永不停歇。"
  },
  Voice_6413_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_6414_AwakerVoiceContent = {
    Text = "鮮血，沐浴全身！"
  },
  Voice_6414_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_6415_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_6416_AwakerVoiceContent = {
    Text = "看這邊！"
  },
  Voice_6416_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_6417_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_6418_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_6419_AwakerVoiceContent = {
    Text = "沒有經歷過苦楚，沒有浸染過悲傷，不曾為病痛折磨，不曾被黑色苦難侵蝕的世界——或許這是永不可得見的幻境，但是我一生追尋的理想。"
  },
  Voice_6419_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_6420_AwakerVoiceContent = {
    Text = "臣服於永恆之國的瑰麗吧！"
  },
  Voice_6420_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_6421_AwakerVoiceContent = {
    Text = "臣服於永恆之國的瑰麗吧！"
  },
  Voice_6421_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_6422_AwakerVoiceContent = {
    Text = "又來乖乖獻上貢品了？真聽話。"
  },
  Voice_6422_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_6422_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_6423_AwakerVoiceContent = {Text = "痛嗎？"},
  Voice_6423_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_6424_AwakerVoiceContent = {
    Text = "專心點。"
  },
  Voice_6424_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_6425_AwakerVoiceContent = {
    Text = "千年的時光讓我有些大意了。"
  },
  Voice_6425_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6426_AwakerVoiceContent = {
    Text = "那一天，嫉恨的火海蔓延，如同血色玫瑰氾濫綻放……所有的詩，都在腥紅的火舌中化為破碎的灰燼……"
  },
  Voice_6426_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_6426_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_6427_AwakerVoiceContent = {
    Text = "學到了新的手法呢！"
  },
  Voice_6427_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_6428_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_6429_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_6430_AwakerVoiceContent = {
    Text = "嗯，這熟悉的空洞的感覺！"
  },
  Voice_6430_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_6431_AwakerVoiceContent = {
    Text = "關節的運動變得更順滑了。"
  },
  Voice_6431_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_6432_AwakerVoiceContent = {
    Text = "那種不祥的黑色，看上去和我這無定形的劍盾有些相似……啊！請主君放心！我的守護之劍絕不會傷害到您！"
  },
  Voice_6432_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_6433_AwakerVoiceContent = {Text = "來吧。"},
  Voice_6433_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_6434_AwakerVoiceContent = {
    Text = "勉強過關吧。"
  },
  Voice_6434_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_6435_AwakerVoiceContent = {
    Text = "我會竭盡全力。"
  },
  Voice_6435_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_6436_AwakerVoiceContent = {
    Text = "今天在這裡玩嗎？"
  },
  Voice_6436_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_6437_AwakerVoiceContent = {
    Text = "地下室有很多水，軟綿綿，冷冰冰的。所以，我的身體總被水汽包圍……彷彿在天地之間，我是唯一的肉體。有時候，我真想融化在水里。\n可是，這樣我就再也不存在了，也不會遇見你。"
  },
  Voice_6437_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_6437_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_6438_AwakerVoiceContent = {
    Text = "告訴您一個秘密......其實我討厭血。討厭它的顏色，討厭它的味道。但是我離不開它。\n......我將鮮血咽進食管，又全部嘔出來......我唾棄我自己。"
  },
  Voice_6438_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_6438_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_6439_AwakerVoiceContent = {
    Text = "唔！您的血……有蜂蜜酒的味道。我想我應該是唯一一個知曉這個秘密的人，對嗎？"
  },
  Voice_6439_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_6439_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_6440_AwakerVoiceContent = {
    Text = "在我的幻想裡，英勇的騎士會將我從黑暗裡拽出來，然後用鎖鏈將我困住。他可以打我、罵我，對我做任何事——痛苦就是我活著的證明。\n您願意，做我的騎士嗎？"
  },
  Voice_6440_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_6440_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_6441_AwakerVoiceContent = {
    Text = "血液像河水一樣流淌。我是屬於您的——這感覺從未如此強烈。"
  },
  Voice_6441_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_6441_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_6442_AwakerVoiceContent = {
    Text = "此即復仇三女神的旨意！"
  },
  Voice_6442_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_6443_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_6444_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_6445_AwakerVoiceContent = {
    Text = "好髒好髒！"
  },
  Voice_6445_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_6446_AwakerVoiceContent = {
    Text = "……艾繼絲，看見了！"
  },
  Voice_6447_AwakerVoiceContent = {
    Text = "……艾繼絲，看見了！"
  },
  Voice_6448_AwakerVoiceContent = {
    Text = "小費，當然是小費。看看學校餐廳裡那些呆頭呆腦的侍應生吧！連躺椅都不提前準備，就這樣還想要什麼額外報酬，做夢！"
  },
  Voice_6448_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_6450_AwakerVoiceContent = {
    Text = "讓我出去！"
  },
  Voice_6451_AwakerVoiceContent = {
    Text = "別這樣......"
  },
  Voice_6451_AwakerVoiceTitle = {
    Text = "技能·一·抑鬱"
  },
  Voice_6452_AwakerVoiceContent = {
    Text = "不必如此多禮，蒼白的使者。你我之間應當沒有隔閡，因著我們都是神的造物，且一同在這條滿是泥濘與考驗的道路上前行。"
  },
  Voice_6452_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_6452_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_6453_AwakerVoiceContent = {
    Text = "我當然不畏懼他們，那些受到消融詛咒折磨的可憐生靈，我隻為他們感到悲傷。我知道我無法替他們承受苦難，但我可以給他們我能給的一切，只要這能讓他們獲得些許慰藉。"
  },
  Voice_6453_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_6453_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_6454_AwakerVoiceContent = {
    Text = "要和我一起禱告嗎，蒼白之火？為了今天死於我們的戰鬥的苦者而禱告。即使他們因消融詛咒而陷入癲狂，也依舊是仁愛之神的造物，是你我的姐妹弟兄。願他們能享受應得的安寧。"
  },
  Voice_6454_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_6454_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_6455_AwakerVoiceContent = {
    Text = "即使紅色的火焰讓我緊張，我也會為了你再一次走上燃燒的木台。不必為此介懷，我的白焰，在你能帶來的福祉面前，我一人的犧牲不值一提。"
  },
  Voice_6455_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_6455_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_6456_AwakerVoiceContent = {
    Text = "後悔？不，當然不會。我的死為他們減輕了痛苦，換來了更多的時間，這就足夠了。但……你對我很坦承，因此我也不會對你隱瞞：那日的火刑還是在我心裡留下了瘡疤。"
  },
  Voice_6456_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_6456_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_6457_AwakerVoiceContent = {
    Text = "能和我做個約定嗎？嗯……我們約定，不管發生什麼，你都永遠記得「拉蒙娜」，如何？"
  },
  Voice_6457_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_6457_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_6458_AwakerVoiceContent = {
    Text = "我不後悔選擇成為這副模樣，再來一次，我還是會這樣做。但是，守密人，我很害怕……害怕「拉蒙娜」不會在世界上留下任何痕跡。"
  },
  Voice_6458_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_6458_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_6459_AwakerVoiceContent = {
    Text = "不用擔心，眼罩並不影響我視物。不如說，這樣一來，我才能不把所有東西都看進眼裡。"
  },
  Voice_6459_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_6459_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_6460_AwakerVoiceContent = {
    Text = "我的表情看起來很陌生？我明明有注意控制……看來，她的存在越來越強了。"
  },
  Voice_6460_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_6460_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_6461_AwakerVoiceContent = {
    Text = "待解決的謎團，待拯救的人實在太多了。我不知道我還能行動多久，我也沒辦法保護所有人……真是難辦啊。"
  },
  Voice_6461_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_6461_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_6462_AwakerVoiceContent = {
    Text = "還要在我身上繼續加注嗎？看來，想要隨心而活也沒那麼容易。安心吧，我會在幫你解決問題的前提下偷懶的。"
  },
  Voice_6462_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_6462_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_6463_AwakerVoiceContent = {
    Text = "事已至此，不能不拿出真本事來了吧？案發現場在哪裡？就算要燃燒我所有的運氣，也一定會在期限內將嫌疑犯帶回來！"
  },
  Voice_6463_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_6463_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_6464_AwakerVoiceContent = {
    Text = "唉呀，收了你這麼多好處，不能不告訴你一些秘密了：其實，我可能是這個世界上運氣最壞的人呢。"
  },
  Voice_6464_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_6464_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_6465_AwakerVoiceContent = {
    Text = "你好像沒把我說的話放在心上……罷了罷了，我還是會幫你撕裂敵人的。反正這爪子這利齒也是偶然得來的，對吧？"
  },
  Voice_6465_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_6465_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_6466_AwakerVoiceContent = {
    Text = "我的幸運不一定能傳遞給夥伴的。你肯定聽過那句話吧？“幸運兔腳對兔子來說，可沒什麼作用。”"
  },
  Voice_6466_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_6466_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_6467_AwakerVoiceContent = {
    Text = "希望在你的靈魂中，烙下余的印記嗎？"
  },
  Voice_6467_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_6468_AwakerVoiceContent = {
    Text = "如此渴求余的力量嗎？"
  },
  Voice_6468_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_6469_AwakerVoiceContent = {
    Text = "別看我這副模樣，我也曾是個淑女……我會刺繡，會讀丁尼生……對了，我還會唱歌：她像不息的河水，在我的血液中流淌~"
  },
  Voice_6469_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_6470_AwakerVoiceContent = {
    Text = "皮克曼與我正在合作一些有趣的裝置藝術，探討如何通過解構視覺原始主義重構抽象表像主義......咦，奧瑞塔怎麼暈倒了？"
  },
  Voice_6470_AwakerVoiceTitle = {
    Text = "閒話·關於奧瑞塔"
  },
  Voice_6470_UnlockDesc = {
    Text = "獲得喚醒體「奧瑞塔」後解鎖"
  },
  Voice_6471_AwakerVoiceContent = {
    Text = "您希望我笑一笑？\n莉莉，有在笑嗎？"
  },
  Voice_6471_AwakerVoiceTitle = {
    Text = "閒話·關於笑容"
  },
  Voice_6472_AwakerVoiceContent = {
    Text = "真是新鮮，我竟然收穫了一段平等的友誼。\n不過嘛……我請求保留驅使你的權利，作為我們之間的一點小情趣。今夜來我的臥室一趟吧，有關人類之間的感情，我還有很多需要學習的地方……"
  },
  Voice_6472_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_6472_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_6473_AwakerVoiceContent = {
    Text = "你知道你最可愛的地方在哪裡嗎？是你對我說「不」的時候。你的鼻子會皺起來，眉毛略微上抬……對，就像現在這樣。"
  },
  Voice_6473_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_6473_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_6474_AwakerVoiceContent = {
    Text = "我愛我的僕從們。這些英俊的小傢伙，被融蝕嚇得瑟瑟發抖，躲在我身後的小模樣，真是惹人憐愛呀。美人的眼淚總是惹人心醉。你呢，你害怕融蝕嗎？"
  },
  Voice_6474_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_6474_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_6475_AwakerVoiceContent = {
    Text = "守密人，你有什麼討厭的傢伙嗎？作為報答，我可以代為調教一二。不出一個禮拜，我會讓他洗心革面，乖乖舔上你的腳趾頭。"
  },
  Voice_6475_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_6475_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_6476_AwakerVoiceContent = {
    Text = "唔……你雖然愚鈍，卻不至於惹人厭煩。明天開始你來伺候我吧。\n你不願意……？這不是在徵求意見，這是命令。"
  },
  Voice_6476_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_6476_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_6477_AwakerVoiceContent = {
    Text = "很久沒有這樣的心情了，我會以萬全的姿態踏上舞臺，為您獻上貫穿寰宇的音浪。"
  },
  Voice_6477_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_6477_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_6478_AwakerVoiceContent = {
    Text = "你要知道，這是沒有意義的。"
  },
  Voice_6478_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_6478_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_6479_AwakerVoiceContent = {
    Text = "摘取勝利的花朵後，我想索取一點小小的報酬……"
  },
  Voice_6479_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_6480_AwakerVoiceTitle = {
    Text = "受擊·抑鬱·三"
  },
  Voice_6481_AwakerVoiceContent = {
    Text = "那艘飛艇狹小逼仄，像是在宇宙中漂浮的金屬棺材。我在等待我的啟明星，直到您的出現。"
  },
  Voice_6481_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_6481_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_6482_AwakerVoiceContent = {
    Text = "怎麼會？！"
  },
  Voice_6482_AwakerVoiceTitle = {
    Text = "受擊·狂躁·一"
  },
  Voice_6483_AwakerVoiceTitle = {
    Text = "受擊·抑鬱·一"
  },
  Voice_6484_AwakerVoiceTitle = {
    Text = "受擊·抑鬱·二"
  },
  Voice_6485_AwakerVoiceContent = {Text = "天罰！"},
  Voice_6486_AwakerVoiceContent = {Text = "天罰！"},
  Voice_6487_AwakerVoiceContent = {Text = "無聊。"},
  Voice_6487_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_6488_AwakerVoiceContent = {
    Text = "（驚呼）"
  },
  Voice_6488_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_6489_AwakerVoiceContent = {
    Text = "還能堅持。"
  },
  Voice_6489_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_6490_AwakerVoiceContent = {
    Text = "（驚呼）"
  },
  Voice_6490_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_6491_AwakerVoiceContent = {
    Text = "（驚呼）"
  },
  Voice_6491_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_6492_AwakerVoiceContent = {
    Text = "不敬之人，消解於燒灼的寧靜中吧。"
  },
  Voice_6492_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_6493_AwakerVoiceContent = {
    Text = "小心點，要是把手伸進另一個維度空間，可就拿不回來了哦！"
  },
  Voice_6493_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_6494_AwakerVoiceContent = {
    Text = "一群廢物，不想被做成肉泥罐頭的話，下次可要好好注意了。"
  },
  Voice_6494_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6495_AwakerVoiceContent = {
    Text = "哎呀，在向我撒嬌嗎？\n真難辦，如此下去，我可等不到守密人完全成熟的時候呀……"
  },
  Voice_6495_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_6496_AwakerVoiceContent = {
    Text = "向自由意志深潛吧！"
  },
  Voice_6496_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_6497_AwakerVoiceContent = {
    Text = "討厭的東西啊……果然，還是做事中途放棄的傢伙吧。一想起那種人，昨天的晚餐都要嘔上來了。"
  },
  Voice_6497_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_6498_AwakerVoiceContent = {
    Text = "無盡的頭顱啊，在此窺見你的面貌吧！"
  },
  Voice_6498_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_6499_AwakerVoiceContent = {
    Text = "無盡的頭顱啊，在此窺見你的面貌吧！"
  },
  Voice_6499_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_6500_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_6501_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_6502_AwakerVoiceContent = {
    Text = "如此信任我嗎？"
  },
  Voice_6502_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_6502_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_6503_AwakerVoiceContent = {
    Text = "回歸吧。"
  },
  Voice_6503_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_6504_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_6505_AwakerVoiceContent = {
    Text = "我當然知道，那是我的另一個側面。但她為何要反抗？接受成為被選中者的命運，祈求之物不是信手拈來？"
  },
  Voice_6505_AwakerVoiceTitle = {
    Text = "閒話·關於「墨菲」"
  },
  Voice_6505_UnlockDesc = {
    Text = "獲得喚醒體「墨菲」後解鎖"
  },
  Voice_6506_AwakerVoiceContent = {
    Text = "您好，我叫達芙黛爾。我曾經與某位客人做過交換，那個人要求我來協助您。那麼，讓我聽聽看您的需求吧。\n哎呀……您所期望之物可是價格不菲哦？"
  },
  Voice_6506_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_6507_AwakerVoiceContent = {
    Text = "*消音*幹什麼！信不信我把你手砍下來！"
  },
  Voice_6507_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_6510_AwakerVoiceContent = {
    Text = "玫瑰刺傷手指，流淌成詩。"
  },
  Voice_6510_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_6511_AwakerVoiceContent = {
    Text = "屈於這哀慟濃墨之下，成為哀悼的歌詠……"
  },
  Voice_6511_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_6512_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_6513_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_6514_AwakerVoiceContent = {
    Text = "災厄降臨！"
  },
  Voice_6514_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_6515_AwakerVoiceContent = {
    Text = "給我吧。"
  },
  Voice_6515_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_6516_AwakerVoiceContent = {
    Text = "……名字，嗚，我想不起來。\n對了，「24」，他們都這樣叫我……不！不許出來！你不能，現在不能……"
  },
  Voice_6516_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_6518_AwakerVoiceContent = {
    Text = "湧現……"
  },
  Voice_6519_AwakerVoiceContent = {
    Text = "我擔不起天籟之聲這樣的稱號……只要您能喜歡我的歌聲就好。"
  },
  Voice_6519_AwakerVoiceTitle = {
    Text = "閒話·關於歌唱"
  },
  Voice_6520_AwakerVoiceContent = {
    Text = "弄髒的衣服，得在下一場沙龍前換掉才行。"
  },
  Voice_6520_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_6521_AwakerVoiceContent = {
    Text = "它要追上我了，永恆的黑暗，誰也逃不掉……"
  },
  Voice_6521_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6522_AwakerVoiceContent = {
    Text = "每次看到你，我就想到你施加在我身上的無形枷鎖。讓你活著已經是我最大的忍讓。"
  },
  Voice_6522_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_6523_AwakerVoiceContent = {
    Text = "無論重來多少次，我都會與你一同前行。"
  },
  Voice_6523_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6524_AwakerVoiceContent = {
    Text = "願神的仁愛溫暖你的靈魂。"
  },
  Voice_6524_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_6525_AwakerVoiceContent = {
    Text = "我喜歡閒逛。漫無目的的閒逛。沼澤、墓地、病房、廢棄的城堡......在這些地方，我總會收穫意外之喜。"
  },
  Voice_6525_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_6526_AwakerVoiceContent = {
    Text = "感到榮幸吧，永恆之國的大門即在此。"
  },
  Voice_6526_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_6527_AwakerVoiceContent = {
    Text = "咯咯——好癢好癢！奧瑞塔也要撓回來！"
  },
  Voice_6527_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_6528_AwakerVoiceContent = {
    Text = "《天鵝之死》，舞蹈者以肢體語言詮釋生命的渴望與掙扎的劇碼。那烈火中扭曲的身姿何嘗不是如此呢。"
  },
  Voice_6528_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_6529_AwakerVoiceContent = {
    Text = "切開，切開，撕碎。就像過去那些人對我做的一樣…呵呵……呵呵呵！！"
  },
  Voice_6529_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_6530_AwakerVoiceContent = {
    Text = "你還是別和泰旖絲小姐走得太近……不，我沒有吃醋，我只是怕有人會上女人的當。"
  },
  Voice_6530_AwakerVoiceTitle = {
    Text = "閒話·關於泰旖絲"
  },
  Voice_6530_UnlockDesc = {
    Text = "獲得喚醒體「泰旖絲」後解鎖"
  },
  Voice_6531_AwakerVoiceContent = {
    Text = "……多謝了。"
  },
  Voice_6531_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_6531_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_6532_AwakerVoiceContent = {
    Text = "很好......你有一雙能夠識人的慧眼。"
  },
  Voice_6532_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_6532_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_6533_AwakerVoiceContent = {
    Text = "珈倫的故鄉非常美麗！是位於湖中的石頭城哦。\n每逢凸月，我們會在火焰中無聲跳舞、祭祀…...\n說實話，珈倫剛來大學的時候，每天晚上都很想家，還在被窩裡偷偷哭呢。不過現在，珈倫擁有了新的家、新的家人，一切都好起來了！"
  },
  Voice_6533_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_6533_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_6534_AwakerVoiceContent = {
    Text = "呀~還這麼不滿足嗎？來吧，讓我抓緊時間調教調教你~"
  },
  Voice_6534_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_6535_AwakerVoiceContent = {
    Text = "肌肉孱弱，面容憔悴，也就這雙死人一樣的眼睛還有點價值——剜下來喂蜘蛛正好。"
  },
  Voice_6535_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_6536_AwakerVoiceContent = {
    Text = "謝、謝謝您為艾繼絲做的一切。艾繼絲會儘量、儘量不辜負您的！"
  },
  Voice_6536_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_6537_AwakerVoiceContent = {
    Text = "（恐懼的驚呼）"
  },
  Voice_6537_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_6538_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_6539_AwakerVoiceContent = {
    Text = "放過我……"
  },
  Voice_6539_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_6540_AwakerVoiceContent = {
    Text = "（恐懼的驚呼）"
  },
  Voice_6540_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_6541_AwakerVoiceContent = {
    Text = "拉蒙娜小姐的劍術，與我所掌握的技藝有很大不同。如果主君允許的話，真想與她切磋一番……當、當然！這只是為了提升自己！"
  },
  Voice_6541_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_6541_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_6542_AwakerVoiceContent = {
    Text = "您問我，為什麼不和其他孩子們玩嗎？ 非常難以啟齒……我生前沒有什麼玩耍的機會，唯一的玩伴還是曾經侍奉的公主……啊！居然在主君面前提起其他君主，請、請原諒我的失言……"
  },
  Voice_6542_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_6542_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_6543_AwakerVoiceContent = {
    Text = "你是受到彌薩格大學承認的守密人，因此，我會為你開放相應的功能權限。"
  },
  Voice_6543_AwakerVoiceTitle = {
    Text = "閒話·關於「主角」"
  },
  Voice_6544_AwakerVoiceContent = {
    Text = "主君對我所學的“騎士七技”感興趣嗎？太棒了！啊……嗯…方才失禮了，我的意思是，如果您願意練習騎射的話，我很榮幸能成為您的陪練！"
  },
  Voice_6544_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_6544_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_6545_AwakerVoiceContent = {
    Text = "我並不是一名合格的騎士。無論是從那邪惡的疫病、還是從進犯的外敵手下，我都沒能守護好曾經的主君。如今，您願意給予這樣的我信任，是我莫大的榮幸……以騎士的榮光與這條微不足道的性命起誓，我將永遠守護您的前進之路。"
  },
  Voice_6545_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_6545_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_6546_AwakerVoiceContent = {
    Text = "勿要傷害。"
  },
  Voice_6546_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_6547_AwakerVoiceContent = {Text = "別呀~"},
  Voice_6547_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_6549_AwakerVoiceContent = {
    Text = "勿要殺戮。"
  },
  Voice_6549_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_6550_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_6551_AwakerVoiceContent = {
    Text = "現在，我們只是不相溶的水與油。"
  },
  Voice_6551_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_6552_AwakerVoiceContent = {
    Text = "我沒有特別喜歡的東西。硬要說的話，外出執行任務的感覺還不錯。"
  },
  Voice_6552_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_6553_AwakerVoiceContent = {
    Text = "為什麼，為什麼把我關在這裡？呵呵……不會讓你得逞的，就讓我來把這拘束，把這監牢……全都撕成碎片！"
  },
  Voice_6553_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_6554_AwakerVoiceContent = {
    Text = "保護大家。"
  },
  Voice_6555_AwakerVoiceContent = {
    Text = "你們幾個，每次都來看魔術秀，不會膩嗎？要乖乖坐好哦？再跑到舞臺上的話，我就把你們丟到異次元空間裡去！"
  },
  Voice_6555_AwakerVoiceTitle = {
    Text = "閒話·關於孩子們"
  },
  Voice_6555_UnlockDesc = {
    Text = "獲得喚醒體「艾繼絲」「詹金」「莉莉」「墨菲」「珈倫」「奧瑞塔」其一後解鎖"
  },
  Voice_6556_AwakerVoiceContent = {
    Text = "您的禮物，我就滿懷敬意地收下了。"
  },
  Voice_6556_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_6557_AwakerVoiceContent = {
    Text = "怎樣的回禮，才能與您的付出相匹配呢？"
  },
  Voice_6557_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_6558_AwakerVoiceContent = {
    Text = "何等瑰麗……"
  },
  Voice_6558_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_6559_AwakerVoiceContent = {
    Text = "檢測到強力電流，即將進行機體維護……修正，為什麼沒有過熱？"
  },
  Voice_6559_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_6559_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_6560_AwakerVoiceContent = {
    Text = "自上次啟靈儀式後，我在休眠狀態時會看到殘破的畫面。在裡面，我擁有著如你一般的血肉之軀，也會滴落淚水。這，是夢嗎？"
  },
  Voice_6560_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_6560_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_6561_AwakerVoiceContent = {
    Text = "每次儀式後，胸口部位都會檢測到高熱，但那裡並沒有能源相關部件。你知道為什麼嗎？"
  },
  Voice_6561_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_6561_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_6562_AwakerVoiceContent = {
    Text = "我看到了，一切都<Del:該在永恆的電流中死亡>抱抱抱抱歉，模組似乎——警告，警告，非艾瑞卡意識活動增強，請銷毀銷毀銷……你好，請問有什麼需要我幫助的嗎？"
  },
  Voice_6562_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_6562_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_6563_AwakerVoiceContent = {
    Text = "經過仔細分析，我斷定我在休眠狀態時看到的並非傳統意義上的夢境，而是我<Del:可悲的血肉身軀就應該摧毀>的記憶。至於那如超載一般燒灼的熱度，或許是被稱為「不甘」的情感。"
  },
  Voice_6563_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_6563_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_6564_AwakerVoiceContent = {
    Text = "想要觀看表演，就在觀眾席乖乖坐好吧！"
  },
  Voice_6564_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_6564_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_6565_AwakerVoiceContent = {
    Text = "仇恨的火焰熊熊燃燒，永不熄滅。"
  },
  Voice_6565_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_6567_AwakerVoiceContent = {
    Text = "我所相融的意志是一個聒噪的傢伙，越提升，「祂」的聲音就越清晰……像海德公園的鵝，挺吵的。"
  },
  Voice_6567_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_6567_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_6568_AwakerVoiceContent = {
    Text = "我將用這力量吞噬背叛者。"
  },
  Voice_6568_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_6569_AwakerVoiceContent = {
    Text = "……多謝了。"
  },
  Voice_6569_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_6570_AwakerVoiceContent = {
    Text = "守密人？可笑至極，這場不切實際的夢，該醒了。"
  },
  Voice_6570_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_6571_AwakerVoiceContent = {
    Text = "復仇的血，正在沸騰……"
  },
  Voice_6571_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_6572_AwakerVoiceContent = {
    Text = "動起來吧，奴僕！"
  },
  Voice_6572_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_6573_AwakerVoiceContent = {
    Text = "別溺水呀！"
  },
  Voice_6573_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_6574_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_6575_AwakerVoiceContent = {
    Text = "食堂後門的捕鼠夾我扔掉了，太危險了，布朗那冒失鬼踩上去怎麼辦！"
  },
  Voice_6575_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_6576_AwakerVoiceContent = {
    Text = "這感覺真奇怪......我是不是快死了？不，救救我！不要！！！"
  },
  Voice_6576_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_6576_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_6579_AwakerVoiceContent = {
    Text = "我想要一盞不會熄滅的燈，她居然說什麼，用“沒有翅膀卻會飛的水螅的標本”來交換。我上哪找這麼怪異的物種啊！"
  },
  Voice_6579_AwakerVoiceTitle = {
    Text = "閒話·關於達芙黛爾"
  },
  Voice_6579_UnlockDesc = {
    Text = "獲得喚醒體「達芙黛爾」後解鎖"
  },
  Voice_6582_AwakerVoiceContent = {Text = "危險。"},
  Voice_6582_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_6583_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_6584_AwakerVoiceContent = {Text = "受擊。"},
  Voice_6584_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_6585_AwakerVoiceContent = {
    Text = "像糖紙一樣閃閃發光的寶物……艾繼絲會好好珍藏的。"
  },
  Voice_6585_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_6586_AwakerVoiceContent = {
    Text = "受到傷害。"
  },
  Voice_6586_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_6587_AwakerVoiceContent = {
    Text = "我的小店在宇宙中的任何維度、任何位置，當然也可以存在於此。何況，我很喜歡彌薩格那些不夠謹慎的孩子們哦？"
  },
  Voice_6587_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_6588_AwakerVoiceContent = {
    Text = "討厭……青椒很難吃。"
  },
  Voice_6588_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_6589_AwakerVoiceContent = {
    Text = "我和您的關係就像帆和船的關係。沒有船，帆就不應存在；沒有帆，船就難以遠航。難道不是嗎？"
  },
  Voice_6589_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_6590_AwakerVoiceContent = {
    Text = "虔誠於舞蹈的人死了，褻瀆藝術的人也死了，死在彌漫著焦油氣味的烈火中。死亡不是結束，而是開始，因為會死去的只有人類，舞蹈和藝術是永恆的。"
  },
  Voice_6590_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_6590_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_6591_AwakerVoiceContent = {
    Text = "感謝您的理解，也許現在是與過去的自我和解的時刻了……我相信自己做的是正確的事情，我不曾辱沒舞蹈世家的名聲。我會登上您準備的舞臺，然後如您所願，大放異彩。"
  },
  Voice_6591_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_6591_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_6592_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_6593_AwakerVoiceContent = {
    Text = "你想要我登上舞臺，在舞臺上綻放？\n這已經無法實現了，這雙眼已經被仇恨吞沒，除了燒盡一切，我什麼都做不到。"
  },
  Voice_6593_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_6593_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_6594_AwakerVoiceContent = {
    Text = "你明白那種感覺嗎？旋轉、旋轉、旋轉，永不停歇。繃直的膝蓋酸軟不堪，足尖滲出的黑色血跡打濕芭蕾舞鞋，依然一刻不停。就因為我不願意接受成為玩具的命運……"
  },
  Voice_6594_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_6594_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_6595_AwakerVoiceContent = {
    Text = "我燒死的不是舞技高超的宮廷舞者，不是芭蕾殿堂的優雅主理人，不是懂得欣賞崇高與美的貴族，而是出賣身體的無能庸人，罔顧他人的諂媚掮客、耽於肉欲的骯髒俗物……你會理解我的，對吧？"
  },
  Voice_6595_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_6595_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_6596_AwakerVoiceContent = {
    Text = "我不喜歡長著黏糊觸手的那些人，也不喜歡海底……你不要露出了然的表情啊！我又不是害怕家長的小孩！"
  },
  Voice_6596_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_6596_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_6597_AwakerVoiceContent = {
    Text = "您如此慷慨，不勝感激……"
  },
  Voice_6597_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_6600_AwakerVoiceContent = {
    Text = "快帶著布朗離開！"
  },
  Voice_6600_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6601_AwakerVoiceTitle = {
    Text = "防禦·抑鬱"
  },
  Voice_6602_AwakerVoiceContent = {Text = "滾！"},
  Voice_6602_AwakerVoiceTitle = {
    Text = "防禦·躁狂"
  },
  Voice_6603_AwakerVoiceContent = {
    Text = "雷婭是誰？哦，那個求我揍她的女人。哈哈，有點意思......這裡也沒那麼無聊嘛。"
  },
  Voice_6603_AwakerVoiceTitle = {
    Text = "閒話·關於雷婭"
  },
  Voice_6603_UnlockDesc = {
    Text = "獲得喚醒體「雷婭」後解鎖"
  },
  Voice_6604_AwakerVoiceContent = {
    Text = "小山坡上的落日時常叫我想起在克利夫蘭的日子……克利夫蘭，我竟然還能記起這個名字，那個讓我留下這些傷疤的地方……"
  },
  Voice_6604_AwakerVoiceTitle = {
    Text = "閒話·關於黃昏"
  },
  Voice_6605_AwakerVoiceContent = {
    Text = "啊……繁星……就此隕落……"
  },
  Voice_6605_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6606_AwakerVoiceContent = {
    Text = "毫無疑問是人類。還有比人類更加骯髒的生物嗎？"
  },
  Voice_6606_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_6607_AwakerVoiceContent = {
    Text = "就是現在！"
  },
  Voice_6607_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_6608_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_6609_AwakerVoiceContent = {
    Text = "融蝕？嗯……是的！霜淇淋是會融化的！但只要大家一起分享，就能在它完全變成奶油之前吃掉哦！"
  },
  Voice_6609_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_6610_AwakerVoiceContent = {
    Text = "我會用這份力量守護您。"
  },
  Voice_6610_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_6610_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_6611_AwakerVoiceContent = {
    Text = "哎呀，本店售出的商品概不退換哦？想要下潛至深海，的確是需要潛水艇的吧？"
  },
  Voice_6611_AwakerVoiceTitle = {
    Text = "閒話·關於凱刻斯"
  },
  Voice_6611_UnlockDesc = {
    Text = "獲得喚醒體「凱刻斯」後解鎖"
  },
  Voice_6612_AwakerVoiceContent = {
    Text = "最棒的舞臺！彌薩格大學裡的師生都能夠理解，我演出的是真正的魔法！這就是魔術師的知音吧？"
  },
  Voice_6612_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_6613_AwakerVoiceContent = {
    Text = "宇宙的秩序，在這裡變化；毀滅的未來，是魔術師的信仰！"
  },
  Voice_6613_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_6613_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_6614_AwakerVoiceContent = {
    Text = "可以讓艾繼絲在這裡多呆一會兒嗎？我會安安靜靜的，不發出任何聲音，儘量不妨礙您……"
  },
  Voice_6614_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_6614_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_6615_AwakerVoiceContent = {
    Text = "以人類知性……解明世界本質！"
  },
  Voice_6615_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_6616_AwakerVoiceContent = {
    Text = "我的夢境裡，時常會出現潮水的聲音，那聲音越來越遠，越來越遠。我知道，我或許會永遠留在這裡了，人類。"
  },
  Voice_6616_AwakerVoiceTitle = {
    Text = "閒話·關於深海"
  },
  Voice_6617_AwakerVoiceContent = {
    Text = "更多記憶、更多情緒、更多夢想——"
  },
  Voice_6617_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_6617_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_6618_AwakerVoiceContent = {
    Text = "開始變了！"
  },
  Voice_6620_AwakerVoiceContent = {
    Text = "等祂降生……我就不用再忍受這種屈辱……"
  },
  Voice_6620_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6621_AwakerVoiceContent = {
    Text = "選我，選我！有派對的地方就有珈倫！"
  },
  Voice_6621_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_6622_AwakerVoiceContent = {
    Text = "嗯？對我感興趣嗎？想必……您已經準備好付出代價嘍？"
  },
  Voice_6622_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_6623_AwakerVoiceContent = {
    Text = "絕不饒恕，絕不饒恕……！"
  },
  Voice_6623_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6624_AwakerVoiceContent = {
    Text = "仍歌頌，來自群星的色彩。"
  },
  Voice_6624_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_6625_AwakerVoiceContent = {
    Text = "詠唱吧，詠唱吧！"
  },
  Voice_6625_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_6626_AwakerVoiceContent = {
    Text = "喜歡母親！"
  },
  Voice_6626_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_6627_AwakerVoiceContent = {Text = "來吧。"},
  Voice_6627_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_6628_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_6629_AwakerVoiceContent = {
    Text = "喚醒體們可能會出於好奇而進食，但食物並不是維持我們存在的必須物。所以，沒必要每次下午茶都來叫我了，攝入糖分只會讓這具身體的球形關節加速老化。"
  },
  Voice_6629_AwakerVoiceTitle = {
    Text = "閒話·關於下午茶"
  },
  Voice_6632_AwakerVoiceContent = {
    Text = "請你們一定要放過主人，珈倫……珈倫任你們處置！"
  },
  Voice_6632_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6633_AwakerVoiceContent = {
    Text = "這些，都是莉莉可以吃的嗎？"
  },
  Voice_6633_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_6633_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_6634_AwakerVoiceContent = {
    Text = "討厭？可以說嗎，艾繼絲最討厭總是無能為力的自己……可是我只要這麼說，詹金就會很生氣很生氣……"
  },
  Voice_6634_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_6635_AwakerVoiceContent = {
    Text = "化成灰燼吧。"
  },
  Voice_6636_AwakerVoiceContent = {
    Text = "化成灰燼吧。"
  },
  Voice_6637_AwakerVoiceContent = {
    Text = "幹得漂亮，守密人。說吧，這次要我替你殺誰？"
  },
  Voice_6637_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_6637_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_6638_AwakerVoiceContent = {
    Text = "融蝕是這所學院成立的理由，也是我們相遇的原因。為了從融蝕手中搶救人類的火種，加油吧，搭檔。"
  },
  Voice_6638_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_6639_AwakerVoiceContent = {
    Text = "我能感覺到那位小姐的敵意，是我對您的愛招致嫉妒了吧……您瞧，那只大翅鯨的嘴都妒忌地張開了呢。"
  },
  Voice_6639_AwakerVoiceTitle = {
    Text = "閒話·關於蘿坦"
  },
  Voice_6639_UnlockDesc = {
    Text = "獲得喚醒體「蘿坦」後解鎖"
  },
  Voice_6640_AwakerVoiceContent = {
    Text = "主人主人！珈倫今天在哈羅爾百貨看到超級——漂亮的卡梅奧胸針！主人能為珈倫買下來嗎，這可是我一生的請求！"
  },
  Voice_6640_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_6641_AwakerVoiceContent = {
    Text = "我會充當你在黑夜中的指向標，但這個期限並不是永久。"
  },
  Voice_6641_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_6642_AwakerVoiceContent = {
    Text = "母親，好痛呀，母親……"
  },
  Voice_6642_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6643_AwakerVoiceContent = {
    Text = "認輸吧！勝利是我的囊中之物！"
  },
  Voice_6643_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_6644_AwakerVoiceContent = {
    Text = "認輸吧！勝利是我的囊中之物！"
  },
  Voice_6644_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_6645_AwakerVoiceContent = {
    Text = "融蝕啊……我的腦容量有限，沒法理解那麼複雜的疾病……如果有需要修繕的機械再找我吧！"
  },
  Voice_6645_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_6646_AwakerVoiceContent = {
    Text = "呀！奧瑞塔被找到了！作為輸掉的懲罰，你可以向奧瑞塔提一個要求哦——但是不要讓奧瑞塔去上課，拜託拜託了——"
  },
  Voice_6646_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_6647_AwakerVoiceContent = {
    Text = "為祂的再臨掃除障礙……"
  },
  Voice_6647_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_6648_AwakerVoiceContent = {
    Text = "終有一天，奧恩叔叔會迎接我重返海底家園。在那之前，可以勉為其難和你做朋友。"
  },
  Voice_6648_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_6648_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_6649_AwakerVoiceContent = {
    Text = "“我們家族流淌著偉大的血脈，蒙選召者將會在深海中享有永恆的安樂。”\n沒想到，遠離海洋來到學院後，才感受到這種安樂。你和那些欺侮我的人是不一樣的，所以，我也不會允許其他人欺負你。"
  },
  Voice_6649_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_6649_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_6650_AwakerVoiceContent = {
    Text = "超級硬的特製材料！"
  },
  Voice_6650_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_6651_AwakerVoiceContent = {
    Text = "被困在這種混了人類成分的殼子裡真令我噁心。好不容易擺脫了過去，現在倒好，又不得不想起來了……"
  },
  Voice_6651_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_6651_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_6652_AwakerVoiceContent = {
    Text = "我知道，偉大血統的傳承者再次淪為了人類的走狗。不過，你也別想隨意驅使我。"
  },
  Voice_6652_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_6652_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_6653_AwakerVoiceContent = {
    Text = "哼，你這孱弱的人類在指揮方面倒是有些才能，只是這劣質的軀殼讓我無法發揮全力。"
  },
  Voice_6653_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_6653_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_6654_AwakerVoiceContent = {
    Text = "身體越來越熱了。"
  },
  Voice_6654_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_6655_AwakerVoiceContent = {
    Text = "逃…要逃！要逃離這裡！"
  },
  Voice_6655_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_6656_AwakerVoiceContent = {
    Text = "逃…要逃！要逃離這裡！"
  },
  Voice_6656_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_6657_AwakerVoiceContent = {
    Text = "感謝您的努力，那麼讓我也給您相應的獎勵吧。"
  },
  Voice_6657_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_6658_AwakerVoiceContent = {
    Text = "沒關係。"
  },
  Voice_6658_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_6659_AwakerVoiceContent = {
    Text = "（吃痛的悶哼）"
  },
  Voice_6659_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_6660_AwakerVoiceContent = {
    Text = "人類，你雖孱弱，但你的信念打動了我。我願成為你的武器，一起大鬧一場吧！"
  },
  Voice_6660_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_6660_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_6662_AwakerVoiceContent = {
    Text = "這可是我的沙龍。"
  },
  Voice_6662_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_6664_AwakerVoiceContent = {
    Text = "人人平等的學院……不知道你們懷有怎樣愚蠢的憧憬。即使你沒有犯任何錯誤，他們也會將你踩在腳下。我知道那種感受。"
  },
  Voice_6664_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_6665_AwakerVoiceContent = {
    Text = "此為一切不淨的根源……"
  },
  Voice_6665_AwakerVoiceTitle = {
    Text = "狂氣爆發·抑鬱"
  },
  Voice_6666_AwakerVoiceContent = {
    Text = "我曾因沒能庇佑船員而受刑。他們說，因為我的失職，消失的船員將永遠無法與家人團聚……融蝕，便是這麼一回事嗎？"
  },
  Voice_6666_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_6667_AwakerVoiceContent = {
    Text = "離吾主更近了一些……"
  },
  Voice_6667_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_6668_AwakerVoiceContent = {
    Text = "為什麼？您為什麼……不肯醒來？"
  },
  Voice_6668_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6669_AwakerVoiceContent = {
    Text = "我是西岱島的奧爾拉，筆名……我曾與人約定，不向任何人透露筆名，十分抱歉，但請叫我奧爾拉就好。"
  },
  Voice_6669_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_6670_AwakerVoiceContent = {
    Text = "我抵觸一切非正義的行為，其中最為嚴重的，便是背叛。在軍隊中，若是不能、不敢將後背交給戰友，整支部隊就會是一盤散沙。"
  },
  Voice_6670_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_6671_AwakerVoiceContent = {
    Text = "為什麼你看起來一片漆黑，又如此明亮？……不，沒事，就當我在胡言亂語吧。"
  },
  Voice_6671_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_6672_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_6673_AwakerVoiceContent = {
    Text = "（堅持的悶哼）"
  },
  Voice_6673_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_6674_AwakerVoiceContent = {
    Text = "什麼？！"
  },
  Voice_6674_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_6675_AwakerVoiceContent = {
    Text = "我喜歡生命，喜歡光。想讓菲茵特從幽閉的殼中走出來，用自己的雙眼去聽、去看這個世界。"
  },
  Voice_6675_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_6676_AwakerVoiceContent = {
    Text = "看不見我！"
  },
  Voice_6676_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_6677_AwakerVoiceContent = {
    Text = "維護工作還需要繼續嗎？"
  },
  Voice_6677_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_6678_AwakerVoiceContent = {
    Text = "零件整備已完成。"
  },
  Voice_6678_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_6679_AwakerVoiceContent = {
    Text = "人會有背叛之心，工具不會。只要利用得當，融蝕也是復仇的工具。"
  },
  Voice_6679_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_6680_AwakerVoiceContent = {
    Text = "蟄伏千年的等待，這一刻終於來臨......我才是非利士人唯一的主宰！"
  },
  Voice_6680_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_6680_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_6681_AwakerVoiceContent = {
    Text = "剛才走過的，是深海的混種麼？唔......看看這挺直的脊樑吧，今夜我就要見到他匍匐跪地的模樣。"
  },
  Voice_6681_AwakerVoiceTitle = {
    Text = "閒話·關於凱刻斯"
  },
  Voice_6681_UnlockDesc = {
    Text = "獲得喚醒體「凱刻斯」後解鎖"
  },
  Voice_6682_AwakerVoiceContent = {
    Text = "力量逐漸回到手中……下一步，奪取屬於我的權力！"
  },
  Voice_6682_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_6682_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_6683_AwakerVoiceContent = {
    Text = "還不錯，距離扯下那女人虛偽的頭紗更近了一步。"
  },
  Voice_6683_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_6683_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_6684_AwakerVoiceContent = {
    Text = "冷靜冷靜冷靜……"
  },
  Voice_6685_AwakerVoiceContent = {
    Text = "不必忌諱。我對疼痛的閾值可能遠遠超出你們的想像。"
  },
  Voice_6685_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_6685_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_6686_AwakerVoiceContent = {
    Text = "要我說，漂亮的蠢東西才是最好的。可惜這裡充斥著太多聰慧卻無用的大腦。"
  },
  Voice_6686_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_6687_AwakerVoiceContent = {
    Text = "以紅巨星的核聚變反應為動力，輔以恒星坍縮時的能量，就能啟動永動機，點亮一盞永恆的燈……誒？你說，這裡沒有條件製造永動機，也沒有紅巨星？唔……"
  },
  Voice_6687_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_6688_AwakerVoiceContent = {
    Text = "敵人的血還沒有流盡。"
  },
  Voice_6688_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_6689_AwakerVoiceContent = {
    Text = "將它們……都交予我！"
  },
  Voice_6689_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_6690_AwakerVoiceContent = {
    Text = "將它們……都交予我！"
  },
  Voice_6690_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_6691_AwakerVoiceContent = {
    Text = "是時候趕赴戰場了。"
  },
  Voice_6691_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_6692_AwakerVoiceContent = {
    Text = "是時候了！"
  },
  Voice_6693_AwakerVoiceContent = {
    Text = "余安眠時，外溢的夢境將召致靈的沸騰。所以，在余熟睡時不要靠近，更不要隨意喚醒余。"
  },
  Voice_6693_AwakerVoiceTitle = {
    Text = "閒話·關於沉眠"
  },
  Voice_6694_AwakerVoiceContent = {
    Text = "是時候了！"
  },
  Voice_6695_AwakerVoiceContent = {
    Text = "雖然赫伯特是個很可怕的人，他的貓卻十分溫順……不對，準確來講，那是兩隻貓吧？"
  },
  Voice_6695_AwakerVoiceTitle = {
    Text = "閒話·關於赫伯特"
  },
  Voice_6695_UnlockDesc = {
    Text = "通關「調查行動」第2章後解鎖"
  },
  Voice_6696_AwakerVoiceContent = {
    Text = "那個叫墨菲的女人，穿得也太招搖了吧……不行，珈倫可不能輸給她！\n或者，乾脆殺掉好了……"
  },
  Voice_6696_AwakerVoiceTitle = {
    Text = "閒話·關於墨菲"
  },
  Voice_6696_UnlockDesc = {
    Text = "獲得喚醒體「墨菲」後解鎖"
  },
  Voice_6697_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_6698_AwakerVoiceContent = {
    Text = "舒服嗎？"
  },
  Voice_6698_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_6699_AwakerVoiceContent = {
    Text = "和彌薩格大學達成合作時，明明說好了不讓我去戰鬥的……"
  },
  Voice_6699_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_6699_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_6700_AwakerVoiceContent = {
    Text = "少得意忘形。有時候，崇高到低賤不過一步之遙。"
  },
  Voice_6700_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_6700_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_6701_AwakerVoiceContent = {
    Text = "法洛思向你問好。將我呼喚至此，想必是已經做好航行準備了吧。"
  },
  Voice_6701_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_6702_AwakerVoiceContent = {
    Text = "呀呼——好累好累，可以去玩了嗎！"
  },
  Voice_6702_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_6703_AwakerVoiceContent = {
    Text = "啊啊……他的光輝是如此灼熱閃耀，不容忽視，是愚昧的狂熱遮住了我的感官……不，我不能為我的愚笨找任何理由……"
  },
  Voice_6703_AwakerVoiceTitle = {
    Text = "閒話·關於圖魯"
  },
  Voice_6703_UnlockDesc = {
    Text = "獲得喚醒體「圖魯」後解鎖"
  },
  Voice_6705_AwakerVoiceContent = {
    Text = "沉眠夢境中的群星，去應去之處，指向神國之所在！"
  },
  Voice_6705_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_6706_AwakerVoiceContent = {
    Text = "你不覺得，推動萬物走向終結，讓世界的法則停止轉動，是很有趣的一件事嗎？"
  },
  Voice_6706_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_6707_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_6708_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_6709_AwakerVoiceContent = {
    Text = "請輸入戰鬥指令。"
  },
  Voice_6709_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_6710_AwakerVoiceContent = {
    Text = "我在星間漂流的日子裡，無數次夢到這一天……謝謝你，讓我和汀克特團聚。"
  },
  Voice_6710_AwakerVoiceTitle = {
    Text = "閒話·關於汀克特"
  },
  Voice_6710_UnlockDesc = {
    Text = "獲得喚醒體「汀克特」後解鎖"
  },
  Voice_6711_AwakerVoiceContent = {
    Text = "彌薩格大學是個好地方呢，尤其是那個每週開設的地下賭場……\n欸，您居然不知道嗎？哎呀，說漏嘴了嗎……"
  },
  Voice_6711_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_6712_AwakerVoiceContent = {
    Text = "「抵抗融蝕危機」，哈，人類的自我滿足，真是笑死人了。"
  },
  Voice_6712_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格大學"
  },
  Voice_6713_AwakerVoiceContent = {
    Text = "說到底，人類也只是一種膚淺的動物罷了。只需幾句話語，一點暗示，就能挑起相互的爭鬥……唉，這種程度可無法讓人打起精神啊。"
  },
  Voice_6713_AwakerVoiceTitle = {
    Text = "閒話·關於人類"
  },
  Voice_6714_AwakerVoiceContent = {
    Text = "也許，將你視作普通人類是我目光短淺，先入為主了。我很好奇，你這般的無信仰者是如何堅守自身城池的？這不是海之聖母的質詢，而是彌利亞姆的疑問，你能為我……解答這個問題嗎？"
  },
  Voice_6714_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_6714_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_6715_AwakerVoiceContent = {
    Text = "如此特殊的你，不會對淺薄紛擾的世間產生厭倦嗎？我由衷認為，永恆之國才會是你的歸宿。你將在神靈的土地上行走，暢遊於聖靈之池，植根於萬里沃土……加入我的聖行，與我一同凌駕塵世之上吧。屆時，你我將一同佇立王座側畔，共用重鑄神國的歡欣……"
  },
  Voice_6715_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_6715_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_6716_AwakerVoiceContent = {
    Text = "你我皆為匍匐塵世的無能之徒，那位聖人卻不一般。他是代行者，是神靈在人間的化身。他的諫諭恍若神靈的醒世之言，將文明指引向不朽……我不希冀你現在就能理解對他的信仰，但你終有一天會臣服於他的王座之下。"
  },
  Voice_6716_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_6716_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_6717_AwakerVoiceContent = {
    Text = "蒙宣召者是幸福的，你不這麼認為嗎？他們分得了神力，擁有了更長的壽命。當神的國再度降臨，祂的旨意重行於地上時，他們將成為光榮的信徒。這對孱弱的人類而言，難道不是莫大的幸運與幸福嗎？"
  },
  Voice_6717_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_6717_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_6718_AwakerVoiceContent = {
    Text = "沐浴神光之下的喜悅，如你一般的無信仰者是無法理解的……願我的神原諒你，原諒你的無知與無禮。"
  },
  Voice_6718_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_6718_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_6719_AwakerVoiceContent = {
    Text = "速戰速決吧，守密人。"
  },
  Voice_6719_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_6720_AwakerVoiceContent = {
    Text = "誒嘿——"
  },
  Voice_6720_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_6720_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_6721_AwakerVoiceContent = {
    Text = "受死吧，斯巴達臭蟲。"
  },
  Voice_6721_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_6722_AwakerVoiceContent = {
    Text = "朵爾小姐說，我可以像她一樣通過拋棄肉體來暫時躲避融蝕……做不到做不到做不到，進行手術時會失去意識，黑暗會趁虛而入……"
  },
  Voice_6722_AwakerVoiceTitle = {
    Text = "閒話·關於朵爾"
  },
  Voice_6722_UnlockDesc = {
    Text = "獲得喚醒體「朵爾」後解鎖"
  },
  Voice_6723_AwakerVoiceContent = {
    Text = "哼……怎麼？想尋求湮滅的命運了？"
  },
  Voice_6723_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_6724_AwakerVoiceContent = {
    Text = "主人還在受失眠的困擾嗎？珈倫為您準備了多比氏鎮靜劑哦~！雖然劑量是有點超標了啦，但良好的睡眠才是第一位哦！"
  },
  Voice_6724_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_6724_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_6725_AwakerVoiceContent = {
    Text = "當時我們喝著小酒，唱著歌，忽然就被變成怪物了！不過沒關係，綠油油的皮膚也很有趣呢！"
  },
  Voice_6725_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_6725_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_6726_AwakerVoiceContent = {
    Text = "珈倫的夢想？唔……買到漂亮的珍珠項鍊，然後戴著它參加舞會，成為最耀眼的明星！"
  },
  Voice_6726_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_6726_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_67276_AwakerVoiceContent = {
    Text = "欲之質體提芙蕾耶索德，她亦求取了自己的存續之道。在未知面前，無人得以判斷手段的崇高與卑劣。"
  },
  Voice_67276_AwakerVoiceTitle = {
    Text = "閒話·關於欲之質體"
  },
  Voice_67276_UnlockDesc = {
    Text = "獲得喚醒體「泰旖絲」後解鎖"
  },
  Voice_67277_AwakerVoiceContent = {
    Text = "穿越銀鑰之扉，抵達祂的王座。"
  },
  Voice_67277_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_67278_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_67279_AwakerVoiceContent = {
    Text = "勿要辜負祂的學識與記憶。"
  },
  Voice_67279_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_6727_AwakerVoiceContent = {
    Text = "左擦擦，右擦擦，灰塵煩惱除光光——"
  },
  Voice_6727_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_6727_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_67280_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_67281_AwakerVoiceContent = {
    Text = "無限時空連續體中的某個碎片降臨在我的靈識之中。"
  },
  Voice_67281_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_67282_AwakerVoiceContent = {
    Text = "我已窺知全貌。"
  },
  Voice_67282_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_67283_AwakerVoiceContent = {
    Text = "一切均在虛空之中。"
  },
  Voice_67284_AwakerVoiceContent = {
    Text = "你已經走得很深很遠了。很快，你就會觸碰到那非凡的奇蹟，希望那時你仍能維持當前的理智與鎮定。"
  },
  Voice_67284_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_67284_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_67285_AwakerVoiceContent = {
    Text = "「無知」。不，孜孜不倦地探求本質上並非無知，真正的無知者生活於朦朧之中，連自己不知曉什麼都無法認知。"
  },
  Voice_67285_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_67286_AwakerVoiceContent = {
    Text = "我將向你展示我的夢境。你在夢中所見的一切怪誕與混沌都比你所認知的現實更接近世界的本質。"
  },
  Voice_67286_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_67286_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_67287_AwakerVoiceContent = {
    Text = "這是予你的忠告：不要急躁。當你感覺到疲倦，立刻停止思考，保存體力和能量。否則，你會永遠迷失於夢境之中。"
  },
  Voice_67287_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_67287_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_67288_AwakerVoiceContent = {
    Text = "宇宙循環不止。"
  },
  Voice_67289_AwakerVoiceContent = {
    Text = "你我之間的同調本無須這等漫長的磨合，不過，為了保護你的靈智不受幻象侵害，我會循序漸進。"
  },
  Voice_67289_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_67289_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_6728_AwakerVoiceContent = {
    Text = "融蝕啊……我湊巧也接過與它相關的案子，不過怎麼說呢，我覺得消失也是種很自然的事情吧？歸根結底，每個人最終都會消失的。"
  },
  Voice_6728_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_67290_AwakerVoiceContent = {
    Text = "第一門。無限宇宙由點中誕生。"
  },
  Voice_67290_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_67290_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_67291_AwakerVoiceContent = {
    Text = "第二門。點綿延出線，通向無盡的兩極。"
  },
  Voice_67291_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_67291_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_67292_AwakerVoiceContent = {
    Text = "第四門。永恆的原型凝固在維度中的一處空間。"
  },
  Voice_67292_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_67292_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_67293_AwakerVoiceContent = {
    Text = "第三門。平面是局部和片面的代詞。"
  },
  Voice_67293_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_67293_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_67294_AwakerVoiceContent = {
    Text = "窮極之門。連結萬千宇宙的最終虛空，穿越窮極之門，世界的終極奧秘將對你敞開。"
  },
  Voice_67294_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_67294_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_67295_AwakerVoiceContent = {
    Text = "第五門。時間的變化只是你的錯覺，這世間從來沒有開始，自然也沒有結束。"
  },
  Voice_67295_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_67295_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_67296_AwakerVoiceContent = {
    Text = "我本應只是你的啟示者，引領你踏上這段旅途後便沉眠於那虛幻的池水中。如今你是我的連結者，你我之間的聯繫便千絲萬縷，再難終絕……"
  },
  Voice_67296_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_67297_AwakerVoiceContent = {
    Text = "你想要確認什麼嗎？可惜，這具軀體的感官與心智受到太多限制和約束，若你我在深淵中相會，我便能帶你領略更多……"
  },
  Voice_67297_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_67298_AwakerVoiceContent = {
    Text = "她亦是我的碎片之一，來自其他維度，一個已經永恆湮滅的世界。很遺憾，她雖然掌握了時間回溯的方式，卻未能理解超越時空的真諦，只能在苦痛中一次次淪陷。這是我的錯誤。"
  },
  Voice_67298_AwakerVoiceTitle = {
    Text = "閒話·關於環行拉蒙娜"
  },
  Voice_67298_UnlockDesc = {
    Text = "獲得喚醒體「環行·拉蒙娜」後解鎖"
  },
  Voice_67299_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_6729_AwakerVoiceContent = {
    Text = "很在意這幅軀體的模樣嗎？請不要胡思亂想，我出生時，是有一張人類臉龐的。"
  },
  Voice_6729_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_67300_AwakerVoiceContent = {Text = "我見。"},
  Voice_67300_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_67301_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_67302_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_67303_AwakerVoiceContent = {
    Text = "與質體的直接連結會毀傷你的靈智……不過，既然你執意如此，我必將回應你的呼喚而來。"
  },
  Voice_67303_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_67304_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_67305_AwakerVoiceContent = {
    Text = "那個孩子，因我的意識碎片，已然承受了太多她本不應承受的。好在她的靈魂仍如流動的銀一般澄澈……"
  },
  Voice_67305_AwakerVoiceTitle = {
    Text = "閒話·關於拉蒙娜"
  },
  Voice_67305_UnlockDesc = {
    Text = "獲得喚醒體「拉蒙娜」後解鎖"
  },
  Voice_67306_AwakerVoiceContent = {
    Text = "造訪祂的夢境，窺探禁忌的宇宙秘密。"
  },
  Voice_67306_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_67307_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_67308_AwakerVoiceContent = {
    Text = "窮極之門為你洞開。迎接門後的死寂世界吧。"
  },
  Voice_67308_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_67308_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_67309_AwakerVoiceContent = {
    Text = "我與他們建立這所學校的目的是為了「儲存」。你們做到的比我預見得更多。"
  },
  Voice_67309_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格"
  },
  Voice_6730_AwakerVoiceContent = {
    Text = "融蝕是神的饋贈。它帶來的痛苦不多不少，剛好能麻痺我們的神經，讓我們心無旁騖地投入美食、紅酒，然後一起狂歡，走向滅亡。"
  },
  Voice_6730_AwakerVoiceTitle = {
    Text = "閒話·關於融蝕"
  },
  Voice_67310_AwakerVoiceContent = {
    Text = "過去、現在、未來，億萬光輝皆繫於此！"
  },
  Voice_67310_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_67311_AwakerVoiceContent = {
    Text = "過去、現在、未來，億萬光輝皆繫於此！"
  },
  Voice_67311_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_67312_AwakerVoiceContent = {
    Text = "窮極之門已然開啟。於此，萬物歸一！"
  },
  Voice_67312_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_67313_AwakerVoiceContent = {
    Text = "窮極之門已然開啟。於此，萬物歸一！"
  },
  Voice_67313_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_67314_AwakerVoiceContent = {
    Text = "諦聽智慧之聲。"
  },
  Voice_67315_AwakerVoiceContent = {
    Text = "無窮、無盡、無限、無垠。"
  },
  Voice_67316_AwakerVoiceContent = {
    Text = "那是祂的意志……不，與其說意志，不如說是無意識，祂無意識的注視即會將萬物納入祂的吐息之中。"
  },
  Voice_67316_AwakerVoiceTitle = {
    Text = "閒話·關於危機"
  },
  Voice_67317_AwakerVoiceContent = {
    Text = "未能細究……蛛絲馬跡……"
  },
  Voice_67317_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_67318_AwakerVoiceContent = {
    Text = "我將展示真實。"
  },
  Voice_67318_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_67319_AwakerVoiceContent = {
    Text = "「答案」。我是因喜愛而守望這座門扉，也是因喜愛將門之鑰交託在你的手中。"
  },
  Voice_67319_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_6731_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_6732_AwakerVoiceContent = {
    Text = "天地萬象，輪回因果！"
  },
  Voice_6732_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_6733_AwakerVoiceContent = {
    Text = "天地萬象，輪回因果！"
  },
  Voice_6733_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_6734_AwakerVoiceContent = {
    Text = "這鋒刃還沒有褪色。"
  },
  Voice_6734_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_6735_AwakerVoiceContent = {
    Text = "訓練也不能鬆懈。"
  },
  Voice_6735_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_6736_AwakerVoiceContent = {
    Text = "更加靈活了。"
  },
  Voice_6736_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_6737_AwakerVoiceContent = {
    Text = "無形之物，將為您所驅使。"
  },
  Voice_6737_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_6737_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_6738_AwakerVoiceContent = {
    Text = "感受這灼熱的呼吸——"
  },
  Voice_6738_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_6739_AwakerVoiceContent = {
    Text = "我們都會成為……綠炎的一部分……"
  },
  Voice_6739_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_6740_AwakerVoiceContent = {
    Text = "我的盾將為了您而閃耀，主君。"
  },
  Voice_6740_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_6740_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_6741_AwakerVoiceContent = {
    Text = "又、又進步了一些，不勝感激！"
  },
  Voice_6741_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_6741_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_6743_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_6744_AwakerVoiceContent = {
    Text = "（不屑的隱忍）"
  },
  Voice_6744_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_6745_AwakerVoiceContent = {
    Text = "（不屑的隱忍）"
  },
  Voice_6745_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_6746_AwakerVoiceContent = {
    Text = "（不屑的隱忍）"
  },
  Voice_6746_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_6747_AwakerVoiceContent = {
    Text = "和大家在一起度過的時間，總是讓人感到閒適……"
  },
  Voice_6747_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_6748_AwakerVoiceContent = {
    Text = "殺戮的血鏈、提希豐的使者、仇恨的鋒刃……是他們給我安上這些稱號的。當然，我也不介意成為那樣的人就是了。"
  },
  Voice_6748_AwakerVoiceTitle = {
    Text = "閒話·關於自己"
  },
  Voice_6749_AwakerVoiceContent = {
    Text = "（驚呼）"
  },
  Voice_6749_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_6751_AwakerVoiceContent = {
    Text = "（驚呼）"
  },
  Voice_6751_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_6752_AwakerVoiceContent = {
    Text = "（驚呼）"
  },
  Voice_6752_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_6753_AwakerVoiceContent = {
    Text = "能去更遠的地方玩了嗎？去海邊吧！"
  },
  Voice_6753_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_6754_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_6755_AwakerVoiceContent = {
    Text = "哇——謝謝夥伴~"
  },
  Voice_6755_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_6756_AwakerVoiceContent = {
    Text = "夥伴~更多夥伴~"
  },
  Voice_6756_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_6757_AwakerVoiceContent = {
    Text = "尤烏哈希……他是很特別。你以為我家風光的日子是怎麼來的？全靠他在競技場像瘋狗一樣殺人。他才是我家最大的搖錢樹。"
  },
  Voice_6757_AwakerVoiceTitle = {
    Text = "閒話·關於尤烏哈希"
  },
  Voice_6757_UnlockDesc = {
    Text = "獲得喚醒體「尤烏哈希」後解鎖"
  },
  Voice_6758_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_6759_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_6760_AwakerVoiceContent = {
    Text = "上吧！下達戰鬥指令！"
  },
  Voice_6760_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_6761_AwakerVoiceContent = {
    Text = "深淵中…會有正義之光。"
  },
  Voice_6761_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_6762_AwakerVoiceContent = {
    Text = "正義之光在此點亮！"
  },
  Voice_6762_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_6763_AwakerVoiceContent = {
    Text = "人的情感，是像花朵般脆弱，又像花朵般珍貴的事物……"
  },
  Voice_6763_AwakerVoiceTitle = {
    Text = "閒話·關於柯蕾特"
  },
  Voice_6764_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_6765_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_67754_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_67756_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_67772_AwakerVoiceContent = {
    Text = "門扉啊，開啟吧。"
  },
  Voice_79297_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_79298_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_80092_AwakerVoiceContent = {
    Text = "水療法、電擊療法、拘束療法，這些並非治療而是折磨，所以義診期間，我會用自己的方式治療精神病院的病人，最終他們都獲得痊癒，找到了真正的自由。"
  },
  Voice_80092_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_80092_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_80093_AwakerVoiceContent = {
    Text = "可憐的懷特，因為附近的收容院已經滿員，他被家人關在豬圈裡飼養。我免費替他進行了治療，那之後，他終於明白了自己是個人，而非牲畜，並親手尋回了身為人類的尊嚴。"
  },
  Voice_80093_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_80093_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_80094_AwakerVoiceContent = {
    Text = "紡織女工、律師、男爵……我絕不會因為費用將病人拒之門外，在我看來，他們都只是需要治癒的病人而已。"
  },
  Voice_80094_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_80094_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_80095_AwakerVoiceContent = {
    Text = "我承認自己確實輕看了你，你的存在，便是痛苦本身。這次不需要事後回訪，我要待在你身邊，親眼看著結局的到來。"
  },
  Voice_80095_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_80095_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_80096_AwakerVoiceContent = {
    Text = "這些患者都給我帶來過美好的記憶。接下來，輪到你了，守密人，我已經為你選好了結局。那將是我生涯中，最值得反復品味的一次諮詢。"
  },
  Voice_80096_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_80096_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_81138_AwakerVoiceContent = {
    Text = "拒絕醫生的幫助對你並沒有好處。或許下一次，我們需要嘗試深度催眠。"
  },
  Voice_81138_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_81139_AwakerVoiceContent = {
    Text = "黑暗的房間，孤身一人，加上腦海中那不斷重複響起的眾多痛苦呢喃，這就是享受時間的最好方式。"
  },
  Voice_81139_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_81140_AwakerVoiceContent = {
    Text = "雖然這麼說有些失禮，但與那孩子談話只會讓我覺得無聊——你永遠只能看到一種表情，那就是笑容。"
  },
  Voice_81140_AwakerVoiceTitle = {
    Text = "閒話·關於奧瑞塔"
  },
  Voice_81140_UnlockDesc = {
    Text = "獲得喚醒體「奧瑞塔」後解鎖"
  },
  Voice_81141_AwakerVoiceContent = {
    Text = "請恕我不請自來，我只是察覺到你低落的心理能量，前來關心。現在，守密人，要開啟一段心靈之旅嗎？"
  },
  Voice_81141_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_81143_AwakerVoiceContent = {
    Text = "精神醫師治癒患者的方法是用環鑽術鑽開患者的頭骨——放輕鬆，那是許久以前了，如今我們有許多方式去測量與深入患者的心靈。"
  },
  Voice_81143_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_81143_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_81144_AwakerVoiceContent = {
    Text = "想要互相了解，只能敞開心扉——摸這裡，我的白銀之心就會為你打開。"
  },
  Voice_81144_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_81145_AwakerVoiceContent = {
    Text = "若是想聽我發表什麼感想，那你可能要失望了。比起傾訴，我更擅長傾聽。"
  },
  Voice_81145_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_81146_AwakerVoiceContent = {
    Text = "啊， 我聽到了祂的聲音，那些囈語，每個音節都充滿了最極致的痛苦！"
  },
  Voice_81146_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_81147_AwakerVoiceContent = {
    Text = "我會將這一刻的痛苦銘記在心裡，反復回憶品嘗……"
  },
  Voice_81147_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_81148_AwakerVoiceContent = {
    Text = "身為那位存在的碎片，你擁有著祂的氣息，那種充滿痛苦的氣息，這讓你的任何記憶，嘗起來都美味無比。"
  },
  Voice_81148_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_81149_AwakerVoiceContent = {
    Text = "回憶那些恐懼，細緻描述自己的痛苦感受，情緒衝擊療法的真諦就是直面痛苦，戰勝痛苦。來，擦去眼淚，將那些回憶慢慢地細緻地講給我聽……"
  },
  Voice_81149_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_81149_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_81150_AwakerVoiceContent = {
    Text = "恭喜你，你已經痊癒了——是的，幻聽、幻視都是正常現象，它們就是你痊癒的證明。"
  },
  Voice_81150_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_81150_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_81151_AwakerVoiceContent = {
    Text = "你的腦中一定充滿了光怪陸離的景象，沒關係，這都是正常的。將它們畫出來，你的潛意識和本能會替你揭示一切。"
  },
  Voice_81151_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_81151_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_81152_AwakerVoiceContent = {
    Text = "接下來是菲力浦·皮內爾的道德療法。你需要說出最深處的渴望和恐懼，這是卸下心靈鐐銬，恢復休眠人性的必要程序。"
  },
  Voice_81152_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_81152_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_81153_AwakerVoiceContent = {
    Text = "守密人，能幫我完成一個小測試嗎？只是羅夏墨跡測試而已，通過它，我就能看出你無人知曉的內在深處，成為唯一揭秘守密人內心秘密的喚醒體。"
  },
  Voice_81153_AwakerVoiceTitle = {
    Text = "閒話·關於心理分析"
  },
  Voice_81154_AwakerVoiceContent = {
    Text = "首先，讓我們先來聽一首音樂。聽到了嗎，舒緩輕柔的音樂。現在，讓自己的身心與音樂共振，進入靈性的放鬆……"
  },
  Voice_81154_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_81154_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_81155_AwakerVoiceContent = {
    Text = "看著靈擺，眼睛跟著它轉動……"
  },
  Voice_81155_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_81156_AwakerVoiceContent = {
    Text = "噓——安靜，然後走向我引導的結局。"
  },
  Voice_81156_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_81157_AwakerVoiceContent = {
    Text = "麻木的心靈不會激起我的任何興趣。他們的靈魂已經死亡，再如何挑撥，也不會有一絲漣漪。"
  },
  Voice_81157_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_81158_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_81159_AwakerVoiceContent = {
    Text = "我在聽，請繼續。"
  },
  Voice_81159_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_81160_AwakerVoiceContent = {
    Text = "請保持安靜。"
  },
  Voice_81160_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_81161_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_81162_AwakerVoiceContent = {
    Text = "再多信賴我一點。"
  },
  Voice_81162_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_81163_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_81164_AwakerVoiceContent = {
    Text = "無需隱瞞，無需羞怯，我是你最信任的唯一傾聽者。來，向我傾吐你最深重的痛苦……"
  },
  Voice_81164_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_81165_AwakerVoiceContent = {
    Text = "如今的艾繼絲看起來開朗了許多。當然，如果我的小小客人有需要，我很樂意提供幫助。我是指，真正的幫助。"
  },
  Voice_81165_AwakerVoiceTitle = {
    Text = "閒話·關於艾繼絲"
  },
  Voice_81165_UnlockDesc = {
    Text = "獲得喚醒體「艾繼絲」後解鎖"
  },
  Voice_81166_AwakerVoiceContent = {
    Text = "將你最真實的一面展露給我。"
  },
  Voice_81168_AwakerVoiceContent = {
    Text = "我會細細品味這甜美的痛苦。"
  },
  Voice_81169_AwakerVoiceContent = {
    Text = "無需隱瞞，無需羞怯，我是你最信任的唯一傾聽者。來，向我傾吐你最深重的痛苦……"
  },
  Voice_81169_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_81170_AwakerVoiceContent = {
    Text = "精神疾病並不是這個時代的專屬，它超脫於時間與空間，融蝕也是如此。兩者都超脫了人類認知的邊界，不是嗎？"
  },
  Voice_81170_AwakerVoiceTitle = {
    Text = "閒話·關於危機"
  },
  Voice_81171_AwakerVoiceContent = {
    Text = "噓——安靜，然後走向我引導的結局。"
  },
  Voice_81171_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_81172_AwakerVoiceContent = {
    Text = "這裡充滿了歷史的痕跡，而某種程度上，歷史代表著記憶——逝去者的痛苦記憶。"
  },
  Voice_81172_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格"
  },
  Voice_81173_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_81174_AwakerVoiceContent = {
    Text = "痛苦、絕望、死亡……這些記憶，嘗起來就像飯後甜點。"
  },
  Voice_81174_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_81175_AwakerVoiceContent = {
    Text = "不用那麼緊張，這只是一次普通的心理諮詢。"
  },
  Voice_81175_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_81176_AwakerVoiceContent = {
    Text = "聆聽我的指引。"
  },
  Voice_81176_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_84185_AwakerVoiceContent = {
    Text = "儀式出現未知意外。請原諒我用旗幟敲擊您的手臂，我必須讓您保持清醒。"
  },
  Voice_84185_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_84185_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_84186_AwakerVoiceContent = {
    Text = "這裡能看到不同的船隻模型、接觸更先進的導航設備，我很喜歡，最重要的是，我認為這艘「船」正走在正確的人類歷史航線上。"
  },
  Voice_84186_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格"
  },
  Voice_84187_AwakerVoiceContent = {
    Text = "儀式舉行成功，感謝您的配合。下次我會創造一些專屬的旗語，幫助我們更安全順利地完成儀式。"
  },
  Voice_84187_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_84187_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_84188_AwakerVoiceContent = {
    Text = "我不清楚它為什麼會存在，我只清楚一點：我必須成功領航，平安帶回出海的所有海員和乘客。"
  },
  Voice_84188_AwakerVoiceTitle = {
    Text = "閒話·關於危機"
  },
  Voice_84189_AwakerVoiceContent = {
    Text = "請放心，我會將這力量用於指引船隻的航行安全，絕不會濫用。"
  },
  Voice_84189_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_84190_AwakerVoiceContent = {
    Text = "請停止反抗。"
  },
  Voice_84190_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_84191_AwakerVoiceContent = {
    Text = "我對您只有敬重，並會誓死完成您下達的所有命令。"
  },
  Voice_84191_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_84192_AwakerVoiceContent = {
    Text = "抱歉，我不了解人只了解船，請原諒我用這種比喻：您的龍骨不是木也不是鐵，而是鋼，堅強又堅定，令人欽佩。"
  },
  Voice_84192_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_84192_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_84193_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_84194_AwakerVoiceContent = {
    Text = "比起喜歡，我更傾向用「皈依」這個詞。當直視那不可名狀的神明時，我的大腦失去理智陷入狂喜，是的，我該恐懼祂，但我無法控制自己。"
  },
  Voice_84194_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_84195_AwakerVoiceContent = {
    Text = "我不會被風暴打倒。"
  },
  Voice_84195_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_84196_AwakerVoiceContent = {
    Text = "如果沒有秩序，這世界還剩下什麼？只有混沌與混亂罷了。"
  },
  Voice_84196_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_84197_AwakerVoiceContent = {
    Text = "下一次出航，我想以領航員之外的身分登船。那個……我的意思是，我願意並接受在您的指引下行動。您值得我的全權信任。"
  },
  Voice_84197_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_84197_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_84198_AwakerVoiceContent = {
    Text = "我只是在履行自己身為領航員的職責，並不需要通報表揚。"
  },
  Voice_84198_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_84199_AwakerVoiceContent = {
    Text = "燈塔系統能夠極大減輕領航的壓力，而她的燈光尤其明亮，我很樂意與法洛思一起出航。"
  },
  Voice_84199_AwakerVoiceTitle = {
    Text = "閒話·關於法洛思"
  },
  Voice_84199_UnlockDesc = {
    Text = "獲得喚醒體「法洛斯」後解鎖"
  },
  Voice_84200_AwakerVoiceContent = {
    Text = "海員們，跟隨我的指引，我們一定會安全到達海港。"
  },
  Voice_84200_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_84201_AwakerVoiceContent = {
    Text = "精神連結成功，我感知到了您的意識……這是我第一次在虛空引航，如果出現偏航問題，請您及時指正。"
  },
  Voice_84201_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_84201_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_84202_AwakerVoiceContent = {
    Text = "觀察到捲雲及氣壓計內水銀持續下降，全體注意，船隻即將遭遇風暴。"
  },
  Voice_84202_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_84203_AwakerVoiceContent = {
    Text = "這次混亂全都是因為我錯誤規劃了航線，我願意按照規則接受懲罰。"
  },
  Voice_84203_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_84204_AwakerVoiceContent = {
    Text = "測量天體高度角。"
  },
  Voice_84205_AwakerVoiceContent = {
    Text = "這種頭暈眼花的感覺和暈船差不多。請閉上眼，抓住我的手靠在我身邊，這樣會好受一些。"
  },
  Voice_84205_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_84205_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_84206_AwakerVoiceContent = {
    Text = "收前桅縱帆，左舷壓浪，舵手按照我的測算重新調整航線。"
  },
  Voice_84206_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_84207_AwakerVoiceContent = {
    Text = "這些經驗彌足珍貴，我會將它詳細記載在航行日誌裡，留給後來海員。"
  },
  Voice_84207_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_84208_AwakerVoiceContent = {
    Text = "加深連結的儀式存在風險和未知結果，但請您放心，我會為您領航，讓儀式順利完成。"
  },
  Voice_84208_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_84208_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_84209_AwakerVoiceContent = {
    Text = "重新調節重心。"
  },
  Voice_84209_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_84210_AwakerVoiceContent = {
    Text = "注意保護船隻。"
  },
  Voice_84210_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_84211_AwakerVoiceContent = {
    Text = "有人是蒸汽船，回應慢但能高速運轉，有人是柴油船，啟動迅速卻功率有限。那麼您呢，守密人？"
  },
  Voice_84211_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_84211_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_84212_AwakerVoiceContent = {
    Text = "我堅信付出就會獲得回報這一基礎規律，今後我會更加努力的。"
  },
  Voice_84212_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_84213_AwakerVoiceContent = {
    Text = "多次的任務行動中，您已經證明了自己。我認為您是和我一樣優秀的領航者，不，或許您要比我優秀得多。"
  },
  Voice_84213_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_84213_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_84214_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_84215_AwakerVoiceContent = {
    Text = "只要您有需要，克珀珊特隨時待命。"
  },
  Voice_84215_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_84215_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_84216_AwakerVoiceContent = {
    Text = "海員們，跟隨我的指引，我們一定會安全到達海港。"
  },
  Voice_84216_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_84217_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_84218_AwakerVoiceContent = {
    Text = "領航員克珀珊特前來報到！旗幟已整備完畢，個人狀態良好，請守密人下達出航命令。"
  },
  Voice_84218_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_84219_AwakerVoiceContent = {
    Text = "我必會將船隻，引領向正確的航向。"
  },
  Voice_84219_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_84220_AwakerVoiceContent = {
    Text = "是帽子歪了嗎？抱歉，我不太明白您這樣做的意圖，請給我明確的指令。"
  },
  Voice_84220_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_84221_AwakerVoiceContent = {
    Text = "旗幟是領航員的語言，也是領航員的墓誌銘。當船隻沉沒，打撈者會從旗幟的殘骸裡，解讀出我留下的最後訊息。"
  },
  Voice_84221_AwakerVoiceTitle = {
    Text = "閒話·關於旗幟"
  },
  Voice_84222_AwakerVoiceContent = {
    Text = "感知船體平衡點。"
  },
  Voice_84222_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_84223_AwakerVoiceContent = {
    Text = "收前桅縱帆，左舷壓浪，舵手按照我的測算重新調整航線。"
  },
  Voice_84223_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_84224_AwakerVoiceContent = {
    Text = "E旗傳達指令。"
  },
  Voice_84225_AwakerVoiceContent = {
    Text = "必要時刻，學過輪機艙協作的領航員也能充當舵手，但為了確保船隻安全，我還是希望能夠將這項任務交給擅長的人。"
  },
  Voice_84225_AwakerVoiceTitle = {
    Text = "閒話·關於希萊斯特"
  },
  Voice_84225_UnlockDesc = {
    Text = "獲得喚醒體「希萊斯特」後解鎖"
  },
  Voice_84226_AwakerVoiceContent = {
    Text = "失重感出現，接下來是猶如船隻劇烈震動的搖晃感。跟著我的動作感知身體重心，保持平衡。"
  },
  Voice_84226_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_84226_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_84406_AwakerVoiceContent = {
    Text = "開始海圖勘誤。"
  },
  Voice_84408_AwakerVoiceContent = {
    Text = "C旗回應指令。"
  },
  Voice_90333_AwakerVoiceContent = {
    Text = "休想跨過我。"
  },
  Voice_90333_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_90334_AwakerVoiceContent = {
    Text = "朋友之間應該如何相處呢？波呂克斯喜歡吩咐我去做很多事，即使他自己完全做得到。而我也會願意幫他做那些事，那是屬於我們之間的交流。如果你想，我也會為你去做些什麼。"
  },
  Voice_90334_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_90334_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_90335_AwakerVoiceContent = {
    Text = "憑此不滅之身，抵擋一切災厄！"
  },
  Voice_90335_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_90336_AwakerVoiceContent = {
    Text = "即使是看過那本書之前，我們也不是沒有好奇過外面的世界，好奇那湖中孤島、暗紅圍牆之外的景色。但在波呂克斯被折磨的時候，我也從沒想過去反抗，與波呂克斯相比，我實在是懦弱很多、笨拙很多。"
  },
  Voice_90336_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_90336_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_90337_AwakerVoiceContent = {
    Text = "我像個笨蛋？對不起，請原諒我的無知，除了提燈教給我們的關於神的知識，我對其他一切都知之甚少。我會快些學習的，你喜歡什麼，討厭什麼，請都告訴我吧，我一定會好好記住的。"
  },
  Voice_90337_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_90337_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_90338_AwakerVoiceContent = {
    Text = "請見證吧，這份追求自由的意志。"
  },
  Voice_90338_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_90339_AwakerVoiceContent = {
    Text = "能夠滿足任何願望的商店，應有盡有的商品，真讓人敬而遠之……不，我沒有質疑那位女士的力量，但，“想要擁有一樣東西，就要付出相應的價格”，這樣的道理，我和波呂克斯已經體會了太多次。"
  },
  Voice_90339_AwakerVoiceTitle = {
    Text = "閒話·關於達芙黛爾"
  },
  Voice_90339_UnlockDesc = {
    Text = "獲得喚醒體「達芙黛爾」後解鎖"
  },
  Voice_90340_AwakerVoiceContent = {
    Text = "這雙被詛咒的羽翼，也能在高空之上翱翔嗎。"
  },
  Voice_90340_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_90341_AwakerVoiceContent = {
    Text = "你們無法摧毀我！"
  },
  Voice_90341_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_90342_AwakerVoiceContent = {
    Text = "您是想摸摸這些羽毛嗎？請吧，需要我將翅膀展開一些嗎？"
  },
  Voice_90342_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_90343_AwakerVoiceContent = {
    Text = "受人幫助的時候我常常會想，那些特別的照顧，那些您贈予的寶貴書卷、瑰麗的隕石礦晶，背後會不會都有其他的代價？抱歉，我不該這樣揣度您。"
  },
  Voice_90343_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_90343_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_90344_AwakerVoiceContent = {
    Text = "飛鳥終將翱翔於高空之上。"
  },
  Voice_90344_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_90345_AwakerVoiceContent = {
    Text = "烹飪美食的大師麼……製作食物的知識果然也是非常必要的，雖然我對進食的要求並不高，但波呂克斯實在太挑嘴了。看來應該找個時間去認真請教一下……不要去？為什麼，可是那位先生製作的食物看起來都十分美味？"
  },
  Voice_90345_AwakerVoiceTitle = {
    Text = "閒話·關於杜勒賽因"
  },
  Voice_90345_UnlockDesc = {
    Text = "獲得喚醒體「杜勒賽因」後解鎖"
  },
  Voice_90346_AwakerVoiceContent = {
    Text = "現在想來，在提燈時的那些侍女其實與我和波呂克斯沒有什麼分別，我們都是戴著一條條鎖鏈在生活，而她們對此始終順從而忍耐。不過那位綠色的侍女似乎不太一樣，她……非常有活力，好像天生就喜愛做這些，或許她已經擁有了最寶貴的自由吧。"
  },
  Voice_90346_AwakerVoiceTitle = {
    Text = "閒話·關於珈倫"
  },
  Voice_90346_UnlockDesc = {
    Text = "獲得喚醒體「珈倫」後解鎖"
  },
  Voice_90347_AwakerVoiceContent = {
    Text = "你們無法摧毀我！"
  },
  Voice_90347_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_90348_AwakerVoiceContent = {
    Text = "還是沒能……飛出去嗎……"
  },
  Voice_90348_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_90349_AwakerVoiceContent = {
    Text = "隨風消散吧！"
  },
  Voice_90350_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_90351_AwakerVoiceContent = {
    Text = "貴安，初次見面，我是卡斯托爾…………還需要說些別的嗎？抱歉，我有些不善言辭，如果你有什麼需要我知道的，請隨時呼喚我。"
  },
  Voice_90351_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_90352_AwakerVoiceContent = {
    Text = "不過如此……"
  },
  Voice_90352_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_90353_AwakerVoiceContent = {
    Text = "墜落吧！"
  },
  Voice_90353_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_90354_AwakerVoiceContent = {
    Text = "我有很多沒見過的東西，沒做過的事，那些荒蕪的深綠湖水、經久不散的濃霧都再也不會困住我們了。海洋、大都市、田園牧場，那本手抄本上說的地方，我都想去看一看，和波呂克斯與您一起。"
  },
  Voice_90354_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_90354_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_90355_AwakerVoiceContent = {
    Text = "當你聽到樹上的葉子沙沙作響，你就知道我已經在你身邊。"
  },
  Voice_90355_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_90355_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_90356_AwakerVoiceContent = {
    Text = "這些黑暗的羽毛，變得更加深邃了。"
  },
  Voice_90356_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_90357_AwakerVoiceContent = {
    Text = "其實我最羡慕的，就是您與您的同伴們那樣毫無猜忌、彼此信任的樣子，被遺忘、被背叛的感覺……實在太痛苦了。"
  },
  Voice_90357_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_90358_AwakerVoiceContent = {
    Text = "那位神偷告訴我，她可以教會我最厲害的街頭生存技巧，只需要付給她五百雷歐坊……我被騙了？不，我認為這是很值得學習的知識，這正是我和波呂克斯所缺少的……是錢的問題？我明白了，那麼，我去找她商量，付給她四百五十雷歐坊如何？"
  },
  Voice_90358_AwakerVoiceTitle = {
    Text = "閒話·關於詹金"
  },
  Voice_90358_UnlockDesc = {
    Text = "獲得喚醒體「詹金」後解鎖"
  },
  Voice_90359_AwakerVoiceContent = {
    Text = "我還能承受……"
  },
  Voice_90359_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_90360_AwakerVoiceContent = {
    Text = "小的時候，提燈對我們的管控還沒有那麼嚴格，有時候波呂克斯不知道去說了些什麼，就能神奇地要來一把糖果。品嘗那些糖果的感覺……就像現在一樣。"
  },
  Voice_90360_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_90360_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_90361_AwakerVoiceContent = {
    Text = "憑此不滅之身，抵擋一切災厄！"
  },
  Voice_90361_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_90362_AwakerVoiceContent = {
    Text = "您能教一教我，關於與人交易的知識嗎？如何與人交換物品，如何管理獲得的貨幣，真是一門深奧的學問。獲得自由只是開始，要做到獨立生活，我和波呂克斯還有很多需要學習的，往後就要多多打擾您了。"
  },
  Voice_90362_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_90363_AwakerVoiceContent = {
    Text = "隨風消散吧！"
  },
  Voice_90364_AwakerVoiceContent = {
    Text = "風，將其吹向死亡之口吧！"
  },
  Voice_90365_AwakerVoiceContent = {
    Text = "波呂克斯他……雖然被提燈灌輸了很多不好的想法，但他的本心是不壞的。他只是迫切地想要得到提燈的認可、教眾的認可，以至於過分地在乎他們的需求。與其說他太過自我，不如說，他一直害怕失去那份“自我”。"
  },
  Voice_90365_AwakerVoiceTitle = {
    Text = "閒話·關於波呂克斯"
  },
  Voice_90365_UnlockDesc = {
    Text = "獲得喚醒體「波呂克斯」後解鎖"
  },
  Voice_90366_AwakerVoiceContent = {
    Text = "抱歉，我不是有意走神的……您問我這片羽毛是什麼？這是……他最重要的東西，也是我最重要的東西。它很美吧？"
  },
  Voice_90366_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_90367_AwakerVoiceContent = {
    Text = "那時候我們每天都要在阿爾比諾或守燈人的教導下學習神學，當時我最大的願望就是有一天那些經文能重新修訂，變得又短又少。這樣我就不會因為背得頭暈眼花，被嚴厲的守燈人批評了。"
  },
  Voice_90367_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_90367_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_90368_AwakerVoiceContent = {
    Text = "感謝您，賜予我掌握自由的鑰匙。"
  },
  Voice_90368_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_90369_AwakerVoiceContent = {
    Text = "這雙翅膀終於長成了最豐滿的樣子，那樣結實、那樣有力。現在我可以一次帶上你和波呂克斯兩個人，當你想飛上天空的時候，就大聲呼喚我吧。"
  },
  Voice_90369_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_90369_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_90370_AwakerVoiceContent = {
    Text = "躲到翅膀後面來！"
  },
  Voice_90371_AwakerVoiceContent = {
    Text = "終於……見到了那本書上說的浩瀚星空啊。"
  },
  Voice_90371_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_90372_AwakerVoiceContent = {
    Text = "曾經教主……於麗埃特對我們也常常有溫情的時刻，她總是不吝於對所有人露出那副和煦的笑容，令人害怕辜負她的期待。只要她笑著摸一摸你的頭，任何抗拒的話就沒辦法說出口了。嗯，現在不會了，您可以任意摸我的頭。"
  },
  Voice_90372_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_90372_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_90373_AwakerVoiceContent = {
    Text = "我曾被浸泡在那些黑色的黏漿中很久、很久，久到我已經忘記了時間，久到……連波呂克斯也將我遺忘了。它帶給人的並不是肉體上的痛苦，而是一種眼睜睜看著自己消失的、靈魂上的恐懼。"
  },
  Voice_90373_AwakerVoiceTitle = {
    Text = "閒話·關於危機"
  },
  Voice_90374_AwakerVoiceContent = {
    Text = "我們從小就不被允許與他人有太多交流，朋友這個詞，也是很久很久以後才知道的。我和波呂克斯，除了對方一無所有，兄弟、朋友、同一所監牢之中的囚徒，都是我們，只有我們。現在，是時候去交些新朋友了。"
  },
  Voice_90374_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_90374_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_90375_AwakerVoiceContent = {Text = "退後！"},
  Voice_90375_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_90376_AwakerVoiceContent = {
    Text = "一座人人都可以自由交流、隨意交朋友的學校嗎？你說這裡不學神學，還可以選擇各種各樣的課程……甚至可以逃課？嗯，真是個美好的地方啊。"
  },
  Voice_90376_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格"
  },
  Voice_90377_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_90378_AwakerVoiceContent = {Text = "讓開！"},
  Voice_90378_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_95050_AwakerVoiceContent = {
    Text = "不敬之人……必有懲罰……"
  },
  Voice_95050_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_95051_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_95052_AwakerVoiceContent = {
    Text = "污穢之物。"
  },
  Voice_95052_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_95053_AwakerVoiceContent = {
    Text = "一位過於狂熱的信者，或許在世人眼中只是不可理喻的瘋子，雖然她也曾走入歧途，但這樣為神明付出一切的決心，卻是絕大多數庸人都做不到的堅毅，我對於她麼……只有些同類相見的悲傷罷了。"
  },
  Voice_95053_AwakerVoiceTitle = {
    Text = "閒話：關於彌利亞姆"
  },
  Voice_95053_UnlockDesc = {
    Text = "獲得喚醒體「彌利亞姆」後解鎖"
  },
  Voice_95054_AwakerVoiceContent = {
    Text = "我將帶來引領與審判，白夜的輝光將驅散你們的罪惡！"
  },
  Voice_95054_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_95055_AwakerVoiceContent = {
    Text = "哈……過去這麼久，他還是一點都沒變。兒時的我或許從沒想到，有一天我會傷害、虧欠哥哥如此之多，多到令我自慚形穢，即便這悲劇的命運並不受我們任何一人控制。我們曾經歷了那麼多分離，但，既然我已經回來了，從今往後，不會再有任何事能將我們分開，哪怕是死亡。"
  },
  Voice_95055_AwakerVoiceTitle = {
    Text = "閒話：關於卡斯托爾"
  },
  Voice_95055_UnlockDesc = {
    Text = "獲得喚醒體「卡斯托爾」後解鎖"
  },
  Voice_95056_AwakerVoiceContent = {
    Text = "以前我討厭的東西很多。不通禮數的雜役，目無尊卑的僕從，褻瀆神明的異教徒……可現在，提燈，唯有提燈！於麗埃特與她的教派，為我和哥哥帶來了無法彌補的傷痛。以聖子之名起誓，這種傷痛，我不會讓它再出現在其他人身上！"
  },
  Voice_95056_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_95057_AwakerVoiceContent = {
    Text = "我將奉行那光明的道路，直到窮盡我的一生。"
  },
  Voice_95057_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_95058_AwakerVoiceContent = {
    Text = "持燈者的光輝終將照徹長夜！"
  },
  Voice_95058_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_95059_AwakerVoiceContent = {
    Text = "您總是如此慷慨而仁慈，我會好好體悟這份光明的溫度。"
  },
  Voice_95059_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_95060_AwakerVoiceContent = {
    Text = "持燈者的使徒、誕於白夜之人、驅散黑暗者、聖心聖子，我，波呂克斯，應您的呼喚而來，為您奉上我黑暗的力量與光明的靈魂。"
  },
  Voice_95060_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_95061_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_95063_AwakerVoiceContent = {
    Text = "曾經所有的人都告訴我，這深淵般的黑色是我的信仰，是我將帶給信徒的賜福。如今，這黑暗早已將我侵蝕，與我融為一體……可這罪孽身體裡那顆跳動的心，是永遠無法被侵蝕的地方。請放心，我一定會用這黑色賦予我的能力，將真正的福祉帶給世人！"
  },
  Voice_95063_AwakerVoiceTitle = {
    Text = "閒話·關於危機"
  },
  Voice_95064_AwakerVoiceContent = {
    Text = "我會傳播您的偉名，一切不潔、不淨之物，終將被光明淨化。"
  },
  Voice_95064_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_95065_AwakerVoiceContent = {
    Text = "過往的種種罪孽已然犯下，不應該再去逃避它。我還要去修正提燈的錯誤，將那些歧路之人引向正途。讓我承擔我的罪孽吧。然後，我將回應這道光、回應您的召喚，踏上那條真正的、屬於聖子的道路。"
  },
  Voice_95065_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_95065_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_95066_AwakerVoiceContent = {
    Text = "多麼慈悲的心靈，讓您竟然願意寬恕一個滿身罪孽的人，我能感受到，您靈魂中那樣純淨的、比燈火還要明亮的光芒，或許您能夠引領我迷途的心……"
  },
  Voice_95066_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_95066_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_95067_AwakerVoiceContent = {
    Text = "那些黑暗，從於麗埃特的咒文中散佈的黑暗，一直籠罩在我的腦海……可現在，那黑暗裡竟然出現了一道光！那微弱的光點，是想告訴我什麼嗎？"
  },
  Voice_95067_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_95067_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_95068_AwakerVoiceContent = {
    Text = "聽說她曾經也是一位聖女，不過，這樣粗魯的儀態、蠻橫的言行……什麼？她連一句祈禱的經文都不會背誦？如此毫無虔誠的樣子，真讓人有些為她的神明汗顏。"
  },
  Voice_95068_AwakerVoiceTitle = {
    Text = "閒話：關於墨菲"
  },
  Voice_95068_UnlockDesc = {
    Text = "獲得喚醒體「墨菲」後解鎖"
  },
  Voice_95069_AwakerVoiceContent = {
    Text = "能夠引領眾人走出迷霧之人，才是真正純銀塑身的持燈者。於麗埃特口中的無罪淨土，卻是以教徒的累累屍骨堆砌而成。身為聖子，我會將新的福音播撒至所有值得拯救的虔信之人。"
  },
  Voice_95069_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格"
  },
  Voice_95070_AwakerVoiceContent = {
    Text = "引領我、給予我光明之人啊，曾經我一直被蒙蔽在虛假的意義中，現在在您的指引下，我已找回了我真正的使命——將那些愚昧而扭曲的偽信者矯邪歸正，為世間帶來恆久不滅的光明。我知曉您的無私，您並不需要我的虔誠與供奉，那麼就請允許我跟隨在您的身邊，記錄下您的每一條聖言與聖行，以供於暗夜之中指引我的前路。"
  },
  Voice_95070_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_95070_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_95071_AwakerVoiceContent = {
    Text = "帶著鐐銬，沐浴著黑暗，朝著那道光走去，堅定不移地走去……這就是您想對我說的話嗎？"
  },
  Voice_95071_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_95071_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_95072_AwakerVoiceContent = {
    Text = "一位光明的侍從失去了他手中的燈火，這盲目的痛苦實在令我心焦，我衷心地懇請您將這個迷失的靈魂拯救，請您握住我的手，貼近這顆聖心，請您賜予我，通往光明的指引……"
  },
  Voice_95072_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_95072_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_95073_AwakerVoiceContent = {
    Text = "不幸的孩子，不過她既已投身於追隨您的事業，便一定能得到最終的救贖。不過她那個猴子一樣的朋友為何也得到了您的垂憐？那個邪惡的小孩甚至偷走了我祈禱的法器！她的靈魂中一定隱藏著洪水一般的罪孽，真是不敬！不敬！"
  },
  Voice_95073_AwakerVoiceTitle = {
    Text = "閒話：關於艾繼絲和詹金"
  },
  Voice_95073_UnlockDesc = {
    Text = "獲得喚醒體「艾繼絲」、喚醒體「詹金」後解鎖"
  },
  Voice_95074_AwakerVoiceContent = {
    Text = "速速離去。"
  },
  Voice_95074_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_95075_AwakerVoiceContent = {
    Text = "持燈者的光輝終將照徹長夜！"
  },
  Voice_95075_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_95076_AwakerVoiceContent = {
    Text = "啊……我已見到了，磅礴的偉力、世界的真相……我已經明悟我過去的歧途，您才是真正的持燈者！請允許我成為您忠誠的使徒，這顆為持燈者而生的心臟，今後會為您而雀躍跳動、顫抖臣服……"
  },
  Voice_95076_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_95076_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_95077_AwakerVoiceContent = {
    Text = "那位神父盲目的救贖實在是不可取的愚行，神的福音自然只能賜予虔誠的義人，若連神的使徒都沒有一雙洞察的慧眼，使不加悔改、滿身罪孽的惡徒獲得獎賞，污染了神純淨的國度，這豈不是對神明與那些義人的背叛嗎？"
  },
  Voice_95077_AwakerVoiceTitle = {
    Text = "閒話：關於薩爾瓦多"
  },
  Voice_95077_UnlockDesc = {
    Text = "獲得喚醒體「薩爾瓦多」後解鎖"
  },
  Voice_95078_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_95079_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_95080_AwakerVoiceContent = {
    Text = "兒時的我一心想要飛出囚籠，那時我總認為這個只會給人帶來痛苦的地方毫不值得留戀。可如今經歷了兩次人生之後，我才發現自由並不是我唯一向往的東西，看到那些教徒們得知將獲得救贖時，那滿懷赤誠、希望與感激的樣子，才是聖子這個身分真正的意義。"
  },
  Voice_95080_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_95081_AwakerVoiceContent = {
    Text = "跟隨於麗埃特的那段時間，我做錯了許多事，本不應再得到這樣的信任。可您依然選擇了我……請放心，我會重新去找尋屬於我的信念。聖子不會再讓他的臣民失望，也不會讓您失望。"
  },
  Voice_95081_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_95081_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_95082_AwakerVoiceContent = {
    Text = "您的賜予，我會心懷感激地使用。"
  },
  Voice_95082_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_95083_AwakerVoiceContent = {Text = "無禮！"},
  Voice_95083_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_95084_AwakerVoiceContent = {Text = "可惡。"},
  Voice_95084_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_95085_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_95086_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_95087_AwakerVoiceContent = {
    Text = "我看到了！那道光，那道閃耀在意識深處的光，它變得越來越明亮了！它在呼喚我……"
  },
  Voice_95087_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_95087_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_95088_AwakerVoiceContent = {
    Text = "在童年時，卡斯托爾與我同任聖子之職。那時候，我總認為他太過木訥、笨拙，需要由我來指引未來的走向。如今了解了您所經歷的道路，我才明白，世界的基石是由您與他那樣正直堅守之人構建和開拓的。"
  },
  Voice_95088_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_95088_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_95089_AwakerVoiceContent = {
    Text = "我的明燈，自從得到您的指引，我想我已走上了完全正確的道路。至此您愚鈍的信徒還有一個困惑，那傳說中無罪的淨土，是否也掌握在您的御下？沒有這種東西？難道您的意思是……無罪的淨土就在人間之中、就在義人純淨的心靈之中？"
  },
  Voice_95089_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_95090_AwakerVoiceContent = {
    Text = "這顆聆聽神意的心臟，與您更加靠近了。"
  },
  Voice_95090_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_95091_AwakerVoiceContent = {
    Text = "您……您有什麼旨意要傳達於我嗎？您的使徒隨時準備聆聽您的教誨。"
  },
  Voice_95091_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_95092_AwakerVoiceContent = {
    Text = "照亮我吧，迷途的指引者！以您的光，我已經看清了我需要看清的全部……我會用這具被詛咒的身體，讓一切過往得到淨化，讓一切未來，都沐浴在這光芒之下！"
  },
  Voice_95092_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_95092_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_95093_AwakerVoiceContent = {
    Text = "吟詠光明！"
  },
  Voice_95391_AwakerVoiceContent = {
    Text = "在殘酷的世界中追求拯救麼？加油吧，充滿希望的小傢伙。"
  },
  Voice_95391_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_95391_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_95392_AwakerVoiceContent = {
    Text = "來，這些拿去玩吧，說是從什麼遺跡裡挖到的禁忌藏品。我對這些沾染祂們氣息的東西不感興趣，本想直接燒掉，但想著或許對你有用，就給你帶過來了。\n你問我怎麼來的？當然是某些人「自願」送給我的，放心吧，保證來路「乾淨」。"
  },
  Voice_95392_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_95392_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_95393_AwakerVoiceContent = {
    Text = "狩獵完成，報酬就用小傢伙的笑容支付吧。"
  },
  Voice_95393_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_95394_AwakerVoiceContent = {
    Text = "知道麼小傢伙，這兩把槍中射出的不是子彈，而是欲望和惡意的集合。\n這些無序的混沌構成了血肉般的火焰，在彼端的第七聲槍響時，它會將一切拖入煉獄中焚燒。"
  },
  Voice_95394_AwakerVoiceTitle = {
    Text = "閒話：關於槍"
  },
  Voice_95395_AwakerVoiceContent = {
    Text = "無需將自己逼得太緊，我的守密人。雖然我知曉這是一條刻不容緩的曲折之路，稍有不慎就會萬劫不復。但若繼續如此，總有一天你會因心力交瘁而倒下。如果有需要的話，就找我聊聊吧，以家人的身分。"
  },
  Voice_95395_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_95395_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_95396_AwakerVoiceContent = {
    Text = "燃燒，毀滅，哀嚎吧！"
  },
  Voice_95396_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_95397_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_95398_AwakerVoiceContent = {
    Text = "吾的視野更加清晰了，吾看到了藏於深淵下的東西……為了你們，吾必須要更強大的力量……"
  },
  Voice_95398_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_95398_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_95399_AwakerVoiceContent = {
    Text = "來守密人，坐過來點，現在顯得太生分了。\n你知道麼，當第一次見到你時，我從未想過有朝一日，可以在你這裡卸下那被稱作殘忍和冷酷的外殼。有些可笑對吧，兇名赫赫的爆燃之主，卻渴望得到一位可以傾訴真心的家人。\n答應我，如果那天你撐不住了……就在心裡呼喚吾之名諱，吾會帶著你一同，前往吾之國度。雖然這只能延緩一切的到來，但起碼在最後的時刻，你可以在吾懷裡，好好地休息一下了。"
  },
  Voice_95399_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_95399_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_95401_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_95402_AwakerVoiceContent = {
    Text = "在億萬欲望和惡意中，焚燒吧！"
  },
  Voice_95403_AwakerVoiceContent = {
    Text = "成功的狩獵後總是需要一場慶功宴，一起來吧，嚐嚐我烤的駱駝肉和剛搞到的龍舌蘭酒。等下，小傢伙你好像不能飲酒……那來喝我特製的果汁吧~"
  },
  Voice_95403_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_95403_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_95404_AwakerVoiceContent = {
    Text = "怎麼了，小傢伙？是想要一個擁抱麼？來吧，我熾熱的胸膛隨時為你張開……哈哈，別害羞嘛，作為大姐關心後輩什麼的，再正常不過了不是麼？"
  },
  Voice_95404_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_95406_AwakerVoiceContent = {Text = "該死。"},
  Voice_95406_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_95408_AwakerVoiceContent = {
    Text = "先撤退吧，我來殿后……放心，我會活著回去的。"
  },
  Voice_95408_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_95409_AwakerVoiceContent = {
    Text = "來吧，讓我們把一切，燒成灰！"
  },
  Voice_95409_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_95410_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_95411_AwakerVoiceContent = {
    Text = "火焰越來越旺了，小傢伙想看盛大的煙火麼？"
  },
  Voice_95411_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_95412_AwakerVoiceContent = {
    Text = "那幫踐踏人倫，匿於陰影，以@1為素材進行他們骯髒獻祭和研究的傢伙……早晚有一天，我會把他們全部殺光。"
  },
  Voice_95412_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_95413_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_95414_AwakerVoiceContent = {
    Text = "我會找到他的，無論他藏到宇宙中哪一個角落，我終會找到他的。\n我要這骯髒的老鼠付出一切作為代價，當我找到他的那一刻，世間一切歡悅和欣愉都將在煉獄中焚燒。\n放心，到時候他的葬禮上，我會給你留個特等席，以便我們一起，品嘗他最後的哀嚎。"
  },
  Voice_95414_AwakerVoiceTitle = {
    Text = "閒話：關於N"
  },
  Voice_95415_AwakerVoiceContent = {
    Text = "聆聽吧，這群星融化的悲嚎。"
  },
  Voice_95415_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_95415_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_95417_AwakerVoiceContent = {
    Text = "你可是我引以為傲的家人，自信點，我的守密人！無論發生什麼，我都是你最堅強的後盾。"
  },
  Voice_95417_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_95418_AwakerVoiceContent = {
    Text = "那些難以名狀的存在正在侵蝕這個世界，你將不可避免的與其為敵。不過這並無關係，因為吾會在你身後。"
  },
  Voice_95418_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_95418_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_95420_AwakerVoiceContent = {
    Text = "燃燒，毀滅，哀嚎吧！"
  },
  Voice_95420_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_95421_AwakerVoiceContent = {
    Text = "保持冷靜。"
  },
  Voice_95421_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_95422_AwakerVoiceContent = {Text = "後退。"},
  Voice_95422_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_95423_AwakerVoiceContent = {
    Text = "你問我怎麼看融蝕？這就像問一個遊走於陰溝裡的小老鼠如何看待高高在上的領主老爺。我的答案只有一個：發自身體本能的厭惡。如果可以，我會一邊喝著美味的駱駝奶酒，一邊欣賞它們在我的槍下死去的尖嘯。"
  },
  Voice_95423_AwakerVoiceTitle = {
    Text = "閒話·關於危機"
  },
  Voice_95424_AwakerVoiceContent = {
    Text = "想讓火焰更熾熱一些麼？"
  },
  Voice_95424_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_95424_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_95425_AwakerVoiceContent = {
    Text = "我只會在接受委託時來到這裡，小傢伙想找我的話，就用這個咒語吧。來，跟著我念：……………… Ia! KathiguRa!"
  },
  Voice_95425_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格"
  },
  Voice_95426_AwakerVoiceContent = {
    Text = "曾幾何時，我們還在那個破舊的小鎮中，靠著兇狠和狡詐掙扎度日。即使成為了所謂的「大勢力」，面對老爺、警衛團以及不願意退出歷史舞臺的「騎士大人」，我們都必須打起十二分的精神。但現在不同了，大家成為了我的「眷族」，不用再看他人臉色行事。嘛，雖然還有個小傢伙流落在外，但我相信那傢伙一定能平安無事，畢竟每次我在外面忙的時候，都是這傢伙去照顧其他人。"
  },
  Voice_95426_AwakerVoiceTitle = {
    Text = "閒話：關於家人"
  },
  Voice_95427_AwakerVoiceContent = {
    Text = "這就是小傢伙的敵人？那麼——狩獵開始。"
  },
  Voice_95427_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_95428_AwakerVoiceContent = {
    Text = "吾乃永不遺忘的爆燃之主！宣告！萬物將亡！"
  },
  Voice_95428_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_95429_AwakerVoiceContent = {
    Text = "燃燒和毀滅就是我的一切，我熱衷於狩獵帶來的死亡……你覺得我會這麼說麼？\n哈哈，說笑的，對我而言，最重要的自然是身邊的大家了。沒有什麼比大家更重要，即使……我自己也不行。"
  },
  Voice_95429_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_95430_AwakerVoiceContent = {
    Text = "小傢伙遇到麻煩了？那麼遵循召喚，凱蒂古拉將帶著毀滅而來。讓所有麻煩都——“碰”的灰飛煙滅。"
  },
  Voice_95430_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_95431_AwakerVoiceContent = {
    Text = "力量的味道，要不要找些倒楣蛋試試手呢？"
  },
  Voice_95431_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_95431_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_95432_AwakerVoiceContent = {
    Text = "吾乃永不遺忘的爆燃之主！宣告！萬物將亡！"
  },
  Voice_95432_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_95433_AwakerVoiceContent = {
    Text = "傳說中的亞蘭女王，偉大的欲之質體提芙蕾耶索德，我曾在追殺N的時候見過她一面。雖然我不認可她所做的那些事情，但平心而論，若那是我能找到的，讓大家從「祂」的瞥視中存活下來的唯一方式……我也會做出相同的選擇。從這個角度上來講，我和她並沒有什麼區別。"
  },
  Voice_95433_AwakerVoiceTitle = {
    Text = "閒話：關於泰旖絲"
  },
  Voice_95433_UnlockDesc = {
    Text = "獲得喚醒體「泰旖絲」後解鎖"
  },
  Voice_95434_AwakerVoiceContent = {
    Text = "手感極佳，槍械保養的不錯嘛。"
  },
  Voice_95434_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_95435_AwakerVoiceContent = {
    Text = "吾即是火，是焰，是永燃不止的混沌……吾會將大家……帶回家……"
  },
  Voice_95435_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_95435_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_96361_AwakerVoiceContent = {
    Text = "這裡的哥特式鐘樓頗具古典氣息，這裡的喚醒體身上也有著一種我從未品鑒過的味道，既有亡者的芳香，又有一絲靈動的活人氣味，真是……讓人有些想要嘗試一下。"
  },
  Voice_96361_AwakerVoiceTitle = {
    Text = "閒話·關於彌薩格"
  },
  Voice_96362_AwakerVoiceContent = {
    Text = "尋求死亡之人，我將滿足你的願望。"
  },
  Voice_96362_AwakerVoiceTitle = {
    Text = "狂氣爆發·二"
  },
  Voice_96363_AwakerVoiceContent = {
    Text = "我已經有些等不及開動了。"
  },
  Voice_96363_AwakerVoiceTitle = {
    Text = "靈知覺醒"
  },
  Voice_96364_AwakerVoiceContent = {
    Text = "心動了，對嗎？來吧，我親愛的客人，成為我的座上之賓，一起來享用這場盛宴。讓我帶領你，共同品味每個亡靈細膩的餘韻。"
  },
  Voice_96364_AwakerVoiceTitle = {
    Text = "啟靈·綻放"
  },
  Voice_96364_UnlockDesc = {
    Text = "啟靈等級達到15解鎖"
  },
  Voice_96365_AwakerVoiceContent = {
    Text = "噓，請別說話，讓我們一起靜靜傾聽亡靈的聲音。"
  },
  Voice_96365_AwakerVoiceTitle = {
    Text = "同調率·一"
  },
  Voice_96365_UnlockDesc = {
    Text = "同調率等級達到2解鎖"
  },
  Voice_96366_AwakerVoiceContent = {
    Text = "永恆之美是我們的信仰。將消解緩慢施加在活人身上，抹去一切存在的痕跡……這對生命來說，是純粹而殘忍的折磨。"
  },
  Voice_96366_AwakerVoiceTitle = {
    Text = "閒話·關於危機"
  },
  Voice_96367_AwakerVoiceContent = {
    Text = "和我一樣，皮克曼也在追求著永恆的藝術，我們本應成為更好的朋友。可他卻認為進食是一種破壞永恆的行為，這種藝術理念實在過於狹隘。"
  },
  Voice_96367_AwakerVoiceTitle = {
    Text = "閒話·關於皮克曼"
  },
  Voice_96367_UnlockDesc = {
    Text = "獲得喚醒體「皮克曼」後解鎖"
  },
  Voice_96368_AwakerVoiceTitle = {
    Text = "打擊·一"
  },
  Voice_96369_AwakerVoiceContent = {
    Text = "任何形容詞都難以描述你身上這種令人迷醉的香氣，既像波爾多葡萄酒酸澀而豐腴的回味，又像乳脂鬆糕般濃郁而醇香，啊……期待你死亡的那一天或許將成為我餘生最重要的事。"
  },
  Voice_96369_AwakerVoiceTitle = {
    Text = "閒話·關於守密人"
  },
  Voice_96370_AwakerVoiceContent = {
    Text = "我曾見過一樁犯罪現場，一個男人正一點點割下一位少女的皮肉、指甲、手與腳，卻又不斷治療著她。他不想讓她死去，也絕不是想讓她活著。我當然不可能賜予他安寧的死亡，只是讓他不斷體驗著與那位少女同樣的經歷，算一算好像有幾年了吧……對於褻瀆死亡之人而言，這很公平，不是嗎？"
  },
  Voice_96370_AwakerVoiceTitle = {
    Text = "閒話·討厭的東西"
  },
  Voice_96371_AwakerVoiceContent = {
    Text = "我是司掌死亡之神，但請不要誤會，我從不製造死亡。我只是追隨死亡的腳步，摘下那豐美成熟的果實。"
  },
  Voice_96371_AwakerVoiceTitle = {
    Text = "啟靈·遠眺"
  },
  Voice_96371_UnlockDesc = {
    Text = "啟靈等級達到1解鎖"
  },
  Voice_96372_AwakerVoiceContent = {
    Text = "你也對我的味道感到渴望嗎，守密人閣下？"
  },
  Voice_96372_AwakerVoiceTitle = {
    Text = "閒話·觸摸"
  },
  Voice_96373_AwakerVoiceContent = {
    Text = "今天應該把誰送上餐桌呢？"
  },
  Voice_96373_AwakerVoiceTitle = {
    Text = "調查開始"
  },
  Voice_96374_AwakerVoiceContent = {
    Text = "我將賜予你們，成為今日晚宴的榮耀。"
  },
  Voice_96374_AwakerVoiceTitle = {
    Text = "調查成功"
  },
  Voice_96375_AwakerVoiceContent = {
    Text = "太不優雅了。"
  },
  Voice_96375_AwakerVoiceTitle = {
    Text = "受擊·三"
  },
  Voice_96376_AwakerVoiceContent = {
    Text = "我將帶來潔淨的安息。"
  },
  Voice_96377_AwakerVoiceContent = {
    Text = "在每一次進食之前，我都會與亡靈對話。對他們而言，被人認真地食用、品嘗，是生命的延長與最後的輝煌。就像我們渴望著他們，他們也在渴望著我們。"
  },
  Voice_96377_AwakerVoiceTitle = {
    Text = "同調率·三"
  },
  Voice_96377_UnlockDesc = {
    Text = "同調率等級達到6解鎖"
  },
  Voice_96378_AwakerVoiceContent = {
    Text = "安靜一點。"
  },
  Voice_96378_AwakerVoiceTitle = {
    Text = "受擊·四"
  },
  Voice_96379_AwakerVoiceContent = {
    Text = "在陰影中消散吧！"
  },
  Voice_96380_AwakerVoiceContent = {
    Text = "我們還是保持距離比較好。"
  },
  Voice_96380_AwakerVoiceTitle = {
    Text = "防禦·一"
  },
  Voice_96381_AwakerVoiceContent = {
    Text = "在陰影中消散吧！"
  },
  Voice_96382_AwakerVoiceContent = {
    Text = "為何對我如此防備？你不應也不必驚慌，對活人下口有悖我的美學。"
  },
  Voice_96382_AwakerVoiceTitle = {
    Text = "閒話·關於食物"
  },
  Voice_96383_AwakerVoiceContent = {
    Text = "尋求死亡之人，我將滿足你的願望。"
  },
  Voice_96383_AwakerVoiceTitle = {
    Text = "狂氣爆發"
  },
  Voice_96384_AwakerVoiceContent = {
    Text = "太不優雅了。"
  },
  Voice_96384_AwakerVoiceTitle = {
    Text = "受擊·一"
  },
  Voice_96385_AwakerVoiceTitle = {
    Text = "防禦·二"
  },
  Voice_96386_AwakerVoiceContent = {
    Text = "那位小姐的熱情雖然十分令人動容，但她的氣味聞起來，有著某種發酵過頭的潮濕味道。哪怕是她不住懇求著我品嘗一下，這也實在不符合我的口味，真叫人為難。"
  },
  Voice_96386_AwakerVoiceTitle = {
    Text = "閒話·關於雷婭"
  },
  Voice_96386_UnlockDesc = {
    Text = "獲得喚醒體「雷婭」後解鎖"
  },
  Voice_96387_AwakerVoiceContent = {
    Text = "你知道嗎？一切生命逝去時都擁有悠長的回聲。它們高低音色各不相同，會從死亡降臨的那一刻一點點拉長，直到漸漸飄散在天地之間，就像某種歎息般的鳴叫。"
  },
  Voice_96387_AwakerVoiceTitle = {
    Text = "同調率·二"
  },
  Voice_96387_UnlockDesc = {
    Text = "同調率等級達到4解鎖"
  },
  Voice_96388_AwakerVoiceContent = {
    Text = "請放心，守密人閣下，我會一直陪伴在你身邊，直到你的生命迎來無可阻擋的消亡的那一天。到那時，我一定會用最隆重的禮儀，將你的身軀一一吞食。我會將你的靈魂，永遠留在我的身體裡。"
  },
  Voice_96388_AwakerVoiceTitle = {
    Text = "同調率·五"
  },
  Voice_96388_UnlockDesc = {
    Text = "同調率等級達到10解鎖"
  },
  Voice_96389_AwakerVoiceContent = {
    Text = "你聞不到自己的味道？那可真是太遺憾了，你錯過了世界上最甜美、最……哎呀，為什麼要躲開呢。"
  },
  Voice_96389_AwakerVoiceTitle = {
    Text = "同調率·四"
  },
  Voice_96389_UnlockDesc = {
    Text = "同調率等級達到8解鎖"
  },
  Voice_96390_AwakerVoiceContent = {
    Text = "我已能看到更多的死亡，彼岸的景色，越發清晰了……"
  },
  Voice_96390_AwakerVoiceTitle = {
    Text = "獲得提升·三"
  },
  Voice_96391_AwakerVoiceContent = {
    Text = "將身體託付給我吧，讓我仔細地品嘗你，每一滴血、每一塊肉、每一根骨頭。"
  },
  Voice_96391_AwakerVoiceTitle = {
    Text = "超限狂氣爆發"
  },
  Voice_96392_AwakerVoiceContent = {
    Text = "不同的食材需要經過不同的處理。內臟需要醃制，腿部的肌腱最好燉煮，富含脂肪的部分適宜發酵熟成，口感特別的部位可以煎炸、炙烤，甚至做成一些造型優美的肉凍，這些都需要考究的選擇。當然，保留並突出食材的本味是必須的尊重。"
  },
  Voice_96392_AwakerVoiceTitle = {
    Text = "啟靈·體悟"
  },
  Voice_96392_UnlockDesc = {
    Text = "啟靈等級達到7解鎖"
  },
  Voice_96393_AwakerVoiceContent = {
    Text = "這會有些冷。"
  },
  Voice_96393_AwakerVoiceTitle = {
    Text = "打擊·二"
  },
  Voice_96394_AwakerVoiceContent = {
    Text = "菜餚的搭配也大有講究，酸與甜、脆與嫩、清爽與厚重、細膩與粗糙，層層遞進的口味與截然相反的口感碰撞在一起，入口、咀嚼、回味時都有不同的感受，這才是合格美食帶給人的無窮而奇妙的樂趣。"
  },
  Voice_96394_AwakerVoiceTitle = {
    Text = "啟靈·構築"
  },
  Voice_96394_UnlockDesc = {
    Text = "啟靈等級達到11解鎖"
  },
  Voice_96395_AwakerVoiceContent = {
    Text = "非常感謝你的熱情，我很榮幸。"
  },
  Voice_96395_AwakerVoiceTitle = {
    Text = "獲得提升·二"
  },
  Voice_96396_AwakerVoiceContent = {
    Text = "美味的食物，總是值得更多等待的。"
  },
  Voice_96396_AwakerVoiceTitle = {
    Text = "調查中止"
  },
  Voice_96397_AwakerVoiceContent = {
    Text = "我當然不是什麼茹毛飲血的怪物，享用死亡的過程是莊重而優雅的，你要滿懷著敬意去溝通、去理解每一份食材獨一無二的風味。"
  },
  Voice_96397_AwakerVoiceTitle = {
    Text = "啟靈·凝視"
  },
  Voice_96397_UnlockDesc = {
    Text = "啟靈等級達到2解鎖"
  },
  Voice_96398_AwakerVoiceContent = {
    Text = "歸於寧靜的亡者是美麗而芬芳的，並非因為他們的肉體會在生前與死後有多大的區別，而是在於他們的靈魂——那些靈魂對於死亡的領悟、對於生命的眷戀、對於被銘記的渴望，是我夢寐以求的珍饈。"
  },
  Voice_96398_AwakerVoiceTitle = {
    Text = "閒話·喜歡的東西"
  },
  Voice_96399_AwakerVoiceContent = {
    Text = "任何香水都比不上人體自然的芳香，聞香而識人，是一件最美妙不過的事。"
  },
  Voice_96399_AwakerVoiceTitle = {
    Text = "啟靈·深思"
  },
  Voice_96399_UnlockDesc = {
    Text = "啟靈等級達到3解鎖"
  },
  Voice_96400_AwakerVoiceContent = {
    Text = "啊，多麼令人刻骨銘心的香味……我已經迫不及待想要迎接你進入我的聖殿了。"
  },
  Voice_96400_AwakerVoiceTitle = {Text = "喚醒"},
  Voice_96401_AwakerVoiceContent = {
    Text = "將身體託付給我吧，讓我仔細地品嘗你，每一滴血、每一塊肉、每一根骨頭。"
  },
  Voice_96401_AwakerVoiceTitle = {
    Text = "超限狂氣爆發·二"
  },
  Voice_96402_AwakerVoiceContent = {
    Text = "我將帶來潔淨的安息。"
  },
  Voice_96403_AwakerVoiceContent = {
    Text = "安靜一點。"
  },
  Voice_96403_AwakerVoiceTitle = {
    Text = "受擊·二"
  },
  Voice_96404_AwakerVoiceTitle = {
    Text = "獲得提升·一"
  },
  Voice_98324_AwakerVoiceContent = {
    Text = "在億萬欲望和惡意中，焚燒吧！"
  }
})
return Text_Voice
